window.AZ104_QUESTIONS=[{"id":"1-1","test":1,"number":1,"stem":["You have an Azure subscription that includes a Recovery Services vault named Vault1.","You plan to configure multi-user authorization (MAU) for Vault1.","Which Azure resource must be created before you can enable MAU?"],"options":[{"text":"an Azure administrative unit","correct":false},{"text":"an Azure managed identity","correct":false},{"text":"a resource guard","correct":true},{"text":"a custom Azure role","correct":false}],"explanation":["a resource guard is correct because enabling Multi-User Authorization (MAU) in a Recovery Services vault requires creating a resource guard. A resource guard protects critical operations (such as disabling soft delete or stopping backup) by requiring additional authorization from designated approvers. The resource guard enforces MAU by ensuring operations cannot proceed without explicit approval from specified users or groups.","an Azure administrative unit is incorrect because administrative units are used for grouping Azure AD resources and delegating administrative tasks, not for securing critical Recovery Services vault operations.","an Azure managed identity is incorrect because managed identities are used to securely authenticate services with Azure resources, not for enabling or managing MAU in a Recovery Services vault.","a custom Azure role is incorrect because, while custom roles may provide granular permissions, they are not required to enable MAU. The primary requirement for MAU is the creation of a resource guard."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-manage?tabs=portal"],"images":[],"topic":"identity","needsImage":false},{"id":"1-2","test":1,"number":2,"stem":["You have an Azure subscription that includes the following public IP address resources:","- IP1 – IPv4, Standard SKU, Regional tier, Static assignment","- IP2 – IPv4, Standard SKU, Global tier, Static assignment","- IP3 – IPv4, Basic SKU, Regional tier, Dynamic assignment","- IP4 – IPv4, Basic SKU, Regional tier, Static assignment","- IP5 – IPv6, Standard SKU, Regional tier, Static assignment","You plan to deploy an Azure Firewall Premium instance named FW1.","Which of these public IP addresses are eligible to be associated with FW1?"],"options":[{"text":"IP1 only","correct":true},{"text":"IP1 and IP2 only","correct":false},{"text":"IP1, IP2, and IP5 only","correct":false},{"text":"IP1, IP2, IP4, and IP5 only","correct":false}],"explanation":["IP1 is correct because it is an IPv4, Standard SKU, Regional tier, Static public IP address. Azure Firewall supports Standard SKU public IP addresses, and Azure Firewall requires a static IPv4 public IP configuration.","IP2 is incorrect because, although it is an IPv4 Standard SKU address with Static assignment, it uses the Global tier. Global-tier public IP addresses are intended for the frontends of cross-region Azure Load Balancers. Azure Firewall is a regional resource and its public IP must therefore use the Regional tier.","IP3 is incorrect because it uses the Basic SKU and Dynamic assignment. Azure Firewall supports Standard SKU public IP addresses; Basic SKU public IP addresses aren't supported. Additionally, Azure Firewall uses static rather than dynamic public IPv4 addresses.","IP4 is incorrect because, although it is an IPv4 Regional address with Static assignment, it uses the Basic SKU. Azure Firewall does not support Basic SKU public IP addresses.","IP5 is incorrect because it is an IPv6 public IP address. Azure Firewall currently does not support IPv6; it operates using IPv4, even when deployed in a dual-stack virtual network.","Therefore, among the listed public IP addresses, only IP1 satisfies all the requirements for association with FW1: IPv4, Standard SKU, Regional tier, and Static assignment."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/configure-public-ip-firewall","https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/public-ip-addresses","https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/ipv6-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"1-3","test":1,"number":3,"stem":["You have an Azure subscription named Sub1 that contains the following resources:","- MG1: Management group","- RG1: Resource group","- VM1: Virtual machine","You create a user account named Admin1.","To which of these resources can you assign Admin1 as a co-administrator?"],"options":[{"text":"VM1","correct":false},{"text":"MG1","correct":false},{"text":"RG1","correct":false},{"text":"Sub1","correct":true}],"explanation":["Sub1 is correct because the Co-administrator role can only be assigned at the subscription level. This role grants the same access as the built-in Owner role but does not allow modifying role assignments within the subscription."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/rbac-and-directory-admin-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"1-4","test":1,"number":4,"stem":["You have an Azure subscription that contains the following resources:","- ManagementGroup1: Management group","- RG1: Resource group","- 5e7a2c91-4b3d-4f68-9a21-c8d7e3b5f402: Subscription ID","- Tag1: Tag","You are working in Azure Cloud Shell and need to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","You must complete the shown command to perform the deployment.","What should you choose for Code Segment A?"],"options":[{"text":"New-AzVm","correct":false},{"text":"New-AzResource","correct":false},{"text":"New-AzTemplateSpec","correct":false},{"text":"New-AzResourceGroupDeployment","correct":true}],"explanation":["New-AzResourceGroupDeployment is correct as we can only deploy the resources via ARM template in powershell when we scope it to a collection in Azure for e.g., a resource group, a subscription or a management group. Although there is no context mentioned in the question, yet among the options, this is the only correct command that can be used during an ARM template deployment.","New-AzVM is incorrect because this command although does create a VM, yet cannot use a template file for the deployment. It uses a VM object with all the parameters you need to define the size, OS and other properties of the new VM.","New-AzResource is incorrect because similar to New-AzVM, this command can be used to create a resource of type VM, but it does not have a parameter where it can take the link of an ARM template to be used for the deployment.","New-AzTemplateSpec is incorrect because creating a templatespec is not going to help in directly creating a VM for you. You would have to manually deploy the VM again in the second step with the templateSpec that you create with this command. Hence this is not the correct answer."],"references":["https://learn.microsoft.com/en-us/powershell/module/az.compute/new-azvm?view=azps-10.1.0","https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azresource?view=azps-10.1.0","https://learn.microsoft.com/en-us/powershell/module/az.resources/new-aztemplatespec?view=azps-10.1.0","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-powershell"],"images":["assets/32c563c6725d662d.png"],"topic":"identity","needsImage":true},{"id":"1-5","test":1,"number":5,"stem":["You have an Azure subscription that contains the following resources:","- ManagementGroup1: Management group","- RG1: Resource group","- 5e7a2c91-4b3d-4f68-9a21-c8d7e3b5f402: Subscription ID","- Tag1: Tag","You are working in Azure Cloud Shell and need to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","You must complete the shown command to perform the deployment.","What should you choose for Code Segment B?"],"options":[{"text":"-Tag Tag1 `","correct":false},{"text":"-ResourceGroupName RG1 `","correct":true},{"text":"-GroupName ManagementGroup1 `","correct":false},{"text":"-Subscription 8c4be1cd-7655-4c66-63ea-a9ee101d8y75 `","correct":false}],"explanation":["-ResourceGroupName RG1 is correct because we are using New-AzResourceGroupDeployment as the first part, and that command uses the name of the resource group as the mandatory parameter.","-Tag Tag1, -GroupName ManagementGroup1 and -Subscription 8c4be1cd-7655-4c66-63ea-a9ee101d8y75 are incorrect options because these switches (parameters) are not used with the New-AzResourceGroupDeployment command used for deploying resources to a resource group using an ARM template. Hence we cannot choose these options."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-powershell"],"images":["assets/32c563c6725d662d.png"],"topic":"identity","needsImage":true},{"id":"1-6","test":1,"number":6,"stem":["You have an Azure App Service web app named app1.","Autoscaling is configured to scale based on a metric. The configuration defines instance limits with a minimum of 1 instance, a maximum of 5 instances, and a default of 1 instance.","A scale-out rule is configured as follows:","- When the average CPU percentage exceeds 70%, increase the instance count by 1.","You configure the autoscale rule criteria as shown below. The rule evaluates the CPU Percentage metric from the App Service plan metrics, uses a specified aggregation method and time grain, applies a threshold condition over a defined duration, and performs a scale-out action with a cooldown period.","Based on the information presented in the configuration, select the option that correctly completes the following statement:","\"After CPU usage has reached 80 percent for 15 minutes, ____________________ will be running.\""],"options":[{"text":"1 instance","correct":false},{"text":"2 instances","correct":true},{"text":"3 instances","correct":false},{"text":"4 instances","correct":false},{"text":"5 instances","correct":false}],"explanation":["2 instances is correct because the default count is 1. So it starts with 1 instance. If the CPU usage remains greater than 70% for more than 10 minutes, it increases the count by 1. And then it does not do any scaling operation for the next 5 minutes. So after 15 minutes, we will have 2 instances running."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-understanding-settings"],"images":["assets/5fc899e15595a6ff.png"],"topic":"compute","needsImage":true},{"id":"1-7","test":1,"number":7,"stem":["You have an Azure App Service web app named app1.","Autoscaling is configured to scale based on a metric. The configuration defines instance limits with a minimum of 1 instance, a maximum of 5 instances, and a default of 1 instance.","A scale-out rule is configured as follows:","- When the average CPU percentage exceeds 70%, increase the instance count by 1.","You configure the autoscale rule criteria as shown below. The rule evaluates the CPU Percentage metric from the App Service plan metrics, uses a specified aggregation method and time grain, applies a threshold condition over a defined duration, and performs a scale-out action with a cooldown period.","Based on the information presented in the configuration, select the option that correctly completes the following statement:","\"Once the first scale-out instance is created, the minimum time before an additional instance is created will be _______________________.\""],"options":[{"text":"1 minute","correct":false},{"text":"5 minutes","correct":true},{"text":"10 minutes","correct":false},{"text":"15 minutes","correct":false}],"explanation":["5 minutes is correct because 5 minutes is the cool down period. Once this period elapses, the system checks again the metrics of the last 10 minutes. If the CPU usage continues to stay above 70% in those 10 minutes, it will increase the count by 1. And then wait again for 5 minutes."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-understanding-settings"],"images":["assets/5fc899e15595a6ff.png"],"topic":"compute","needsImage":true},{"id":"1-8","test":1,"number":8,"stem":["You have an Azure subscription that includes the following resources:","- share1: An Azure file share hosted in storage1","- storage1: An Azure Storage account","- User1: A Microsoft Entra user","You need to assign User1 the Storage File Data SMB Share Contributor role for share1.","What action should you perform first?"],"options":[{"text":"Enable identity-based data access for the file shares in storage1.","correct":false},{"text":"Update the security configuration for the file shares in storage1.","correct":false},{"text":"Set the default authorization method to Microsoft Entra ID in the Azure portal for storage1.","correct":false},{"text":"Configure Access control (IAM) for share1.","correct":true}],"explanation":["Configure Access control (IAM) for share1 is correct as you can add access for a user from Access control for any type of resource in Azure. For share specific role also you need to go to IAM of the share and then add the respective Azure AD user.","Enable identity-based data access for the file shares in storage1 is incorrect because this is needed when you want a hybrid user to access the share. In that case, you enable access to Active Directory, Azure AD DS and Azure AD Kerberos. But in our case, the user is an Azure AD entity so a RBAC role assignment would be the way to go.","Update the security configuration for the file shares in storage1 is incorrect because security profile of a share has nothing to do with how a user authorizes itself against the share. It has other security features which you can configure for each of your shares.","Set the default authorization method to Microsoft Entra ID in the Azure portal for storage1 is incorrect because this option is not enough to allow user to be able to act as contributor for the share in your storage account."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-active-directory-overview","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"1-9","test":1,"number":9,"stem":["You have an Azure subscription with offices located in the East US and West US Azure regions.","You plan to create a storage account with the configuration shown below. The configuration specifies the subscription, resource group, region, performance tier, redundancy option, networking settings, data protection options, and encryption settings for the storage account.","The networking configuration shows that the storage account is accessible through a public endpoint and uses Microsoft network routing. Other settings, such as replication type and file share options, are also defined.","Based on the information presented in the graphic, select the answer choice that completes the following statement correctly.","\"To minimize the network costs of accessing adatum22, modify the ____________________ setting.\""],"options":[{"text":"Default routing tier","correct":true},{"text":"Endpoint type","correct":false},{"text":"Location","correct":false},{"text":"Network connectivity","correct":false},{"text":"Performance","correct":false}],"explanation":["Default routing tier is correct because by default the routing method is set to be through Microsoft global network. But this configuration sometimes increases the network costs if the data you are trying to access is in another region, and in order to reach your system it has to traverse through Microsoft global network to a great extent. In order to minimize this, you can change to Internet routing where it is passed on to the transit ISP at the earliest opportunity.","Endpoint type is incorrect as changing the endpoint type will not have any effect on the network costs of the traffic coming in or going out from the storage account.","Location is incorrect because we do not know as of now where the user, who is trying to access the file share is located. So changing the location will not help.","Network connectivity is incorrect because this defines how you connect to different services in the storage account. If you select Public endpoints then you can access them over the internet otherwise your requests should be coming in from inside the VNet provided VNet integration is already enabled.","Performance is incorrect because this chooses the tier in which your storage account runs. It basically defines the resources available to the services to handle your data and requests. Changing this may have effect on billing cost but it would not affect the networking cost."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/network-routing-preference"],"images":["assets/1047acb529d74c1a.png"],"topic":"identity","needsImage":true},{"id":"1-10","test":1,"number":10,"stem":["You have an Azure subscription with offices located in the East US and West US Azure regions.","You plan to create a storage account with the configuration shown below. The configuration specifies the subscription, resource group, region, performance tier, redundancy option, networking settings, data protection options, and encryption settings for the storage account.","The networking configuration shows that the storage account is accessible through a public endpoint and uses Microsoft network routing. Other settings, such as replication type and file share options, are also defined.","Based on the information presented in the graphic, select the answer choice that completes the following statement correctly.","\"After adatum22 is created, you can modify the ___________________________ setting.\""],"options":[{"text":"Enable infrastructure encryption","correct":false},{"text":"Enable support for customer-managed keys","correct":false},{"text":"Encryption type","correct":true},{"text":"Premium account type","correct":false}],"explanation":["Encryption Type is correct as we can change this setting even after creation of the storage account. It can be changed to customer-managed keys from Microsoft managed keys or vice-versa.","Enable infrastructure encryption is incorrect because we can only configure this option during the creation of the storage account.","Enable support for customer-managed keys is incorrect because this setting is final once configured during the creation. It cannot be changed later.","Premium account type is incorrect because we can only decide what type of account service we need during its creation. It cannot be extended later to include other services which were excluded before."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-service-encryption"],"images":["assets/1047acb529d74c1a.png"],"topic":"identity","needsImage":true},{"id":"1-11","test":1,"number":11,"stem":["You have an Azure subscription.","You plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template, as shown in the configuration below. The template defines the storage account location, SKU, and kind, along with network access settings. It also configures Blob service–level data protection features, including soft delete, container delete retention, change feed, and blob versioning, each with specified retention periods.","Based on this ARM template configuration, determine whether the following statement is True or False.","`\"Changes made to the data in storage1 can be rolled back after seven days\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because rolling back the data means restoring to a point in time. As per the configuration, the max period to which we can restore is 6 days. Hence we cannot roll back the data change done 7 days before."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-enable?tabs=portal","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-overview","https://learn.microsoft.com/en-us/azure/templates/microsoft.storage/storageaccounts/blobservices?pivots=deployment-language-arm-template#restorepolicyproperties-1"],"images":["assets/204a2293629cd8a9.png"],"topic":"identity","needsImage":true},{"id":"1-12","test":1,"number":12,"stem":["You have an Azure subscription.","You plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template, as shown in the configuration below. The template defines the storage account location, SKU, and kind, along with network access settings. It also configures Blob service–level data protection features, including soft delete, container delete retention, change feed, and blob versioning, each with specified retention periods.","Based on this ARM template configuration, determine whether the following statement is True or False.","`\"Only users located in the East US Azure region can connect to storage1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because allowPublicAccess is set to true and there is no ACL for region/IP-based. So everyone on the internet can access the storage account if the person has the access keys."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-enable?tabs=portal","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-overview","https://learn.microsoft.com/en-us/azure/templates/microsoft.storage/storageaccounts/blobservices?pivots=deployment-language-arm-template#restorepolicyproperties-1"],"images":["assets/204a2293629cd8a9.png"],"topic":"identity","needsImage":true},{"id":"1-13","test":1,"number":13,"stem":["You have an Azure subscription.","You plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template, as shown in the configuration below. The template defines the storage account location, SKU, and kind, along with network access settings. It also configures Blob service–level data protection features, including soft delete, container delete retention, change feed, and blob versioning, each with specified retention periods.","Based on this ARM template configuration, determine whether the following statement is True or False.","`\"Three copies of storage1 will be maintained in the East US Azure region.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because with LRS type of redundancy you get 3 copies of the data spread in 3 different zones/datacenters of the region."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-enable?tabs=portal","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-overview","https://learn.microsoft.com/en-us/azure/templates/microsoft.storage/storageaccounts/blobservices?pivots=deployment-language-arm-template#restorepolicyproperties-1"],"images":["assets/204a2293629cd8a9.png"],"topic":"identity","needsImage":true},{"id":"1-14","test":1,"number":14,"stem":["An Azure subscription contains a virtual machine called VM1 and an Azure Key Vault named KV1.","You are required to implement disk encryption for VM1 while meeting the following conditions:","- The encryption key must be stored and accessed from KV1.","- Encryption must remain intact if the virtual machine is downloaded from Azure.","- Both the operating system disk and any attached data disks must be encrypted.","Which encryption method should be implemented?"],"options":[{"text":"customer-managed keys","correct":false},{"text":"Azure Disk Encryption","correct":true},{"text":"Confidential disk encryption","correct":false},{"text":"encryption at host","correct":false}],"explanation":["`Azure Disk Encryption` is correct because it supports encrypting both the operating system and data disks of virtual machines using customer-managed keys stored in an Azure Key Vault. It ensures that the encryption persists even if the virtual machine disks are downloaded from Azure, meeting the specified requirements.","`customer-managed keys` is incorrect because while they allow managing encryption keys in Azure Key Vault, they are typically used for server-side encryption at the storage account level, not for encrypting the disks of virtual machines directly.","`Confidential disk encryption` is incorrect because it is designed for confidential computing environments where the data is encrypted in use, but it doesn't meet the requirement to persist encryption when VM disks are downloaded.","`encryption at host` is incorrect because this feature encrypts data stored on the host for VMs but does not encrypt the disks themselves, nor does it persist when the VM is downloaded."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/linux/disk-encryption-overview","https://learn.microsoft.com/en-us/azure/key-vault/general/customer-managed-keys-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"1-15","test":1,"number":15,"stem":["An Azure environment contains the following virtual machines:","- VM1: IP address 10.0.0.4, deployed in VNET1","- VM2: IP address 172.16.0.4, deployed in VNET2","- VM3: IP address 192.168.0.4, deployed in VNET3","- VM4: IP address 192.168.0.5, deployed in VNET3","The virtual networks VNET1, VNET2, and VNET3 are peered with each other.","A DNS server is running on VM4. This DNS server is authoritative for the contoso.com zone and contains the following records:","- Server1: \"A\" record with the value 131.107.2.3","- Server2: \"A\" record with the value 131.107.2.4","Additionally, VNET1 and VNET2 are linked to an Azure private DNS zone named contoso.com, which contains these records:","- Server1: \"A\" record with the value 131.107.3.3","- Server2: \"A\" record with the value 131.107.3.4","The virtual networks are configured to use the following DNS servers:","- VNET1: Azure-provided default DNS","- VNET2: Custom DNS server at 192.168.0.5","- VNET3: Custom DNS server at 192.168.0.5","True or False:","`\"From VM1, server1.contoso.com resolves to 131.107.3.3.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM1 is connected to private DNS zone , where we do see that an A record exists for Server1 which will resolve from server1.contoso.com to 131.107.3.3."],"references":["https://learn.microsoft.com/en-us/answers/questions/1150496/private-dns-vs-custom-dns-for-one-vnet","https://learn.microsoft.com/en-us/azure/dns/private-dns-virtual-network-links"],"images":[],"topic":"network","needsImage":false},{"id":"1-16","test":1,"number":16,"stem":["An Azure environment contains the following virtual machines:","- VM1: IP address 10.0.0.4, deployed in VNET1","- VM2: IP address 172.16.0.4, deployed in VNET2","- VM3: IP address 192.168.0.4, deployed in VNET3","- VM4: IP address 192.168.0.5, deployed in VNET3","The virtual networks VNET1, VNET2, and VNET3 are peered with each other.","A DNS server is running on VM4. This DNS server is authoritative for the contoso.com zone and contains the following records:","- Server1: \"A\" record with the value 131.107.2.3","- Server2: \"A\" record with the value 131.107.2.4","Additionally, VNET1 and VNET2 are linked to an Azure private DNS zone named contoso.com, which contains these records:","- Server1: \"A\" record with the value 131.107.3.3","- Server2: \"A\" record with the value 131.107.3.4","The virtual networks are configured to use the following DNS servers:","- VNET1: Azure-provided default DNS","- VNET2: Custom DNS server at 192.168.0.5","- VNET3: Custom DNS server at 192.168.0.5","True or False:","`\"From VM2, server1.contoso.com resolves to 131.107.3.3.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because VM2 is connected to private DNS zone, but the VNet itself is connected to a custom DNS server where we do see that an A record exists for Server1 which will resolve from server1.contoso.com to 131.107.2.3.","The key point here is that DNS resolution for a VM depends on the DNS server settings configured at the VNet level, not just the private DNS zone links.","- VM2 is in VNET2, and according to the table, VNET2 is configured to use a custom DNS server (192.168.0.5). That IP address belongs to VM4, which is itself authoritative for the `contoso.com` DNS zone (see the table showing Server1 → 131.107.2.3 and Server2 → 131.107.2.4).","- Even though VNET2 is also linked to the Azure private DNS zone `contoso.com` (which contains Server1 → 131.107.3.3 and Server2 → 131.107.3.4), that zone will not be queried by VMs in VNET2. Why? Because Azure Private DNS only applies if the VNet is configured to use the Azure-provided DNS. Since VNET2 is overridden to use the custom DNS server, all queries (like `server1.contoso.com`) go to VM4’s DNS instead.","- Therefore, when VM2 resolves `server1.contoso.com`, it will get the record from VM4’s DNS server (131.107.2.3), not from the private DNS zone (131.107.3.3)."],"references":["https://learn.microsoft.com/en-us/answers/questions/1150496/private-dns-vs-custom-dns-for-one-vnet","https://learn.microsoft.com/en-us/azure/dns/private-dns-virtual-network-links"],"images":[],"topic":"network","needsImage":false},{"id":"1-17","test":1,"number":17,"stem":["An Azure environment contains the following virtual machines:","- VM1: IP address 10.0.0.4, deployed in VNET1","- VM2: IP address 172.16.0.4, deployed in VNET2","- VM3: IP address 192.168.0.4, deployed in VNET3","- VM4: IP address 192.168.0.5, deployed in VNET3","The virtual networks VNET1, VNET2, and VNET3 are peered with each other.","A DNS server is running on VM4. This DNS server is authoritative for the contoso.com zone and contains the following records:","- Server1: \"A\" record with the value 131.107.2.3","- Server2: \"A\" record with the value 131.107.2.4","Additionally, VNET1 and VNET2 are linked to an Azure private DNS zone named contoso.com, which contains these records:","- Server1: \"A\" record with the value 131.107.3.3","- Server2: \"A\" record with the value 131.107.3.4","The virtual networks are configured to use the following DNS servers:","- VNET1: Azure-provided default DNS","- VNET2: Custom DNS server at 192.168.0.5","- VNET3: Custom DNS server at 192.168.0.5","True or False:","`\"From VM3, server2.contoso.com resolves to 131.107.2.4.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct as VM3 is connected to VNet3 which is connected to the DNS server VM4 and that DNS server does have an existing A record for server2 which will help in resolving server2.contoso.com to 131.107.2.4."],"references":["https://learn.microsoft.com/en-us/answers/questions/1150496/private-dns-vs-custom-dns-for-one-vnet","https://learn.microsoft.com/en-us/azure/dns/private-dns-virtual-network-links"],"images":[],"topic":"network","needsImage":false},{"id":"1-18","test":1,"number":18,"stem":["An Azure subscription contains a storage account named storage1, which includes a blob container called container1.","You need to define a lifecycle management policy for storage1 that automatically moves blobs stored in container1 to the lowest-cost access tier after they have remained unchanged for 90 days.","You are completing the lifecycle management rule shown in the configuration. The rule enables lifecycle management, targets base blobs, applies an action after a specified number of days since modification, and filters the scope of the rule to a specific container.","What should you choose for `Code Segment A`?"],"options":[{"text":"“enableAutoTierToHotFromCool”: {","correct":false},{"text":"“tierToArchive”: {","correct":true},{"text":"“tierToCool”: {","correct":false}],"explanation":["`tierToArchive”: {` is correct because here you define the action you want to take via the policy. As per the requirement we need to move the blobs to the lowest-cost tier which is the Archive tier after 90 days."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-policy-configure?tabs=azure-portal"],"images":["assets/74e46ccd9a67609d.png"],"topic":"identity","needsImage":true},{"id":"1-19","test":1,"number":19,"stem":["An Azure subscription contains a storage account named storage1, which includes a blob container called container1.","You need to define a lifecycle management policy for storage1 that automatically moves blobs stored in container1 to the lowest-cost access tier after they have remained unchanged for 90 days.","You are completing the lifecycle management rule shown in the configuration. The rule enables lifecycle management, targets base blobs, applies an action after a specified number of days since modification, and filters the scope of the rule to a specific container.","What should you choose for `Code Segment B`?"],"options":[{"text":"“blobIndexMatch”: [","correct":false},{"text":"“blobTypes”: [","correct":false},{"text":"“prefixMatch”: [","correct":true}],"explanation":["`“prefixMatch”: [` is correct because you need to apply the filter which will look for only the blobs in a specified container, container1 in this case. And PrefixMatch does exactly that, because the full name/address of the blob always includes the name of the container they are stored in.","`blobIndexMatch` is incorrect because we do not need to filter on the index of the blobs. We need to apply this policy for all the blobs in the container. Hence we do not use this.","`blobTypes` is incorrect because again we do not need to filter on the type of the blobs. We need to make all the blobs in container1 to move to the archive tier."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-policy-configure?tabs=azure-portal"],"images":["assets/74e46ccd9a67609d.png"],"topic":"identity","needsImage":true},{"id":"1-20","test":1,"number":20,"stem":["An Azure subscription includes the following virtual network configuration:","- VNet1 contains Subnet1, which is associated with NSG1, and is peered with VNet2.","- VNet2 contains Subnet2, which is associated with NSG2, and is peered with VNet1.","The subscription also includes the following virtual machines:","- VM1 is connected to Subnet1.","- VM2 is connected to Subnet2.","In addition, the subscription contains the following Azure App Service web apps:","- WebApp1 uses the Premium pricing tier and has virtual network integration with VNet1.","- WebApp2 uses the Isolated pricing tier and is deployed to Subnet2.","True or False:","`\"WebApp1 can communicate with VM2.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because it has VNet integration enabled with VNet1 which in turn is peered with VNet2. And VM2 is deployed under VNet2. So the communication can be established unless there are explicit NSG inbound rules on subnet2 which we do not know of as per the context given in the question."],"references":["https://learn.microsoft.com/en-us/azure/app-service/configure-vnet-integration-enable","https://learn.microsoft.com/en-us/azure/app-service/overview-vnet-integration#subnet-requirements"],"images":[],"topic":"identity","needsImage":false},{"id":"1-21","test":1,"number":21,"stem":["An Azure subscription includes the following virtual network configuration:","- VNet1 contains Subnet1, which is associated with NSG1, and is peered with VNet2.","- VNet2 contains Subnet2, which is associated with NSG2, and is peered with VNet1.","The subscription also includes the following virtual machines:","- VM1 is connected to Subnet1.","- VM2 is connected to Subnet2.","In addition, the subscription contains the following Azure App Service web apps:","- WebApp1 uses the Premium pricing tier and has virtual network integration with VNet1.","- WebApp2 uses the Isolated pricing tier and is deployed to Subnet2.","True or False:","`\"NSG1 controls inbound traffic to WebApp1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because VNet integration needs a dedicated subnet and NSG1 is attached to Subnet1. And dedicated subnet means it cannot hold any other resource. But VM1 is already deployed to Subnet1 so NSG1 has no control over the traffic reaching to WebApp1."],"references":["https://learn.microsoft.com/en-us/azure/app-service/configure-vnet-integration-enable","https://learn.microsoft.com/en-us/azure/app-service/overview-vnet-integration#subnet-requirements"],"images":[],"topic":"identity","needsImage":false},{"id":"1-22","test":1,"number":22,"stem":["An Azure subscription includes the following virtual network configuration:","- VNet1 contains Subnet1, which is associated with NSG1, and is peered with VNet2.","- VNet2 contains Subnet2, which is associated with NSG2, and is peered with VNet1.","The subscription also includes the following virtual machines:","- VM1 is connected to Subnet1.","- VM2 is connected to Subnet2.","In addition, the subscription contains the following Azure App Service web apps:","- WebApp1 uses the Premium pricing tier and has virtual network integration with VNet1.","- WebApp2 uses the Isolated pricing tier and is deployed to Subnet2.","True or False:","`\"WebApp2 can communicate with VM1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct again because of the isolated APP service environment in which VNet integration is enabled by default. Hence WebApp2 can easily talk to VM1."],"references":["https://learn.microsoft.com/en-us/azure/app-service/configure-vnet-integration-enable","https://learn.microsoft.com/en-us/azure/app-service/overview-vnet-integration#subnet-requirements"],"images":[],"topic":"identity","needsImage":false},{"id":"1-23","test":1,"number":23,"stem":["Your Azure subscription includes an Azure SQL database named DB1.","You plan to use Azure Monitor to collect performance data for DB1. The solution must allow you to run queries against the collected log data for analysis.","Which destination should you select in the Diagnostic settings of DB1 to meet this requirement?"],"options":[{"text":"Archive the logs to an Azure Storage account","correct":false},{"text":"Send the logs to a Log Analytics workspace","correct":true},{"text":"Stream the logs to an Azure Event Hub","correct":false}],"explanation":["`Send the logs to a Log Analytics workspace` is correct because Azure Monitor enables querying and analyzing performance data and logs by sending them to a Log Analytics workspace. This allows you to use Kusto Query Language (KQL) to analyze log data and create visualizations in Azure Monitor Workbooks, meeting the requirement to run queries for analyzing log data.","`Archive the logs to an Azure Storage account` is incorrect because it is designed for long-term storage of diagnostic data. While useful for archiving, it doesn't support querying or analyzing log data directly.","`Stream the logs to an Azure Event Hub` is incorrect because it is used for streaming diagnostics data to external systems for real-time processing or integration, not for querying or analyzing log data."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/logs/log-analytics-workspace-overview","https://learn.microsoft.com/en-us/azure/data-factory/monitor-configure-diagnostics","https://learn.microsoft.com/en-us/azure/active-directory/reports-monitoring/tutorial-azure-monitor-stream-logs-to-event-hub"],"images":[],"topic":"identity","needsImage":false},{"id":"1-24","test":1,"number":24,"stem":["An Azure subscription named Sub1 contains the following resources:","- RG1: Resource group","- storage1: Storage account","- VNET1: Virtual network","You assign an Azure Policy with these characteristics:","- The policy is applied at the Sub1 scope.","- An exclusion is configured for Sub1/RG1/VNET1.","- The policy definition appends a tag and its value to resources.","- Policy enforcement is enabled.","- The tag name is Tag4, and the tag value is value4.","You then apply tags to the resources as follows:","- Sub1 has the tag Tag1: subscription.","- RG1 has the tag Tag2: IT.","- storage1 has the tag Tag3: value1.","- VNET1 has the tag Tag3: value2.","True or False:","`\"RG1 has the Tag2:IT tag assigned only.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct. If you look at the policy, only VNET1 is excluded. (sub1/RG1/VNET1 is just the path). So, when you add the tag Tag2: IT to RG1 manually, the policy won't trigger for the resource group because policies are applicable to resources and not on resource group.","Therefore, RG1 will only have the Tag2:IT tag assigned."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies"],"images":[],"topic":"identity","needsImage":false},{"id":"1-25","test":1,"number":25,"stem":["An Azure subscription named Sub1 contains the following resources:","- RG1: Resource group","- storage1: Storage account","- VNET1: Virtual network","You assign an Azure Policy with these characteristics:","- The policy is applied at the Sub1 scope.","- An exclusion is configured for Sub1/RG1/VNET1.","- The policy definition appends a tag and its value to resources.","- Policy enforcement is enabled.","- The tag name is Tag4, and the tag value is value4.","You then apply tags to the resources as follows:","- Sub1 has the tag Tag1: subscription.","- RG1 has the tag Tag2: IT.","- storage1 has the tag Tag3: value1.","- VNET1 has the tag Tag3: value2.","True or False:","`\"Storage1 has the Tag1:subscription, Tag2:IT, Tag3:value1, and Tag4:value4 tags assigned.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct as Storage1 has Tag3, which was assigned manually, and Tag4 which is assigned by the policy. So it has only 2 tags and not all."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies"],"images":[],"topic":"identity","needsImage":false},{"id":"1-26","test":1,"number":26,"stem":["An Azure subscription named Sub1 contains the following resources:","- RG1: Resource group","- storage1: Storage account","- VNET1: Virtual network","You assign an Azure Policy with these characteristics:","- The policy is applied at the Sub1 scope.","- An exclusion is configured for Sub1/RG1/VNET1.","- The policy definition appends a tag and its value to resources.","- Policy enforcement is enabled.","- The tag name is Tag4, and the tag value is value4.","You then apply tags to the resources as follows:","- Sub1 has the tag Tag1: subscription.","- RG1 has the tag Tag2: IT.","- storage1 has the tag Tag3: value1.","- VNET1 has the tag Tag3: value2.","True or False:","`\"VNET1 has the Tag2:IT and Tag3:value2 tags assigned only.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because VNet1 originally has Tag3: value2 and there will be no action performed on it via policy because of the exclusion mentioned in the policy definition, so there will not be any addition of a tag. Hence it will just have only one tag."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies"],"images":[],"topic":"identity","needsImage":false},{"id":"1-27","test":1,"number":27,"stem":["An Azure subscription is associated with a Microsoft Entra tenant that includes two users named User1 and User2.","The subscription contains the following Azure resources:","- RG1: A resource group","- VM1: A virtual machine that is created in RG1","The subscription also has the following alert rules configured:","- Alert1: Scoped to RG1 and triggered by all administrative operations","- Alert2: Scoped to VM1 and triggered by all administrative operations","The users perform these actions:","- User1 creates a new virtual disk and attaches the disk to VM1.","- User2 creates a new resource tag and assigns the tag to both RG1 and VM1.","Which alert rule is triggered by User1?"],"options":[{"text":"No alert is triggered","correct":false},{"text":"Only Alert1 is triggered","correct":false},{"text":"Only Alert2 is triggered","correct":false},{"text":"Alert1 and Alert2 are triggered","correct":true}],"explanation":["`Alert1 and Alert2 are triggered` is correct because these operations are administrative actions. Basically any create/update/delete operation is logged as an admin action in the Activity log which will then trigger these alerts. And the activity by User1 has create operation in RG1 and update operation in VM1."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/activity-log-schema#administrative-category"],"images":[],"topic":"identity","needsImage":false},{"id":"1-28","test":1,"number":28,"stem":["An Azure subscription is associated with a Microsoft Entra tenant that includes two users named User1 and User2.","The subscription contains the following Azure resources:","- RG1: A resource group","- VM1: A virtual machine that is created in RG1","The subscription also has the following alert rules configured:","- Alert1: Scoped to RG1 and triggered by all administrative operations","- Alert2: Scoped to VM1 and triggered by all administrative operations","The users perform these actions:","- User1 creates a new virtual disk and attaches the disk to VM1.","- User2 creates a new resource tag and assigns the tag to both RG1 and VM1.","Which alert rule is triggered by User2?"],"options":[{"text":"No alert is triggered","correct":false},{"text":"Only Alert1 is triggered","correct":false},{"text":"Only Alert2 is triggered","correct":false},{"text":"Alert1 and Alert2 are triggered","correct":true}],"explanation":["`Alert1 and Alert2 are triggered` is correct because again in this case, assigning the tag is an update operation on the resource itself (RG and VM) as it changes the metadata. So both the alerts will be triggered in this case too."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-types#log-alert"],"images":[],"topic":"identity","needsImage":false},{"id":"1-29","test":1,"number":29,"stem":["An Azure subscription contains the following vault resources:","- Backup1: Backup vault","- Recovery1: Recovery Services vault","You then create a storage account that contains these resources:","- cont1: Blob container","- share1: File share","You need to determine where cont1 can be backed up.","To which vault can you back up cont1?"],"options":[{"text":"Backup1 only","correct":true},{"text":"Recovery1 only","correct":false},{"text":"Backup1 or Recovery1","correct":false},{"text":"Cannot be backed up to Backup1 or Recovery1","correct":false}],"explanation":["`Backup1 only` is correct because Azure blob container can only be backed up in Azure Backup vault as it supports Azure blob storage service. Azure Recovery service vault on the other hand does not support Azure Blob storage."],"references":["https://learn.microsoft.com/en-us/answers/questions/405915/what-is-difference-between-recovery-services-vault"],"images":[],"topic":"identity","needsImage":false},{"id":"1-30","test":1,"number":30,"stem":["An Azure subscription contains the following vault resources:","- Backup1: Backup vault","- Recovery1: Recovery Services vault","You then create a storage account that contains these resources:","- cont1: Blob container","- share1: File share","You need to determine where cont1 can be backed up.","To which vault can you back up share1?"],"options":[{"text":"Backup1 only","correct":false},{"text":"Recovery1 only","correct":true},{"text":"Backup1 or Recovery1","correct":false},{"text":"Cannot be backed up to Backup1 or Recovery1","correct":false}],"explanation":["`Recovery1 only` is correct because Azure file share can only be backed up in Azure RS vault as it supports Azure file share service. Azure Backup vault on the other hand does not support Azure File Share."],"references":["https://learn.microsoft.com/en-us/answers/questions/405915/what-is-difference-between-recovery-services-vault"],"images":[],"topic":"identity","needsImage":false},{"id":"1-31","test":1,"number":31,"stem":["You have multiple Azure virtual machines deployed in a virtual network named VNet1.","You configure an Azure Storage account as shown below. The networking settings restrict public network access to selected virtual networks and subnets, and VNet1 is explicitly added with a service endpoint enabled on a specific subnet. No additional IP address ranges are configured in the firewall section. The network routing preference is set to use Microsoft network routing, and no private endpoints are configured.","Based on the configuration shown, select the option that correctly completes the following statement:","`\"The virtual machines on the 10.2.9.0/24 subnet will have network connectivity to the file shares in the storage account ________________________________.\"`"],"options":[{"text":"always","correct":false},{"text":"during a backup","correct":false},{"text":"never","correct":true}],"explanation":["`Never` is correct.","Public network access is set to \"Enabled from selected virtual networks and IP addresses.\" This means that the storage account can only be accessed from specific virtual networks and IP addresses.","Under Virtual networks, VNet1 is listed with a subnet named Prod (10.2.0.0/24) having an \"Enabled\" endpoint status. This means the storage account permits access only from this specific subnet within VNet1.","The address space of VNet1 is 10.2.0.0/16, but the only associated subnet is 10.2.0.0/24, which includes IP addresses in the range 10.2.0.0 to 10.2.0.255.","The virtual machines on the 10.2.9.0/24 subnet would have IP addresses in the range 10.2.9.0 to 10.2.9.255. This range is outside the defined Prod subnet (10.2.0.0/24).","Since the network connectivity to the storage account is segmented by subnets and not by the entire virtual network, the virtual machines on the 10.2.9.0/24 subnet will not have network connectivity to the file shares in the storage account.","Therefore, the virtual machines on the 10.2.9.0/24 subnet will never have network connectivity to the file shares in the storage account."],"references":["https://azure.microsoft.com/en-us/blog/azure-backup-now-supports-storage-accounts-secured-with-azure-storage-firewalls-and-virtual-networks"],"images":["assets/e94ca477311dc372.png"],"topic":"storage","needsImage":true},{"id":"1-32","test":1,"number":32,"stem":["You have multiple Azure virtual machines deployed in a virtual network named VNet1.","You configure an Azure Storage account as shown below. The networking settings restrict public network access to selected virtual networks and subnets, and VNet1 is explicitly added with a service endpoint enabled on a specific subnet. No additional IP address ranges are configured in the firewall section. The network routing preference is set to use Microsoft network routing, and no private endpoints are configured.","Based on the configuration shown, select the option that correctly completes the following statement:","`\"Azure Backup will be able to back up the unmanaged disks of the virtual machines in the storage account ________________________________.\"`"],"options":[{"text":"always","correct":false},{"text":"during a backup","correct":false},{"text":"never","correct":true}],"explanation":["`Never` is the correct answer because if you enable Virtual network in the firewall setting, you need to select the option at the bottom - Allow Azure services on the trusted services list to access this storage account and enable it. Otherwise the access will be limited to the resources in the VNet only."],"references":["https://azure.microsoft.com/en-us/blog/azure-backup-now-supports-storage-accounts-secured-with-azure-storage-firewalls-and-virtual-networks"],"images":["assets/e94ca477311dc372.png"],"topic":"storage","needsImage":true},{"id":"1-33","test":1,"number":33,"stem":["An Azure subscription includes a storage account named storageaccount1. The storage account has the following lifecycle management rules configured:","On June 1, you upload the following blobs to storageaccount1:","- File1 is stored in container1 and uses the Hot access tier.","- File2 is stored in container2 and uses the Hot access tier.","True or False:**","`\"On June 6, File1 will be stored in the Cool access tier.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because once the file1 is moved to archive after 3 days, the modified date time remains the same. Which means, after 5+ days for Rule 2, it will not be able to move it back to cool tier from archive, as it needs to be rehydrated which cannot be done via a policy."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/archive-rehydrate-overview"],"images":["assets/be660e91107b617f.png"],"topic":"identity","needsImage":true},{"id":"1-34","test":1,"number":34,"stem":["An Azure subscription includes a storage account named storageaccount1. The storage account has the following lifecycle management rules configured:","On June 1, you upload the following blobs to storageaccount1:","- File1 is stored in container1 and uses the Hot access tier.","- File2 is stored in container2 and uses the Hot access tier.","True or False:**","`\"On June 1, File2 will be stored in the Cool access tier.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because Rule3 states that blobs in container2/ older than 10 days will be deleted, and Rule4 moves blobs older than 15 days to archive storage. File2, added on June 1, does not meet the conditions for any lifecycle management rule to trigger. Therefore, it remains in the Hot tier, and no rule moves it to the Cool tier.","Reference(s):**","- https://learn.microsoft.com/en-us/azure/storage/blobs/archive-rehydrate-overview"],"references":[],"images":["assets/be660e91107b617f.png"],"topic":"identity","needsImage":true},{"id":"1-35","test":1,"number":35,"stem":["An Azure subscription includes a storage account named storageaccount1. The storage account has the following lifecycle management rules configured:","On June 1, you upload the following blobs to storageaccount1:","- File1 is stored in container1 and uses the Hot access tier.","- File2 is stored in container2 and uses the Hot access tier.","True or False:**","`\"On June 16, File2 will be stored in the Archive access tier.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because after 10 days, rule3 deletes the file2 and hence it will not be available to be put to archive tier after 15 days by rule4."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/archive-rehydrate-overview"],"images":["assets/be660e91107b617f.png"],"topic":"identity","needsImage":true},{"id":"1-36","test":1,"number":36,"stem":["An Azure subscription contains an Azure Storage account named storageaccount1.","You export storageaccount1 as an Azure Resource Manager (ARM) template. The exported template defines the storage account type, location, SKU, encryption settings, access tier, and network access configuration. The network rules allow access by default and include a bypass for Azure services, with no virtual network rules or IP address restrictions specified.","{","\"type\": \"Microsoft.Storage/storageAccount\",","\"apiVersion\": \"2019-06-01\",","\"name\": \"storageaccount1\",","\"location\": \"eastus\",","\"sku\": {","\"name\": \"Standard_LRS\",","\"tier\": \"Standard\"","},","\"kind\": \"StorageV2\",","\"properties\": {","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"virtualNetworkRules\": [],","\"ipRules\": [],","\"defaultAction\": \"Allow\"","},","\"supportsHttpsTrafficOnly\": true,","\"encryption\": {","\"services\": {","\"file\": {","\"keyType\": \"Account\",","\"enabled\": true","},","\"blob\": {","\"keyType\": \"Account\",","\"enabled\": true","}","}","},","\"keySource\": \"Microsoft.Storage\"","},","\"accessTier\": \"Hot\"","}","True or False:","`\"A server with the public IP address of 131.107.103.10 can access storageaccount1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because default action is set to allow for Network ACLs. So any server on the public internet can access the storage account if it has the access keys.","A note about the `bypass` setting in the Network ACL:**","The `bypass` setting is used to allow trusted Azure services to access the storage account even when network rules restrict other traffic. For example, services like Azure Backup, Azure Site Recovery, or Azure Monitor often need access to storage accounts. When the `bypass` value includes `AzureServices`, these trusted services can bypass the firewall restrictions if the `defaultAction` is set to Deny.","In this case:","- The `defaultAction` is set to `Allow`, meaning all IPs (including public IPs) are currently allowed by default.","- The `bypass` setting is irrelevant in this situation because access isn’t restricted to begin with.","- If `defaultAction` were set to `Deny`, then the `bypass: AzureServices` would ensure that trusted Azure services can still reach the storage account — but not general users or applications, even if they are Azure-joined."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","https://learn.microsoft.com/en-us/azure/well-architected/service-guides/storage-accounts/security"],"images":[],"topic":"identity","needsImage":false},{"id":"1-37","test":1,"number":37,"stem":["An Azure subscription contains an Azure Storage account named storageaccount1.","You export storageaccount1 as an Azure Resource Manager (ARM) template. The exported template defines the storage account type, location, SKU, encryption settings, access tier, and network access configuration. The network rules allow access by default and include a bypass for Azure services, with no virtual network rules or IP address restrictions specified.","{","\"type\": \"Microsoft.Storage/storageAccount\",","\"apiVersion\": \"2019-06-01\",","\"name\": \"storageaccount1\",","\"location\": \"eastus\",","\"sku\": {","\"name\": \"Standard_LRS\",","\"tier\": \"Standard\"","},","\"kind\": \"StorageV2\",","\"properties\": {","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"virtualNetworkRules\": [],","\"ipRules\": [],","\"defaultAction\": \"Allow\"","},","\"supportsHttpsTrafficOnly\": true,","\"encryption\": {","\"services\": {","\"file\": {","\"keyType\": \"Account\",","\"enabled\": true","},","\"blob\": {","\"keyType\": \"Account\",","\"enabled\": true","}","}","},","\"keySource\": \"Microsoft.Storage\"","},","\"accessTier\": \"Hot\"","}","True or False:","`\"Individual blobs in storageaccount1 can be set to use the archive tier.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because this storage account is of type StandardV2 which supports blob-level tiering. So individual blob can have different tiers."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","https://learn.microsoft.com/en-us/azure/well-architected/service-guides/storage-accounts/security"],"images":[],"topic":"identity","needsImage":false},{"id":"1-38","test":1,"number":38,"stem":["An Azure subscription contains an Azure Storage account named storageaccount1.","You export storageaccount1 as an Azure Resource Manager (ARM) template. The exported template defines the storage account type, location, SKU, encryption settings, access tier, and network access configuration. The network rules allow access by default and include a bypass for Azure services, with no virtual network rules or IP address restrictions specified.","{","\"type\": \"Microsoft.Storage/storageAccount\",","\"apiVersion\": \"2019-06-01\",","\"name\": \"storageaccount1\",","\"location\": \"eastus\",","\"sku\": {","\"name\": \"Standard_LRS\",","\"tier\": \"Standard\"","},","\"kind\": \"StorageV2\",","\"properties\": {","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"virtualNetworkRules\": [],","\"ipRules\": [],","\"defaultAction\": \"Allow\"","},","\"supportsHttpsTrafficOnly\": true,","\"encryption\": {","\"services\": {","\"file\": {","\"keyType\": \"Account\",","\"enabled\": true","},","\"blob\": {","\"keyType\": \"Account\",","\"enabled\": true","}","}","},","\"keySource\": \"Microsoft.Storage\"","},","\"accessTier\": \"Hot\"","}","True or False:","`\"Global administrators can access a file share hosted in storageaccount1 by using their Microsoft Entra credentials.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because we do not know if the user has been added to the storage account IAM for data access. Simply having the role of Global Admin does not allow the user access to file share data."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","https://learn.microsoft.com/en-us/azure/well-architected/service-guides/storage-accounts/security"],"images":[],"topic":"identity","needsImage":false},{"id":"1-39","test":1,"number":39,"stem":["You manage a Microsoft Entra tenant.","You need to modify the Default user role permissions to meet the following requirements:","- Standard users must not be able to create new service principals.","- Standard users must be limited to using PowerShell or Microsoft Graph when managing their own Azure resources.","The current Default user role permissions settings are configured as follows:","User permissions","- `Setting 1`: Users can register applications: Yes","- `Setting 2`: Restrict non-admin users from creating tenants: No","- `Setting 3`: Users can create security groups: Yes","Guest user access","- `Setting 4`:Guest user access restrictions: Guest users have limited access to properties and memberships of directory objects","Administration center","- `Setting 5`: Restrict access to Microsoft Entra admin center: No","Session settings","- `Setting 6`: Show keep user signed in: Yes","Based on the requirements and the current configuration, which two settings should you modify?"],"options":[{"text":"1","correct":true},{"text":"2","correct":false},{"text":"3","correct":false},{"text":"4","correct":false},{"text":"5","correct":true},{"text":"6","correct":false}],"explanation":["`1` is correct because this setting enables the users to register an application in Microsoft Entra from which a service principal can be created. So in order to prevent this, this setting needs to be turned off.","`5` is correct because this setting, if turned on, will not allow non-admin users to access Microsoft Entra admin portal, and hence not allow them to manage their resources from it. So the only way those users can manage their resources are via Powershell, CLI or Microsoft graph API (for Microsoft Entra objects)."],"references":["https://learn.microsoft.com/en-us/azure/active-directory/fundamentals/users-default-permissions"],"images":[],"topic":"identity","needsImage":false},{"id":"1-40","test":1,"number":40,"stem":["An Azure subscription contains a storage account named contoso2024. The storage account includes the following resources:","- cont1: Blob container","- share1: File share","The contoso2024 storage account is configured with the settings shown below. The configuration defines the account kind, performance tier, security and access options, minimum TLS version, copy scope, and the default blob access tier.","You also have a Microsoft Entra tenant with the following users, each assigned a Shared Access Signature (SAS) token for contoso2024:","True or False:","`\"User1 can access content in cont1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User1 has a User Delegation SAS, which does not rely on the storage account keys. In this storage account, the setting Allow storage account key access is disabled, meaning that any SAS signed with the account keys (such as an Account SAS or a Service SAS) cannot be used. However, a User Delegation SAS is signed with a user delegation key that is derived from the user’s Microsoft Entra ID credentials, not from the storage account keys. This makes it valid and usable even when key access is disabled.","The Secure transfer required setting enforces that all connections must use HTTPS, but it is not the determining factor in this scenario because a User Delegation SAS already generates HTTPS URLs by default. Therefore, the reason User1 can access content in cont1 is specifically due to the use of a User Delegation SAS, which remains supported under the current configuration."],"references":["https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/create-account-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/authorize-with-shared-key"],"images":["assets/7d56d84dfc7fe8d0.png","assets/71562634e9c7b2ac.png"],"topic":"identity","needsImage":true},{"id":"1-41","test":1,"number":41,"stem":["An Azure subscription contains a storage account named contoso2024. The storage account includes the following resources:","- cont1: Blob container","- share1: File share","The contoso2024 storage account is configured with the settings shown below. The configuration defines the account kind, performance tier, security and access options, minimum TLS version, copy scope, and the default blob access tier.","You also have a Microsoft Entra tenant with the following users, each assigned a Shared Access Signature (SAS) token for contoso2024:","True or False:","`\"User2 can access content in cont1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct. User2 cannot access content in cont1 because the storage account contoso2024 has \"Allow storage account key access\" set to Disabled. This setting prevents any requests that rely on shared key authorization, including those using Service SAS tokens.","Although User2 has a Service SAS token with maximum available permissions, Service SAS tokens are signed using the storage account key. When shared key access is disabled, these SAS tokens become invalid, regardless of their permissions."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/shared-key-authorization-prevent?tabs=portal#understand-how-disallowing-shared-key-affects-sas-tokens","https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/create-account-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/authorize-with-shared-key"],"images":["assets/7d56d84dfc7fe8d0.png","assets/71562634e9c7b2ac.png"],"topic":"identity","needsImage":true},{"id":"1-42","test":1,"number":42,"stem":["An Azure subscription contains a storage account named contoso2024. The storage account includes the following resources:","- cont1: Blob container","- share1: File share","The contoso2024 storage account is configured with the settings shown below. The configuration defines the account kind, performance tier, security and access options, minimum TLS version, copy scope, and the default blob access tier.","You also have a Microsoft Entra tenant with the following users, each assigned a Shared Access Signature (SAS) token for contoso2024:","True or False:","`\"User3 can access content in share1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because because Key access on the storage account is disabled for this storage account. Hence no matter if the user has account-level SAS key, it cannot access the content."],"references":["https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/create-account-sas","https://learn.microsoft.com/en-us/rest/api/storageservices/authorize-with-shared-key"],"images":["assets/7d56d84dfc7fe8d0.png","assets/71562634e9c7b2ac.png"],"topic":"identity","needsImage":true},{"id":"1-43","test":1,"number":43,"stem":["An Azure subscription contains 10 virtual machines and the following resources:","You must ensure that Bastion1 can support 100 simultaneous SSH connections. The solution should require the least possible administrative effort.","What action should you take first?"],"options":[{"text":"Configure scaling for the Bastion host.","correct":false},{"text":"Upgrade Bastion1 to the standard SKU.","correct":true},{"text":"Create and associate a network security group (NSG).","correct":false},{"text":"Resize the subnet of Bastion1.","correct":false}],"explanation":["`Upgrade Bastion1 to the standard SKU` is correct because with Basic SKU, only 2 instances can be created. And each instance supports upto 40 SSH concurrent users. Hence in order to support 10 sessions, we need to upgrade the SKU of the Bastion service to Standard which allows to define the number of instances you need. We need at least 3 instances in this case.","`Configure scaling for the Bastion host` is incorrect because this is only supported in Standard SKU of the Bastion service. Since the service is of type Basic, we first need to upgrade it to Standard.","`Create and associate a network security group (NSG)` is incorrect because an NSG only has rules for Inbound and Outbound traffic. It cannot help in configuring concurrent SSH sessions for Bastion service. For that you need to have multiple instances of the service running parallely,","`Resize the subnet of Bastion1` is incorrect because the size of the subnet does not matter here. For concurrent sessions, users can use the same machine to connect to backend VMs, so subnet does not need to have 100 IP addresses available."],"references":["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings"],"images":["assets/777e141446b16921.png"],"topic":"identity","needsImage":true},{"id":"1-44","test":1,"number":44,"stem":["You have an Azure App Service app named App1 that is currently running two instances.","You configure an autoscale rule as shown below. The rule monitors the Memory Percentage metric across all instances, evaluates the average memory usage at a one-minute time grain, and triggers a scale-out action when the defined threshold is exceeded for a specified duration. When the condition is met, the rule increases the instance count by one and applies a cooldown period before another scale action can occur.","For the Instance limits scale condition, the Maximum number of instances is set to 5.","Over a continuous 30-minute period, App1 uses 80 percent of the available memory.","What is the maximum number of instances that App1 can reach during the 30-minute period?"],"options":[{"text":"2","correct":false},{"text":"3","correct":false},{"text":"4","correct":false},{"text":"5","correct":true}],"explanation":["`5` is correct because it starts with 2 instances. After the first 15 min, it increases the count by 1 instance. The new count is 3 after 15 minutes. 5 minutes is the cool down period in which no scaling happens. After these 5 minutes, at 20 minutes past the starting point, the scaling happens again since the Memory percentage is still more than 70%. Similarly after 25 min, there will be one more increase in the instance count. Total count at this point is 5. So after the next 5 minutes (making it 30 minutes), it cannot increase the count anymore because the max instance count is set to 5. So the final count will remain 5 after 30 minutes."],"references":[],"images":["assets/15895f6a8126c905.png"],"topic":"compute","needsImage":true},{"id":"1-45","test":1,"number":45,"stem":["You have an Azure subscription.","You create an Azure Resource Manager (ARM) template file named deploy.json. The template defines a StorageV2 storage account that uses a Premium_LRS SKU. The resource name is generated dynamically by combining an index value with a unique string, and the template uses a copy loop to deploy multiple instances of the storage account.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {","\"location\": {","\"type\": \"string\",","\"defaultValue\": \"westus\"","}","},","\"resources\": [","{","\"apiVersion\": \"2019-04-01\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"name\": \"[concat(copyIndex(), 'storage', uniqueString(resourceGroup().id))]\",","\"location\": \"[resourceGroup().location]\",","\"sku\": {","\"name\": \"Premium_LRS\"","},","\"kind\": \"StorageV2\",","\"properties\": {},","\"copy\": {","\"name\": \"storagecopy\",","\"count\": 3","}","}","]","}","You then connect to the subscription and run the following commands.","- New-AZResourceGroup -Name RG1 -Location “centralus”","- New-AZResourceGroupDeployment -ResourceGroupName RG1 -TemplateFile “deploy.json”","True or False:","`\"The commands will create four new resources.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because the first command creates a resource group, and the second command creates three storage accounts in the previously created resource group. Hence it total creates 4 resources.","Note: A resource group is also a resource."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/overview","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources#resource-iteration"],"images":[],"topic":"identity","needsImage":false},{"id":"1-46","test":1,"number":46,"stem":["You have an Azure subscription.","You create an Azure Resource Manager (ARM) template file named deploy.json. The template defines a StorageV2 storage account that uses a Premium_LRS SKU. The resource name is generated dynamically by combining an index value with a unique string, and the template uses a copy loop to deploy multiple instances of the storage account.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {","\"location\": {","\"type\": \"string\",","\"defaultValue\": \"westus\"","}","},","\"resources\": [","{","\"apiVersion\": \"2019-04-01\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"name\": \"[concat(copyIndex(), 'storage', uniqueString(resourceGroup().id))]\",","\"location\": \"[resourceGroup().location]\",","\"sku\": {","\"name\": \"Premium_LRS\"","},","\"kind\": \"StorageV2\",","\"properties\": {},","\"copy\": {","\"name\": \"storagecopy\",","\"count\": 3","}","}","]","}","You then connect to the subscription and run the following commands.","- New-AZResourceGroup -Name RG1 -Location “centralus”","- New-AZResourceGroupDeployment -ResourceGroupName RG1 -TemplateFile “deploy.json”","True or False:","`\"The commands will create storage accounts in the West US Azure region.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the storage accounts are created in the location of the resource group which is Central US.","NOTE: If the `location` value in the template uses:","- `[parameters('location')]`: the resource gets deployed to the location provided in the parameter (`westus` in this case).","- `[resourceGroup().location]`: the resource inherits the region from the resource group, regardless of the parameter."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/overview","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources#resource-iteration"],"images":[],"topic":"identity","needsImage":false},{"id":"1-47","test":1,"number":47,"stem":["You have an Azure subscription.","You create an Azure Resource Manager (ARM) template file named deploy.json. The template defines a StorageV2 storage account that uses a Premium_LRS SKU. The resource name is generated dynamically by combining an index value with a unique string, and the template uses a copy loop to deploy multiple instances of the storage account.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {","\"location\": {","\"type\": \"string\",","\"defaultValue\": \"westus\"","}","},","\"resources\": [","{","\"apiVersion\": \"2019-04-01\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"name\": \"[concat(copyIndex(), 'storage', uniqueString(resourceGroup().id))]\",","\"location\": \"[resourceGroup().location]\",","\"sku\": {","\"name\": \"Premium_LRS\"","},","\"kind\": \"StorageV2\",","\"properties\": {},","\"copy\": {","\"name\": \"storagecopy\",","\"count\": 3","}","}","]","}","You then connect to the subscription and run the following commands.","- New-AZResourceGroup -Name RG1 -Location “centralus”","- New-AZResourceGroupDeployment -ResourceGroupName RG1 -TemplateFile “deploy.json”","True or False:","`\"The first storage account that is created will have a prefix of 0.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because there is a copy loop running in the template which deploys three count of storage account. And the indexing of this loop, like any other programming language, starts with 0."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/overview","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources#resource-iteration"],"images":[],"topic":"identity","needsImage":false},{"id":"1-48","test":1,"number":48,"stem":["You manage a Microsoft Entra tenant.","You need to create a Microsoft 365 group that dynamically includes only users who belong to the finance department and are located in US.","To accomplish this, you must complete the dynamic membership rule shown below. The rule evaluates a user attribute for department membership and combines it with a country-based condition.","What should you choose for `Code Segment A`?"],"options":[{"text":"device.managementType","correct":false},{"text":"device.organizationalUnit","correct":false},{"text":"user.department","correct":true},{"text":"user.usageLocation","correct":false}],"explanation":["`user.department` is correct because the requirement is to create a group that contains members from a specific department, in this case, the finance department. The user.department attribute in dynamic membership rules is used to filter users based on their department property."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership"],"images":["assets/ff58f41cc084f0d0.png"],"topic":"identity","needsImage":true},{"id":"1-49","test":1,"number":49,"stem":["You manage a Microsoft Entra tenant.","You need to create a Microsoft 365 group that dynamically includes only users who belong to the finance department and are located in US.","To accomplish this, you must complete the dynamic membership rule shown below. The rule evaluates a user attribute for department membership and combines it with a country-based condition.","What should you choose for `Code Segment B`?"],"options":[{"text":"and","correct":true},{"text":"or","correct":false},{"text":"typeof","correct":false}],"explanation":["`and` is correct because you want to include users who meet both criteria: being in the finance department and being located in US. Using \"and\" ensures that both conditions must be true for a user to be included in the dynamic membership."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership"],"images":["assets/ff58f41cc084f0d0.png"],"topic":"identity","needsImage":true},{"id":"1-50","test":1,"number":50,"stem":["You manage a Microsoft Entra tenant.","You need to create a Microsoft 365 group that dynamically includes only users who belong to the finance department and are located in US.","To accomplish this, you must complete the dynamic membership rule shown below. The rule evaluates a user attribute for department membership and combines it with a country-based condition.","What should you choose for `Code Segment C`?"],"options":[{"text":"-and","correct":false},{"text":"-eq","correct":true},{"text":"-in","correct":false},{"text":"-match","correct":false}],"explanation":["`-eq` is correct because the goal is to specify a condition where the attribute (in this case, the country) is equal to a specific value, \"US\". The operator -eq stands for \"equals\" and is used in dynamic membership rules to match exact attribute values."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership"],"images":["assets/ff58f41cc084f0d0.png"],"topic":"identity","needsImage":true},{"id":"1-51","test":1,"number":51,"stem":["You have an Azure subscription that includes a storage account named storageacct1234 and two users named User1 and User2.","You assign User1 the role assignments shown below. The assignments indicate that User1 has a Reader role inherited from the resource group scope and a Storage Blob Data Contributor role assigned directly at the storage account level.","Based on these role assignments, which two actions can User1 perform?"],"options":[{"text":"Assign roles to User2 for storageacct1234.","correct":false},{"text":"Upload blob data to storageacct1234.","correct":true},{"text":"Modify the firewall of storageacct1234.","correct":false},{"text":"View blob data in storageacct1234.","correct":true},{"text":"View file shares in storageacct1234.","correct":false}],"explanation":["`Upload blob data to storageacct1234` is correct because the Storage Blob Data Contributor role is a data-plane role that allows read, write, and delete operations on blob containers and blobs within the storage account.","`View blob data in storageacct1234` is correct because the ability to read blob content is granted by the Storage Blob Data Contributor role. The Reader role alone does not provide data access, but it allows viewing the storage account resource itself in the Azure portal.**","`Assign roles to User2 for storageacct1234` is incorrect because assigning RBAC roles requires Owner or User Access Administrator permissions. Neither the Reader role nor the Storage Blob Data Contributor role includes authorization to assign roles.**","`Modify the firewall of storageacct1234` is incorrect because changing networking or firewall settings is a management-plane operation that requires Contributor, Owner, or specific networking permissions. The Reader role is read-only, and the Storage Blob Data Contributor role applies only to blob data access.**","`View file shares in storageacct1234` is incorrect because Azure Files access is controlled by separate data-plane roles such as Storage File Data SMB Share Reader or Storage File Data SMB Share Contributor. The Storage Blob Data Contributor role applies only to blob storage and does not grant access to file shares."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":["assets/6164bcad76c25f11.png"],"topic":"identity","needsImage":true},{"id":"1-52","test":1,"number":52,"stem":["You have an Azure subscription that includes the following virtual networks:","The subscription also contains the following virtual machines:","Each virtual machine has only a private IP address assigned.","You then deploy an Azure Bastion resource with the following configuration:","True or False:","`\"The Remote Desktop Connection client (mstsc.exe) can be used to connect to VM1 through Bastion1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct. The Remote Desktop Connection client (`mstsc.exe`) cannot be used to connect to VM1 through Bastion1 because Bastion1 is deployed using the Basic SKU, and the Basic SKU does not support native client access. Native client access refers to using external tools such as `mstsc.exe` or SSH from a local terminal, rather than the Azure portal's browser-based Bastion session.","To use `mstsc.exe` for RDP access to a virtual machine through Azure Bastion, you must deploy Azure Bastion with the Standard SKU, and explicitly enable the “Native client support” feature. Since the Bastion instance in this scenario uses the Basic tier, the native client feature is not available, and RDP access is only possible through the Azure portal."],"references":["https://learn.microsoft.com/en-us/azure/bastion/native-client","https://learn.microsoft.com/en-us/azure/bastion/configuration-settings#skus","https://learn.microsoft.com/en-us/azure/bastion/bastion-overview"],"images":["assets/b3af504ee146775b.png","assets/55f9bff09b3eac44.png","assets/99333c5bf2324b37.png"],"topic":"identity","needsImage":true},{"id":"1-53","test":1,"number":53,"stem":["You have an Azure subscription that includes the following virtual networks:","The subscription also contains the following virtual machines:","Each virtual machine has only a private IP address assigned.","You then deploy an Azure Bastion resource with the following configuration:","True or False:","`\"The Azure portal can use SSH to connect to VM2 through Bastion1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because Bastion1 is deployed in VNet1 using the Basic SKU, which supports RDP for Windows VMs and SSH for Linux VMs through the Azure portal’s browser-based session. VM2 is a Linux VM located in VNet2, and since VNet2 is directly peered with VNet1, Bastion1 can be used to establish an SSH session from the portal. The Basic SKU limitation only applies to native client support (mstsc.exe or ssh.exe), which requires the Standard SKU. Since the question specifically states “Azure portal”, SSH through the portal is fully supported."],"references":["https://learn.microsoft.com/en-us/azure/bastion/native-client#deploy-bastion-with-the-native-client-feature","https://learn.microsoft.com/en-us/azure/bastion/configuration-settings#skus"],"images":["assets/b3af504ee146775b.png","assets/883d4bb5c727dbf8.png","assets/99333c5bf2324b37.png"],"topic":"identity","needsImage":true},{"id":"1-54","test":1,"number":54,"stem":["You have an Azure subscription that includes the following virtual networks:","The subscription also contains the following virtual machines:","Each virtual machine has only a private IP address assigned.","You then deploy an Azure Bastion resource with the following configuration:","True or False:","`\"The Azure portal can be used to connect to VM3 through Bastion1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because there is no direct connection between VNet1 in which Bastion1 is and VNet3. Hence the connection from Bastion1 will not be possible to VM3."],"references":["https://learn.microsoft.com/en-us/azure/bastion/native-client#deploy-bastion-with-the-native-client-feature","https://learn.microsoft.com/en-us/azure/bastion/configuration-settings#skus"],"images":["assets/b3af504ee146775b.png","assets/55f9bff09b3eac44.png","assets/99333c5bf2324b37.png"],"topic":"identity","needsImage":true},{"id":"1-55","test":1,"number":55,"stem":["You have an Azure subscription that contains an Azure container registry named ShireenReg1.","You enable the Admin user for ShireenReg1.","After enabling the Admin user, you want to sign in directly to the container registry.","Which username can you use to sign in to ShireenReg1?"],"options":[{"text":"root","correct":false},{"text":"admin","correct":false},{"text":"administrator","correct":false},{"text":"ShireenReg1","correct":true}],"explanation":["ShireenReg1 is correct because when you enable the admin user for an Azure container registry, Azure provides the registry name itself as the username. This means you can use the container registry's name (in this case, \"ShireenReg1\") as the username, along with the admin user access key as the password, to log in."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication?tabs=azure-cli","https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-azure-cli"],"images":[],"topic":"identity","needsImage":false},{"id":"1-56","test":1,"number":56,"stem":["You have an Azure Storage account named contoso2024 that contains the following resources:","- container1: a blob container that stores File1","- share1: an Azure File share that stores File2","You have the following users and permissions assigned for contoso2024:","- User1: Reader role","- User2: Storage Account Contributor role","- User3: Has an access key for contoso2024","The storage account contoso2024 is configured with secure transfer enabled, public blob access enabled, storage account key access disabled, and Azure Active Directory authorization disabled in the Azure portal.","True or False:","`\"User1 can read File1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because Reader role gives you access to read the metadata and configuration of the storage account (on the service-level). It does not give you read access to the content of blob storage. Hence User1 cannot read File1.","Note: While \"Allow Blob public access\" is enabled at the storage account level, this only means that public access is permitted if the individual container is configured to allow it (such as \"container\" or \"blob\" level anonymous access). However, unless the container is explicitly set to public access (which is not indicated in the question), anonymous users cannot access the blob data. In this scenario, User1 has only the Reader role (control plane access) and no data plane permissions, and we have no information that public access is configured on the container. Therefore, User1 cannot read File1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"],"images":["assets/71b0b3a000ea0921.png"],"topic":"identity","needsImage":true},{"id":"1-57","test":1,"number":57,"stem":["You have an Azure Storage account named contoso2024 that contains the following resources:","- container1: a blob container that stores File1","- share1: an Azure File share that stores File2","You have the following users and permissions assigned for contoso2024:","- User1: Reader role","- User2: Storage Account Contributor role","- User3: Has an access key for contoso2024","The storage account contoso2024 is configured with secure transfer enabled, public blob access enabled, storage account key access disabled, and Azure Active Directory authorization disabled in the Azure portal.","True or False:","`\"User2 can read File2.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the Storage Account Contributor role has all the permissions to manage a storage account, but not access to it. Along with it, it does not have the access to read data from any of the storage services be it blob or fileshares. But it does have access to Access-keys, from which the data can be read. However in the configuration we see that the Storage Account key access has been disabled. So User2 cannot read file2."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"],"images":["assets/71b0b3a000ea0921.png"],"topic":"identity","needsImage":true},{"id":"1-58","test":1,"number":58,"stem":["You have an Azure Storage account named contoso2024 that contains the following resources:","- container1: a blob container that stores File1","- share1: an Azure File share that stores File2","You have the following users and permissions assigned for contoso2024:","- User1: Reader role","- User2: Storage Account Contributor role","- User3: Has an access key for contoso2024","The storage account contoso2024 is configured with secure transfer enabled, public blob access enabled, storage account key access disabled, and Azure Active Directory authorization disabled in the Azure portal.","True or False:","`\"User3 can read File1 and File2.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because access to Storage account via Access Keys has been disabled. So User3 cannot do anything in the storage account."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"],"images":["assets/71b0b3a000ea0921.png"],"topic":"identity","needsImage":true},{"id":"1-59","test":1,"number":59,"stem":["You create a virtual machine scale set named Scale1.","During deployment, Scale1 is configured with custom autoscaling settings, as shown in the exhibit. The configuration specifies an initial number of instances, minimum and maximum instance limits, and CPU-based scale-out and scale-in rules. In particular, the scale-out rule increases the instance count when average CPU usage exceeds the defined threshold for a specified duration.","Based on the autoscaling configuration shown in the exhibit, complete the following statement:","`“If Scale1 is utilized at 85 percent for six minutes after it is deployed, Scale1 will be running _______________.”`"],"options":[{"text":"2 virtual machines","correct":false},{"text":"4 virtual machines","correct":false},{"text":"6 virtual machines","correct":true},{"text":"10 virtual machines","correct":false},{"text":"20 virtual machines","correct":false}],"explanation":["`6 virtual machines` is the correct option because the virtual machine scale set (VMSS) is configured to scale out when CPU utilization exceeds 80% for 5 minutes. In this case:","- The initial number of VMs is 4.","- When the CPU usage crosses 80% for 6 minutes (exceeding the configured threshold of 5 minutes), 2 additional VMs will be added.","- Therefore, the total number of VMs becomes 4 + 2 = 6 VMs.","**Reference(s):","- https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-best-practices","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview"],"references":[],"images":["assets/d1644a43a1c87705.png"],"topic":"compute","needsImage":true},{"id":"1-60","test":1,"number":60,"stem":["You create a virtual machine scale set named Scale1.","During deployment, Scale1 is configured with custom autoscaling settings, as shown in the exhibit. The configuration specifies an initial number of instances, minimum and maximum instance limits, and CPU-based scale-out and scale-in rules. In particular, the scale-out rule increases the instance count when average CPU usage exceeds the defined threshold for a specified duration.","Based on the autoscaling configuration shown in the exhibit, complete the following statement:","`“If Scale1 is first utilized at 25 percent for six minutes after it is deployed, and then utilized at 50 percent for six minutes, Scale1 will be running _______________.”`"],"options":[{"text":"2 virtual machines","correct":true},{"text":"4 virtual machines","correct":false},{"text":"6 virtual machines","correct":false},{"text":"10 virtual machines","correct":false},{"text":"20 virtual machines","correct":false}],"explanation":["`2 virtual machines` is the correct answer because the Azure Virtual Machine Scale Set (VMSS) configuration specifies:","- Initial instance count: 4","- Minimum number of VMs: 2","- Scale-in threshold: CPU usage below 30% triggers a reduction of 4 VMs","In the given scenario:","- The CPU utilization drops to 25% and stays at this level for 6 minutes.","- This satisfies the scale-in policy, which reduces the number of VMs by 4.","- However, the minimum VM threshold is set to 2, and a scale set cannot scale below the configured minimum limit.","As a result, Scale1 will be running 2 virtual machines after the scale-in process completes."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-best-practices","https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview"],"images":["assets/d1644a43a1c87705.png"],"topic":"compute","needsImage":true},{"id":"1-61","test":1,"number":61,"stem":["You have an Azure App Service plan configured with autoscaling. In the autoscale configuration, the plan uses metric-based scaling with defined scale-out and scale-in rules. The instance limits specify a minimum, maximum, and default number of instances. Scale-out occurs when CPU usage exceeds a configured threshold, and scale-in occurs when","The scale-in settings for the App Service plan are configured as shown in the following exhibit.","The scale out rule is configured with the same duration and cool down tile as the scale in rule.","Based on the information presented, select the answer choice that completes the following statement correctly.","`“If after deployment CPU usage is 70 percent for one hour and then reaches 90 percent for five minutes, at that time the total number of instances will be ________.”`"],"options":[{"text":"1","correct":false},{"text":"2","correct":true},{"text":"3","correct":false},{"text":"4","correct":false},{"text":"5","correct":false}],"explanation":["`2` is the correct answer because the scaling conditions are set as follows:","- Scale-out condition: When CPU usage exceeds 85%, the instance count increases by 1.","- Scale-in condition: When CPU usage drops below 30%, the instance count decreases by 1.","- Instance limits: Minimum = 1, Maximum = **5","- Initial State: The default instance count starts at 1.","- First Condition (70% for one hour): This does not trigger a scale-out because it doesn’t exceed the 85% threshold. The instance count remains at 1.","- Second Condition (90% for 5 minutes): This exceeds the 85% threshold, triggering a scale-out by 1 instance.","As a result, after these events, the total number of instances will increase from 1 to 2.","**Reference(s):","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-common-scale-patterns","- https://learn.microsoft.com/en-us/previous-versions/azure/azure-monitor/autoscale/tutorial-autoscale-performance-schedule"],"references":[],"images":["assets/4cb0b4541117adca.png","assets/8673e0ad3f7277fe.png"],"topic":"compute","needsImage":true},{"id":"1-62","test":1,"number":62,"stem":["You have an Azure App Service plan configured with autoscaling. In the autoscale configuration, the plan uses metric-based scaling with defined scale-out and scale-in rules. The instance limits specify a minimum, maximum, and default number of instances. Scale-out occurs when CPU usage exceeds a configured threshold, and scale-in occurs when","The scale-in settings for the App Service plan are configured as shown in the following exhibit.","The scale out rule is configured with the same duration and cool down tile as the scale in rule.","Based on the information presented, select the answer choice that completes the following statement correctly.","`“If after deployment the CPU maintains constant usage of 90 percent for one hour, and then the average CPU usage is below 25 percent for nine minutes, at that point the number of instances will be ___________.”`"],"options":[{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":false},{"text":"4","correct":true},{"text":"5","correct":false}],"explanation":["`4` is correct. The App Service Plan starts with 1 instance. When the CPU usage is consistently at 90% for 1 hour, the scale-out rule applies. The rule checks if the maximum CPU percentage exceeds 85% over a 5-minute window, and if it does, it increases the instance count by 1. After scaling out, a 5-minute cooldown period begins before the next evaluation.","Since both the evaluation period and the cooldown duration are set to 5 minutes, the system can scale out every 5 minutes as long as the CPU remains above 85%. Therefore, in 60 minutes, scaling can occur up to 12 times. However, the maximum instance limit is capped at 5, so only 4 scale-out operations can occur before hitting the cap, bringing the instance count from 1 to 5.","Afterward, when the CPU usage drops below 30% and stays there for 9 minutes, the scale-in rule (which evaluates on a 5-minute basis and then applies a 5-minute cooldown) is triggered. Only 1 full scale-in cycle can be completed during that 9-minute low usage period. So, the instance count is reduced by 1, resulting in a final count of 4 instances."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-common-scale-patterns","https://learn.microsoft.com/en-us/previous-versions/azure/azure-monitor/autoscale/tutorial-autoscale-performance-schedule"],"images":["assets/4cb0b4541117adca.png","assets/8673e0ad3f7277fe.png"],"topic":"compute","needsImage":true},{"id":"1-63","test":1,"number":63,"stem":["You have a deployment template named Template1 that provisions 10 Azure web apps.","Before deploying Template1, you need to determine which prerequisite resource must be created in advance. The solution should be designed to keep Azure costs as low as possible.","What should you identify?"],"options":[{"text":"one Azure Traffic Manager","correct":false},{"text":"one Azure Application Gateway","correct":false},{"text":"one App Service plan","correct":true},{"text":"10 App Service plans","correct":false},{"text":"five Azure Application Gateways","correct":false}],"explanation":["`one App Service plan` is correct because an App Service Plan allows multiple web apps to run within a single plan, sharing the same resources (e.g., CPU, memory). This approach minimizes Azure costs by avoiding the need for separate App Service Plans for each web app. Instead of provisioning separate infrastructure for each app, a single App Service Plan can host multiple apps, as long as they share similar performance and scaling requirements.","`one Azure Traffic Manager` is incorrect because Azure Traffic Manager is a DNS-based load balancer primarily used for global traffic routing across multiple regions. It is not required to host or run Azure Web Apps.","`one Azure Application Gateway` is incorrect because an Application Gateway is a layer 7 load balancer for web traffic routing and SSL offloading. It is useful for managing incoming web traffic but is not a requirement for deploying Azure Web Apps.","`10 App Service plans` is incorrect because deploying 10 separate App Service Plans for 10 web apps is unnecessary and would significantly increase costs. A single App Service Plan can host multiple web apps efficiently.","`five Azure Application Gateways` is incorrect because, similar to one Azure Application Gateway, five instances would be redundant and cost-inefficient for deploying just 10 web apps."],"references":["https://learn.microsoft.com/en-us/azure/app-service/overview-hosting-plans","https://learn.microsoft.com/en-us/azure/app-service/overview"],"images":[],"topic":"monitor","needsImage":false},{"id":"1-64","test":1,"number":64,"stem":["You have an Azure subscription that contains the resources shown in the following table.","You are required to control and manage outbound traffic originating from VNET1 by using Firewall1.","What should you do first?"],"options":[{"text":"Create a route table.","correct":true},{"text":"Configure the Hybrid Connection Manager.","correct":false},{"text":"Create an Azure Network Watcher.","correct":false},{"text":"Upgrade ASP1 to the Premium SKU.","correct":false}],"explanation":["`Create a route table` is correct because to manage outbound traffic from a virtual network (VNET1) using Azure Firewall (Firewall1), you must first create a route table. The route table is used to define how outbound traffic is directed through the Azure Firewall. Specifically, you configure a user-defined route (UDR) in the route table to ensure that outbound traffic is routed through the Azure Firewall. Without this configuration, the traffic will not pass through the firewall, and you won't be able to control or manage it effectively.","`Configure the Hybrid Connection Manager` is incorrect because Hybrid Connection Manager is used to connect Azure App Services to on-premises resources securely. It is not relevant to managing outbound traffic via Azure Firewall.","`Create an Azure Network Watcher` is incorrect because Azure Network Watcher is used for monitoring and diagnosing network issues, not for managing or directing outbound traffic through an Azure Firewall.","`Upgrade ASP1 to the Premium SKU` is incorrect because upgrading to the Premium SKU of the App Service Plan does not affect the routing of outbound traffic through an Azure Firewall."],"references":["https://learn.microsoft.com/en-us/azure/app-service/network-secure-outbound-traffic-azure-firewall","https://docs.microsoft.com/en-us/azure/virtual-network/tutorial-create-route-table-portal","https://docs.microsoft.com/en-us/azure/network-watcher/network-watcher-monitoring-overview"],"images":["assets/90f520283c934b80.png"],"topic":"identity","needsImage":true},{"id":"1-65","test":1,"number":65,"stem":["You have an Azure subscription with the following virtual networks:","The subnets are configured with the following IP address ranges:","- Subnet1: 10.1.128.0/24","- Subnet21: 192.168.0.0/17","- Subnet22: 192.168.128.0/17","- Subnet3: 172.16.1.0/24","You plan to deploy a container app named app1 in the East US region.","To support this, you need to create a container app environment named env1 with the following conditions:","- Uses its own (and existing) virtual network.","- Uses its own (and new) subnet.","- Is connected to the smallest possible subnet.","To which virtual networks can you connect env1?"],"options":[{"text":"VNet1 only","correct":false},{"text":"VNet2 only","correct":false},{"text":"VNet3 only","correct":true},{"text":"VNet1 or VNet2 only","correct":false},{"text":"VNet2 or VNet3 only","correct":false},{"text":"VNet1, VNet2, or VNet3","correct":false}],"explanation":["`VNet3 only` is correct because the requirement specifies that the container app environment (env1) must use its own (and new) subnet and must connect to the smallest possible subnet. Additionally, the subnet must be able to accommodate a minimum /23 CIDR range, which requires at least 512 IP addresses.","- VNet1 has an IP address space of /23 (512 IP addresses in total). Subnet1 already occupies /24, which uses 256 addresses, leaving insufficient IP addresses to create a new /23 subnet.","- VNet2 has an IP address space of /16 (65,536 IP addresses). However, it already contains two subnets, each with /17 ranges (32,768 IP addresses each). This allocation exhausts the available IP space, leaving no room for an additional /23 subnet.","- VNet3 also has an IP address space of /16 (65,536 IP addresses). Subnet3, which occupies /24, only consumes 256 addresses, leaving sufficient IP space to create a new /23 subnet."],"references":["https://www.ipaddressguide.com/cidr","https://www.calculator.net/ip-subnet-calculator.html?cclass=any&csubnet=17&cip=10.128.1.0&ctype=ipv4&printit=0&x=55&y=24"],"images":["assets/b67ab0e81b2f5d9d.png"],"topic":"identity","needsImage":true},{"id":"1-66","test":1,"number":66,"stem":["You have an Azure subscription with the following virtual networks:","The subnets are configured with the following IP address ranges:","- Subnet1: 10.1.128.0/24","- Subnet21: 192.168.0.0/17","- Subnet22: 192.168.128.0/17","- Subnet3: 172.16.1.0/24","You plan to deploy a container app named app1 in the East US region.","To support this, you need to create a container app environment named env1 with the following conditions:","- Uses its own (and existing) virtual network.","- Uses its own (and new) subnet.","- Is connected to the smallest possible subnet.","Which subnet mask should you use?"],"options":[{"text":"/16","correct":false},{"text":"/23","correct":true},{"text":"/24","correct":false},{"text":"/26","correct":false},{"text":"/28","correct":false}],"explanation":["`/23` is correct because, as per Microsoft's official recommendation, a container app environment requires a dedicated subnet with a minimum address space of /23 when connecting to a virtual network. This allocation ensures sufficient IP addresses (512) for both current and future scaling needs of the container app environment. Additionally, the requirement specifies selecting the smallest possible subnet that meets these prerequisites, and /23 is the optimal choice in this scenario.","Therefore, /23 satisfies both the minimum requirement and the smallest possible subnet criteria for deploying a container app environment in an Azure virtual network."],"references":["https://www.calculator.net/ip-subnet-calculator.html?cclass=any&csubnet=17&cip=10.128.1.0&ctype=ipv4&printit=0&x=55&y=24","https://learn.microsoft.com/en-us/azure/container-apps/vnet-custom?tabs=bash&pivots=azure-portal#restrictions"],"images":["assets/b67ab0e81b2f5d9d.png"],"topic":"identity","needsImage":true},{"id":"1-67","test":1,"number":67,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an application named App1 that runs on two Azure virtual machines, VM1 and VM2. Incoming traffic to App1 is handled through an Azure Load Balancer. The effective network security rules applied to VM2 are shown in the exhibit.","You observe that connection attempts from the IP address 131.107.100.50 to App1 over TCP port 443 are unsuccessful, even though the Load Balancer rules have been confirmed to be correctly configured.","You want to ensure that traffic from 131.107.100.50 can successfully reach App1 on port 443.","Proposed Solution: You remove the inbound network security rule named BlockAllOther443.","Does this solution achieve the stated objective?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because the inbound security rule Block_All_Other_443 (priority 200) denies all TCP 443 traffic from any source to any destination. This rule inadvertently blocks the Azure Load Balancer’s health probe traffic, which also uses TCP 443. Since health probes are required to mark backend VMs as healthy, VM2 is excluded from the load balancer rotation, causing all client traffic (even from 131.107.100.50, which is explicitly allowed by rule 100) to fail. By deleting the overly broad deny rule, the health probe is allowed through via the built-in AllowAzureLoadBalancerInBound rule (priority 65001), restoring VM2’s healthy state. Once the probe succeeds, the client IP 131.107.100.50 can connect successfully because its explicit allow rule (priority 100) is already in place."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/manage-rules-how-to"],"images":["assets/2a13a2539ebd7707.png"],"topic":"network","needsImage":true},{"id":"1-68","test":1,"number":68,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an application named App1 that runs on two Azure virtual machines, VM1 and VM2. Incoming traffic to App1 is handled through an Azure Load Balancer. The effective network security rules applied to VM2 are shown in the exhibit.","You observe that connection attempts from the IP address 131.107.100.50 to App1 over TCP port 443 are unsuccessful, even though the Load Balancer rules have been confirmed to be correctly configured.","You want to ensure that traffic from 131.107.100.50 can successfully reach App1 on port 443.","Proposed Solution: You create an inbound security rule that allows any traffic from the AzureLoadBalancer source and has a priority of 150.","Does this solution achieve the stated objective?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because adding a new inbound rule at priority 150 that explicitly allows traffic from the AzureLoadBalancer service tag ensures that health probe traffic is not blocked by the existing deny rule at priority 200. With this higher-priority rule in place, the health probe can once again mark VM2 as healthy, enabling the load balancer to forward traffic to it. As in Q1, once the probe succeeds, the existing allow rule at priority 100 for 131.107.100.50 ensures the client connection over TCP 443 is successful."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/manage-rules-how-to"],"images":["assets/2a13a2539ebd7707.png"],"topic":"network","needsImage":true},{"id":"1-69","test":1,"number":69,"stem":["You have an Azure subscription that contains an Azure Availability Set named WEBPROD-AS-USE2 as shown below.","PS Azure:\\> az vm availability-set list -g RG1","[","{","\"id\": \"/subscriptions/8372f433-2dcd-4361-b5ef-5b188fed87d0/resourceGroups/RG1/providers/Microsoft.Compute/availabilitySets/WEBPROD-AS-USE2\",","\"location\": \"eastus2\",","\"name\": \"WEBPROD-AS-USE2\",","\"platformFaultDomainCount\": 2,","\"platformUpdateDomainCount\": 10,","\"proximityPlacementGroup\": null,","\"resourceGroup\": \"RG1\",","\"sku\": {","\"capacity\": null,","\"name\": \"Aligned\",","\"tier\": null","},","\"statuses\": null,","\"tags\": {},","\"type\": \"Microsoft.Compute/availabilitySets\",","\"virtualMachines\": []","}","]You then add 14 virtual machines to WEBPROD-AS-USE2.","Select the answer choice that completes the following statement based on the information presented.","`“When Microsoft carries out planned maintenance in the East US 2 region, the highest number of virtual machines that could be unavailable at the same time will be __________.”`"],"options":[{"text":"2","correct":true},{"text":"7","correct":false},{"text":"10","correct":false},{"text":"14","correct":false}],"explanation":["`2` is the correct answer here. The Availability Set named WEBPROD-AS-USE2 is configured with 10 update domains, as shown in the exhibit (`\"platformUpdateDomainCount\": 10`). When Azure performs planned maintenance, only one update domain is rebooted at a time to maintain high availability.","If there are 14 virtual machines in the availability set, Azure distributes them evenly across the 10 update domains. This means:","- 4 update domains will host 2 VMs each.","- 6 update domains will host 1 VM each.","Since maintenance affects only one update domain at a time, the maximum number of VMs that can be offline simultaneously is 2—the worst case being an update domain with 2 VMs.","This behavior ensures that at least 12 out of 14 VMs remain available during any planned maintenance event.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"1-70","test":1,"number":70,"stem":["You have an Azure subscription that contains an Azure Availability Set named WEBPROD-AS-USE2 as shown below.","PS Azure:\\> az vm availability-set list -g RG1","[","{","\"id\": \"/subscriptions/8372f433-2dcd-4361-b5ef-5b188fed87d0/resourceGroups/RG1/providers/Microsoft.Compute/availabilitySets/WEBPROD-AS-USE2\",","\"location\": \"eastus2\",","\"name\": \"WEBPROD-AS-USE2\",","\"platformFaultDomainCount\": 2,","\"platformUpdateDomainCount\": 10,","\"proximityPlacementGroup\": null,","\"resourceGroup\": \"RG1\",","\"sku\": {","\"capacity\": null,","\"name\": \"Aligned\",","\"tier\": null","},","\"statuses\": null,","\"tags\": {},","\"type\": \"Microsoft.Compute/availabilitySets\",","\"virtualMachines\": []","}","]You then add 14 virtual machines to WEBPROD-AS-USE2.","Select the answer choice that completes the following statement based on the information presented.","`“If a power outage occurs in the Azure datacenter rack hosting WEBPROD-AS-USE2, the maximum number of virtual machines that could become unavailable will be ______.”`"],"options":[{"text":"2","correct":false},{"text":"7","correct":true},{"text":"10","correct":false},{"text":"14","correct":false}],"explanation":["`7` is the correct. The exhibit shows that the Availability Set WEBPROD-AS-USE2 is configured with:","- `\"platformFaultDomainCount\": 2`","Fault domains represent physical server racks in the Azure datacenter. Virtual machines in an Availability Set are distributed across the specified number of fault domains to protect against rack-level failures, such as power or network outages.","If the availability set contains 14 virtual machines and is configured with 2 fault domains, Azure will distribute the VMs as evenly as possible across both fault domains:","- One fault domain will host 7 VMs","- The other fault domain will host 7 VMs","If one server rack (i.e., one fault domain) experiences a power failure, all VMs in that fault domain will be unavailable. Hence, a maximum of 7 virtual machines could be offline in such a scenario.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"1-71","test":1,"number":71,"stem":["You have an Azure subscription that uses the public IP addresses shown in the following table.","You need to create a public Azure Standard Load Balancer.","Which of the listed public IP addresses can be used for this deployment?"],"options":[{"text":"IP2 only","correct":false},{"text":"IP3 only","correct":true},{"text":"IP1 and IP3 only","correct":false},{"text":"IP1, IP2, and IP3","correct":false}],"explanation":["`IP3 only` is the correct answer here. Azure Standard Load Balancers require a Standard SKU public IP address with a Static assignment. From the table:","- IP3 has IP version IPv6, SKU Standard, Static assignment, and is zone-redundant. All these characteristics make it eligible to be associated with a Standard Load Balancer.","`IP1` is incorrect because it uses the Basic SKU, which is not compatible with Standard Load Balancers.","`IP2` is incorrect because it also uses the Basic SKU and is dynamically assigned, both of which disqualify it for use with a Standard Load Balancer.","Azure Load Balancers follow strict compatibility rules:","- Standard Load Balancers support only Standard SKU public IPs with Static assignments.","- Basic Load Balancers support only Basic SKU public IPs and allow Dynamic assignment, especially for IPv6, but cannot be used with Standard Load Balancers.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/load-balancer/skus#sku-comparison","- https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/ipv6-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview","- https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/public-ip-addresses#sku","- https://learn.microsoft.com/en-us/azure/load-balancer/quickstart-load-balancer-standard-public-portal"],"references":[],"images":["assets/50b1d736b7d20bb9.png"],"topic":"identity","needsImage":true},{"id":"1-72","test":1,"number":72,"stem":["You have an Azure Storage account named storage1 that includes a blob container called container1. The default access tier for storage1 is set to Hot.","You configure lifecycle management rules for storage1 as summarized below:","You then carry out the following actions:","- October 1: Upload three files, Dep1File1.docx, File2.docx, and File3.docx, to container1.","- October 2: Edit Dep1File1.docx and File3.docx.","- October 5: Edit File2.docx.","True or False:","`“On October 10, you are able to read Dep1File1.docx without any delay.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. According to Rule1, blobs with the prefix `container1/Dep1` are moved to archive storage if they are not modified for two days, and deleted if not modified for nine days. The file Dep1File1.docx falls under this prefix rule, and although it was edited on October 2, it hasn't been modified since.","By October 4, two full days have passed since the last modification, so the blob is moved to the archive tier. On October 10, the file would still be in the archive tier. Reading from archive storage requires rehydration, which is not instantaneous and introduces a delay. Therefore, you cannot read `Dep1File1.docx` without a delay on October 10.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview#archive-access-tier"],"references":[],"images":["assets/254ed08fb6f509d8.png"],"topic":"storage","needsImage":true},{"id":"1-73","test":1,"number":73,"stem":["You have an Azure Storage account named storage1 that includes a blob container called container1. The default access tier for storage1 is set to Hot.","You configure lifecycle management rules for storage1 as summarized below:","You then carry out the following actions:","- October 1: Upload three files, Dep1File1.docx, File2.docx, and File3.docx, to container1.","- October 2: Edit Dep1File1.docx and File3.docx.","- October 5: Edit File2.docx.","True or False:","`“On October 10, you are able to read File2.docx without any delay.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. The blob File2.docx is stored in container1, but it does not match the prefix filter `container1/Dep1` defined in Rule1, so Rule1 does not apply to it. Only Rule2, which applies to all blobs in `storage1`, governs File2.docx.","Rule2 specifies that if base blobs are not modified for three days, they are moved to cool storage, and if not modified for nine days, they are moved to archive. File2.docx was last modified on October 5, and by October 10, only five days have passed since that modification. Therefore, it would have been moved to the cool tier, but not to the archive tier.","Blobs in the cool tier can be accessed without delay (unlike archive tier blobs that require rehydration). Hence, File2.docx can be read on October 10 without a delay.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","- https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview"],"references":[],"images":["assets/254ed08fb6f509d8.png"],"topic":"storage","needsImage":true},{"id":"1-74","test":1,"number":74,"stem":["You have an Azure Storage account named storage1 that includes a blob container called container1. The default access tier for storage1 is set to Hot.","You configure lifecycle management rules for storage1 as summarized below:","You then carry out the following actions:","- October 1: Upload three files, Dep1File1.docx, File2.docx, and File3.docx, to container1.","- October 2: Edit Dep1File1.docx and File3.docx.","- October 5: Edit File2.docx.","True or False:","`“On October 10, you are able to read File3.docx without any delay.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. File3.docx is stored in container1 and does not fall under the prefix filter `container1/Dep1` used in Rule1. Therefore, only Rule2 applies to this file.","Rule2 states that if a base blob is not modified for three days, it moves to cool storage, and after nine days of no modification, it moves to archive storage. File3.docx was last modified on October 2, and by October 10, it has not been modified for eight days.","This means File3.docx would have been moved to cool storage on October 5, but it would not yet be in the archive tier (which would happen on October 11). Since the cool access tier allows immediate read access without delay, File3.docx is readable on October 10 without requiring rehydration.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","- https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview"],"references":[],"images":["assets/394f77d825fa7893.png"],"topic":"storage","needsImage":true},{"id":"1-75","test":1,"number":75,"stem":["You have an Azure virtual machine named VM1 that is running Windows Server 2019. You export VM1 as an Azure Resource Manager template named Template1 and store it in the Azure Resource Manager library.","You then plan to use Template1 to deploy a new virtual machine called VM2.","What can you configure during the deployment of VM2?"],"options":[{"text":"administrator username","correct":false},{"text":"operating system","correct":false},{"text":"resource group","correct":true},{"text":"virtual machine size","correct":false}],"explanation":["`resource group` is correct because when deploying a virtual machine from a saved Azure Resource Manager (ARM) template, the deployment process prompts you to select or create a resource group. This is a required part of any ARM deployment as the resource group defines the logical container for the resources created.","`administrator username` is incorrect because although it may appear as a parameter in some templates, a saved template from an existing VM typically contains the username already configured and does not prompt for a new one unless manually modified in the template.","`operating system` is incorrect because the OS is defined in the base image used in the original virtual machine and carried forward in the template. You cannot change the OS during deployment from a saved template without editing the template's image reference.","`virtual machine size` is incorrect because while it can be configured in custom templates, deploying from a saved template does not always expose the size as a parameter unless it was explicitly defined that way in the template configuration. Without modification, the size remains the same as that of the source VM.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/quickstart-create-templates-use-the-portal","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-powershell","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/template-tutorial-create-first-template"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"1-76","test":1,"number":76,"stem":["You are preparing to enable backup for an Azure virtual machine named VM1.","During the backup setup process, you notice that the Backup Pre-Check reports a Warning status.","Which of the following situations could explain why the pre-check shows a warning?"],"options":[{"text":"VM1 has a disk configuration that does not match the expected requirements.","correct":false},{"text":"VM1 is missing the most recent version of the Azure VM Agent (WaAppAgent.exe).","correct":true},{"text":"VM1 is currently in a stopped state.","correct":false},{"text":"The associated Recovery Services vault is not available.","correct":false}],"explanation":["`VM1 is missing the most recent version of the Azure VM Agent (WaAppAgent.exe)` is the correct answer here. When configuring backup for an Azure virtual machine, Azure performs a Backup Pre-Check to validate whether the VM is properly configured for backup. If the Azure VM Agent is outdated or missing, it may not be able to communicate with the backup service properly, which results in a Warning status in the Backup Pre-Check. The agent is essential for snapshot-based backup and must be up to date for backup extensions to function reliably.","`VM1 has a disk configuration that does not match the expected requirements` is incorrect because that condition typically results in a Failed status, not just a warning. Unmatched or unmanaged disks can prevent backup from proceeding altogether.","`VM1 is currently in a stopped state` is incorrect because a stopped VM can still be backed up, and Azure will handle backup at the storage level. Being stopped does not automatically trigger a warning status in Backup Pre-Check.","`The associated Recovery Services vault is not available` is incorrect because that would lead to a critical error or failed status, not a warning. The vault must be available for any backup operation to proceed.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-troubleshoot","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-arm-vms-prepare#install-the-vm-agent","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm","- https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/agent-windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"1-77","test":1,"number":77,"stem":["You have an Azure subscription and you create an Azure Resource Manager (ARM) template named Template.json.","The template defines the creation of a resource group called Marketing in the East US region and contains no parameters, variables, or outputs.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {},","\"variables\": {},","\"resources\": [","{","\"type\": \"Microsoft.Resources/resourceGroups\",","\"apiVersion\": \"2024-11-01\",","\"location\": \"eastus\",","\"name\": \"Marketing\"","}","],","\"outputs\": {}","}You now want to deploy Template.json by using Azure Cloud Shell.","Which PowerShell cmdlet should you use to perform this deployment?"],"options":[{"text":"New-AzSubscriptionDeployment","correct":true},{"text":"New-AzManagementGroupDeployment","correct":false},{"text":"New-AzResourceGroupDeployment","correct":false},{"text":"New-AzTenantDeployment","correct":false}],"explanation":["`New-AzSubscriptionDeployment` is the correct answer here. The ARM template defines a resource group creation, but it's not scoped to an existing resource group because it creates the group itself. Therefore, it must be deployed at the subscription level, not the resource group level. The `New-AzSubscriptionDeployment` cmdlet is specifically used to deploy templates that create or manage resource groups.","`New-AzResourceGroupDeployment` is incorrect because this cmdlet is used when deploying resources within a specific, existing resource group. Since the template creates a new resource group (`\"type\": \"Microsoft.Resources/resourceGroups\"`), this cmdlet cannot be used—it assumes the resource group already exists.","`New-AzManagementGroupDeployment` is incorrect because it is used for ARM deployments at the management group level, which is not applicable here. The template is not managing resources across management groups.","`New-AzTenantDeployment` is incorrect because it is used to deploy tenant-scoped resources (such as Microsoft Entra tenants or policy definitions at the tenant level). That does not apply in this scenario.","Reference(s.):","- https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azresourcegroupdeployment","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"1-78","test":1,"number":78,"stem":["You have a Microsoft Entra tenant named ironclad.onmicrosoft.com, and a user named Admin1 is assigned the User administrator role. An external partner uses a Microsoft account with the sign-in address user1@outlook.com.","When Admin1 tries to invite this external partner to access the Microsoft Entra tenant, the invitation fails with the error message:","`“Unable to invite user user1@outlook.com - Generic authorization exception”.`","You need to make sure that Admin1 is able to successfully invite the external partner to sign in to the Microsoft Entra tenant.","What action should you take?"],"options":[{"text":"From the Custom domain names blade, add a custom domain.","correct":false},{"text":"From the Users blade, modify the External collaboration settings.","correct":true},{"text":"From the Organizational relationships blade, add an identity provider.","correct":false},{"text":"From the Roles and administrators blade, assign the Security administrator role to Admin1.","correct":false}],"explanation":["`From the Users blade, modify the External collaboration settings` is the correct answer here. The error message “Generic authorization exception” typically occurs when external collaboration is not properly configured to allow guest invitations. In Microsoft Entra ID (formerly Azure AD), external user invitations depend on the External collaboration settings under the Users blade. By enabling guest invites and configuring who can invite external users (like Admin1), you can resolve this error and allow Admin1 to successfully invite the partner user.","`From the Custom domain names blade, add a custom domain` is incorrect because adding a custom domain is unrelated to external collaboration or guest user invitations. It's used for domain branding and user email domains within the tenant.","`From the Organizational relationships blade, add an identity provider` is incorrect because this is typically used for B2B direct connect or federation with another organization, not for inviting an individual Microsoft account user like `user1@outlook.com`.","`From the Roles and administrators blade, assign the Security administrator role to Admin1` is incorrect because the User administrator role already grants the ability to invite guest users—if external collaboration is enabled. The issue isn’t with permissions but with the tenant-wide settings for guest collaboration.","Reference(s.):","- https://learn.microsoft.com/en-us/entra/external-id/user-properties#external-collaboration-settings","- https://learn.microsoft.com/en-us/azure/active-directory/roles/permissions-reference#user-administrator","- https://portal.azure.com/#view/Microsoft_AAD_IAM/DirectoryUserSettingsBladeV2","- https://portal.azure.com/#view/Microsoft_AAD_IAM/AllowlistPolicyBlade"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"1-79","test":1,"number":79,"stem":["You have an Azure subscription named Subscription1 that includes the following resources:","You assign a policy to RG6 as shown in the following table.","Additionally, the following action is performed:","- The tag RGroup: RG6 is applied directly to the resource group RG6.","After the policy assignment and tag configuration, you deploy a new virtual network named VNET2 into RG6.","Which tag(s) apply to VNET1?"],"options":[{"text":"None","correct":false},{"text":"Department: D1 only","correct":true},{"text":"Department: D1, and RGroup: RG6 only","correct":false},{"text":"Department: D1, and Label: Value1 only","correct":false},{"text":"Department: D1, RGroup: RG6, and Label: Value1","correct":false}],"explanation":["`Department: D1 only` is the correct answer here. According to the first table, VNET1 was already deployed in RG6 and has a tag of `Department: D1`. The Azure Policy that appends the `Label: Value1` tag was assigned after the deployment of VNET1 and therefore does not apply retroactively to existing resources. Azure policy with an `Append` effect only enforces the tagging requirement at the time of resource creation or modification, not on existing untouched resources.","The policy will apply to new resources deployed in RG6 after the policy was assigned. VNET1 is unaffected unless it is updated or redeployed.","`None` is incorrect because VNET1 already has a `Department: D1` tag.","`Department: D1, and RGroup: RG6 only` is incorrect because the `RGroup: RG6` tag was applied to the resource group (RG6), but tags from resource groups do not automatically inherit to the resources inside them unless explicitly applied via policy or ARM template.","`Department: D1, and Label: Value1 only` and `Department: D1, RGroup: RG6, and Label: Value1` are both incorrect because the `Label: Value1` tag would only apply to resources created after the policy was assigned.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effect-append","- https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"references":[],"images":["assets/f3b3e651a76bb6bd.png","assets/be0da51a0774d2c4.png"],"topic":"identity","needsImage":true},{"id":"1-80","test":1,"number":80,"stem":["You have an Azure subscription named Subscription1 that includes the following resources:","You assign a policy to RG6 as shown in the following table.","Additionally, the following action is performed:","- The tag RGroup: RG6 is applied directly to the resource group RG6.","After the policy assignment and tag configuration, you deploy a new virtual network named VNET2 into RG6.","Which tag(s) apply to VNET2?"],"options":[{"text":"None","correct":false},{"text":"RGroup: RG6 only","correct":false},{"text":"Label: Value1 only","correct":true},{"text":"RGroup: RG6, and Label: Value1","correct":false}],"explanation":["`Label: Value1 only` is the correct answer here. Azure resources do not automatically inherit tags from their resource group or subscription. While the tag `RGroup: RG6` was manually applied to the resource group RG6, this tag is not automatically passed down to newly created resources within that group.","The only tag that applies to VNET2 is the one enforced through the assigned Azure Policy. The policy uses the Append effect to apply a tag with name `Label` and value `Value1` to all new resources created in RG6. Since VNET2 was deployed after this policy was applied, it receives only the tag defined by the policy.","`None` is incorrect because the policy explicitly appends a tag to any newly created resource in RG6.","`RGroup: RG6 only` is incorrect because tags from the resource group are not automatically inherited by its resources unless explicitly defined by a policy or script.","`RGroup: RG6, and Label: Value1` is incorrect because only the policy-defined tag is applied, and resource group tags are not inherited.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effect-append","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources?tabs=json#tag-inheritance-at-deployment","- https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"references":[],"images":["assets/f3b3e651a76bb6bd.png","assets/3976f3939e84af89.png"],"topic":"identity","needsImage":true},{"id":"1-81","test":1,"number":81,"stem":["You have an Azure subscription that includes a storage account named storage1.","You plan to create a blob container named container1 within storage1.","You must configure customer-managed key (CMK) encryption for container1.","Which encryption key should you select?"],"options":[{"text":"An elliptic curve (EC) key that uses only the P-384 curve","correct":false},{"text":"An elliptic curve (EC) key that uses only the P-521 curve","correct":false},{"text":"An elliptic curve (EC) key that uses either the P-384 or P-521 curve","correct":false},{"text":"an RSA key with a key size of 4096 only","correct":false},{"text":"an RSA key type with a key size of 2048, 3072, or 4096 only","correct":true}],"explanation":["`an RSA key type with a key size of 2048, 3072, or 4096 only` is the correct answer because Azure Storage supports customer-managed keys (CMK) for encryption using RSA keys only, and those keys must have a key size of 2048, 3072, or 4096 bits. EC (Elliptic Curve) keys are not supported for encrypting data in Azure Storage with CMK.","`An elliptic curve (EC) key that uses only the P-384 curve` and `An elliptic curve (EC) key that uses either the P-384 or P-521` curve are all incorrect because Azure Storage does not support EC keys for customer-managed encryption.","`an RSA key with a key size of 4096 only` is incorrect because it unnecessarily restricts the valid RSA key sizes. While 4096 is supported, 2048 and 3072 are also valid, and the question does not require the only 4096 constraint."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/customer-managed-keys-overview","https://learn.microsoft.com/en-us/azure/key-vault/keys/about-keys#supported-key-types-and-sizes"],"images":[],"topic":"identity","needsImage":false},{"id":"1-82","test":1,"number":82,"stem":["You have an Azure virtual machine called VM1, and Azure Monitor is set up to capture events from the virtual machine.","You need to configure an alert rule that notifies an administrator whenever an error is recorded in the System event log on VM1.","Which resource should be selected as the target when creating this alert rule?"],"options":[{"text":"virtual machine extension","correct":false},{"text":"virtual machine","correct":false},{"text":"metric alert","correct":false},{"text":"Azure Log Analytics workspace","correct":true}],"explanation":["`Azure Log Analytics workspace` is the correct answer because when you want to create an alert based on event logs (such as System event log) collected from a virtual machine, those logs are first sent to a Log Analytics workspace via the Azure Monitor agent or Log Analytics agent.","Once the logs are in the workspace, you can query them using Kusto Query Language (KQL) and create log alert rules based on the results — such as triggering an alert when an error is logged in the System event log of VM1.","`virtual machine` is incorrect because you can only use metric-based alerts directly on VMs, not event log-based queries.","`virtual machine extension` is incorrect because extensions are agents that help collect data but are not targets for alerts.","`metric alert` is incorrect because event logs are not metrics. You need a log-based alert, not a metric-based one."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-sources-windows-events","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-sources-windows-events"],"images":[],"topic":"compute","needsImage":false},{"id":"2-1","test":2,"number":1,"stem":["You have an application named App1 that is hosted on an Azure App Service web app named webapp1.","Developers in your organization commit an updated version of App1 to a Git repository named Git1.","The webapp1 App Service has the following deployment slots configured:","- webapp1-prod – Production","- webapp1-test – Staging","You must ensure that the updated version of App1 is validated in a test environment before it is made available to end users.","Which two actions should you take?"],"options":[{"text":"Stop the webapp1-prod deployment slot.","correct":false},{"text":"Deploy the updated version of App1 directly to webapp1-prod, and then perform testing.","correct":false},{"text":"Deploy the updated version of App1 to webapp1-test, and then perform testing.","correct":true},{"text":"Stop the webapp1-test deployment slot.","correct":false},{"text":"Perform a swap between the deployment slots.","correct":true}],"explanation":["`Deploy the updated version of App1 to webapp1-test, and then perform testing` is correct because deploying the update to the webapp1-test slot allows you to test the new version of App1 in a staging environment without impacting the production environment. This approach aligns with best practices for deploying updates to staging before production.","`Perform a swap between the deployment slots` is correct because once testing is complete and the update is verified, you can swap webapp1-test with webapp1-prod. Swapping slots allows you to seamlessly promote the tested version to production without downtime, making the update available to users.","`Stop the webapp1-prod deployment slot` is incorrect because stopping the production slot is unnecessary for testing updates in the staging slot.","`Deploy the updated version of App1 directly to webapp1-prod, and then perform testing` is incorrect because deploying directly to production bypasses the staging environment and does not allow testing before making the update available to users.","`Perform a swap between the deployment slots` is incorrect because stopping the staging slot is not required for testing or deploying updates."],"references":["https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"],"images":[],"topic":"compute","needsImage":false},{"id":"2-2","test":2,"number":2,"stem":["You have an Azure subscription.","You are required to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","To proceed, you must complete the following ARM template configuration.","Which value should you choose for `Code Segment A`?"],"options":[{"text":"reference","correct":false},{"text":"resourceId","correct":true},{"text":"Union","correct":false}],"explanation":["`resourceId` is correct because in Azure Resource Manager (ARM) templates, resourceId is used to reference the unique identifier of an existing resource. In this template, resourceId can generate the ID for the network interface, which is required to establish the dependency on the network interface for VM1.","`reference` is incorrect because it is used to obtain runtime properties of a resource, rather than generating a resource ID within the template.","`Union` is incorrect as it does not apply to this context in ARM templates."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"],"images":["assets/7f0c76bfe13247a4.png"],"topic":"identity","needsImage":true},{"id":"2-3","test":2,"number":3,"stem":["You have an Azure subscription.","You are required to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","To proceed, you must complete the following ARM template configuration.","Which value should you choose for `Code Segment B`?"],"options":[{"text":"Array","correct":false},{"text":"Image","correct":false},{"text":"ImageReference","correct":true},{"text":"vhd","correct":false}],"explanation":["`ImageReference` is correct because in an Azure Resource Manager (ARM) template, ImageReference is used within the storageProfile section to specify the image details (such as publisher, offer, SKU, and version) for a virtual machine. This configuration tells Azure which image to use when creating the VM.","`Array` is incorrect as it is not relevant to defining the image configuration for a virtual machine in an ARM template.","`Image` is incorrect because it is not the specific attribute used within storageProfile for defining the VM image. The correct term is ImageReference.","`vhd` is incorrect because vhd is used to specify a virtual hard disk file when using a custom VHD image rather than a platform image."],"references":["https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines","https://learn.microsoft.com/en-us/azure/virtual-machines/windows/ps-template"],"images":["assets/7f0c76bfe13247a4.png"],"topic":"identity","needsImage":true},{"id":"2-4","test":2,"number":4,"stem":["You are required to configure an Azure App Service web app named bluerock.azurewebsites.net so that it can host the custom domain www.bluerock.com.","What action should you perform first?"],"options":[{"text":"Create a TXT record named asuid that includes the domain verification identifier.","correct":true},{"text":"Create a TXT record named www.bluerock.com with a value pointing to bluerock.azurewebsites.net.","correct":false},{"text":"Create a CNAME record named asuid that includes the domain verification identifier.","correct":false},{"text":"Create A records for www.bluerock.com and asuid.bluerock.com.","correct":false}],"explanation":["`Create a TXT record named asuid that includes the domain verification identifier` is correct because, to verify a custom domain for an Azure web app, you first need to create a TXT record with the name asuid in the DNS zone of your domain. This TXT record should contain the domain verification ID provided by Azure. This step is essential to prove ownership of the domain before configuring it to point to the Azure web app.","`Create a TXT record named www.bluerock.com with a value pointing to bluerock.azurewebsites.net` is incorrect because a TXT record with this configuration will not verify domain ownership. The asuid TXT record with the verification ID is required for domain verification.","`Create a CNAME record named asuid that includes the domain verification identifier` is incorrect because a TXT record (not a CNAME) is required for domain verification purposes.","`Create A records for www.bluerock.com and asuid.bluerock.com` is incorrect because A records are not used for domain verification. A TXT record with asuid is required for the initial verification step."],"references":["https://learn.microsoft.com/en-us/azure/app-service/app-service-web-tutorial-custom-domain"],"images":[],"topic":"compute","needsImage":false},{"id":"2-5","test":2,"number":5,"stem":["You are planning to deploy an Azure Container Instance by using the Azure Resource Manager (ARM) template shown.","{","\"type\": \"Microsoft.ContainerInstance/containerGroups\",","\"apiVersion\": \"2018-10-01\",","\"name\": \"webprod\",","\"location\": \"westus\",","\"properties\": {","\"containers\": [","{","\"name\": \"webprod\",","\"properties\": {","\"image\": \"microsoft/iis:nanoserver\",","\"ports\": [","{","\"protocol\": \"TCP\",","\"port\": 80","}","],","\"environmentVariables\": [],","\"resources\": {","\"requests\": {","\"memoryInGB\": 1.5,","\"cpu\": 1","}","}","}","}","],","\"restartPolicy\": \"OnFailure\",","\"ipAddress\": {","\"ports\": [","{","\"protocol\": \"TCP\",","\"port\": 80","}","],","\"ip\": \"[parameters('IPAddress')]\",","\"type\": \"Public\"","},","\"osType\": \"Windows\"","}","}","Based on the configuration provided, choose the option that correctly completes the following statement:","“Internet users ________________________________________.”"],"options":[{"text":"are able to connect to the container instance from any device.","correct":true},{"text":"are not able to connect to the container instance.","correct":false},{"text":"are only able to connect to the container instance from devices running Windows.","correct":false}],"explanation":["`are able to connect to the container instance from any device` is correct because the template specifies a public IP address (\"type\": \"Public\") and opens TCP port 80, which is a common HTTP port accessible from any internet-enabled device. This configuration allows internet users to connect to the container instance without restrictions on device type.","`are not able to connect to the container instance` is incorrect because the template has a public IP and open port 80, making the container accessible from the internet.","`are only able to connect to the container instance from devices running Windows` is incorrect because there is no configuration in the template that restricts access to specific operating systems."],"references":["https://learn.microsoft.com/en-us/azure/container-instances","https://learn.microsoft.com/en-us/azure/container-instances/container-instances-multi-container-group"],"images":[],"topic":"identity","needsImage":false},{"id":"2-6","test":2,"number":6,"stem":["You are planning to deploy an Azure Container Instance by using the Azure Resource Manager (ARM) template shown.","{","\"type\": \"Microsoft.ContainerInstance/containerGroups\",","\"apiVersion\": \"2018-10-01\",","\"name\": \"webprod\",","\"location\": \"westus\",","\"properties\": {","\"containers\": [","{","\"name\": \"webprod\",","\"properties\": {","\"image\": \"microsoft/iis:nanoserver\",","\"ports\": [","{","\"protocol\": \"TCP\",","\"port\": 80","}","],","\"environmentVariables\": [],","\"resources\": {","\"requests\": {","\"memoryInGB\": 1.5,","\"cpu\": 1","}","}","}","}","],","\"restartPolicy\": \"OnFailure\",","\"ipAddress\": {","\"ports\": [","{","\"protocol\": \"TCP\",","\"port\": 80","}","],","\"ip\": \"[parameters('IPAddress')]\",","\"type\": \"Public\"","},","\"osType\": \"Windows\"","}","}","Based on the configuration provided, choose the option that correctly completes the following statement:","“If Internet Information Services (IIS) running inside the container fails, ____________________.”"],"options":[{"text":"the container instance will restart automatically","correct":true},{"text":"the container instance will restart only through a manual action","correct":false},{"text":"the container instance must be redeployed","correct":false}],"explanation":["`the container instance will restart automatically` is correct because the template specifies a restart policy of \"OnFailure\", which means that if the application within the container (in this case, Internet Information Services or IIS) fails, the container instance will automatically restart.","`the container instance will restart only through a manual action` is incorrect because the \"OnFailure\" restart policy ensures that the container restarts automatically upon a failure.","`the container instance must be redeployed` is incorrect because the container does not need to be redeployed; it will automatically restart based on the defined restart policy."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-restart-policy"],"images":[],"topic":"identity","needsImage":false},{"id":"2-7","test":2,"number":7,"stem":["You have an Azure subscription that includes several virtual machines deployed in the West US Azure region.","You want to use Traffic Analytics in Azure Network Watcher to monitor network traffic for the virtual machines.","Which two resources must you create?"],"options":[{"text":"a storage account","correct":true},{"text":"a Microsoft Sentinel workspace","correct":false},{"text":"a Log Analytics workspace","correct":true},{"text":"a Data Collection Rule (DCR) in Azure Monitor","correct":false},{"text":"an Azure Monitor workbook","correct":false}],"explanation":["`a storage account` is correct because Traffic Analytics in Azure Network Watcher requires a storage account to store NSG flow logs. These logs capture information about the traffic to and from virtual machines, which Traffic Analytics uses for analysis.","`a Log Analytics workspace` is correct because Traffic Analytics processes the data collected from NSG flow logs and stores it in a Log Analytics workspace. This workspace allows you to query and analyze the traffic data collected by Traffic Analytics.","`a Microsoft Sentinel workspace` is incorrect because while Microsoft Sentinel can integrate with Log Analytics for security purposes, it is not required specifically for Traffic Analytics in Azure Network Watcher.","`a Data Collection Rule (DCR) in Azure Monitor` is incorrect because DCRs are used for configuring data collection in Azure Monitor but are not required for setting up Traffic Analytics.","`an Azure Monitor workbook` is incorrect because an Azure Monitor workbook provides visualization for data already collected in Azure Monitor or Log Analytics but is not a requirement for enabling Traffic Analytics."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/traffic-analytics"],"images":[],"topic":"identity","needsImage":false},{"id":"2-8","test":2,"number":8,"stem":["You have an Azure subscription named Subscription1 in which you create an alert rule named Alert1.","The Alert1 action group is configured as shown in the following exhibit.","ResourceGroupName : default-activitylogalerts","GroupShortName    : AG1","Enabled           : True","EmailReceivers    : {Action1 - EmailAction}","SmsReceivers      : {Action1 - SMSAction}","WebhookReceivers  : {}","Id                : /subscriptions/7c1e9b42-3f6a-4d88-9a21-5e7c4b2f9d10/resourceGroups/default-activitylogalerts/providers/microsoft.insights/actionGroups/ActionGroup1","Name              : ActionGroup1","Type              : Microsoft.Insights/ActionGroups","Location          : Global","Tags              : {}The alert condition for Alert1 is evaluated and triggered every minute.","Based on the information presented, select the answer choice that completes the following statement correctly.","“The number of email messages that Alert1 will send in an hour _____.”"],"options":[{"text":"0","correct":false},{"text":"4","correct":false},{"text":"6","correct":false},{"text":"12","correct":false},{"text":"60","correct":true}],"explanation":["`60` is correct because the alert rule Alert1 is set to trigger every minute. Since there are 60 minutes in an hour, Alert1 will trigger 60 times in one hour. Each time the alert is triggered, it sends an email based on the configured action group."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"],"images":[],"topic":"identity","needsImage":false},{"id":"2-9","test":2,"number":9,"stem":["You have an Azure subscription named Subscription1 in which you create an alert rule named Alert1.","The Alert1 action group is configured as shown in the following exhibit.","ResourceGroupName : default-activitylogalerts","GroupShortName    : AG1","Enabled           : True","EmailReceivers    : {Action1 - EmailAction}","SmsReceivers      : {Action1 - SMSAction}","WebhookReceivers  : {}","Id                : /subscriptions/7c1e9b42-3f6a-4d88-9a21-5e7c4b2f9d10/resourceGroups/default-activitylogalerts/providers/microsoft.insights/actionGroups/ActionGroup1","Name              : ActionGroup1","Type              : Microsoft.Insights/ActionGroups","Location          : Global","Tags              : {}The alert condition for Alert1 is evaluated and triggered every minute.","Based on the information presented, select the answer choice that completes the following statement correctly.","“The number of SMS messages that Alert1 will send in an hour is ________.”"],"options":[{"text":"0","correct":false},{"text":"4","correct":false},{"text":"6","correct":false},{"text":"12","correct":true},{"text":"60","correct":false}],"explanation":["`12` is correct because, although Alert1 is configured to trigger every minute (which would normally result in 60 alerts per hour), Azure imposes a limit of one SMS notification every 5 minutes. Due to this restriction, only 12 SMS messages will be sent per hour (one SMS every 5 minutes)."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"],"images":[],"topic":"identity","needsImage":false},{"id":"2-10","test":2,"number":10,"stem":["You have an Azure subscription named Subscription1 that contains the resources shown in the following table.","Within storage1, you create a blob container named blob1 and a file share named share1.","Which of the listed resources are eligible to be backed up to `Vault1`?"],"options":[{"text":"VM1 only","correct":true},{"text":"VM1 and share1 only","correct":false},{"text":"VM1 and SQL1 only","correct":false},{"text":"VM1, storage1, and SQL1 only","correct":false},{"text":"VM1, blob1, share1, and SQL1","correct":false}],"explanation":["`VM1 only` is correct because a Recovery Services vault can only back up resources that are in the same geographic region as the vault itself. In this case, Vault1 is located in Central US, so it can only protect resources within the Central US region. VM1 is the only resource in Central US and, therefore, the only resource that can be backed up by Vault1.","`VM1 and share1 only` is incorrect because share1 is in West US, which is not the same region as Vault1. Recovery Services vaults cannot back up resources in a different region.","`VM1 and SQL1 only` is incorrect because SQL1 is in East US, which is not the same region as Vault1.","`VM1, storage1, and SQL1 only` and `VM1, blob1, share1, and SQL1` are both incorrect because Vault1 cannot back up blobs or resources located outside of the Central US region."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-create-rs-vault","https://docs.microsoft.com/en-us/azure/backup/backup-afs"],"images":["assets/94a81158b12c343d.png"],"topic":"identity","needsImage":true},{"id":"2-11","test":2,"number":11,"stem":["You have an Azure subscription named Subscription1 that contains the resources shown in the following table.","Within storage1, you create a blob container named blob1 and a file share named share1.","Which of the listed resources are eligible to be backed up to `Vault2`?"],"options":[{"text":"storage1 only","correct":false},{"text":"share1 only","correct":true},{"text":"VM1 and share1 only","correct":false},{"text":"blob1 and share1 only","correct":false},{"text":"storage1 and SQL1 only","correct":false}],"explanation":["`share1 only` is correct because Vault2 is a Recovery Services vault located in West US and can only back up resources within the same region. share1 is an Azure file share in storage1 (also located in West US) and is eligible for backup by the Recovery Services vault. Blobs are not supported for backup in a Recovery Services vault, and VM1 is in Central US, so it cannot be backed up by Vault2.","`storage1 only` is incorrect because Recovery Services vaults do not directly back up storage accounts themselves. They can back up Azure file shares within a storage account, but not the storage account as a whole.","`VM1 and share1 only` is incorrect because VM1 is located in Central US, not West US, so it cannot be backed up by Vault2.","`blob1 and share1 only` is incorrect because blobs cannot be backed up by a Recovery Services vault. Only file shares within a storage account are eligible for backup, provided they are in the same region.","`storage1 and SQL1 only` is incorrect because SQL1 is located in East US and cannot be backed up by Vault2 in West US."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-create-rs-vault","https://azure.microsoft.com/en-in/blog/microsoft-azure-block-blob-storage-backup/","https://docs.microsoft.com/en-us/azure/backup/backup-afs"],"images":["assets/94a81158b12c343d.png"],"topic":"identity","needsImage":true},{"id":"2-12","test":2,"number":12,"stem":["You manage a Recovery Services vault named RSV1. The backup policy configured for RSV1 has the following settings:","- Instant snapshots are retained for 5 days","- Daily backup recovery points are retained for 14 days","RSV1 is configured to perform daily backups of a virtual machine named VM1.","VM1 hosts a static website, and the site content was last updated eight days ago.","You must restore VM1 to its state from eight days ago, and the solution must minimize service downtime.","What should you do first?"],"options":[{"text":"Delete VM1.","correct":false},{"text":"Restore VM1 by using the Create new restore configuration option.","correct":true},{"text":"Deallocate VM1.","correct":false},{"text":"Restore VM1 by using the Replace existing restore configuration option.","correct":false}],"explanation":["`Restore VM1 by using the Create new restore configuration option` is correct because it allows you to recover VM1 to a previous state from eight days ago without affecting the existing VM. This approach minimizes downtime as it creates a new VM instance based on the backup from eight days ago, enabling you to test and verify the restored version separately before making it live if needed.","`Delete VM1` is incorrect because deleting VM1 would not be required to perform the restore operation and would lead to unnecessary downtime and data loss.","`Deallocate VM1` is incorrect because deallocating VM1 is unnecessary for restoring from a backup. This option does not achieve the goal of recovering to a specific point in time.","`Restore VM1 by using the Replace existing restore configuration option` is incorrect because using the replace option would overwrite the current VM, causing downtime while the restore is performed. This does not align with the goal of minimizing downtime."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-13","test":2,"number":13,"stem":["You have a Microsoft Entra tenant that includes the following users:","- Admin1 with the User Administrator role","- User1 with the User role","You must complete the following tasks:","- Create a custom attribute named Property1.","- Ensure that Admin1 is able to assign Property1 to User1.","Which two settings should you configure from the Microsoft Entra ID blade?"],"options":[{"text":"Custom security attributes","correct":true},{"text":"Roles and administrators","correct":true},{"text":"External Identities","correct":false},{"text":"Administrative units","correct":false},{"text":"Application proxy","correct":false},{"text":"Microsoft Entra Connect","correct":false}],"explanation":["`Custom security attributes` is correct because this setting allows you to define attributes like `Property1` within Microsoft Entra ID. These attributes can then be assigned to users, groups, service principals, or managed identities as needed.","`Roles and administrators` is also correct because although Admin1 currently has the User Administrator role—which does not grant the ability to create or assign custom security attributes—this blade is used to assign the appropriate roles. To fulfill the requirement, Admin1 must be granted two additional roles: Attribute Definition Administrator to create `Property1`, and Attribute Assignment Administrator to assign it to User1. These roles must be explicitly assigned through the Roles and administrators section in the Microsoft Entra admin center.","`External Identities` is incorrect because it manages access and collaboration with external users and is not relevant to custom attribute configuration.","`**","Administrative units` is incorrect** because they are used for scoping administrative permissions to subsets of users or devices, not for managing attribute definitions or assignments.","`Application proxy` is incorrect this is unrelated to identity or attribute management; it provides secure remote access to on-premises applications.","`Microsoft Entra Connect` is incorrect because this is used for syncing identities from on-premises directories and has no role in attribute creation or assignment."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/whatis"],"images":[],"topic":"identity","needsImage":false},{"id":"2-14","test":2,"number":14,"stem":["You have an Azure subscription.","You plan to create an Azure Storage account with the configuration shown in the following exhibit.","Based on the information presented, select the answer choice that completes the following statement correctly.","“The minimum number of copies of the storage account will be ________.”"],"options":[{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":true},{"text":"4","correct":false}],"explanation":["`3` is correct because the storage account is using Locally-redundant storage (LRS), which replicates data three times within a single data center in the selected region. This ensures that there are three copies of the data, providing local redundancy in case of hardware failures."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-redundancy"],"images":["assets/b8b71f807a6276ef.png"],"topic":"identity","needsImage":true},{"id":"2-15","test":2,"number":15,"stem":["You have an Azure subscription.","You plan to create an Azure Storage account with the configuration shown in the following exhibit.","Based on the information presented, select the answer choice that completes the following statement correctly.","“To reduce the cost of infrequently accessed data in the storage account, you must modify the ____________________ setting.”"],"options":[{"text":"Access tier (default)","correct":true},{"text":"Performance","correct":false},{"text":"Account kind","correct":false},{"text":"Replication","correct":false}],"explanation":["`Access tier (default)` is correct because changing the access tier to Cool, Cold, or Archive can help reduce the cost of storing data that is infrequently accessed. Switching from Hot to Cool, Cold, or Archive will optimize cost depending on the data access pattern.","`Performance` is incorrect because this setting affects the performance of the storage account (Standard vs. Premium) but does not specifically target cost savings for infrequently accessed data.","`Account kind` is incorrect because changing the account kind to a different type (e.g., StorageV1 to StorageV2) does not directly reduce costs for infrequently accessed data.","`Replication` is incorrect because replication affects data durability and redundancy but does not specifically reduce costs for infrequently accessed data."],"references":["https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blob-storage-tiers?tabs=azure-portal","https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blob-performance-tiers","https://docs.microsoft.com/en-us/azure/storage/common/storage-account-overview?toc=%2fazure%2fstorage%2fblobs%2ftoc.json","https://azure.microsoft.com/en-us/pricing/details/storage/"],"images":["assets/b8b71f807a6276ef.png"],"topic":"identity","needsImage":true},{"id":"2-16","test":2,"number":16,"stem":["You are designing an Azure Storage solution and must provision a storage account that satisfies the following design constraints:","- Blob data must be able to use all access tiers, including hot, cool, and archive","- The solution must remain resilient if the primary Azure region becomes unavailable","- The configuration should be as cost-effective as possible","You plan to deploy the storage account by using the Azure CLI command shown below:","How should you complete the following command?","`az storage account create -g RG1 -n storageaccount1 --kind ____ --sku ____`"],"options":[{"text":"--kind FileStorage --sku Standard_GRS","correct":false},{"text":"--kind Storage --sku Standard_LRS","correct":false},{"text":"--kind StorageV2 --sku Standard_RAGRS","correct":false},{"text":"--kind StorageV2 --sku Standard_GRS","correct":true},{"text":"--kind FileStorge --sku Premium_LRS","correct":false}],"explanation":["`--kind StorageV2 --sku Standard_GRS` is correct because StorageV2 is the only account kind that supports all three blob storage tiers—Hot, Cool, and Archive. Additionally, the Standard_GRS SKU provides geo-redundancy, which replicates data to a secondary region to ensure resiliency against regional failures, aligning with the requirement for regional fault tolerance."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview"],"images":[],"topic":"storage","needsImage":false},{"id":"2-17","test":2,"number":17,"stem":["An Azure subscription contains the following networking resources, all deployed in the East US region:","- VNet1: a virtual network","- Subnet1: a subnet within VNet1","- NIC1: a network interface","You create a user-defined route table named RT1 in the East US region.","Which of the listed resources can RT1 be linked to?"],"options":[{"text":"VNet1 only","correct":false},{"text":"Subnet1 only","correct":true},{"text":"VNet1 and NIC1 only","correct":false},{"text":"Subnet1 and NIC1 only","correct":false},{"text":"VNet1, Subnet1, and NIC1","correct":false}],"explanation":["`Subnet1 only` is the correct answer because in Azure, route tables (like RT1) can only be associated with subnets, not with virtual networks (VNet1) or network interfaces (NIC1). When you associate a route table with a subnet, all resources (like virtual machines) within that subnet use the custom routes defined in the route table.","- VNet1 cannot be directly associated with a route table. Instead, route tables are applied at the subnet level within a virtual network.","- NIC1 (network interface) cannot be associated with a route table either."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://learn.microsoft.com/en-us/azure/virtual-network/manage-route-table"],"images":[],"topic":"identity","needsImage":false},{"id":"2-18","test":2,"number":18,"stem":["You are preparing to deploy a containerized workload in Azure.","As part of the solution design, you must identify which Azure service options are capable of automatically adjusting capacity for the container based on demand.","Which Azure service should you recommend?"],"options":[{"text":"Azure Container Apps only","correct":false},{"text":"Azure Container Instances only","correct":false},{"text":"Azure Container Apps or Azure App Service only","correct":true},{"text":"Azure Container Instances or Azure App Service only","correct":false},{"text":"Azure Container Apps, Azure Container Instances, or Azure App Service","correct":false}],"explanation":["`Azure Container Apps or Azure App Service only` is the correct answer here. Both Azure Container Apps and Azure App Service provide built-in autoscaling capabilities for containers based on demand, such as HTTP requests or CPU usage. These services can automatically scale out or in depending on the workload.","`Azure Container Instances only` is incorrect because it does not have built-in autoscaling. It allows you to run containers but requires manual scaling.","`Azure Container Apps, Azure Container Instances, or Azure App Service` is incorrect because Azure Container Instances does not support automatic scaling."],"references":["https://learn.microsoft.com/en-us/azure/container-apps/scale-app?pivots=azure-cli","https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up"],"images":[],"topic":"compute","needsImage":false},{"id":"2-19","test":2,"number":19,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","An application named App1 is deployed on two Azure virtual machines, VM1 and VM2. Incoming traffic to App1 is distributed by an Azure Load Balancer.","The effective network security rules applied to VM2 are shown in the exhibit.","You observe that client connections originating from the IP address 131.107.100.50 fail when attempting to reach App1 over TCP port 443. You verify that the Load Balancer configuration is correct.","Your objective is to ensure that connections from 131.107.100.50 to App1 over TCP port 443 are successfully established.","Proposed solution: You change the priority value of the inbound network security rule named Allow_131.107.100.50.","Does this solution achieve the stated objective?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer because the inbound security rule named Allow_131.107.100.50 already has the highest priority (100), meaning it is the first rule to be evaluated. Since no higher-priority rule is blocking the traffic, modifying the rule's priority will have no effect. Furthermore, the source, destination, protocol, and port settings in the rule already allow traffic from IP `131.107.100.50` over TCP port `443` to the virtual network."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://docs.microsoft.com/en-us/security/benchmark/azure/baselines/load-balancer-security-baseline"],"images":["assets/36f7dc1d99dbd25d.png"],"topic":"network","needsImage":true},{"id":"2-20","test":2,"number":20,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","An application named App1 is deployed on two Azure virtual machines, VM1 and VM2. Incoming traffic to App1 is distributed by an Azure Load Balancer.","The effective network security rules applied to VM2 are shown in the exhibit.","You observe that client connections originating from the IP address 131.107.100.50 fail when attempting to reach App1 over TCP port 443. You verify that the Load Balancer configuration is correct.","Your objective is to ensure that connections from 131.107.100.50 to App1 over TCP port 443 are successfully established.","Proposed solution: You add a new inbound network security rule that explicitly blocks all incoming traffic originating from the IP address 131.107.100.50 and assign the rule a priority value of 64999.","Does this solution achieve the stated objective?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because creating an inbound security rule that denies all traffic from 131.107.100.50 with a priority of 64999 will block connections from this IP, which is the opposite of the requirement. The goal is to allow connections to App1 from 131.107.100.50 on TCP port 443, not to deny them. Additionally, a deny rule would prevent any successful connection from this IP, making it impossible to establish the required connectivity to App1."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview#azure-platform-considerations"],"images":["assets/36f7dc1d99dbd25d.png"],"topic":"network","needsImage":true},{"id":"2-21","test":2,"number":21,"stem":["You are working within an Azure subscription and must deploy an Azure Container Instance named cont1.","The deployment must satisfy the following conditions:","- Ensure that specific configuration parameters are applied to cont1 during the container startup.","- Provide secure values to cont1 during the container startup.","What should you configure for cont1?"],"options":[{"text":"a command override","correct":false},{"text":"tags","correct":false},{"text":"customer-managed keys","correct":false},{"text":"environment variables","correct":true}],"explanation":["`environment variables` is correct because they allow you to set specific configuration parameters and pass secure values (such as sensitive data or credentials) to the container instance cont1 during startup. Environment variables can be securely stored in Azure and referenced in the container, meeting both requirements.","`a command override` is incorrect because it allows you to override the default command for a container but does not handle secure values or configuration parameters needed during startup.","`tags` is incorrect because tags are used for organizing and categorizing resources in Azure but are not used to pass configuration parameters or secure values to containers.","`customer-managed keys` is incorrect because they are related to encryption in Azure and do not provide a mechanism for applying configuration parameters or passing secure values to a container instance at startup."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-22","test":2,"number":22,"stem":["Your Azure environment contains the following virtual machines:","- VM1 and VM2, both deployed in the West Europe region","- VM3 and VM4, both deployed in the North Europe region","A Recovery Services vault is already in place and is currently configured to back up VM1 and VM2.","You now need to enable Recovery Services protection for VM3 and VM4.","What is the first action you should take?"],"options":[{"text":"Create a new Recovery Services vault","correct":true},{"text":"Provision a new storage account","correct":false},{"text":"Set up the required extensions on VM3 and VM4.","correct":false},{"text":"Define and configure a new backup policy","correct":false}],"explanation":["`Create a new Recovery Services vault` is correct because a Recovery Services vault must be in the same region as the virtual machines it protects. Since VM3 and VM4 are in the \"North Europe\" region, a new Recovery Services vault must be created in that region to back up these virtual machines.","`Provision a new storage account` is incorrect because a storage account is not required for setting up backups through Recovery Services Vaults.","`Set up the required extensions on VM3 and VM4` is incorrect because configuring extensions is not the initial step required to back up these VMs. Extensions are typically configured as part of the backup process.","`Define and configure a new backup policy` is incorrect because a backup policy does not address the requirement of having a Recovery Services vault in the correct region for VM3 and VM4."],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"2-23","test":2,"number":23,"stem":["You are working in an Azure subscription that includes a storage account named storage1.","The following client devices are available:","- Device1 - running Windows 10","- Device2 -  running Linux","- Device3 -  running macOS","You want to transfer data to storage1 by using the AzCopy utility.","From which of the listed devices can you perform this operation?"],"options":[{"text":"Device1 and Device2 only","correct":false},{"text":"Device1 only","correct":false},{"text":"Device1 and Device3 only","correct":false},{"text":"Device1, Device2, and Device3","correct":true}],"explanation":["`Device1, Device2, and Device3` is correct because AzCopy is a cross-platform command-line utility available for Windows, Linux, and macOS. This means it can be used on all three devices listed in the table to copy data to an Azure storage account."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-24","test":2,"number":24,"stem":["You have an Azure subscription and are preparing to move 50 virtual machines from an on-premises VMware vSphere environment into Azure.","As part of the migration setup, you have already created a Recovery Services vault.","What should you do next to continue the migration process?"],"options":[{"text":"Define a recovery plan to orchestrate the migration workflow.","correct":false},{"text":"Deploy an Open Virtualization Application (OVA) template to vSphere.","correct":false},{"text":"Set up an Azure virtual network that will host the migrated virtual machines.","correct":true},{"text":"Configure a network extension between the on-premises environment and Azure.","correct":false}],"explanation":["`Set up an Azure virtual network that will host the migrated virtual machines` is correct because for migrating virtual machines from VMware vSphere to Azure using Azure Site Recovery (ASR), the next step after creating a Recovery Services vault is to configure a virtual network in Azure. This network will act as the target network for the VMs once they are migrated.","`Define a recovery plan to orchestrate the migration workflow` is incorrect because creating a recovery plan is part of the orchestration phase of disaster recovery and is not required as the next step in setting up ASR for migration.","`Deploy an Open Virtualization Application (OVA) template to vSphere` is incorrect because using Azure Site Recovery (ASR) does not require the Azure Migrate appliance or an OVA template. The OVA template is specific to Azure Migrate.","`Configure a network extension between the on-premises environment and Azure` is incorrect as configuring an extended network may be part of the networking requirements, but configuring a virtual network in Azure is the immediate next step."],"references":["https://learn.microsoft.com/en-us/azure/site-recovery/tutorial-prepare-azure"],"images":[],"topic":"identity","needsImage":false},{"id":"2-25","test":2,"number":25,"stem":["An Azure subscription contains a resource group named RG1.","You intend to deploy a new storage account called storage1 by using infrastructure-as-code. A Bicep file named File1 is available and will be used for this deployment.","To ensure that storage1 is automatically deployed into RG1, you must modify File1 accordingly.","Which property in the Bicep file should you change?"],"options":[{"text":"kind","correct":false},{"text":"scope","correct":true},{"text":"sku","correct":false},{"text":"location","correct":false}],"explanation":["`scope` is correct because setting the scope property is necessary to target a specific resource group, such as RG1, when deploying resources in Bicep. By configuring the scope property, you direct the deployment of storage1 specifically to RG1. This approach is especially useful when deploying resources to a resource group that isn’t the default target in the Bicep file.","`kind` is incorrect because it specifies the type of storage account (e.g., StorageV2, BlobStorage) and does not control the deployment target.","`sku` is incorrect because it defines the storage account’s performance and redundancy (e.g., Standard_LRS, Standard_GRS) but does not determine the deployment target resource group.","`location` is incorrect because it specifies the Azure region for the storage account, but does not target the resource group for deployment."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/deploy-to-resource-group"],"images":[],"topic":"identity","needsImage":false},{"id":"2-26","test":2,"number":26,"stem":["You are working in an Azure subscription called Subscription1.","Within this subscription, you provision an Azure Storage account named contosostorage and then create an Azure Files share called data.","You are writing a script that must access files stored in the data file share.","Which UNC path should the script reference to correctly access those files?","UNC Path to include:","Values to choose from:","- blob","- blob.core.windows.net","- contosostorage","- data","- file","- file.core.windows.net","- portal.azure.com","- subscription1"],"options":[{"text":"contosostorage.file.core.windows.net\\data","correct":true},{"text":"data.file.core.windows.net\\contosostorage","correct":false},{"text":"contosostorage.blob.core.windows.net\\data","correct":false},{"text":"data.blob.core.windows.net\\contosostorage","correct":false},{"text":"file.subscription1\\portal.azure.com","correct":false},{"text":"blob.data\\file.core.windows.net","correct":false}],"explanation":["contosostorage.file.core.windows.net\\data is correct.","The correct UNC path to include in a script that references files from the `data` file share in the `contosostorage` storage account would be:","`\\\\contosostorage.file.core.windows.net\\data`","Here’s why this is correct:","- The correct format for accessing an Azure file share is `\\\\<storage-account-name>.file.core.windows.net\\<file-share-name>`.","- In this case:","- `<storage-account-name>` is `contosostorage`","- `<file-share-name>` is `data`","Thus, `\\\\contosostorage.file.core.windows.net\\data` is the appropriate path."],"references":["https://docs.microsoft.com/en-us/azure/storage/files/storage-how-to-use-files-windows"],"images":["assets/92648fd79c440c8c.png"],"topic":"identity","needsImage":true},{"id":"2-27","test":2,"number":27,"stem":["Your Azure subscription includes two virtual networks with the following characteristics:","- VNet1, deployed in the East US region and peered with VNet2","- VNet2, deployed in the East US region and peered with VNet1","Each virtual network hosts 50 virtual machines.","You are required to deploy Azure Bastion and must ensure that the configuration meets the following criteria:","- Allows automatic scaling of Bastion hosts.","- Supports file upload and download.","- Support the virtual machines on both VNet1 and VNet2.","- Minimize the number of addresses on the Azure Bastion subnet.","You need to configure Azure Bastion.","Which type of Public IP address should you select?"],"options":[{"text":"A Basic SKU public IP address that uses dynamic assignment","correct":false},{"text":"A Basic SKU public IP address that uses static assignment","correct":false},{"text":"A Standard SKU public IP address that uses static assignment","correct":true}],"explanation":["`A Standard SKU public IP address that uses static assignment` is correct because it is required to support host scaling and advanced features such as file upload and download when implementing Azure Bastion. The Standard SKU is necessary to meet these requirements, and static allocation of the Public IP ensures a consistent IP address for accessing the Bastion host, which is recommended for production environments.","`A Basic SKU public IP address that uses dynamic assignment` is incorrect because the Basic SKU does not support the necessary features like file upload and download or host scaling.","`A Basic SKU public IP address that uses static assignment` is incorrect because, similar to the dynamic allocation, the Basic SKU does not support the advanced features required for this setup."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/configuration-settings"],"images":[],"topic":"identity","needsImage":false},{"id":"2-28","test":2,"number":28,"stem":["Your Azure subscription includes two virtual networks with the following characteristics:","- VNet1, deployed in the East US region and peered with VNet2","- VNet2, deployed in the East US region and peered with VNet1","Each virtual network hosts 50 virtual machines.","You are required to deploy Azure Bastion and must ensure that the configuration meets the following criteria:","- Allows automatic scaling of Bastion hosts.","- Supports file upload and download.","- Support the virtual machines on both VNet1 and VNet2.","- Minimize the number of addresses on the Azure Bastion subnet.","You need to configure Azure Bastion.","What subnet size should you use?"],"options":[{"text":"/24","correct":false},{"text":"/26","correct":true},{"text":"/28","correct":false},{"text":"/29","correct":false}],"explanation":["`/26` is correct because Azure Bastion requires a dedicated subnet called AzureBastionSubnet, and it is recommended to allocate a subnet with at least a /26 prefix to support scaling and additional features. This size provides sufficient IP addresses for supporting multiple concurrent sessions and scaling requirements.","`/24` is incorrect as it is unnecessarily large for this requirement, leading to wasted IP address space.","`/28` and `/29` are incorrect because these subnet sizes are too small and do not provide enough IP addresses to support scaling and the advanced features of Azure Bastion."],"references":["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings"],"images":[],"topic":"identity","needsImage":false},{"id":"2-29","test":2,"number":29,"stem":["Your Azure subscription includes the storage accounts described below:","- storage1","- Microsoft Entra authentication: Enabled","- Contains a blob container named container1 with no public access","- storage2","- Microsoft Entra authentication: Enabled","- Contains an Azure Files share named share1","You intend to use AzCopy to transfer a blob directly from container1 in storage1 to share1 in storage2.","To complete this operation, you must choose an appropriate authentication mechanism for AzCopy.","Which authentication method should you use when accessing \"storage1\"?"],"options":[{"text":"OAuth","correct":false},{"text":"Anonymous","correct":false},{"text":"A storage account access key","correct":false},{"text":"A shared access signature (SAS) token","correct":true}],"explanation":["`A Shared Access Signature (SAS) token` is correct because in this scenario, AzCopy requires a SAS token for copying a blob from a container that has \"No public access\" set. The SAS token provides limited, scoped permissions, allowing access only to the specific blob container and file share, ensuring secure data transfer between storage resources. This approach adheres to the principle of least privilege by not exposing full access to the storage account.","`OAuth` is incorrect because OAuth cannot be used as the source URL for copying from a blob container to a file share. OAuth is suitable for blob-to-blob copies but not when file shares are involved.","`Anonymous` is incorrect because public access is disabled on the container, so a SAS token or other authentication method is required.","`A Storage Account Access key` is incorrect because it grants broader permissions than necessary, covering the entire storage account, which goes against the principle of least privilege and poses a security risk for this specific transfer."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-v10","https://learn.microsoft.com/en-us/azure/storage/common/storage-ref-azcopy-copy?toc=%2Fazure%2Fstorage%2Fblobs%2Ftoc.json"],"images":[],"topic":"identity","needsImage":false},{"id":"2-30","test":2,"number":30,"stem":["Your Azure subscription includes the storage accounts described below:","- storage1","- Microsoft Entra authentication: Enabled","- Contains a blob container named container1 with no public access","- storage2","- Microsoft Entra authentication: Enabled","- Contains an Azure Files share named share1","You intend to use AzCopy to transfer a blob directly from container1 in storage1 to share1 in storage2.","To complete this operation, you must choose an appropriate authentication mechanism for AzCopy.","Which authentication method should you use when accessing \"storage2\"?"],"options":[{"text":"OAuth","correct":false},{"text":"Anonymous","correct":false},{"text":"A storage account access key","correct":false},{"text":"A shared access signature (SAS) token","correct":true}],"explanation":["`A shared access signature (SAS) token` is correct because Azure File shares only support SAS as an authentication method for all operations when using AzCopy. This ensures secure access and aligns with the access control requirements for file shares in AzCopy operations.","`OAuth`, `Anonymous`, and `A storage account access key` are incorrect because Azure File shares exclusively support SAS for all types of operations with AzCopy. Therefore, these methods cannot be used in this scenario."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-v10","https://learn.microsoft.com/en-us/azure/storage/common/storage-ref-azcopy-copy?toc=%2Fazure%2Fstorage%2Fblobs%2Ftoc.json"],"images":[],"topic":"identity","needsImage":false},{"id":"2-31","test":2,"number":31,"stem":["You have an Azure subscription that includes a storage account named storage1, which contains a blob container called container1.","You create a blob lifecycle management policy named rule1. The purpose of this rule is to automatically move blobs in container1 to the Cool access tier if they have not been modified for 45 days.","To implement this behavior, you must complete the lifecycle policy definition shown in the exhibit.","What should you choose for `Code Segment A`?"],"options":[{"text":"\"daysAfterCreationGreaterThan\"","correct":false},{"text":"\"daysAfterLastAccessTimeGreaterThan\"","correct":false},{"text":"\"daysAfterModificationGreaterThan\"","correct":true}],"explanation":["`daysAfterModificationGreaterThan` is correct because it specifies the condition to move blobs that have not been modified within the specified period (45 days, in this case) to the Cool access tier. This meets the requirement of moving blobs based on the last modification date.","`daysAfterCreationGreaterThan` is incorrect because it moves blobs based on the number of days since creation, not since the last modification or update.","`daysAfterLastAccessTimeGreaterThan` is incorrect because it uses the last access time, which is not the required condition for this scenario. The requirement is based on the last modification date."],"references":[],"images":["assets/676ad2fe73842478.png"],"topic":"identity","needsImage":true},{"id":"2-32","test":2,"number":32,"stem":["You have an Azure subscription that includes a storage account named storage1, which contains a blob container called container1.","You create a blob lifecycle management policy named rule1. The purpose of this rule is to automatically move blobs in container1 to the Cool access tier if they have not been modified for 45 days.","To implement this behavior, you must complete the lifecycle policy definition shown in the exhibit.","What should you choose for `Code Segment B`?"],"options":[{"text":"\"AppendBlob\"","correct":false},{"text":"\"Blockblob\"","correct":true},{"text":"\"Pageblob\"","correct":false}],"explanation":["`Blockblob` is correct because block blobs are typically used for storing general-purpose files and are the default choice for most Azure blob storage scenarios, including lifecycle management. Since the requirement involves moving blobs to a different access tier, block blobs are the appropriate selection.","`AppendBlob` is incorrect because append blobs are used for scenarios like logging, where data is continuously appended to the end of the blob. They are not typically managed by lifecycle policies for tiering.","`Pageblob` is incorrect because page blobs are primarily used for Azure Virtual Machine disks and are not suited for lifecycle tiering in this context."],"references":[],"images":["assets/49d2bb3b99e3330a.png"],"topic":"identity","needsImage":true},{"id":"2-33","test":2,"number":33,"stem":["You are designing an Azure deployment that uses Azure Resource Manager (ARM) templates to provision 50 virtual machines. All virtual machines will be placed in the same availability set.","The goal of the design is to maximize the number of virtual machines that remain online during either Azure platform failures or planned maintenance events.","To achieve this, you are configuring an ARM template that defines an availability set, as shown in the exhibit. The template includes settings for fault domains and update domains.","Which value should you specify for the `platformFaultDomainCount` property in the availability set configuration?"],"options":[{"text":"0","correct":false},{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":true}],"explanation":["`3` is correct because, in regions that support it, Azure availability sets can be spread across up to 3 fault domains by default. This configuration maximizes availability by distributing virtual machines across more physical racks, thereby increasing the likelihood of VM availability during a fabric failure.","`0`, `1`, and `2` are incorrect because:","- 0 would mean no fault domain distribution, resulting in no fault tolerance.","- 1 would only provide minimal distribution, reducing high availability.","- 2 would offer some availability, but 3 provides the maximum distribution across fault domains, which is preferred when trying to maximize the number of available VMs in case of a failure."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-and-updates"],"images":["assets/23fdb067828086f9.png"],"topic":"compute","needsImage":true},{"id":"2-34","test":2,"number":34,"stem":["You are designing an Azure deployment that uses Azure Resource Manager (ARM) templates to provision 50 virtual machines. All virtual machines will be placed in the same availability set.","The goal of the design is to maximize the number of virtual machines that remain online during either Azure platform failures or planned maintenance events.","To achieve this, you are configuring an ARM template that defines an availability set, as shown in the exhibit. The template includes settings for fault domains and update domains.","Which value should you specify for the `platformUpdateDomainCount` property in the availability set configuration?"],"options":[{"text":"0","correct":false},{"text":"1","correct":false},{"text":"6","correct":false},{"text":"12","correct":false},{"text":"17","correct":false},{"text":"20","correct":true}],"explanation":["`20` is correct because Azure Availability Sets support up to 20 update domains by default. Update domains are used to ensure that virtual machines in the same availability set do not go down for maintenance at the same time. By setting the platformUpdateDomainCount to 20, you maximize the distribution of virtual machines across update domains, which helps maintain availability during planned maintenance events.","`0`, `1`, `6`, `12`, and `17` are incorrect because:","- 0 would mean no update domain distribution, resulting in all VMs potentially being impacted by maintenance at the same time.","- 1, 6, 12, and 17 would offer fewer update domains, which would not maximize availability during updates as effectively as using 20."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-and-updates","https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"images":["assets/c9bdf1556f194b04.png"],"topic":"compute","needsImage":true},{"id":"2-35","test":2,"number":35,"stem":["**Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You administer a virtual network named VNet1 located in the West US Azure region.","Within VNet1, there are two virtual machines, VM1 and VM2, both running Windows Server.","You are required to analyze and observe all network traffic flowing from VM1 to VM2 over a continuous three-hour window.","Proposed solution: Using Azure Monitor, you configure metrics to track Network In and Network Out traffic.","Does this proposed solution achieve the stated requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because creating a metric on Network In and Network Out in Azure Monitor will only provide information on the volume of network traffic, not the contents or details of the network traffic. To inspect all network traffic between VM1 and VM2, you would need to use a tool or service that allows for deeper traffic inspection, such as Azure Network Watcher with Packet Capture or a Network Security Group flow log."],"references":["https://docs.microsoft.com/en-us/azure/azure-monitor/platform/metrics-supported"],"images":[],"topic":"network","needsImage":false},{"id":"2-36","test":2,"number":36,"stem":["**Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You administer a virtual network named VNet1 located in the West US Azure region.","Within VNet1, there are two virtual machines, VM1 and VM2, both running Windows Server.","You are required to analyze and observe all network traffic flowing from VM1 to VM2 over a continuous three-hour window.","Proposed solution: Using Azure Network Watcher, you set up a Connection Monitor to track and evaluate the traffic flow between the virtual machines.","Does this proposed solution achieve the stated requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because Connection Monitor in Azure Network Watcher is primarily used to monitor connectivity status and latency between two endpoints rather than to inspect the content of network traffic. It provides insights into the connection quality, including packet loss and response time, but it does not capture or analyze all network traffic between VM1 and VM2. For inspecting all network traffic, you would need to use Packet Capture in Azure Network Watcher, which allows you to capture network traffic for deeper inspection."],"references":["https://docs.microsoft.com/en-us/azure/network-watcher/connection-monitor","https://docs.microsoft.com/en-us/azure/network-watcher/network-watcher-packet-capture-overview"],"images":[],"topic":"network","needsImage":false},{"id":"2-37","test":2,"number":37,"stem":["**Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You administer a virtual network named VNet1 located in the West US Azure region.","Within VNet1, there are two virtual machines, VM1 and VM2, both running Windows Server.","You are required to analyze and observe all network traffic flowing from VM1 to VM2 over a continuous three-hour window.","Proposed solution: You use Performance Monitor to configure a Data Collector Set (DCS).","Does this proposed solution achieve the stated requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because Performance Monitor and creating a Data Collector Set (DCS) on Windows Server allows you to collect performance metrics, such as CPU, memory, and disk usage, but it does not capture or inspect network traffic between VMs. To inspect all network traffic between VM1 and VM2, you would need to use Packet Capture in Azure Network Watcher, which is specifically designed for capturing and analyzing network traffic."],"references":["https://docs.microsoft.com/en-us/azure/azure-monitor/insights/network-performance-monitor"],"images":[],"topic":"network","needsImage":false},{"id":"2-38","test":2,"number":38,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named Bluerock.com and an Azure subscription called Subscription1. Within Bluerock.com, there is a security group named Developers. Within Subscription1, there is a resource group named Dev.","You must grant the Developers group permissions that allow them to create Azure Logic Apps within the Dev resource group.","Proposed solution: At the Dev resource group scope, you assign the Logic App Operator role to the Developers group.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the Logic App Operator role allows users to perform runtime operations on logic apps, such as triggering, enabling, disabling, and viewing runs and history. However, it does not provide the permissions required to create, update, or delete logic apps. This means that assigning the Logic App Operator role to the Developers group does not fulfill the requirement to allow them to create Azure Logic Apps."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#logic-app-operator"],"images":[],"topic":"identity","needsImage":false},{"id":"2-39","test":2,"number":39,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named Bluerock.com and an Azure subscription called Subscription1. Within Bluerock.com, there is a security group named Developers. Within Subscription1, there is a resource group named Dev.","You must grant the Developers group permissions that allow them to create Azure Logic Apps within the Dev resource group.","Proposed solution: At the Subscription1 scope, you grant the Developers group the DevTest Labs User role.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the DevTest Labs User role allows users to connect to, start, restart, and shut down virtual machines in Azure DevTest Labs. It does not provide permissions to create Azure Logic Apps. The ability to create Logic Apps requires a role such as Logic App Contributor or Contributor, which explicitly includes permissions for managing logic apps. Therefore, assigning the DevTest Labs User role does not meet the stated requirement."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#devtest-labs-user"],"images":[],"topic":"identity","needsImage":false},{"id":"2-40","test":2,"number":40,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named Bluerock.com and an Azure subscription called Subscription1. Within Bluerock.com, there is a security group named Developers. Within Subscription1, there is a resource group named Dev.","You must grant the Developers group permissions that allow them to create Azure Logic Apps within the Dev resource group.","Proposed solution: At the Subscription1 scope, you grant the Developers group the Logic App Contributor role.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because the Logic App Contributor role grants permissions to create and manage Azure Logic Apps within a specified scope, such as a subscription or resource group. This role enables the Developers group to create Azure Logic Apps in the Dev resource group. While the Logic App Contributor role allows for creation and management, it does not permit assigning or modifying access to these Logic Apps, which is not a requirement in this scenario.","- The Logic App Operator role only allows actions such as reading, enabling, or disabling Logic Apps but does not permit their creation or editing, making it insufficient for the stated goal.","- The Logic App Contributor role meets the goal by enabling the necessary level of management without over-provisioning permissions."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#logic-app-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"2-41","test":2,"number":41,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named Bluerock.com and an Azure subscription called Subscription1. Within Bluerock.com, there is a security group named Developers. Within Subscription1, there is a resource group named Dev.","You must grant the Developers group permissions that allow them to create Azure Logic Apps within the Dev resource group.","Proposed solution: At the Subscription1 scope, you grant the Developers group the Logic App Operator role.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the Logic App Operator role only provides permissions to read, enable, and disable Azure Logic Apps. It does not grant permissions to create or update Logic Apps. To allow the Developers group to create Azure Logic Apps in the Dev resource group, they need the Logic App Contributor role, which explicitly grants creation and management rights for Logic Apps."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#logic-app-operator"],"images":[],"topic":"identity","needsImage":false},{"id":"2-42","test":2,"number":42,"stem":["You manage an Azure Storage account called storage1.","Within storage1, you configure a custom encryption scope named Scope1.","You now need to determine which types of storage data can be protected by applying Scope1.","Which storage types support encryption by using an encryption scope?"],"options":[{"text":"file shares only","correct":false},{"text":"containers only","correct":true},{"text":"file shares and containers only","correct":false},{"text":"containers and tables only","correct":false},{"text":"file shares, containers, and tables only","correct":false},{"text":"file shares, containers, tables, and queues","correct":false}],"explanation":["`containers only` is correct because encryption scopes in Azure Storage are applicable to Azure Blob Storage and Data Lake Gen2 storage accounts. Since blobs are stored within containers, encryption scopes can be used to encrypt containers, but not other storage types such as file shares, tables, or queues."],"references":[],"images":[],"topic":"storage","needsImage":false},{"id":"2-43","test":2,"number":43,"stem":["An Azure subscription contains eight virtual machines and the following resources:","You are required to configure network access for VNet1 while meeting these conditions:","- Virtual machines in VNet1 must be able to communicate with virtual machines in VNet2 over the Microsoft backbone network.","- Virtual machines in VNet1 must be able to securely access storage1, storage2, and Microsoft Entra using the Microsoft backbone.","To satisfy these requirements, you plan to use service endpoints.","What is the minimum number of service endpoints that must be enabled on VNet1?"],"options":[{"text":"1","correct":true},{"text":"2","correct":false},{"text":"3","correct":false},{"text":"5","correct":false}],"explanation":["`1` is correct because we can use 1 service endpoint for all storage accounts deployed in the same region. Apart from this, the service endpoint is not needed for Microsoft Entra, because VMs accessing Microsoft Entra users (e.g., for user management, authentication, or authorization purposes) relies on Microsoft Entra's authentication and authorization mechanisms, and it doesn't require a service endpoint. Microsoft Entra is a cloud-based identity and access management service that operates independently of a VNet's service endpoints.","Setting up a service endpoint for Microsoft Entra can be advantageous in specific situations, like when VMs require secure access to Microsoft Entra-related APIs. However, it's not mandatory for VMs to connect with Microsoft Entra users or entities.","While it's possible to use two service endpoints for two separate storage accounts, the question asks for the least number of endpoints necessary."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview","https://docs.microsoft.com/en-us/azure/storage/common/storage-network-security","https://docs.microsoft.com/en-us/azure/key-vault/general/network-security"],"images":["assets/0f65370a71e68a65.png"],"topic":"identity","needsImage":true},{"id":"2-58","test":2,"number":58,"stem":["You have an Azure subscription that contains virtual machines running Windows Server, configured as shown in the table below:","You create the following DNS resources:","- A public Azure DNS zone named adatum.com","- A private Azure DNS zone named contoso.com","You then create a virtual network link between the contoso.com private DNS zone and VNET2, with auto-registration enabled.","True or False:","`\"When VM1 starts, a DNS record for VM1 is created in the contoso.com DNS zone.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM1 is in VNET2, and VNET2 is linked to the `contoso.com` private DNS zone with auto-registration enabled. Azure will automatically register the DNS record for VM1 in the `contoso.com` zone. The DNS suffix configured inside the VM (e.g., `contoso.com`) does not affect auto-registration; Azure registers the VM in the zone linked to its VNet, not based on the VM’s internal settings.","**Reference(s):","- https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","- https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances?tabs=redhat"],"references":[],"images":["assets/b2ce86a05b36a844.png","assets/f7b86200c8361be6.png"],"topic":"identity","needsImage":true},{"id":"2-59","test":2,"number":59,"stem":["You have an Azure subscription that contains virtual machines running Windows Server, configured as shown in the table below:","You create the following DNS resources:","- A public Azure DNS zone named adatum.com","- A private Azure DNS zone named contoso.com","You then create a virtual network link between the contoso.com private DNS zone and VNET2, with auto-registration enabled.","True or False:","`\"When VM2 starts, a DNS record for VM2 is created in the contoso.com DNS zone.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM2 is also in VNET2, which is linked to the `contoso.com` private DNS zone with auto-registration enabled. Azure will register VM2’s DNS record in `contoso.com`, regardless of any DNS suffix configured in the VM's OS. Azure Private DNS zones do not consider the OS-configured DNS suffix; they rely solely on the VNet linkage and auto-registration settings.","Reference(s):**","- https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","- https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances?tabs=redhat"],"references":[],"images":["assets/b2ce86a05b36a844.png","assets/f7b86200c8361be6.png"],"topic":"identity","needsImage":true},{"id":"2-60","test":2,"number":60,"stem":["You have an Azure subscription that contains virtual machines running Windows Server, configured as shown in the table below:","You create the following DNS resources:","- A public Azure DNS zone named adatum.com","- A private Azure DNS zone named contoso.com","You then create a virtual network link between the contoso.com private DNS zone and VNET2, with auto-registration enabled.","True or False:","`\"When VM3 starts, a DNS record for VM3 is created in the adatum.com DNS zone.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because VM3 is in VNET2, and VNET2 is linked only to the contoso.com private DNS zone with auto-registration enabled. While VM3 has the DNS suffix adatum.com configured at the OS level, this suffix is ignored for auto-registration purposes. Also, adatum.com is a public Azure DNS zone, and Azure does not support auto-registration into public DNS zones. Therefore, when VM3 is registered through the private DNS zone auto-registration process, its DNS record will be created in contoso.com, not adatum.com."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-overview","https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances?tabs=redhat"],"images":["assets/5a1d483bcf90e257.png","assets/f7b86200c8361be6.png"],"topic":"identity","needsImage":true},{"id":"2-61","test":2,"number":61,"stem":["You are reviewing alert instances in Azure Monitor.","The alert list displays four total alerts, all with a severity level of Verbose (Severity 4).","There are:","- Two instances of Alert2, each with:","- Alert condition: Fired","- User response: New","- Fired time: 4/29/2022, 2:09 PM","- Two instances of Alert1, each with:","- Alert condition: Fired","- User response: Closed","- Fired time: 4/29/2022, 2:04 PM","Based on the information presented, select the answer choice that completes the following statement correctly.","“For Alert1, User response _______________________.”"],"options":[{"text":"cannot be modified","correct":false},{"text":"can only be changed back to New","correct":false},{"text":"can only be changed to Acknowledged","correct":false},{"text":"can be updated to either New or Acknowledged","correct":true}],"explanation":["`can be updated to either New or Acknowledged` is the correct option because in Azure Monitor, an alert's status can be changed between New, Acknowledged, and Closed at any point based on the current state or requirement. Even if an alert is marked as Closed, it can be reopened and transitioned back to New or Acknowledged. This flexibility allows teams to revisit alerts and reassess their status as conditions change."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/training/modules/incident-response-with-alerting-on-azure/"],"images":[],"topic":"monitor","needsImage":false},{"id":"2-62","test":2,"number":62,"stem":["You are reviewing alert instances in Azure Monitor.","The alert list displays four total alerts, all with a severity level of Verbose (Severity 4).","There are:","- Two instances of Alert2, each with:","- Alert condition: Fired","- User response: New","- Fired time: 4/29/2022, 2:09 PM","- Two instances of Alert1, each with:","- Alert condition: Fired","- User response: Closed","- Fired time: 4/29/2022, 2:04 PM","Based on the information presented, select the answer choice that completes the following statement correctly.","“For Alert2, User response _______________________.”"],"options":[{"text":"cannot be modified","correct":false},{"text":"can only be changed to Acknowledged","correct":false},{"text":"can only be changed to Closed","correct":false},{"text":"can be updated to either Acknowledged or Closed","correct":true}],"explanation":["`can be updated to either Acknowledged or Closed` is the correct option because an Azure alert currently marked as New can transition to either Acknowledged or Closed, depending on how the issue is being managed. Azure Monitor allows flexibility in alert status transitions, enabling teams to track, acknowledge, or resolve alerts effectively.","`cannot be modified` is incorrect because Azure Monitor supports transitions between alert statuses.","`can only be changed to Acknowledged` is incorrect because the alert can also be transitioned to Closed.","`can only be changed to closed` is incorrect because the alert can also be transitioned to Acknowledged."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/training/modules/incident-response-with-alerting-on-azure"],"images":[],"topic":"monitor","needsImage":false},{"id":"2-63","test":2,"number":63,"stem":["You have an Azure subscription that includes a resource group named RG1.","You intend to deploy resources to RG1 by using an Azure Resource Manager (ARM) template named template1. The deployment must meet the following conditions:","- Deploy new resources to RG1.","- All existing resources in RG1 must be deleted before deployment.","You are using the following Azure PowerShell command, which is currently incomplete:","Which value should you choose for `Code Segment A`"],"options":[{"text":"-Name","correct":false},{"text":"-QueryString","correct":false},{"text":"-ResourceGroupName","correct":true},{"text":"-Tag","correct":false}],"explanation":["`-ResourceGroupName` is the correct option because when deploying an Azure Resource Manager (ARM) template to a specific resource group using the New-AzResourceGroupDeployment command, the -ResourceGroupName parameter is used to specify the target resource group where resources will be deployed.","`-Name` is incorrect because this parameter is used to provide a deployment name, not a resource group name.","`-QueryString` is incorrect because it is not a valid parameter for specifying the target resource group in the context of New-AzResourceGroupDeployment.","`-Tag` is incorrect because it is used to assign metadata tags to resources, not to specify the resource group."],"references":["https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azresourcegroupdeployment","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deployment-manager-overview"],"images":["assets/b2b26f32d334fdb5.png"],"topic":"identity","needsImage":true},{"id":"2-64","test":2,"number":64,"stem":["You have an Azure subscription that includes a resource group named RG1.","You intend to deploy resources to RG1 by using an Azure Resource Manager (ARM) template named template1. The deployment must meet the following conditions:","- Deploy new resources to RG1.","- All existing resources in RG1 must be deleted before deployment.","You are using the following Azure PowerShell command, which is currently incomplete:","Which value should you choose for `Code Segment B`?"],"options":[{"text":"All","correct":false},{"text":"Complete","correct":true},{"text":"Incremental","correct":false}],"explanation":["`Complete` is the correct option because the Complete deployment mode ensures that all existing resources in the specified resource group are deleted if they are not defined in the ARM template. This mode is ideal for scenarios where you want to ensure that the resource group exactly matches the template's definition, removing any unnecessary or outdated resources.","`All` is incorrect because it is not a valid mode for the New-AzResourceGroupDeployment command.","`Incremental` is incorrect because, in Incremental mode, only the resources specified in the template are updated or created, and existing resources not mentioned in the template remain unchanged. This does not meet the requirement to remove all existing resources."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deployment-modes","https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azresourcegroupdeployment"],"images":["assets/b2b26f32d334fdb5.png"],"topic":"identity","needsImage":true},{"id":"2-65","test":2,"number":65,"stem":["You have an Azure subscription that includes a virtual machine named VM1.","VM1 hosts a financial reporting application (App1) that is designed to run as a single active instance only.","At the end of every month, App1 performs intensive processing, which causes CPU utilization on VM1 to spike significantly.","You are required to create an Azure Automation scheduled runbook that temporarily improves the CPU performance of VM1 during this monthly processing window.","Which action should the runbook perform?"],"options":[{"text":"Move VM1 into a virtual machine scale set so that compute capacity can scale automatically.","correct":false},{"text":"Install the Azure Performance Diagnostics extension on VM1 to analyze CPU bottlenecks.","correct":false},{"text":"Change the virtual machine size of VM1 to a SKU that provides more vCPUs and processing power.","correct":true},{"text":"Request an increase to the subscription’s vCPU quota to allow additional processors.","correct":false},{"text":"Apply a Desired State Configuration (DSC) extension to VM1 to optimize system settings.","correct":false}],"explanation":["`Change the virtual machine size of VM1 to a SKU that provides more vCPUs and processing power` is correct as we need to add more processing power to the machine, which can be achieved by increasing the size of the VM. This approach allows scaling vertically by assigning more vCPUs or memory resources, ensuring the virtual machine can handle the increased CPU demand at the end of each month when the financial reporting application runs.","`Install the Azure Performance Diagnostics extension on VM1 to analyze CPU bottlenecks` is incorrect as this agent is primarily used for collecting diagnostic logs and performance data from the virtual machine into Azure Monitor. It does not enhance the processing power of the VM, which is the core requirement in this scenario.","`Move VM1 into a virtual machine scale set so that compute capacity can scale automatically` is incorrect because a scale set runs identical instances of a VM to handle increased load horizontally. However, the financial reporting application running on VM1 does not support multiple active instances, rendering this option unsuitable.","`Request an increase to the subscription’s vCPU quota to allow additional processors` is incorrect because increasing the vCPU quota is only necessary when the subscription has exhausted its vCPU limit. In this scenario, we only need to increase the resources of a single virtual machine, not the overall quota for the subscription.","`Apply a Desired State Configuration (DSC) extension to VM1 to optimize system settings` is incorrect as DSC is used to enforce consistent configurations across multiple virtual machines. This approach does not address the requirement to increase the processing power of a single VM for a specific period."],"references":["https://docs.microsoft.com/en-us/azure/virtual-machines/windows/resize-vm"],"images":[],"topic":"identity","needsImage":false},{"id":"2-66","test":2,"number":66,"stem":["You are working in an Azure subscription and plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template.","The template configuration enables several data protection features for the Blob service, including blob versioning, soft delete, container soft delete, and point-in-time restore with specific retention periods.","{","\"$schema\": \"http://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"resources\": [","{","\"name\": \"storage1\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"apiVersion\": \"2021-08-01\",","\"location\": \"East US\",","\"properties\": {","\"allowBlobPublicAccess\": true,","\"defaultToOAuthAuthentication\": false,","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"defaultAction\": \"Allow\",","\"ipRules\": []","}","},","\"sku\": {","\"name\": \"Standard_LRS\"","},","\"kind\": \"StorageV2\"","},","{","\"name\": \"storage1/default\",","\"type\": \"Microsoft.Storage/storageAccounts/blobServices\",","\"apiVersion\": \"2021-08-01\",","\"properties\": {","\"restorePolicy\": {","\"enabled\": true,","\"days\": 6","},","\"deleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"containerDeleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"changeFeed\": {","\"enabled\": true","},","\"isVersioningEnabled\": true","},","\"dependsOn\": [","\"[concat('Microsoft.Storage/storageAccounts/', 'storage1')]\"","]","}","]","}","True or False:","`\"Changes made to the data in storage1 can be rolled back after seven days\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because the configuration specifies a restorePolicy with the following settings:","- \"enabled\": true","- \"days\": 6\"","This means the maximum duration for point-in-time recovery of blob data is 6 days. Any changes made beyond this period cannot be rolled back. The statement specifically mentions rolling back data changes after 7 days, which exceeds the configured recovery window.","The deleteRetentionPolicy and containerDeleteRetentionPolicy are both set to 7 days, but these policies only apply to deleted blobs and containers. They do not allow point-in-time recovery of modified data beyond the 6-day limit set in the restore policy."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/anonymous-read-access-configure","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-overview","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-enable?tabs=portal","https://learn.microsoft.com/en-us/azure/templates/microsoft.storage/storageaccounts/blobservices?pivots=deployment-language-arm-template#restorepolicyproperties-1"],"images":[],"topic":"identity","needsImage":false},{"id":"2-67","test":2,"number":67,"stem":["You are working in an Azure subscription and plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template.","The template configuration enables several data protection features for the Blob service, including blob versioning, soft delete, container soft delete, and point-in-time restore with specific retention periods.","{","\"$schema\": \"http://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"resources\": [","{","\"name\": \"storage1\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"apiVersion\": \"2021-08-01\",","\"location\": \"East US\",","\"properties\": {","\"allowBlobPublicAccess\": true,","\"defaultToOAuthAuthentication\": false,","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"defaultAction\": \"Allow\",","\"ipRules\": []","}","},","\"sku\": {","\"name\": \"Standard_LRS\"","},","\"kind\": \"StorageV2\"","},","{","\"name\": \"storage1/default\",","\"type\": \"Microsoft.Storage/storageAccounts/blobServices\",","\"apiVersion\": \"2021-08-01\",","\"properties\": {","\"restorePolicy\": {","\"enabled\": true,","\"days\": 6","},","\"deleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"containerDeleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"changeFeed\": {","\"enabled\": true","},","\"isVersioningEnabled\": true","},","\"dependsOn\": [","\"[concat('Microsoft.Storage/storageAccounts/', 'storage1')]\"","]","}","]","}","True or False:","`\"Only users who are geographically located in the East US Azure region are permitted to access storage1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because there is nothing in the ARM template that restricts network access to the East US region. The `\"location\": \"East US\"` property only specifies where the storage account is deployed — it does not limit who can access it. The `networkAcls` configuration explicitly allows all traffic with `\"defaultAction\": \"Allow\"` and contains no IP rules or virtual network restrictions. This means users from any region can connect to `storage1` as long as they have valid credentials.","The allowBlobPublicAccess property in the template controls anonymous blob access, not regional access. Since no firewall, IP restrictions, or private endpoint configurations are defined, the account remains globally accessible over the internet."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/anonymous-read-access-configure","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-overview","https://learn.microsoft.com/en-us/azure/storage/blobs/versioning-enable?tabs=portal","https://learn.microsoft.com/en-us/azure/templates/microsoft.storage/storageaccounts/blobservices?pivots=deployment-language-arm-template#restorepolicyproperties-1"],"images":[],"topic":"identity","needsImage":false},{"id":"2-68","test":2,"number":68,"stem":["You are working in an Azure subscription and plan to deploy a storage account named storage1 by using an Azure Resource Manager (ARM) template.","The template configuration enables several data protection features for the Blob service, including blob versioning, soft delete, container soft delete, and point-in-time restore with specific retention periods.","{","\"$schema\": \"http://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"resources\": [","{","\"name\": \"storage1\",","\"type\": \"Microsoft.Storage/storageAccounts\",","\"apiVersion\": \"2021-08-01\",","\"location\": \"East US\",","\"properties\": {","\"allowBlobPublicAccess\": true,","\"defaultToOAuthAuthentication\": false,","\"networkAcls\": {","\"bypass\": \"AzureServices\",","\"defaultAction\": \"Allow\",","\"ipRules\": []","}","},","\"sku\": {","\"name\": \"Standard_LRS\"","},","\"kind\": \"StorageV2\"","},","{","\"name\": \"storage1/default\",","\"type\": \"Microsoft.Storage/storageAccounts/blobServices\",","\"apiVersion\": \"2021-08-01\",","\"properties\": {","\"restorePolicy\": {","\"enabled\": true,","\"days\": 6","},","\"deleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"containerDeleteRetentionPolicy\": {","\"enabled\": true,","\"days\": 7","},","\"changeFeed\": {","\"enabled\": true","},","\"isVersioningEnabled\": true","},","\"dependsOn\": [","\"[concat('Microsoft.Storage/storageAccounts/', 'storage1')]\"","]","}","]","}","True or False:","`\"Data in storage1 is replicated across three instances within the East US Azure region.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because the sku property in the ARM template specifies:","- \"name\": \"Standard_LRS\"","LRS (Locally Redundant Storage) ensures that three copies of the data are maintained within a single Azure region (East US in this case). These copies are stored synchronously across multiple fault domains and update domains within the same region to provide redundancy against hardware failures.","If regional redundancy was intended (e.g., data being replicated to another region), a different SKU like Geo-Redundant Storage (GRS) or Zone-Redundant Storage (ZRS) would have been specified instead of Standard_LRS."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-redundancy"],"images":[],"topic":"identity","needsImage":false},{"id":"2-69","test":2,"number":69,"stem":["You have an Azure subscription that includes the following Azure Container Instances (ACI):","- container1: Deployed in East US, running a Windows image","- container2: Deployed in West US, running a Windows image","- container3: Deployed in East US, running a Linux image","A storage account with an Azure file share named storage1 is created in the East US region.","You need to mount storage1 to supported container instances.","Which container instances can successfully mount storage1?"],"options":[{"text":"container1 only","correct":false},{"text":"container3 only","correct":true},{"text":"container1 and container2 only","correct":false},{"text":"container1 and container3 only","correct":false},{"text":"container1, container2, and container3","correct":false}],"explanation":["`container3 only` is the correct answer because Azure Container Instances (ACI) supports mounting Azure Files only to Linux-based containers, not to Windows-based ones."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-volume-azure-files#limitations"],"images":[],"topic":"identity","needsImage":false},{"id":"2-70","test":2,"number":70,"stem":["You have an Azure subscription that contains the following resource groups:","- RG1: Region: East US","- RG2: Region: West US","You create the following Azure Resource Manager (ARM) template named deploy.json.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {},","\"variables\": {},","\"resources\": [","{","\"type\": \"Microsoft.Resources/resourceGroups\",","\"apiVersion\": \"2018-05-01\",","\"location\": \"eastus\",","\"name\": \"[concat('RG', copyIndex())]\",","\"copy\": {","\"name\": \"copy\",","\"count\": 4","}","}","],","\"outputs\": {}","}","You deploy the template by running the following cmdlet:","`New-AzSubscriptionDeployment -Location westus -TemplateFile deploy.json`","True or False:","`“The template creates a resource group named RG0 in the East US Azure region.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. The ARM template defines a resource group resource type (`Microsoft.Resources/resourceGroups`) and uses a `copy` loop to create 4 resource groups named RG0, RG1, RG2, and RG3. The key detail is the `\"location\": \"eastus\"` line inside the resource definition, which specifies that each of these resource groups should be created in the East US Azure region, regardless of the location specified when deploying the template.","The command used to deploy the template is:","New-AzSubscriptionDeployment -Location westus -TemplateFile deploy.json","The `-Location westus` in this context refers to the location of the deployment metadata, not the location of the resources being created. Therefore, the deployment itself is tracked in West US, but the actual resource groups defined in the template are created in East US as specified in the `\"location\"` property of the resource block.","Hence, RG0 is created in East US, making the statement true.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-71","test":2,"number":71,"stem":["You have an Azure subscription that contains the following resource groups:","- RG1: Region: East US","- RG2: Region: West US","You create the following Azure Resource Manager (ARM) template named deploy.json.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {},","\"variables\": {},","\"resources\": [","{","\"type\": \"Microsoft.Resources/resourceGroups\",","\"apiVersion\": \"2018-05-01\",","\"location\": \"eastus\",","\"name\": \"[concat('RG', copyIndex())]\",","\"copy\": {","\"name\": \"copy\",","\"count\": 4","}","}","],","\"outputs\": {}","}","You deploy the template by running the following cmdlet:","`New-AzSubscriptionDeployment -Location westus -TemplateFile deploy.json`","True or False:","`“The template creates four new resource groups.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. While the ARM template is intended to create four resource groups (RG0, RG1, RG2, RG3), the table provided in the question shows that RG1 and RG2 already exist in the subscription. Azure Resource Manager (ARM) templates do not overwrite existing resource groups — attempting to create a resource group with a name that already exists will cause that specific deployment iteration to fail, unless the template logic explicitly handles existing resources (which this one does not).","As a result:","- RG0 and RG3 will be created","- RG1 and RG2 will fail to deploy because they already exist.","Reference(s.):**","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-72","test":2,"number":72,"stem":["You have an Azure subscription that contains the following resource groups:","- RG1: Region: East US","- RG2: Region: West US","You create the following Azure Resource Manager (ARM) template named deploy.json.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"parameters\": {},","\"variables\": {},","\"resources\": [","{","\"type\": \"Microsoft.Resources/resourceGroups\",","\"apiVersion\": \"2018-05-01\",","\"location\": \"eastus\",","\"name\": \"[concat('RG', copyIndex())]\",","\"copy\": {","\"name\": \"copy\",","\"count\": 4","}","}","],","\"outputs\": {}","}","You deploy the template by running the following cmdlet:","`New-AzSubscriptionDeployment -Location westus -TemplateFile deploy.json`","True or False:","`“The template creates a resource group named RG3 in the West US Azure region.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. The ARM template defines the creation of resource groups using the `Microsoft.Resources/resourceGroups` type and specifies the `\"location\": \"eastus\"` inside the resource definition. This means all resource groups created by the template, including RG3, are created in the East US region.","While the deployment is executed using the command:","New-AzSubscriptionDeployment -Location westus -TemplateFile deploy.json","the `-Location westus` argument only defines the deployment metadata region, not the region of the resources being deployed. The actual resource group location is explicitly defined in the template as `\"eastus\"`.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-73","test":2,"number":73,"stem":["You are planning to migrate a distributed on-premises application named App1 to Azure.","After the migration is complete:","- App1 will run across nine Azure virtual machines","- The application must remain highly available during planned Azure platform maintenance","You must design the solution so that at least eight virtual machines remain operational whenever Azure performs planned maintenance activities.","Which solution should you implement?"],"options":[{"text":"Create a single virtual machine scale set configured with 12 VM instances.","correct":false},{"text":"Create a single virtual machine scale set configured with 10 VM instances.","correct":true},{"text":"Create one availability set configured with three fault domains and one update domain.","correct":false},{"text":"Create one availability set configured with 10 update domains and one fault domain.","correct":false}],"explanation":["`Create a single virtual machine scale set configured with 10 VM instances` is the correct answer here. Azure Virtual Machine Scale Sets (VMSS) automatically distribute VM instances across fault and update domains to provide high availability. By default, VMSS placement groups are configured with 5 fault domains and 5 update domains, and update domains are updated one at a time during planned Azure maintenance.","With 10 instances spread across 5 update domains, each update domain will host 2 VMs. During a planned update, only one update domain is affected at a time, meaning at most 2 out of 10 VMs are impacted, and at least 8 VMs remain running, which satisfies the requirement.","`Create a single virtual machine scale set configured with 12 VM instances` is incorrect because it exceeds the requirement unnecessarily. While it would also ensure 8 VMs are running during maintenance, it's not optimal in terms of cost and resource efficiency.","`Create one availability set configured with three fault domains and one update domain` is incorrect because a single update domain means all VMs in the set could be impacted at once during planned maintenance, violating the requirement of keeping at least 8 VMs up.","`Create one availability set configured with 10 update domains and one fault domain` is incorrect because, although Azure can support this availability set configuration, it is not the best solution for this scenario. The requirement is to keep at least eight virtual machines operational during planned Azure platform maintenance for an application that runs across nine virtual machines. A single virtual machine scale set with 10 VM instances provides a more suitable and scalable design because Azure distributes the instances across update domains and updates one update domain at a time during planned maintenance. This ensures that at most two VMs are affected at a time and at least eight VMs remain operational.","Reference(s.):","- https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-faq","- https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-use-availability-zones","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"2-74","test":2,"number":74,"stem":["You have an Azure subscription that contains the following vaults:","- Recovery1 – Recovery Services vault","- Backup1 – Azure Backup vault","You deploy two virtual machines:","- VM1 – Windows Server, configured with Azure Disk Encryption","- VM2 – Linux, configured with Trusted launch","The following backup policies are configured:","True or False:","`“VM1 can be backed up by using Policy1.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. VM1 is a Windows Server virtual machine that uses Azure Disk Encryption and is intended to be backed up using a Recovery Services vault. According to Azure backup support policies, Standard policy types in Recovery Services vaults fully support backing up Windows VMs with Azure Disk Encryption enabled. Policy1, being a Standard policy in the Recovery1 vault, is compatible with this scenario.","There is no limitation that prevents using a Standard policy for encrypted Windows VMs when the vault type is Recovery Services vault. Azure officially supports encrypted disks with both Standard and Enhanced policies for Windows VMs.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"],"references":[],"images":["assets/6f3287b506ef90b7.png"],"topic":"identity","needsImage":true},{"id":"2-75","test":2,"number":75,"stem":["You have an Azure subscription that contains the following vaults:","- Recovery1 – Recovery Services vault","- Backup1 – Azure Backup vault","You deploy two virtual machines:","- VM1 – Windows Server, configured with Azure Disk Encryption","- VM2 – Linux, configured with Trusted launch","The following backup policies are configured:","True or False:","`“VM2 can be backed up by using Policy3.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. Policy3 is associated with Backup1, which is an Azure Backup vault. However, Azure Backup vaults do not support backup of Azure virtual machines. Instead, Recovery Services vaults are required for backing up Azure VMs, whether the VM is Windows or Linux, and regardless of whether it uses features like Trusted Launch.","Additionally, Policy3 is marked as Not applicable, indicating that it does not contain backup configurations applicable for VM workloads. Azure Backup vaults are designed to support specific workloads such as:","- Azure Disks","- Azure Blobs (in Azure Storage)","- Azure Database for PostgreSQL servers","- Azure Kubernetes Services (AKS)","Since VM2 is a virtual machine, it cannot be backed up using Policy3 in Backup1.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix","- https://learn.microsoft.com/en-us/azure/backup/backup-vault-overview","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"],"references":[],"images":["assets/6f3287b506ef90b7.png"],"topic":"identity","needsImage":true},{"id":"2-76","test":2,"number":76,"stem":["You have an Azure subscription that contains the following vaults:","- Recovery1 – Recovery Services vault","- Backup1 – Azure Backup vault","You deploy two virtual machines:","- VM1 – Windows Server, configured with Azure Disk Encryption","- VM2 – Linux, configured with Trusted launch","The following backup policies are configured:","True or False:","`“VM2 can be backed up by using Policy2.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer. Enhanced backup policies are used specifically for protecting Azure virtual machines in Recovery Services vaults, and they support advanced scenarios such as Trusted Launch virtual machines. Since Policy2 is defined as an Enhanced policy, it must be associated with a Recovery Services vault, because Backup vaults do not support VM backup policies of this type.","Even though Recovery2 is not explicitly listed among the available vaults, the presence of an Enhanced policy implicitly indicates that it belongs to a Recovery Services vault. Azure Backup supports protecting Linux virtual machines configured with Trusted Launch when using Enhanced policies in a Recovery Services vault. Therefore, VM2 meets the requirements for being backed up using Policy2.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix","- https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-enhanced-policy?tabs=azure-portal","- https://learn.microsoft.com/en-us/azure/virtual-machines/trusted-launch"],"references":[],"images":["assets/6f3287b506ef90b7.png"],"topic":"identity","needsImage":true},{"id":"2-77","test":2,"number":77,"stem":["You are planning to deploy a new Azure App Service application named WebApp1. The configuration must satisfy the following conditions:","- WebApp1 must support validating a custom domain name: app.bluerock.com.","- WebApp1 must be able to automatically scale up to a maximum of eight instances.","- The selected solution should keep costs low and reduce ongoing administrative overhead as much as possible.","Based on these requirements, which App Service pricing plan should you select for WebApp1?"],"options":[{"text":"Basic","correct":false},{"text":"Free","correct":false},{"text":"Shared","correct":false},{"text":"Standard","correct":true}],"explanation":["`Standard` is correct. The Standard App Service plan supports both custom domain name verification and auto-scaling, which are required for WebApp1. It allows binding of a custom domain such as `app.bluerock.com` and supports automatic scaling up to 10 instances, which satisfies the requirement to scale up to eight instances. Additionally, it offers a balance between cost and functionality, minimizing administrative effort while supporting enterprise-grade features.","`Basic` is incorrect because although it supports custom domains, it does not support auto-scaling. The scaling process under the Basic tier is manual, which does not meet the requirement for automatic scaling.","`Free` is incorrect because it does not support custom domain binding or scaling beyond a single instance. It is intended for development or testing scenarios with limited capabilities.","`Shared` is incorrect because it also lacks support for custom domains and does not offer scalability. Like the Free tier, it is meant for lightweight, shared environments with constrained features.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/app-service/overview-hosting-plans","- https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up","- https://azure.microsoft.com/en-us/pricing/details/app-service/windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"2-78","test":2,"number":78,"stem":["You are planning to deploy a new Azure App Service application named WebApp1. The configuration must satisfy the following conditions:","- WebApp1 must support validating a custom domain name: app.bluerock.com.","- WebApp1 must be able to automatically scale up to a maximum of eight instances.","- The selected solution should keep costs low and reduce ongoing administrative overhead as much as possible.","Based on these requirements, which record type should you use to verify the domain?"],"options":[{"text":"A","correct":false},{"text":"AAAA","correct":false},{"text":"PTR","correct":false},{"text":"TXT","correct":true}],"explanation":["`TXT` is the correct answer here. To verify a custom domain name like `app.bluerock.com` for an Azure App Service app (such as WebApp1), Azure requires the domain owner to prove ownership by adding a `TXT` record to the domain’s DNS zone. This record contains a unique verification string provided by Azure and is the standard method for verifying custom domains in App Service. It enables the service to confirm that you have administrative control over the domain before allowing it to be associated with the app.","`A` is incorrect because while it maps a domain name to an IPv4 address, it is not used for domain verification. It is generally used for pointing domain names to web servers or hosting environments.","`AAAA` is incorrect because it maps a domain to an IPv6 address and, like the `A` record, is used for routing rather than ownership verification.","`PTR` is incorrect because it is used for reverse DNS lookups (resolving IP addresses to domain names), which is unrelated to domain ownership verification for web apps.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/app-service/app-service-web-tutorial-custom-domain","- https://learn.microsoft.com/en-us/azure/app-service/manage-custom-dns-buy-domain","- https://learn.microsoft.com/en-us/azure/dns/dns-web-sites-custom-domain"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"2-79","test":2,"number":79,"stem":["Your on-premises environment includes the following resource:","- An SMB file share named Share1","Your Azure subscription contains these resources:","- A web app named webapp1","- An Azure virtual network named VNET1","You need to ensure that webapp1 can connect to Share1.","Which Azure resource should you deploy to meet this requirement?"],"options":[{"text":"an Azure Virtual Network Gateway","correct":true},{"text":"an Azure Application Gateway","correct":false},{"text":"a Microsoft Entra Application Proxy","correct":false}],"explanation":["`an Azure Virtual Network Gateway` is the correct answer here. Since `Share1` is an SMB file share hosted on-premises, and the web app (`webapp1`) is hosted in Azure, you need to establish network-level connectivity between your on-premises network and Azure. This can be accomplished by using an Azure Virtual Network Gateway in combination with either a site-to-site VPN or ExpressRoute connection. Once that private connectivity is established, webapp1 can access resources like the SMB share via VNet Integration, assuming webapp1 is integrated with `VNET1`.","`an Azure Application Gateway` is incorrect because Application Gateway is used for HTTP/HTTPS load balancing and web traffic routing; it does not provide connectivity to on-premises file shares or private networks.","`a Microsoft Entra Application Proxy` is incorrect because Entra Application Proxy is designed to provide secure remote access to on-premises web applications, not file shares like SMB. It works at the application layer, not the network layer.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/vpn-gateway/tutorial-site-to-site-portal","- https://learn.microsoft.com/en-us/azure/app-service/web-sites-integrate-with-vnet","- https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-80","test":2,"number":80,"stem":["You are planning to upload the disk files of a virtual machine to a storage account named account1 from your on-premises network. The on-premises environment uses the public IP address range 131.107.1.0/24. These disk files will later be used to provision an Azure virtual machine named VM1, which will be connected to a virtual network called VNet1. The address space of VNet1 is 192.168.0.0/24.","You need to configure account1 to meet the following requirements:","- Allow disk files to be uploaded from the on-premises network.","- Allow the uploaded disks to be attached to VM1 after provisioning.","- Block all other access to the storage account.","Which two actions should you perform?"],"options":[{"text":"From the Networking blade of account1, select Allow Azure services on the trusted services list to access this storage account.","correct":false},{"text":"From the Service endpoints blade of VNet1, add a service endpoint.","correct":false},{"text":"From the Networking blade of account1, add the 131.107.1.0/24 IP address range.","correct":true},{"text":"From the Networking blade of account1, add VNet1.","correct":false},{"text":"From the Networking blade of account1, select Enabled from selected virtual networks and IP addresses.","correct":true}],"explanation":["`From the Networking blade of account1, add the 131.107.1.0/24 IP address range` is the correct answer here. Since your on-premises network uses this public IP range, adding it allows connectivity from your location so you can upload the disk files to the Azure storage account. Without adding this IP range, access from your on-premises environment would be denied.","`From the Networking blade of account1, select Enabled from selected virtual networks and IP addresses` is also correct because it activates network-level restrictions and ensures that only the explicitly defined IP ranges and virtual networks have access to the storage account. This setting is necessary to prevent all other access, fulfilling the security requirement.","`From the Networking blade of account1, select Allow Azure services on the trusted services list to access this storage account` is incorrect because this would allow broader Azure services to access the storage account, which violates the requirement to prevent all other access. It provides platform-wide service access beyond your defined IPs and VNets.","`From the Service endpoints blade of VNet1, add a service endpoint` is incorrect because service endpoints do not help in enabling access from on-premises networks. They are intended for traffic routing from Azure virtual networks only.","`From the Networking blade of account1, add VNet1` is incorrect because there is no need to allow VNet1 directly for VM1 to attach the disk during provisioning. Azure handles disk attachment through trusted services internally, and access from the VM at that point is not needed.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview","- https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview"],"references":[],"images":[],"topic":"storage","needsImage":false},{"id":"2-81","test":2,"number":81,"stem":["You have an Azure subscription with a Microsoft Entra ID P1 license. You need to enable self-service password reset for all users and ensure that, during registration, users are required to answer four security questions.","Which two settings should you use?"],"options":[{"text":"Properties","correct":true},{"text":"Authentication methods","correct":true},{"text":"Registration","correct":false},{"text":"Notifications","correct":false},{"text":"Customization","correct":false},{"text":"On-premises integration","correct":false}],"explanation":["Properties is the correct answer because this setting allows you to enable Self-Service Password Reset (SSPR) for either a specific group or for all users in the tenant. This directly meets the requirement of enabling SSPR for all users.","Authentication methods is the correct answer because this setting is used to configure how many and which authentication methods users must provide to reset their passwords. It specifically allows you to require users to answer a minimum number of security questions, which fulfills the requirement to answer four questions during registration.","Registration is incorrect because this setting controls whether users are prompted to register their authentication methods for SSPR and MFA, but it does not allow you to enable SSPR itself or configure how many questions must be answered.","Notifications is incorrect because this setting only manages whether users and administrators receive email notifications for password reset events; it does not configure SSPR eligibility or authentication question settings.","Customization is incorrect because this setting is used for UI branding and does not affect SSPR registration or authentication method configuration.","On-premises integration is incorrect because it is used to configure integration with on-premises Active Directory for password writeback, not to manage SSPR enablement or question requirements.","Reference(s.):","- https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-howitworks","- https://learn.microsoft.com/en-us/entra/identity/authentication/howto-sspr-authenticationdata"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"2-82","test":2,"number":82,"stem":["You have an Azure virtual machine named VM1 and an Azure Key Vault named Vault1. You plan to enable Azure Disk Encryption on VM1 and use a key encryption key (KEK) stored in Vault1.","Before configuring disk encryption, you must ensure that Vault1 is properly prepared to support Azure Disk Encryption.","Which two configuration actions must be performed on Vault1 to meet this requirement?"],"options":[{"text":"Create a new key.","correct":true},{"text":"Select Azure Virtual machines for deployment.","correct":false},{"text":"Select Azure Disk Encryption for volume encryption.","correct":true},{"text":"Configure a key rotation policy.","correct":false},{"text":"Create a new secret.","correct":false}],"explanation":["`Create a new key` is correct because Azure Disk Encryption with a key encryption key (KEK) requires a key vault key (not a secret) to wrap the encryption key used to encrypt the VM disks.","`Select Azure Disk Encryption for volume encryption` is correct because the key vault must have the “Azure Disk Encryption for volume encryption” permission enabled. This allows the disk encryption process to access the key vault during encryption and decryption operations.","`Select Azure Virtual machines for deployment` is incorrect because this setting is related to deployment credentials for virtual machines, not required for enabling encryption.","`Configure a key rotation policy` is incorrect because although key rotation is good practice for long-term security, it's not required to prepare the key vault for Azure Disk Encryption.","`Create a new secret` is incorrect because secrets are not used in KEK-based encryption. The process uses a key, not a secret, to wrap the encryption key."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/windows/disk-encryption-overview","https://learn.microsoft.com/en-us/azure/security/fundamentals/encryption-atrest#azure-disk-encryption","https://learn.microsoft.com/en-us/azure/key-vault/keys/quick-create-portal"],"images":[],"topic":"storage","needsImage":false},{"id":"2-83","test":2,"number":83,"stem":["Your organization purchases a new Azure subscription and creates an ARM template file named deploy.json, as shown in the below exhibit. The template provisions multiple resource groups and applies management locks with different lock levels to specific resource groups by using nested deployments.","After connecting to the subscription, you run the New-AzDeployment cmdlet with the template file and a deployment location of West US as shown below:","`New-AzDeployment -Location westus -TemplateFile “deploy.json”`","Based on this deployment, determine whether the following statement is True or False:","`\"You can deploy a virtual machine to RG1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because the ARM template (`deploy.json`) uses a `copy` loop to create three resource groups (`RG0`, `RG1`, and `RG2`). After creating the resource groups, it deploys a `CanNotDelete` lock on `RG1` and a `ReadOnly` lock on `RG2`. A CanNotDelete lock only prevents deletion of the resource or resource group—it does not block updates or new resource deployments. Therefore, you can still deploy a virtual machine to RG1."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/template-syntax#copy-loop-for-resources"],"images":["assets/01f0ebc254718026.png"],"topic":"identity","needsImage":true},{"id":"2-84","test":2,"number":84,"stem":["Your organization purchases a new Azure subscription and creates an ARM template file named deploy.json, as shown in the below exhibit. The template provisions multiple resource groups and applies management locks with different lock levels to specific resource groups by using nested deployments.","After connecting to the subscription, you run the New-AzDeployment cmdlet with the template file and a deployment location of West US as shown below:","`New-AzDeployment -Location westus -TemplateFile “deploy.json”`","Based on this deployment, determine whether the following statement is True or False:","`\"You can deploy a virtual machine to RG2.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`True` is the correct answer because the ARM template applies a ReadOnly lock to the resource group RG2. A ReadOnly lock prevents any write operations within the resource group, including creating, updating, or deleting resources. Therefore, you cannot deploy a virtual machine or any other resource to RG2 while the lock is in place."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/template-syntax#copy-loop-for-resources"],"images":["assets/01f0ebc254718026.png"],"topic":"identity","needsImage":true},{"id":"2-85","test":2,"number":85,"stem":["Your organization purchases a new Azure subscription and creates an ARM template file named deploy.json, as shown in the below exhibit. The template provisions multiple resource groups and applies management locks with different lock levels to specific resource groups by using nested deployments.","After connecting to the subscription, you run the New-AzDeployment cmdlet with the template file and a deployment location of West US as shown below:","`New-AzDeployment -Location westus -TemplateFile “deploy.json”`","Based on this deployment, determine whether the following statement is True or False:","`\"You can manually create a resource group named RG3.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because although the ARM template includes a `copy` loop to create three resource groups named `RG0`, `RG1`, and `RG2`, it does not restrict or block manual creation of additional resource groups outside of the template. Azure allows users to manually create new resource groups such as `RG3` using the portal, CLI, or PowerShell, provided there are no policy restrictions preventing it."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/manage-resource-groups-portal","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/template-syntax#copy-loop-for-resources"],"images":["assets/01f0ebc254718026.png"],"topic":"identity","needsImage":true},{"id":"2-86","test":2,"number":86,"stem":["You are planning to automate the deployment of a virtual machine scale set that is based on the Windows Server Datacenter image.","As part of the deployment process, you must ensure that all virtual machines created in the scale set automatically have the required web server components installed at provisioning time.","Based on this requirement, determine which two actions you should perform."],"options":[{"text":"Create a new virtual machine scale set in the Azure portal.","correct":false},{"text":"Upload a configuration script that installs the required web server components.","correct":true},{"text":"Update the `extensionProfile` section of the Azure Resource Manager (ARM) template to run the configuration during provisioning.","correct":true},{"text":"Create an Azure Policy to enforce the installation of web server components.","correct":false},{"text":"Create an Azure Automation account to manage post-deployment configuration.","correct":false}],"explanation":["`Upload a configuration script that installs the required web server components` is correct because to automate the installation of web server components (e.g., IIS), you need a PowerShell or DSC (Desired State Configuration) script that defines those installation steps.","`Update the extensionProfile section of the Azure Resource Manager (ARM) template to run the configuration during provisioning` is correct because this section allows you to add VM extensions such as Custom Script Extension or DSC Extension, which execute your uploaded configuration script on each VM instance when the scale set is deployed.","`Create a new virtual machine scale set in the Azure portal` is incorrect for this purpose alone, as it doesn’t inherently ensure web server components are installed unless you use extensions or post-deployment scripts.","`Create an Azure Policy to enforce the installation of web server components` is incorrect because policies are used to enforce resource configurations or compliance—not to deploy software like a web server on VMs.","`Create an Azure Automation account to manage post-deployment configuration` is incorrect because Automation Accounts are used for orchestrating broader tasks like runbooks across Azure, not for provisioning software during VM creation in scale sets."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/tutorial-install-apps-template","https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/custom-script-windows","https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-overview"],"images":[],"topic":"compute","needsImage":false},{"id":"2-87","test":2,"number":87,"stem":["You have an Azure subscription that includes a storage account named storage1. The subscription is associated with a Microsoft Entra tenant named bluerock.com, which is synchronized with an on-premises Active Directory domain. This on-premises domain contains the following security principals:","- User1, which is a user account.","- Computer1, which is a computer account.","In Microsoft Entra tenant, you create a user named User2.","The storage1 account contains an Azure file share named share1 and is configured to use Active Directory–based authentication for Azure Files and has the following configurations.","\"kind\": \"StorageV2\",","\"properties\": {","\"azureFilesIdentityBasedAuthentication\": {","\"directoryServiceOptions\": \"AD\",","\"activeDirectoryProperties\": {","\"domainName\": \"Bluerock.com\",","\"netBiosDomainName\": \"Bluerock.com\",","\"forestName\": \"Bluerock.com\"",". . .","}","}","True or False:","`“You can assign the Storage File Data SMB Share Contributor role to User1 for Share1.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because User1 is a user account that exists in the on-premises Active Directory, which is synced to Microsoft Entra ID (Azure AD). Since Azure Files supports identity-based authentication using AD DS, and the configuration shows that the storage account is using the \"AD\" directoryServiceOptions, you can assign Azure RBAC roles like Storage File Data SMB Share Contributor to an Entra ID user who originates from on-prem AD via synchronization.","This setup enables access control for SMB file shares through Entra ID roles, and User1 qualifies as a principal that can be assigned such roles."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-assign-share-level-permissions?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-active-directory-overview","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-file-data-smb-share-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"2-88","test":2,"number":88,"stem":["You have an Azure subscription that includes a storage account named storage1. The subscription is associated with a Microsoft Entra tenant named bluerock.com, which is synchronized with an on-premises Active Directory domain. This on-premises domain contains the following security principals:","- User1, which is a user account.","- Computer1, which is a computer account.","In Microsoft Entra tenant, you create a user named User2.","The storage1 account contains an Azure file share named share1 and is configured to use Active Directory–based authentication for Azure Files and has the following configurations.","\"kind\": \"StorageV2\",","\"properties\": {","\"azureFilesIdentityBasedAuthentication\": {","\"directoryServiceOptions\": \"AD\",","\"activeDirectoryProperties\": {","\"domainName\": \"Bluerock.com\",","\"netBiosDomainName\": \"Bluerock.com\",","\"forestName\": \"Bluerock.com\"",". . .","}","}","True or False:","`“You can assign the Storage File Data SMB Share Reader role to Computer1 for share1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because Computer1 is a computer account from the on-premises Active Directory. Azure role-based access control (Azure RBAC), including roles like Storage File Data SMB Share Reader, can only be assigned to users, groups, service principals, and managed identities in Microsoft Entra ID. Computer accounts are not valid principals for Azure RBAC role assignments.","While the storage account is configured for Active Directory authentication (`directoryServiceOptions: \"AD\"`), role assignments using Azure RBAC require an Entra ID identity, and Computer1, being a traditional AD computer object, is not eligible."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-assign-share-level-permissions?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-active-directory-overview","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"],"images":[],"topic":"identity","needsImage":false},{"id":"2-89","test":2,"number":89,"stem":["You have an Azure subscription that includes a storage account named storage1. The subscription is associated with a Microsoft Entra tenant named bluerock.com, which is synchronized with an on-premises Active Directory domain. This on-premises domain contains the following security principals:","- User1, which is a user account.","- Computer1, which is a computer account.","In Microsoft Entra tenant, you create a user named User2.","The storage1 account contains an Azure file share named share1 and is configured to use Active Directory–based authentication for Azure Files and has the following configurations.","\"kind\": \"StorageV2\",","\"properties\": {","\"azureFilesIdentityBasedAuthentication\": {","\"directoryServiceOptions\": \"AD\",","\"activeDirectoryProperties\": {","\"domainName\": \"Bluerock.com\",","\"netBiosDomainName\": \"Bluerock.com\",","\"forestName\": \"Bluerock.com\"",". . .","}","}","True or False:","`\"User2 can access share1 over SMB by using identity-based authentication after being assigned the Storage File Data SMB Share Elevated Contributor role.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because User2 is a cloud-only user created directly in Microsoft Entra ID and does not have a corresponding identity in the on-premises Active Directory Domain Services (AD DS) environment.","The storage account storage1 is configured to use on-premises AD DS for Azure Files identity-based authentication, as indicated by `\"directoryServiceOptions\": \"AD\"`. When using AD DS authentication with granular share-level Azure RBAC permissions, the corresponding identity must originate from the on-premises AD DS environment and be represented in Microsoft Entra ID.","User2 exists only in Microsoft Entra ID and therefore cannot authenticate to share1 by using the configured AD DS authentication. Assigning the Storage File Data SMB Share Elevated Contributor role does not change the authentication method or provide User2 with an on-premises AD DS identity.","Therefore, User2 cannot access share1 over SMB by using the configured identity-based authentication, even after the role is assigned."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-active-directory-overview","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-overview","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-file-data-smb-share-elevated-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"2-90","test":2,"number":90,"stem":["You are planning to create an Azure Storage account named storage1, which will host an Azure file share called share1. The file share must support SMB Multichannel, and the overall configuration should be chosen in a way that keeps costs as low as possible.","How should storage1 be configured to meet these requirements?"],"options":[{"text":"Standard performance with locally-redundant storage (LRS)","correct":false},{"text":"Premium performance with locally-redundant storage (LRS)","correct":true},{"text":"Standard performance with zone-redundant storage (ZRS)","correct":false}],"explanation":["`Premium performance with locally redundant storage (LRS)` is correct because SMB Multichannel is only supported on Premium File Shares, which use SSD-based storage. These premium shares deliver high throughput and low latency required for parallel SMB connections. Using LRS keeps costs minimal while maintaining adequate redundancy within a single region.","`Standard performance with LRS` and `Standard performance with ZRS` are incorrect because SMB Multichannel is not available on Standard File Shares, regardless of redundancy type. These tiers are optimized for general file storage and lower-cost scenarios, but they lack the performance capabilities and protocol support needed for SMB Multichannel."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-smb-multichannel-performance"],"images":[],"topic":"storage","needsImage":false},{"id":"3-1","test":3,"number":1,"stem":["You have a Microsoft Entra tenant named apexcore.com.","There are two external partner organizations: ironclad.com and bluerock.com.","Only ironclad.com is configured as a connected organization in Microsoft Entra.","You create an access package as shown in the below exhibit.","The external user lifecycle settings are configured so that when an external user loses their last access package assignment:","- The user is blocked from signing in.","- The user is removed from the directory after 30 days.","True or False:","`“Users from bluerock.com can be assigned to package1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. The access package package1 is configured to allow access requests from \"All configured connected organizations.\" Based on the information given, only ironclad.com is set up as a connected organization. Since bluerock.com is not configured as a connected organization, users from litwareinc.com are not eligible to be assigned to package1."],"references":["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role","https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"3-2","test":3,"number":2,"stem":["You have a Microsoft Entra tenant named apexcore.com.","There are two external partner organizations: ironclad.com and bluerock.com.","Only ironclad.com is configured as a connected organization in Microsoft Entra.","You create an access package as shown in the below exhibit.","The external user lifecycle settings are configured so that when an external user loses their last access package assignment:","- The user is blocked from signing in.","- The user is removed from the directory after 30 days.","True or False:","`“After the 365-day assignment period ends, users from ironclad.com will be removed from Group1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer. When you assign `ironclad` users to Group1 through an access package, their assignment is set to expire after 365 days. At that point, the users’ access package assignment expires, which means:","- They lose access to Group1 and other resources tied to the package.","- Their membership in Group1 is revoked immediately at expiration.","However, this is not the same as being “removed” from the tenant. The external user lifecycle settings add another step:","- After the assignment expires, external users remain in the tenant directory for an additional 30 days.","- During that time, they cannot access Group1 because their assignment has expired, but their guest account still exists in the directory.","- Only after day 395 (365 + 30) are they actually removed from the directory, which finalizes their removal from all groups."],"references":["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role","https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"3-3","test":3,"number":3,"stem":["You have a Microsoft Entra tenant named apexcore.com.","There are two external partner organizations: ironclad.com and bluerock.com.","Only ironclad.com is configured as a connected organization in Microsoft Entra.","You create an access package as shown in the below exhibit.","The external user lifecycle settings are configured so that when an external user loses their last access package assignment:","- The user is blocked from signing in.","- The user is removed from the directory after 30 days.","True or False:","`“Once 395 days have passed, users from ironclad.com will be removed from the apexcore.com tenant.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because, according to the external user lifecycle settings, after a ironclad.com user loses their last assignment to an access package, they are set to be removed from the apexcore.com tenant after 30 days. Given that the access package assignment expires after 365 days, ironclad.com users will be removed from the apexcore.com tenant 30 days later, totaling 395 days from the start of their assignment."],"references":["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role","https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"3-4","test":3,"number":4,"stem":["You have an Azure subscription that includes a resource group named ResGrp1.","ResGrp1 is located in the West Europe region and is used to host temporary resources for a project.","The resource group contains the following resources:","- VM1 is a virtual machine deployed in the North Europe region.","- RGV1 is a Recovery Services vault located in North Europe.","- SQLDB01 is a SQL Server running on an Azure virtual machine in North Europe.","- sa001 is a storage account deployed in West Europe.","The virtual machine SQLDB01 is configured to be backed up to the Recovery Services vault RGV1.","After the project is completed, you attempt to delete ResGrp1 from the Azure portal, but the deletion operation fails.","You need to successfully remove ResGrp1.","What should you do first?"],"options":[{"text":"Delete the VM1 virtual machine","correct":false},{"text":"Delete the sa001 storage account","correct":false},{"text":"Stop the backup of SQLDB01","correct":true},{"text":"Stop the VM1 virtual machine","correct":false}],"explanation":["`Stop the backup of SQLDB01` is correct because the deletion of a resource group that contains a Recovery Services vault with active backup jobs or protected items will fail. In this scenario, SQLDB01 is backed up to RGV1, which means there are active backup items associated with it. To successfully delete ResGrp1, you first need to stop the backup for SQLDB01 and delete any protected items from the Recovery Services vault (RGV1). Once the backup is stopped and protected items are removed, ResGrp1 can be deleted.","`Delete the VM1 virtual machine` is incorrect because deleting VM1 would not impact the active backup configuration associated with SQLDB01 in RGV1. The deletion of the resource group fails due to the active backup in the Recovery Services vault, not because of the presence of VM1.","`Delete the sa001 storage account` is incorrect because deleting the storage account in a different region (West Europe) does not address the active backup in RGV1. The storage account (sa001) is unrelated to the backup process of SQLDB01 and does not prevent the deletion of the resource group.","`Stop the VM1 virtual machine` is incorrect because stopping the virtual machine does not affect the backup status in the Recovery Services vault. The issue lies with the active backup of SQLDB01, not with the state of VM1."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-delete-vault"],"images":[],"topic":"identity","needsImage":false},{"id":"3-5","test":3,"number":5,"stem":["You have an Azure subscription that includes two storage accounts named contoso101 and contoso102.","The subscription also contains two virtual machines with the following configurations:","- VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU.","- VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU.","Within VNet1, service endpoints are configured as follows:","- Microsoft.AzureActiveDirectory is enabled on Subnet2.","- Microsoft.Storage is enabled on Subnet1.","A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled.","True or False:","`“VM1 can access contoso102.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. According to the information provided, the service endpoint policy is configured to allow access only to the contoso101 storage account through the Microsoft.Storage service endpoint associated with Subnet1 in VNet1. Since VM1 is connected to Subnet1 and the policy only permits access to contoso101, VM1 cannot access contoso102 because it is not included in the endpoint policy."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies?tabs=portal"],"images":[],"topic":"identity","needsImage":false},{"id":"3-6","test":3,"number":6,"stem":["You have an Azure subscription that includes two storage accounts named contoso101 and contoso102.","The subscription also contains two virtual machines with the following configurations:","- VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU.","- VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU.","Within VNet1, service endpoints are configured as follows:","- Microsoft.AzureActiveDirectory is enabled on Subnet2.","- Microsoft.Storage is enabled on Subnet1.","A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled.","True or False:","`“VM2 can access contoso101.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer. Service endpoint policies are always scoped to the subnet where they are applied, meaning they only control traffic originating from that specific subnet. In this scenario, the Microsoft.Storage service endpoint and its associated policy are applied to Subnet1, which contains VM1. Subnet2, where VM2 resides, has only an Azure Active Directory service endpoint and no storage endpoint or policy applied. This means the policy on Subnet1 does not restrict VM2’s traffic. By default, subnets in the same virtual network can communicate freely unless explicit network security groups or custom routes block that communication, and no such restrictions are mentioned here.","Because the question also does not state that the storage account firewall is locked down to specific networks, we assume the default configuration of allowing traffic from all networks. Under these conditions, VM2 can still reach contoso101 using the storage account’s public endpoint, bypassing the need for a storage service endpoint or policy. The idea that Subnet1’s policy would block all other subnets even via public endpoints, is a common misconception; Microsoft’s documentation makes clear that service endpoint policies only affect traffic from the subnets to which they are applied. Therefore, the correct choice is that VM2 can indeed access contoso101.","Reference(s);","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies?tabs=portal#restrict-network-access-to-azure-storage-accounts"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"3-7","test":3,"number":7,"stem":["You have an Azure subscription that includes two storage accounts named contoso101 and contoso102.","The subscription also contains two virtual machines with the following configurations:","- VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU.","- VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU.","Within VNet1, service endpoints are configured as follows:","- Microsoft.AzureActiveDirectory is enabled on Subnet2.","- Microsoft.Storage is enabled on Subnet1.","A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled.","True or False:","`“VM2 uses a private IP address to access Microsoft Entra ID.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. While there is a service endpoint for Microsoft.AzureActiveDirectory on Subnet2, which VM2 is connected to, this does not mean that VM2 can use a private IP address to access Microsoft Entra ID. Microsoft Entra ID is a global service that is accessible only via public IP addresses. The service endpoint for Microsoft.AzureActiveDirectory allows secure access to Entra ID but does not provide connectivity via private IP addresses; it only restricts access to specific VNets and subnets to enhance security while still using public IPs for the actual connection."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/whatis"],"images":[],"topic":"identity","needsImage":false},{"id":"3-8","test":3,"number":8,"stem":["You have an Azure subscription that contains the following resources:","- A virtual network named VNET1, which includes two subnets.","- subnet1 uses the IP address range 10.3.0.0/24.","- subnet2 uses the IP address range 10.4.0.0/24.","- A network security group named NSG1.","- A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1.","- A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2.","- A storage account named storage1.","The network security group NSG1 is configured with custom security rules as follows:","True or False:","`“VM1 can access storage1.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. NSG1 has an outbound security rule named Storage_Access configured to allow TCP traffic on port 443 from the virtual network to resources tagged as Storage. This rule enables VM1 to access storage1 on port 443. Additionally, there is no inbound restriction on the Storage endpoint, so VM1 can successfully connect to storage1 as required."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"],"images":["assets/325747a315f12033.png"],"topic":"identity","needsImage":true},{"id":"3-9","test":3,"number":9,"stem":["You have an Azure subscription that contains the following resources:","- A virtual network named VNET1, which includes two subnets.","- subnet1 uses the IP address range 10.3.0.0/24.","- subnet2 uses the IP address range 10.4.0.0/24.","- A network security group named NSG1.","- A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1.","- A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2.","- A storage account named storage1.","The network security group NSG1 is configured with custom security rules as follows:","True or False:","`“VM2 can access VM1 by using the HTTPS protocol.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. The HTTPS_VM1_Deny rule with priority 110 specifically blocks HTTPS (TCP port 443) traffic only from the Internet to VM1. Since VM2 is within the same virtual network (VNet1), the default VNet-to-VNet communication rule will allow HTTPS traffic between VM2 and VM1. Therefore, VM2 can access VM1 using the HTTPS protocol."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"],"images":["assets/325747a315f12033.png"],"topic":"identity","needsImage":true},{"id":"3-10","test":3,"number":10,"stem":["You have an Azure subscription that contains the following resources:","- A virtual network named VNET1, which includes two subnets.","- subnet1 uses the IP address range 10.3.0.0/24.","- subnet2 uses the IP address range 10.4.0.0/24.","- A network security group named NSG1.","- A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1.","- A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2.","- A storage account named storage1.","The network security group NSG1 is configured with custom security rules as follows:","True or False:","`“The NSG1 security rules apply to all virtual machines on VNET1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. NSG1 is attached to a subnet, and by examining the inbound rule, the destination is specified as the private IP of VM1, indicating that NSG1 is likely connected to subnet1. Network Security Group (NSG) rules apply only to the resources within the scope to which the NSG is associated. Therefore, these rules will apply only to the virtual machines in subnet1 and not to all virtual machines on VNET1."],"references":["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"],"images":["assets/325747a315f12033.png"],"topic":"identity","needsImage":true},{"id":"3-11","test":3,"number":11,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains the virtual machines shown in the following table.","You deploy a load balancer with the following characteristics:","- The load balancer is named LB1.","- It is an internal load balancer.","- It uses the Standard SKU.","- It is deployed in VNET1.","You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1.","Proposed solution: You create a Basic SKU public IP address, associate it with the network interface of VM1, and then start VM1.","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. For a Standard SKU load balancer, all virtual machines in the backend pool must be within the same region and connected to the same virtual network (VNET) as the load balancer itself. Additionally, they must either have a Standard SKU public IP address or no public IP address at all. In this scenario, associating a Basic SKU public IP address to VM1 does not meet the requirements for the Standard SKU load balancer. Therefore, this configuration does not allow VM1 and VM2 to be added to the backend pool of LB1."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"],"images":["assets/f2a3ffb8ae9d0333.png"],"topic":"identity","needsImage":true},{"id":"3-12","test":3,"number":12,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains the virtual machines shown in the following table.","You deploy a load balancer with the following characteristics:","- The load balancer is named LB1.","- It is an internal load balancer.","- It uses the Standard SKU.","- It is deployed in VNET1.","You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1.","Proposed solution: You create two public IP addresses using the Standard SKU, and you assign one Standard SKU public IP address to the network interface of each virtual machine.","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is the correct answer here. The load balancer in question has a Standard SKU, which requires any associated virtual machines in the backend pool to either have no public IP or a Standard SKU public IP. In this scenario, by creating Standard SKU public IP addresses and associating them with VM1 and VM2, you meet the requirement for compatibility with the Standard SKU load balancer.","For Standard SKU load balancers, virtual machines added to the backend pool must be within the same virtual network and location. Moreover, it’s important that, if public IPs are present, they are also of the Standard SKU type to ensure compatibility with the Standard SKU load balancer."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"],"images":["assets/f2a3ffb8ae9d0333.png"],"topic":"identity","needsImage":true},{"id":"3-13","test":3,"number":13,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains the virtual machines shown in the following table.","You deploy a load balancer with the following characteristics:","- The load balancer is named LB1.","- It is an internal load balancer.","- It uses the Standard SKU.","- It is deployed in VNET1.","You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1.","Proposed solution: You remove the public IP address association from VM2’s network interface.","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is the correct answer because a Standard Load Balancer can only attach virtual machines that:","- Are in the same location and same virtual network as the Load Balancer.","- Have either a Standard SKU public IP or no public IP.","In this scenario:","- VM1 has no public IP attached, which makes it eligible for the backend pool.","- VM2 has a Basic SKU public IP, which is not compatible with a Standard Load Balancer.","By removing the Basic SKU Public IP from VM2, the virtual machine aligns with the requirements of a Standard Load Balancer and can be added to the backend pool alongside VM1."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview","https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/virtual-network-public-ip-addresses","https://learn.microsoft.com/en-us/azure/load-balancer/quickstart-load-balancer-standard-internal-portal"],"images":["assets/628a96d3f1df1b0d.png"],"topic":"identity","needsImage":true},{"id":"3-14","test":3,"number":14,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains the virtual machines shown in the following table.","You deploy a load balancer with the following characteristics:","- The load balancer is named LB1.","- It is an internal load balancer.","- It uses the Standard SKU.","- It is deployed in VNET1.","You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1.","Proposed solution: You create a Standard SKU public IP address, attach it to VM1’s network interface, and then shut down VM2.","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. To add VM1 and VM2 to the backend pool of a Standard SKU internal load balancer, both virtual machines need to be configured to meet the requirements for a Standard SKU load balancer. Specifically, both VMs must have Standard SKU public IP addresses or no public IP at all. VM2 currently has a Basic SKU public IP, which is incompatible with the Standard SKU load balancer."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"],"images":["assets/f2a3ffb8ae9d0333.png"],"topic":"identity","needsImage":true},{"id":"3-15","test":3,"number":15,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group.","Another administrator intends to create multiple network security groups (NSGs) within the subscription.","You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks.","Proposed solution: Assign a built-in Azure Policy definition at the subscription scope.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. To meet the specific requirement of automatically blocking TCP port 8080 between virtual networks when an NSG is created, you would need to create a custom Azure policy. Built-in policies provided by Microsoft focus on general compliance and best practices and do not cover specific, custom configurations such as blocking a specific port across all new NSGs. Creating a custom policy allows you to define specific actions, such as blocking or allowing certain ports, tailored to your Azure environment's unique needs."],"references":["https://docs.microsoft.com/en-us/azure/azure-policy/policy-definition","https://learn.microsoft.com/en-us/azure/governance/policy/tutorials/create-custom-policy-definition"],"images":[],"topic":"identity","needsImage":false},{"id":"3-16","test":3,"number":16,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group.","Another administrator intends to create multiple network security groups (NSGs) within the subscription.","You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks.","Proposed solution: You create a custom Azure Policy definition and assign it at the subscription level.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is the correct answer here. By configuring a custom policy definition and assigning it to the subscription, you can enforce specific rules on NSGs, such as automatically blocking TCP port 8080 between virtual networks. Custom policies allow you to specify detailed compliance requirements and enforce specific configurations, which in this case include blocking a particular port across newly created NSGs within the subscription."],"references":["https://docs.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure"],"images":[],"topic":"identity","needsImage":false},{"id":"3-17","test":3,"number":17,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group.","Another administrator intends to create multiple network security groups (NSGs) within the subscription.","You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks.","Proposed solution: You go to the Resource providers blade and unregister the Microsoft.ClassicNetwork provider.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. Unregistering the Microsoft.ClassicNetwork provider has no effect on network security groups (NSGs) created in the Azure Resource Manager (ARM) model, as it is associated with the classic deployment model in Azure. The requirement here is to automatically block TCP port 8080 between virtual networks in the ARM model, which cannot be achieved by unregistering a provider. Instead, you would need to implement a custom policy or directly configure NSG rules."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-18","test":3,"number":18,"stem":["Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group.","Another administrator intends to create multiple network security groups (NSGs) within the subscription.","You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks.","Proposed solution: You create a resource lock and apply it at the subscription scope.","Does this solution satisfy the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. A resource lock is used to prevent accidental deletion or modification of Azure resources, but it does not enforce security rules or configurations, such as network access control. Resource locks are intended to protect resources from changes, not to configure their behavior.","To meet the stated goal of automatically blocking TCP port 8080 between virtual networks whenever a network security group (NSG) is created, you should use Azure Policy. You can create a policy definition that audits or enforces the presence of specific inbound or outbound security rules (such as blocking port 8080) in NSGs and assign that policy at the subscription level.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources","- https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"3-19","test":3,"number":19,"stem":["You have an Azure subscription with the following resources in the same resource group (RG1):","- Vault1: A Recovery Services vault located in the East US region","- VM1: A virtual machine running Windows Server in the East US region","- VM2: A virtual machine running Windows Server in the West US region","On VM1, you configure Azure Backup to protect a folder named Folder1 using a scheduled file-and-folder backup policy. The backup schedule is configured as follows:","- Backup frequency: Daily","- Backup times: 6:00 AM and 10:00 PM","You plan to restore this backup to a different virtual machine and want the data to be recovered on VM2.","What is the first action you must take?"],"options":[{"text":"On VM2, install the Windows Server Backup feature.","correct":false},{"text":"On VM1, install the Microsoft Azure Recovery Services Agent.","correct":false},{"text":"On VM1, install the Windows Server Backup feature.","correct":false},{"text":"On VM2, install the Microsoft Azure Recovery Services Agent.","correct":true}],"explanation":["`On VM2, install the Microsoft Azure Recovery Services Agent` is correct because in order to restore a backup from the Recovery Services vault to a different virtual machine (in this case, VM2), you need to have the Microsoft Azure Recovery Services (MARS) Agent installed on the destination VM. This agent enables the VM to communicate with the Recovery Services vault, allowing it to access and restore backups stored in Azure.","`On VM2, install the Windows Server Backup feature` is incorrect because the Windows Server Backup feature alone does not provide the necessary integration with Azure Recovery Services. The MARS Agent is required to retrieve backups from Azure.","`On VM1, install the Microsoft Azure Recovery Services Agent` is incorrect as the MARS Agent is already installed on VM1 to perform the initial backup. The task here is to restore the backup to VM2.","`On VM1, install the Windows Server Backup feature` is incorrect because this feature does not assist in restoring a backup to another VM. The backup is already configured on VM1, and the requirement is to restore it to VM2, which requires the MARS Agent on VM2."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-restore-windows-server"],"images":[],"topic":"identity","needsImage":false},{"id":"3-20","test":3,"number":20,"stem":["You have an Azure subscription named Subscription1 that is shared across multiple departments. The subscription currently includes the following resources:","- storage1 - Azure Storage account","- RG1 - Resource group","- container1 - Blob container","- share1 - Azure file share","Another administrator deploys two new resources, a virtual machine named VM1 and a storage account named storage2, by using a single Azure Resource Manager (ARM) template.","You want to review the ARM template that was used for this deployment.","From which Azure portal blade can you view the template associated with the deployment?"],"options":[{"text":"container1","correct":false},{"text":"RG1","correct":true},{"text":"storage1","correct":false},{"text":"VM1","correct":false}],"explanation":["`RG1` is correct because to view the Azure Resource Manager (ARM) template used for a deployment, you need to access the Resource Group (in this case, `RG1`) where the deployment was made. The Resource Group blade in the Azure portal includes an option to view the deployment history and allows you to access the templates used in those deployments.","`container1` is incorrect because a Blob container does not have deployment information or templates associated with it directly. It is a storage object within a storage account and lacks deployment-level insights.","`storage1` is incorrect as it is the storage account itself, and the ARM template used for deployments would not be accessible from the storage account blade. Templates are accessible through the Resource Group level.","`VM1` is incorrect because while you can see configuration and settings specific to `VM1`, the VM blade does not provide access to the ARM template used in the original deployment. The Resource Group blade is needed for viewing deployment templates."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deployment-history"],"images":[],"topic":"identity","needsImage":false},{"id":"3-21","test":3,"number":21,"stem":["You have a public load balancer that distributes traffic on ports 80 and 443 across three virtual machines named VM1, VM2, and VM3.","You want all Remote Desktop Protocol (RDP) connections to be routed exclusively to VM3.","What configuration should you apply?"],"options":[{"text":"Create a separate public load balancer dedicated to VM3","correct":false},{"text":"Configure an additional frontend IP configuration","correct":false},{"text":"Configure an inbound NAT rule","correct":true},{"text":"Configure a load balancing rule","correct":false}],"explanation":["`Configure an inbound NAT rule` is correct because an inbound NAT rule allows you to direct specific traffic, such as RDP, to a particular virtual machine (VM3 in this case) behind the load balancer. By setting up an inbound NAT rule for port 3389 (RDP), you ensure that all RDP connections go directly to VM3 instead of balancing across all VMs.","`Create a separate public load balancer dedicated to VM3` is incorrect because creating a separate load balancer is unnecessary for directing RDP connections to VM3. An inbound NAT rule is sufficient to achieve this without additional load balancers.","`Configure an additional frontend IP configuration` is incorrect as a frontend IP configuration is used to define the IP address on which the load balancer is accessible. It does not control how RDP traffic is directed to specific VMs.","`Configure a load balancing rule` is incorrect because load balancing rules are intended for distributing traffic across multiple VMs based on specific ports, which is not the goal here. The objective is to direct all RDP traffic to VM3 specifically, not balance it across VMs."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/tutorial-load-balancer-port-forwarding-portal"],"images":[],"topic":"network","needsImage":false},{"id":"3-22","test":3,"number":22,"stem":["You have an Azure subscription that includes several virtual networks deployed across different regions and resource groups.","The virtual networks are configured as follows:","- VNET1 is deployed in the West US region and belongs to resource group RG1.","- VNET2 is deployed in the Central US region and belongs to resource group RG1.","- VNET3 is deployed in the Central US region and belongs to resource group RG2.","- VNET4 is deployed in the West US region and belongs to resource group RG2.","You plan to deploy an Azure Firewall named AF1 in resource group RG1, located in the West US region.","Which virtual networks are valid targets for deploying AF1?"],"options":[{"text":"VNET1 only","correct":true},{"text":"VNET1 and VNET2 only","correct":false},{"text":"VNET1 and VNET4 only","correct":false},{"text":"VNET1, VNET2, and VNET4 only","correct":false},{"text":"VNET1, VNET2, VNET3, and VNET4","correct":false}],"explanation":["`VNET1 only` is correct because Azure Firewall can connect to a virtual network within the same region and resource group. In this scenario, AF1 is deployed in RG1 in the West US region. While VNET4 is also in the West US region, it is in a different resource group (RG2), which prevents AF1 from connecting to it. Therefore, VNET1 is the only virtual network eligible for connection to AF1."],"references":["https://learn.microsoft.com/en-us/azure/firewall/firewall-faq#are-there-any-firewall-resource-group-restrictions"],"images":[],"topic":"identity","needsImage":false},{"id":"3-23","test":3,"number":23,"stem":["You have an Azure subscription that includes the following resources:","- VM1 - a virtual machine","- App1 - an Azure web app","- apexcore.com, which is a Microsoft Entra Domain Services domain","All of these resources are connected to the same virtual network, VNet1.","You plan to deploy an Azure Bastion host named Bastion1 into VNet1.","Which of these resources can be secured by using Bastion1?"],"options":[{"text":"VM1 only","correct":true},{"text":"apexcore.com only","correct":false},{"text":"App1 and apexcore.com only","correct":false},{"text":"VM1 and apexcore.com only","correct":false},{"text":"VM1, App1, and apexcore.com","correct":false}],"explanation":["`VM1 only` is correct because Azure Bastion is designed to provide secure and seamless RDP and SSH connectivity to virtual machines within a virtual network. In this scenario, VM1 is the only virtual machine listed in the table, and thus the only resource that can be accessed and protected via Bastion1. Azure Bastion does not support direct connectivity to web apps (such as App1) or to Microsoft Entra Domain Services domains (like apexcore.com)."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-24","test":3,"number":24,"stem":["You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table.","Within these subscriptions, the following resource groups exist:","- RG1 is in SubA and contains a storage account named storage1.","- RG2 is in SubB and contains a web app named App1.","- RG3 is in SubC and contains a virtual machine named VM1.","Role assignments are configured as follows:","- User1 is assigned the Contributor role at the MG2 management group scope.","- User2 is assigned the Storage Account Contributor role scoped specifically to storage1.","- User3 is assigned the User Access Administrator role at the Tenant Root Group scope.","True or False:","`\"User1 can resize VM1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User1 has the Contributor role assigned at the scope of MG2. Since MG2 is the management group that contains the subscription SubC, which in turn contains the resource group RG3 (where VM1 is located), User1 has Contributor permissions on VM1. The Contributor role provides permissions to manage resources, including resizing virtual machines."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":["assets/8864e79918068c99.png"],"topic":"identity","needsImage":true},{"id":"3-25","test":3,"number":25,"stem":["You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table.","Within these subscriptions, the following resource groups exist:","- RG1 is in SubA and contains a storage account named storage1.","- RG2 is in SubB and contains a web app named App1.","- RG3 is in SubC and contains a virtual machine named VM1.","Role assignments are configured as follows:","- User1 is assigned the Contributor role at the MG2 management group scope.","- User2 is assigned the Storage Account Contributor role scoped specifically to storage1.","- User3 is assigned the User Access Administrator role at the Tenant Root Group scope.","True or False:","`\"User2 can create a new storage account in RG1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User2’s Storage Account Contributor role is assigned only at the scope of the existing storage account (storage1). Although this role includes permissions to create storage accounts when assigned at the resource group or subscription level, permissions granted at an individual resource scope do not allow the creation of new sibling resources. Since User2 has no role assignment at the RG1 or subscription scope, they cannot create a new storage account in RG1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":["assets/fbd0185801ca24e1.png"],"topic":"identity","needsImage":true},{"id":"3-26","test":3,"number":26,"stem":["You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table.","Within these subscriptions, the following resource groups exist:","- RG1 is in SubA and contains a storage account named storage1.","- RG2 is in SubB and contains a web app named App1.","- RG3 is in SubC and contains a virtual machine named VM1.","Role assignments are configured as follows:","- User1 is assigned the Contributor role at the MG2 management group scope.","- User2 is assigned the Storage Account Contributor role scoped specifically to storage1.","- User3 is assigned the User Access Administrator role at the Tenant Root Group scope.","True or False:","`\"User3 can assign User1 the Owner role for RG3.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User3 has the User Access Administrator role assigned at the scope of the Tenant Root Group. This role grants User3 permission to manage user access to Azure resources at or below the assigned scope. Since the Tenant Root Group is the highest level in the hierarchy, User3 has permission to assign roles, including the Owner role, to any resource within the tenant, including RG3."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":["assets/fbd0185801ca24e1.png"],"topic":"identity","needsImage":true},{"id":"3-27","test":3,"number":27,"stem":["You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:","- User1 is a member of Group1 and has no directory role assigned.","- User2 is a member of Group2 and has no directory role assigned.","- User3 is a member of Group1 and Group2, and is assigned the User Administrator role.","You enable password reset for apexcore.onmicrosoft.com as below:","- SSPR is enabled for Selected users only.","- The selected group is Group2.","Authentication method settings for password reset are configured with these options:","- Number of methods required to reset: 2","- Enabled methods:","- Mobile phone","- Security questions","- The following methods are not enabled:","- Mobile app notification","- Mobile app code","- Email","- Office phone","- Number of security questions required to register: 5","- Number of security questions required to reset: 3","- A total of 10 security questions are available.","True or False:","`\"After User2 answers three security questions correctly, he can reset his password immediately.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because, based on the password reset settings, two methods are required for a successful password reset. Although User2 can use security questions as one of the authentication methods, they would still need to provide a second method (such as a mobile phone verification) to reset their password. Answering only three security questions alone is insufficient as per the configured policy, which mandates two authentication methods."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr","https://learn.microsoft.com/en-us/entra/identity/authentication/passwords-faq"],"images":[],"topic":"identity","needsImage":false},{"id":"3-28","test":3,"number":28,"stem":["You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:","- User1 is a member of Group1 and has no directory role assigned.","- User2 is a member of Group2 and has no directory role assigned.","- User3 is a member of Group1 and Group2, and is assigned the User Administrator role.","You enable password reset for apexcore.onmicrosoft.com as below:","- SSPR is enabled for Selected users only.","- The selected group is Group2.","Authentication method settings for password reset are configured with these options:","- Number of methods required to reset: 2","- Enabled methods:","- Mobile phone","- Security questions","- The following methods are not enabled:","- Mobile app notification","- Mobile app code","- Email","- Office phone","- Number of security questions required to register: 5","- Number of security questions required to reset: 3","- A total of 10 security questions are available.","True or False:","`\"If User1 forgets her password, she can reset the password by using the mobile phone app.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 is a member of Group1, and self-service password reset (SSPR) has been enabled only for Group2. Since User1 is not part of Group2, she does not have access to the self-service password reset feature, regardless of the authentication methods configured."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr","https://learn.microsoft.com/en-us/entra/identity/authentication/passwords-faq"],"images":[],"topic":"identity","needsImage":false},{"id":"3-29","test":3,"number":29,"stem":["You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:","- User1 is a member of Group1 and has no directory role assigned.","- User2 is a member of Group2 and has no directory role assigned.","- User3 is a member of Group1 and Group2, and is assigned the User Administrator role.","You enable password reset for apexcore.onmicrosoft.com as below:","- SSPR is enabled for Selected users only.","- The selected group is Group2.","Authentication method settings for password reset are configured with these options:","- Number of methods required to reset: 2","- Enabled methods:","- Mobile phone","- Security questions","- The following methods are not enabled:","- Mobile app notification","- Mobile app code","- Email","- Office phone","- Number of security questions required to register: 5","- Number of security questions required to reset: 3","- A total of 10 security questions are available.","True or False:","`\"User3 can add security questions to the password reset process.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because although User3 has the User Administrator role, this role does not include permissions to modify the security questions configured for self-service password reset (SSPR). Only users with the Global Administrator or Authentication Administrator roles have the necessary permissions to modify security questions in the SSPR settings."],"references":["https://docs.microsoft.com/en-us/azure/active-directory/authentication/quickstart-sspr","https://docs.microsoft.com/en-us/azure/active-directory/authentication/active-directory-passwords-faq","https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy","https://docs.microsoft.com/en-us/azure/active-directory/authentication/tutorial-enable-sspr","https://docs.microsoft.com/en-us/azure/active-directory/authentication/howto-sspr-authenticationdata","https://docs.microsoft.com/en-us/azure/active-directory/roles/permissions-reference#user-administrator"],"images":[],"topic":"identity","needsImage":false},{"id":"3-30","test":3,"number":30,"stem":["You manage a Microsoft Entra tenant that contains approximately 7,000 user accounts.","You create a new user named AdminUsr1.","You must assign the User Administrator administrative role to AdminUsr1.","Which action should you take from the user account properties to complete this task?"],"options":[{"text":"From the Licenses blade, assign a new license.","correct":false},{"text":"From the Groups blade, invite the user account to a new group.","correct":false},{"text":"From the Directory role blade, modify the directory role.","correct":true}],"explanation":["`From the Directory role blade, modify the directory role` is correct because to assign an administrative role, such as the User Administrator role, to AdminUsr1, you need to navigate to the Directory role blade in the user account properties. From there, you can modify the directory role and assign the appropriate administrative role.","`From the Licenses blade, assign a new license` is incorrect because assigning a license is unrelated to assigning an administrative role. Licenses are used for service access, not role-based access control.","`From the Groups blade, invite the user account to a new group` is incorrect because adding the user to a group does not assign the User Administrator role. Role assignments are handled through the Directory role settings."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/how-subscriptions-associated-directory"],"images":[],"topic":"identity","needsImage":false},{"id":"3-31","test":3,"number":31,"stem":["You have the following Azure resources:","- Tenant Root Group - tenant root management group","- MG1 - management group","- Sub1 - subscription","- RG1 - resource group","- VM1 - virtual machine","You want to monitor resource usage and ensure that resources cannot be accidentally deleted.","To which resources can you apply locks?"],"options":[{"text":"RG1 and VM1 only","correct":false},{"text":"Sub1 and RG1 only","correct":false},{"text":"Sub1, RG1, and VM1 only","correct":true},{"text":"MG1, Sub1, RG1, and VM1 only","correct":false},{"text":"Tenant Root Group, MG1, Sub1, RG1, and VM1","correct":false}],"explanation":["`Sub1, RG1, and VM1 only` is correct because locks can be applied at the subscription, resource group, and resource (such as a virtual machine) levels to prevent accidental deletion or modification. In this case, Sub1 (the subscription), RG1 (the resource group), and VM1 (the virtual machine) are valid targets for applying locks to track usage and prevent deletion.","`RG1 and VM1 only` is incorrect because locks can also be applied at the subscription level (Sub1), not just at the resource group and resource levels.","`Sub1 and RG1 only` is incorrect because locks can also be applied directly to resources like VM1.","`MG1, Sub1, RG1, and VM1 only` is incorrect because locks cannot be applied to management groups (MG1).","`Tenant Root Group, MG1, Sub1, RG1, and VM1` is incorrect because locks cannot be applied to the Tenant Root Group or management groups."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources?tabs=json"],"images":[],"topic":"identity","needsImage":false},{"id":"3-32","test":3,"number":32,"stem":["You have the following Azure resources:","- Tenant Root Group - tenant root management group","- MG1 - management group","- Sub1 - subscription","- RG1 - resource group","- VM1 - virtual machine","You want to monitor resource usage and ensure that resources cannot be accidentally deleted.","To which resources can you apply tags?"],"options":[{"text":"RG1 and VM1 only","correct":false},{"text":"Sub1 and RG1 only","correct":false},{"text":"Sub1, RG1, and VM1 only","correct":true},{"text":"MG1, Sub1, RG1, and VM1 only","correct":false},{"text":"Tenant Root Group, MG1, Sub1, RG1, and VM1","correct":false}],"explanation":["`Sub1, RG1, and VM1 only` is correct because tags can be applied to subscriptions (Sub1), resource groups (RG1), and resources (such as VM1) in Azure. Tags cannot be applied to management groups (MG1) or the Tenant Root Group."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources?tabs=json"],"images":[],"topic":"identity","needsImage":false},{"id":"3-33","test":3,"number":33,"stem":["You are provided with a JSON file that lists several Azure role assignments at different scopes as shown below.","[","{","\"RoleAssignmentId\": \"f1a9c2d4-8b35-4e71-9c2a-6d5e7f8a9012\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10\",","\"DisplayName\": \"User1\",","\"SignInName\": \"User1@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"a7c4e1b2-5d93-4f60-8a1e-2b6c9d7f3e44\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG2\",","\"DisplayName\": \"User2\",","\"SignInName\": \"User2@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"d3e8f7a1-2c44-4b9e-91fa-5c6d8e2b7a33\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1\",","\"DisplayName\": \"User3\",","\"SignInName\": \"User3@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"b6d2a9f8-1e73-4c55-8b0d-9f2e6a4c7d88\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1\",","\"DisplayName\": \"User4\",","\"SignInName\": \"User4@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Contributor\"","}","]","Using the details in the role assignment file, choose the option that correctly completes the following statement:","“____________________________ assigned the Owner role for VM1.”"],"options":[{"text":"User3 is","correct":false},{"text":"User3 and User4 are","correct":false},{"text":"User1 and User3 are","correct":true},{"text":"User1, User3, and User4 are","correct":false},{"text":"User1, User2, User3, and User4 are","correct":false}],"explanation":["`User1 and User3 are` is correct because in the provided role assignment file, User3 is specifically assigned the Owner role at the scope of VM1 (/subscriptions/.../resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1).","And User1 is the owner of the subscription, which inherently makes it the owner of VM inside that subscription as well."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/rbac-and-directory-admin-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"3-34","test":3,"number":34,"stem":["You are provided with a JSON file that lists several Azure role assignments at different scopes as shown below.","[","{","\"RoleAssignmentId\": \"f1a9c2d4-8b35-4e71-9c2a-6d5e7f8a9012\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10\",","\"DisplayName\": \"User1\",","\"SignInName\": \"User1@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"a7c4e1b2-5d93-4f60-8a1e-2b6c9d7f3e44\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG2\",","\"DisplayName\": \"User2\",","\"SignInName\": \"User2@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"d3e8f7a1-2c44-4b9e-91fa-5c6d8e2b7a33\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1\",","\"DisplayName\": \"User3\",","\"SignInName\": \"User3@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Owner\"","},","{","\"RoleAssignmentId\": \"b6d2a9f8-1e73-4c55-8b0d-9f2e6a4c7d88\",","\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1\",","\"DisplayName\": \"User4\",","\"SignInName\": \"User4@apexcore.onmicrosoft.com\",","\"RoleDefinitionName\": \"Contributor\"","}","]","Using the details in the role assignment file, choose the option that correctly completes the following statement:","“____________________________ can create a virtual machine in RG1.”"],"options":[{"text":"User1 and User4","correct":true},{"text":"User1, User2, and User3","correct":false},{"text":"User1, User2, and User4","correct":false},{"text":"User1, User3, and User4","correct":false},{"text":"User1, User2, User3, and User4","correct":false}],"explanation":["`User1 and User4` is correct because creating a virtual machine in RG1 requires permissions at the RG1 level or higher within the subscription.","- User1 has the Owner role at the subscription level, which grants full access to manage resources within the entire subscription, including RG1.","- User4 has the Contributor role specifically on RG1, which allows them to manage resources within RG1, including creating and deleting virtual machines. However, as a Contributor, User4 cannot modify Role-Based Access Control (RBAC) settings.","User2 is incorrect because their Owner role is limited to RG2, and they do not have permissions in RG1.","User3 is incorrect because their Owner role applies only to VM1, so they do not have permissions to create new resources in RG1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/rbac-and-directory-admin-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"3-35","test":3,"number":35,"stem":["You have a Microsoft Entra tenant named bluerock.com that includes the following group hierarchy:","- Group1 is not a member of any other group.","- Group2 is a member of Group1.","- Group3 is a member of Group2.","The tenant also contains the following users and their group memberships:","- User1 is a member of Group1.","- User2 is a member of Group2.","- User3 is a member of Group3.","- User4 is not a member of any group.","You assign the Microsoft Entra ID P2 license directly to Group1 and also directly to User4.","Which users receive the Microsoft Entra ID P2 license as a result of this configuration?"],"options":[{"text":"User4 only","correct":false},{"text":"User1 and User4 only","correct":true},{"text":"User1, User2, and User4 only","correct":false},{"text":"User1, User2, User3, and User4","correct":false}],"explanation":["`User1 and User4 only` is correct because group-based licensing in Microsoft Entra ID does not support nested groups. When a license is assigned to Group1, only the direct members of Group1 receive the license. This means User1 (direct member of Group1) and User4 (who received the license directly) are the only users assigned the Microsoft Entra ID P2 license. User2 and User3 do not receive the license because they are members through nested groups (Group2 and Group3)."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/licensing-group-advanced#limitations-and-known-issues"],"images":[],"topic":"identity","needsImage":false},{"id":"3-36","test":3,"number":36,"stem":["You have several virtual networks in your Azure environment. The peering settings for vNET6 are configured as follows:","- A peering connection Peering1 to vNET1 exists, but its Peering status is Disconnected and Gateway transit is Enabled.","- A peering connection Peering2 to vNET2 exists, but its Peering status is Disconnected and Gateway transit is Disabled.","Based on this configuration, complete the statement:","“Virtual machines hosted in vNET6 are able to communicate with virtual machines hosted in ____________________.”"],"options":[{"text":"vNET6 only","correct":true},{"text":"vNET6 and vNET1 only","correct":false},{"text":"vNET6, vNET1, and vNET2 only","correct":false},{"text":"all the virtual networks in the subscription","correct":false}],"explanation":["`vNET6 only` is correct because the peering status for vNET6 with both vNET1 and vNET2 is mentioned as Disconnected. This means there is no active peering connection between vNET6 and any other virtual network. As a result, hosts on vNET6 can only communicate within vNET6 itself and cannot reach vNET1, vNET2, or any other virtual network in the subscription."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"],"images":[],"topic":"network","needsImage":false},{"id":"3-37","test":3,"number":37,"stem":["You have several virtual networks in your Azure environment. The peering settings for vNET6 are configured as follows:","- A peering connection Peering1 to vNET1 exists, but its Peering status is Disconnected and Gateway transit is Enabled.","- A peering connection Peering2 to vNET2 exists, but its Peering status is Disconnected and Gateway transit is Disabled.","Based on this configuration, complete the statement:","“To change the peering connection between vNET6 and vNET1 to a Connected state, you must first _____________________.”"],"options":[{"text":"add a service endpoint","correct":false},{"text":"add a subnet","correct":false},{"text":"delete peering1","correct":true},{"text":"modify the address space","correct":false}],"explanation":["`delete peering1` is the correct answer because a peering connection in the Disconnected state indicates that the peering relationship is broken or missing from one side. To restore connectivity between vNET6 and vNET1, the disconnected peering must first be deleted and then recreated.","Although Azure now supports modifying the address space of peered virtual networks without deleting the peering, that functionality applies to active peerings that can be synchronized afterward. In this scenario, the issue is the Disconnected peering state itself, not an address-space update."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"],"images":[],"topic":"network","needsImage":false},{"id":"3-38","test":3,"number":38,"stem":["You have an Azure subscription that includes the following resources:","- VM1 - a virtual machine","- VM2 - a virtual machine","- LB1 - a load balancer that uses the Basic SKU","You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1.","LB1 is configured as shown below.","Rule1 is configured as shown below.","True or False:","`\"VM1 is in the same availability set as VM2.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because a Basic SKU load balancer requires that all network interfaces (NICs) connected to it be part of the same availability set. This restriction means that both VM1 and VM2 must be in the same availability set to be added to LB1 (a Basic SKU load balancer). The Basic SKU does not support flexibility across multiple availability sets, enforcing that all associated VMs are within the same availability set."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview","https://learn.microsoft.com/en-us/azure/load-balancer/skus"],"images":["assets/bf78440dc967d538.png","assets/c15dccb98a072135.png"],"topic":"identity","needsImage":true},{"id":"3-39","test":3,"number":39,"stem":["You have an Azure subscription that includes the following resources:","- VM1 - a virtual machine","- VM2 - a virtual machine","- LB1 - a load balancer that uses the Basic SKU","You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1.","LB1 is configured as shown below.","Rule1 is configured as shown below.","True or False:","`\"If Probe1.htm is present on VM1 and VM2, LB1 will balance traffic for TCP port 80 between VM1 and VM2.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because Probe1 is configured as an HTTP probe on port 80, checking for the presence of Probe1.htm on both VM1 and VM2. If Probe1.htm is present on both virtual machines, the health probe will mark both VMs as healthy, enabling LB1 (the Basic SKU load balancer) to balance incoming traffic on TCP port 80 across VM1 and VM2. The load balancer will distribute traffic only to VMs that pass the health probe check, so the presence of Probe1.htm ensures load balancing between the two VMs."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-custom-probe-overview"],"images":["assets/bf78440dc967d538.png","assets/c15dccb98a072135.png"],"topic":"identity","needsImage":true},{"id":"3-40","test":3,"number":40,"stem":["You have an Azure subscription that includes the following resources:","- VM1 - a virtual machine","- VM2 - a virtual machine","- LB1 - a load balancer that uses the Basic SKU","You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1.","LB1 is configured as shown below.","Rule1 is configured as shown below.","True or False:","`\"If you delete Rule1, LB1 will balance all the requests between VM1 and VM2 for all the ports.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because if Rule1 is deleted, LB1 will lack the configuration needed to balance traffic for any ports between VM1 and VM2. Additionally, if all health probes fail for all instances in the backend pool, no new flows will be directed to the backend pool, and the Basic Load Balancer will terminate any existing TCP flows to the backend pool. Therefore, deleting Rule1 would prevent LB1 from balancing any requests across VM1 and VM2."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-custom-probe-overview"],"images":["assets/bf78440dc967d538.png","assets/c15dccb98a072135.png"],"topic":"identity","needsImage":true},{"id":"3-41","test":3,"number":41,"stem":["You have an Azure subscription named Subscription1 that contains a virtual machine named VM1.","On VM1, you install and configure the following services:","- A web server","- A DNS server","VM1 has the effective network security rules shown in the following exhibit.","Based on this configuration, select the option that correctly completes the following statement:","“Internet users _________________________________________.”"],"options":[{"text":"can connect to only the DNS server on VM1","correct":false},{"text":"can connect to only the web server on VM1","correct":true},{"text":"can connect to the web server and the DNS server on VM1","correct":false},{"text":"cannot connect to the web server and the DNS server on VM1","correct":false}],"explanation":["`can connect to only the web server on VM1` is correct because the web server uses port 80, which is not blocked by any of the inbound security rules. However, Rule2 (with priority 100) explicitly denies access to ports 50-60 for all protocols, including port 53, which is used by the DNS service. Since port 53 is blocked by Rule2, internet users cannot connect to the DNS server on VM1 but can still connect to the web server.","`Can connect to only the DNS server on VM1` is incorrect because port 53 for DNS is blocked by Rule2.","`Can connect to the web server and the DNS server on VM1` is incorrect because the DNS port (53) is blocked.","`Cannot connect to the web server and the DNS server on VM1` is incorrect because the web server on port 80 is still accessible."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"images":["assets/52760bc5559b39ae.png"],"topic":"identity","needsImage":true},{"id":"3-42","test":3,"number":42,"stem":["You have an Azure subscription named Subscription1 that contains a virtual machine named VM1.","On VM1, you install and configure the following services:","- A web server","- A DNS server","VM1 has the effective network security rules shown in the following exhibit.","Based on this configuration, select the option that correctly completes the following statement:","“If you delete Rule2, Internet users _________________________________________.”"],"options":[{"text":"can connect to only the DNS server on VM1","correct":false},{"text":"can connect to only the web server on VM1","correct":false},{"text":"can connect to the web server and the DNS server on VM1","correct":true},{"text":"cannot connect to the web server and the DNS server on VM1","correct":false}],"explanation":["`can connect to the web server and the DNS server on VM1` is correct because if Rule2 is deleted, the restriction on ports 50-60 is removed, allowing port 53 (used by DNS) to be accessible. The web server on port 80 is already accessible, as it falls outside the range that was blocked by Rule2. Therefore, with Rule2 deleted, internet users would be able to connect to both the web server (on port 80) and the DNS server (on port 53).","`Can connect to only the DNS server on VM1` is incorrect because port 80 for the web server is also accessible.","`Can connect to only the web server on VM1` is incorrect because port 53 for DNS would also be accessible once Rule2 is deleted.","`Cannot connect to the web server and the DNS server on VM1` is incorrect because deleting Rule2 allows access to both port 80 and port 53."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"images":["assets/52760bc5559b39ae.png"],"topic":"identity","needsImage":true},{"id":"3-43","test":3,"number":43,"stem":["You have two Azure subscriptions named Subscription1 and Subscription2.","Each subscription is associated with a different Microsoft Entra tenant.","The resources are configured as follows:","- Subscription1","- Contains a virtual network named VNet1","- VNet1 has an address space of 10.0.0.0/16","- VNet1 contains a virtual machine named VM1","- Subscription2","- Contains a virtual network named VNet2","- VNet2 has an address space of 10.10.0.0/24","- VNet2 contains a virtual machine named VM2","You need to establish network connectivity between VNet1 and VNet2.","What should you do first?"],"options":[{"text":"Move the virtual machine VM1 from Subscription1 to Subscription2.","correct":false},{"text":"Create and configure virtual network gateways for the virtual networks.","correct":true},{"text":"Move the virtual network VNet1 into Subscription2.","correct":false},{"text":"Change the IP address range assigned to VNet2.","correct":false}],"explanation":["`Create and configure virtual network gateways for the virtual networks` is correct because to connect VNet1 in Subscription1 to VNet2 in Subscription2, you need to set up VNet-to-VNet connectivity across different subscriptions and tenants. The recommended approach for achieving this connection is to provision virtual network gateways in each virtual network and establish a VPN connection between them. This approach supports cross-subscription and cross-tenant connections.","`Move the virtual machine VM1 from Subscription1 to Subscription2` is incorrect because moving the VM does not address the need to connect the virtual networks across different subscriptions and tenants.","`Move the virtual network VNet1 into Subscription2` is incorrect because moving the entire virtual network to the same subscription is unnecessary when you can achieve connectivity through virtual network gateways.","`Change the IP address range assigned to VNet2` is incorrect because there is no overlapping IP address space that would prevent connectivity; both address spaces are already compatible."],"references":["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-howto-vnet-vnet-resource-manager-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"3-44","test":3,"number":44,"stem":["You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep.","param location string = resourceGroup().location","resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {","name: 'VNET1'","location: location","properties: {","addressSpace: {","addressPrefixes: [","'10.0.0.0/16'","]","}","subnets: [","{","name: 'Subnet-1'","properties: {","addressPrefix: '10.0.0.0/24'","}","}","{","name: 'Subnet-2'","properties: {","addressPrefix: '10.0.1.0/24'","}","}","]","}","}","True or False:","`“The virtual network will be named using the same value as the resource group’s location.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the name of the virtual network in the provided Bicep file is explicitly set as 'VNET1'. The location parameter is assigned based on the location of the resource group, but this value only determines where the virtual network is deployed, not its name. Therefore, the name of the virtual network will be 'VNET1', regardless of the resource group's location."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/bicep-functions-resourcegroup"],"images":[],"topic":"identity","needsImage":false},{"id":"3-45","test":3,"number":45,"stem":["You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep.","param location string = resourceGroup().location","resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {","name: 'VNET1'","location: location","properties: {","addressSpace: {","addressPrefixes: [","'10.0.0.0/16'","]","}","subnets: [","{","name: 'Subnet-1'","properties: {","addressPrefix: '10.0.0.0/24'","}","}","{","name: 'Subnet-2'","properties: {","addressPrefix: '10.0.1.0/24'","}","}","]","}","}","True or False:","`“Both subnet objects will be created successfully without any deployment errors.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because both Subnet-1 and Subnet-2 in the Bicep file have unique address prefixes (10.0.0.0/24 for Subnet-1 and 10.0.1.0/24 for Subnet-2) that fall within the address space of VNET1 (10.0.0.0/16). Since the subnets have non-overlapping address ranges within the virtual network's address space, they will be provisioned successfully."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-subnet"],"images":[],"topic":"identity","needsImage":false},{"id":"3-46","test":3,"number":46,"stem":["You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep.","param location string = resourceGroup().location","resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {","name: 'VNET1'","location: location","properties: {","addressSpace: {","addressPrefixes: [","'10.0.0.0/16'","]","}","subnets: [","{","name: 'Subnet-1'","properties: {","addressPrefix: '10.0.0.0/24'","}","}","{","name: 'Subnet-2'","properties: {","addressPrefix: '10.0.1.0/24'","}","}","]","}","}","True or False:","`“Deploying File1.bicep multiple times will result in a deployment error.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because deploying File01.bicep more than once will not inherently cause an error, as Azure Resource Manager is designed to perform idempotent deployments. This means that if you deploy the same Bicep file multiple times without changing the parameters, Azure will recognize that the resources already exist and will not attempt to recreate them, avoiding any conflict or error. Any subsequent deployments would simply update the existing resources if there are changes; otherwise, the deployment will succeed without modification."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-47","test":3,"number":47,"stem":["You have an on-premises environment that includes a VPN gateway.","Your Azure subscription contains the following resources:","- vgw1 – a virtual network gateway configured for a site-to-site VPN connection to the on-premises network","- storage1 – a storage account using the Standard performance tier","- Vnet1 – a virtual network with forced tunneling enabled","- VM1 – a virtual machine connected to Vnet1","You must guarantee that any traffic originating from VM1 and destined for storage1 travels only across the Microsoft backbone network, and not through the public internet or the on-premises network.","What configuration should you implement?"],"options":[{"text":"Azure Peering Service","correct":false},{"text":"service endpoints","correct":true},{"text":"Microsoft Entra Application Proxy","correct":false},{"text":"Azure Application Gateway","correct":false}],"explanation":["`service endpoints` is correct because configuring service endpoints for storage1 will ensure that traffic from VM1 to storage1 travels across the Microsoft backbone network. Service endpoints allow private access to Azure services over the Azure backbone network by extending a virtual network's identity to the Azure service. This setup secures the traffic from VM1 to storage1 by keeping it within Microsoft’s network infrastructure.","`Azure Peering Service` is incorrect because it is designed for optimizing internet traffic but does not ensure that traffic stays within the Microsoft backbone for specific resources like storage1.","`Microsoft Entra Application Proxy` is incorrect because it provides secure remote access to on-premises applications, not for managing internal Azure network traffic between resources.","`Azure Application Gateway` is incorrect as it is a layer 7 load balancer for managing HTTP/HTTPS traffic and does not direct traffic over the Microsoft backbone for a virtual machine accessing a storage account."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-48","test":3,"number":48,"stem":["You have an Azure subscription that includes a storage account named storacc1.","The storacc1 account contains blob data stored in a container named cont1.","You plan to share access to storacc1 by generating a shared access signature (SAS).","The SAS must meet the following requirements:","- Ensure that the SAS can only be used to enumerate and download blobs stored in cont1.","- Use the principle of least privilege.","Which three settings should you enable?"],"options":[{"text":"File","correct":false},{"text":"Container","correct":true},{"text":"Object","correct":false},{"text":"Read","correct":true},{"text":"List","correct":true},{"text":"Filter","correct":false}],"explanation":["`Container` is correct.  This level of access limits the scope to container-level operations, specifically allowing access to cont1 where the blobs are stored.","`Read` and `List` are correct. Enabling Read and List permissions ensures that the SAS can only enumerate and download blobs within container1. Read permission allows downloading the blobs, and List permission allows enumerating the blobs within the container."],"references":["https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas#specify-the-signed-resource-field","https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas#specify-permissions"],"images":[],"topic":"identity","needsImage":false},{"id":"3-49","test":3,"number":49,"stem":["You have an Azure Storage account named storage1.","You also have two Azure App Service applications named App1 and App2. Both applications run in Azure container instances and both use managed identities.","You must ensure that both App1 and App2 can read blobs stored in storage1. The solution must meet the following requirements:","- Use the fewest possible secrets.","- Ensure that App2 is allowed to read data from storage1 for only the next 30 days.","What should you configure in storage1 for App1?"],"options":[{"text":"Configure storage account access keys.","correct":false},{"text":"Enable advanced security settings on the storage account.","correct":false},{"text":"Configure role-based access control (RBAC) by using Access control (IAM).","correct":true},{"text":"Generate Shared access signatures (SAS)","correct":false}],"explanation":["`Configure role-based access control (RBAC) by using Access control (IAM)` is correct because Azure Role-Based Access Control (RBAC) enables you to assign the Storage Blob Data Reader role to App1’s managed identity, allowing it to read blobs in storage1 without using secrets like keys or tokens. This meets the requirement to minimize the number of secrets used. RBAC is the most secure and manageable approach for long-term access and works seamlessly with managed identities. While RBAC does not natively support automatic expiration of access after a specific period, that requirement only applies to App2.","`Configure storage account access keys` is incorrect because access keys grant full access to the storage account and must be stored and rotated as secrets, violating the principle of least privilege.","`Enable advanced security settings on the storage account` is incorrect because it enhances storage account protection (e.g., firewalls or encryption), but it is not used to control identity-based read permissions.","`Generate Shared access signatures (SAS)` is incorrect for App1 because it involves generating and managing a token (a secret) and is better suited for time-limited access scenarios. While SAS does support expiration, it requires more overhead compared to RBAC for apps with managed identities."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","https://learn.microsoft.com/en-us/azure/azure-resource-manager/managed-applications/publish-managed-identity#granting-access-to-azure-resources"],"images":[],"topic":"storage","needsImage":false},{"id":"3-50","test":3,"number":50,"stem":["You have an Azure Storage account named storage1.","You also have two Azure App Service applications named App1 and App2. Both applications run in Azure container instances and both use managed identities.","You must ensure that both App1 and App2 can read blobs stored in storage1. The solution must meet the following requirements:","- Use the fewest possible secrets.","- Ensure that App2 is allowed to read data from storage1 for only the next 30 days.","What should you configure in storage1 for App2?"],"options":[{"text":"Configure storage account access keys.","correct":false},{"text":"Enable advanced security settings on the storage account.","correct":false},{"text":"Configure role-based access control (RBAC) by using Access control (IAM).","correct":false},{"text":"Generate Shared access signatures (SAS).","correct":true}],"explanation":["`Generate Shared access signatures (SAS)` is correct because it enables time-bound access by allowing you to generate a token that grants App2 read access to blobs in storage1 with an exact expiration, such as 30 days. This satisfies the requirement to limit App2’s access duration. While a SAS token is considered a secret, it’s the most practical built-in option for temporary access enforcement. It avoids the need for manual revocation logic that would be required with IAM-based roles.","`Configure storage account access keys` is incorrect because they provide full control over the storage account and are not time-limited, making them unsuitable for scoped or temporary access.","`Enable advanced security settings on the storage account` is incorrect as it does not control time-limited access and does not apply to managed identity permissions.","`Configure role-based access control (RBAC) by using Access control (IAM)` is incorrect for App2 because RBAC does not natively support automated expiration of permissions. You would need external tooling like scripts or Azure PIM to revoke access after 30 days, which is less direct than a SAS token with an expiration."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview","https://learn.microsoft.com/en-us/azure/storage/common/authorize-data-access?tabs=blobs"],"images":[],"topic":"storage","needsImage":false},{"id":"3-51","test":3,"number":51,"stem":["You have a Microsoft Entra user named User1 and an Azure Storage account named contoso2026 that uses read-access geo-redundant storage (RA-GRS).","You must meet the following requirements:","- User1 must be able to write blob data to contoso2026.","- The contoso2026 storage account must be able to fail over to its secondary endpoint.","Which two settings should you configure?"],"options":[{"text":"Access Control (IAM)","correct":true},{"text":"Access Keys","correct":false},{"text":"Shared access signature","correct":false},{"text":"Redundancy","correct":true}],"explanation":["`Access Control (IAM)` is correct because to enable User1 to write blob data to contoso2026, you can assign the Storage Blob Data Contributor role to User1 through Access Control (IAM). This role provides the necessary permissions for writing blob data without using account keys or SAS tokens, aligning with best practices for managing access in Azure.","`Redundancy` is correct because to configure contoso2026 to fail over to its secondary endpoint, you need to adjust the Redundancy setting. This setting allows you to manage the geo-redundant failover behavior for the storage account, enabling automatic or manual failover to the secondary region when needed.","`Access Keys` is incorrect because using access keys would not meet the principle of least privilege and would grant full access rather than just write permissions.","`Shared access signature` is incorrect because while it can provide specific permissions, using IAM roles is a more secure and manageable way to provide User1 with write access."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-redundancy#read-access-geo-redundant-storage","https://docs.microsoft.com/en-us/azure/storage/common/storage-initiate-account-failover?tabs=azure-portal","https://docs.microsoft.com/en-us/azure/role-based-access-control/overview","https://docs.microsoft.com/en-us/azure/storage/common/storage-sas-overview","https://docs.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage"],"images":[],"topic":"identity","needsImage":false},{"id":"3-52","test":3,"number":52,"stem":["You have the following App Service plans:","- ASP1","- OS: Windows","- Region: West US","- ASP2","- OS: Windows","- Region: Central US","- ASP3","- OS: Linux","- Region: West US","You plan to create the following Azure web apps:","- WebApp1","- Runtime stack: .NET 8 (LTS)","- Location: West US","- WebApp2","- Runtime stack: ASP.NET 4.8","- Location: West US","Which App Service plan can be used to host WebApp1?"],"options":[{"text":"ASP1 only","correct":false},{"text":"ASP3 only","correct":false},{"text":"ASP1 and ASP2 only","correct":false},{"text":"ASP1 and ASP3 only","correct":true},{"text":"ASP1, ASP2, and ASP3","correct":false}],"explanation":["`ASP1 and ASP3 only` is correct because WebApp1 requires a .NET 8 (LTS) runtime stack, which is supported on both Windows and Linux platforms. ASP1 is a Windows-based App Service plan in the West US region, which aligns with the requirements for WebApp1. ASP3 is a Linux-based App Service plan, also located in the West US region, which is compatible with .NET 8. Therefore, both ASP1 and ASP3 can host WebApp1.","`ASP1 only` is incorrect because ASP3 can also support .NET 8 (LTS) on Linux.","`ASP3 only` is incorrect because ASP1 also supports .NET 8 (LTS) on Windows.","`ASP1 and ASP2 only` is incorrect because ASP2 is in the Central US region, which does not align with the West US requirement for WebApp1.","`ASP1, ASP2, and ASP3` is incorrect because ASP2 is not in the West US region."],"references":["https://learn.microsoft.com/en-us/azure/app-service/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-53","test":3,"number":53,"stem":["You have the following App Service plans:","- ASP1","- OS: Windows","- Region: West US","- ASP2","- OS: Windows","- Region: Central US","- ASP3","- OS: Linux","- Region: West US","You plan to create the following Azure web apps:","- WebApp1","- Runtime stack: .NET 8 (LTS)","- Location: West US","- WebApp2","- Runtime stack: ASP.NET 4.8","- Location: West US","Which App Service plan can be used to host WebApp2?"],"options":[{"text":"ASP1 only","correct":true},{"text":"ASP3 only","correct":false},{"text":"ASP1 and ASP2 only","correct":false},{"text":"ASP1 and ASP3 only","correct":false},{"text":"ASP1, ASP2, and ASP3","correct":false}],"explanation":["`ASP1 only` is correct because WebApp2 requires the ASP.NET 4.8 runtime stack, which is supported only on Windows-based App Service plans. ASP1 is a Windows-based App Service plan in the West US region, matching the requirements for WebApp2.","In the screenshot below, you can see that the Linux option for the Operating System is greyed out when the Runtime stack is selected as ASP.NET 4.8.","`ASP3 only` is incorrect because ASP3 is a Linux-based plan, which does not support the ASP.NET 4.8 runtime stack.","`ASP1 and ASP2 only` is incorrect because, although ASP2 is a Windows-based plan, it is in the Central US region, whereas WebApp2 requires a plan in the West US region.","`ASP1 and ASP3 only` is incorrect because ASP3 does not support ASP.NET 4.8.","`ASP1, ASP2, and ASP3` is incorrect because ASP2 and ASP3 do not meet the requirements for WebApp2 due to either region mismatch or OS incompatibility."],"references":["https://learn.microsoft.com/en-us/azure/app-service/"],"images":[],"topic":"identity","needsImage":false},{"id":"3-54","test":3,"number":54,"stem":["Your on-premises network hosts an Active Directory Domain Services (AD DS) domain named apexcore.com. The domain includes the following servers:","You are planning to migrate the apexcore.com domain to Azure.","You create an Azure virtual network named VNET1 with these configurations:","- Address space: 10.0.0.0/16","- Subnet configuration:","- Subnet name: Subnet1","- IPv4 address range: 10.0.1.0/24","You need to move DC1 into VNET1. The configuration must ensure that all member servers in apexcore.com can continue to resolve Active Directory DNS records correctly.","How should the IP address be configured?"],"options":[{"text":"Obtain an IP address automatically.","correct":true},{"text":"Use 10.0.1.3","correct":false},{"text":"Use 10.0.2.1","correct":false},{"text":"Use 192.168.2.1","correct":false}],"explanation":["`Obtain an IP address automatically` is correct because, out of the options given, this is the most feasible solution. While it's generally best practice to assign a static IP to a Domain Controller (DC) to ensure consistent DNS resolution, obtaining an IP automatically can work as long as DC1 remains active. If DC1 is shut down, it may receive a different IP upon restart, which could disrupt DNS resolution.","`Use 10.0.1.3` is incorrect because the first four IP addresses within a subnet range (like 10.0.1.0/24) are reserved by Azure, making 10.0.1.3 unavailable for assignment.","`Use 10.0.2.1` is incorrect because, although it’s within the overall VNET1 address space, it falls outside of Subnet1’s range (10.0.1.0/24), which would prevent proper network connectivity.","`Use 192.168.2.1` is incorrect as this IP is part of the on-premises network and does not exist within VNET1’s address space, making it unusable in the Azure virtual network."],"references":["https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/azure-best-practices/dns-for-on-premises-and-azure-resources"],"images":["assets/d6d822422d2f592d.png"],"topic":"network","needsImage":true},{"id":"3-55","test":3,"number":55,"stem":["Your on-premises network hosts an Active Directory Domain Services (AD DS) domain named apexcore.com. The domain includes the following servers:","You are planning to migrate the apexcore.com domain to Azure.","You create an Azure virtual network named VNET1 with these configurations:","- Address space: 10.0.0.0/16","- Subnet configuration:","- Subnet name: Subnet1","- IPv4 address range: 10.0.1.0/24","You need to move DC1 into VNET1. The configuration must ensure that all member servers in apexcore.com can continue to resolve Active Directory DNS records correctly.","How should the Name resolution be configured?"],"options":[{"text":"Configure VNET1 to use a custom DNS server.","correct":true},{"text":"Configure VNET1 to use the default Azure-provided DNS server.","correct":false},{"text":"Create an Azure Private DNS zone named apexcore.com.","correct":false},{"text":"Create an Azure public DNS zone named apexcore.com.","correct":false}],"explanation":["`Configure VNET1 to use a custom DNS server` is correct because to ensure that the member servers in apexcore.com can resolve Active Directory Domain Services (AD DS) DNS names, VNET1 should be configured to use the IP address of DC1 (acting as the DNS server) as a custom DNS server. This configuration will allow resources within VNET1 to resolve DNS queries for apexcore.com using DC1's DNS service, which is essential for Active Directory domain name resolution.","`Configure VNET1 to use the default Azure-provided DNS server` is incorrect because Azure’s default DNS server does not support resolving on-premises or custom domain names like apexcore.com.","`Create an Azure Private DNS zone named apexcore.com` is incorrect because, while a private DNS zone could theoretically support name resolution, it would not integrate seamlessly with AD DS DNS requirements. Using DC1 as the DNS server directly provides better compatibility with AD DS.","`Create an Azure public DNS zone named apexcore.com` is incorrect because a public DNS zone is intended for resolving internet-facing names and is not suitable for internal AD DS name resolution within VNET1."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances#name-resolution-that-uses-your-own-dns-server","https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/azure-best-practices/dns-for-on-premises-and-azure-resources"],"images":["assets/d6d822422d2f592d.png"],"topic":"network","needsImage":true},{"id":"3-56","test":3,"number":56,"stem":["You have an Azure subscription that includes a virtual machine named VM1.","You plan to attach a 1 TB data disk to VM1. The disk must meet the following requirements:","- It must remain available if an entire datacenter becomes unavailable.","- It must deliver the lowest possible latency and the highest performance.","- It must prevent data loss in the event that the host fails.","Which storage type should you choose?"],"options":[{"text":"Premium SSD that uses locally-redundant storage (LRS)","correct":false},{"text":"Premium SSD that uses zone-redundant storage (ZRS)","correct":true},{"text":"Standard SSD that uses locally-redundant storage (LRS)","correct":false},{"text":"Standard SSD that uses zone-redundant storage (ZRS)","correct":false}],"explanation":["`Premium SSD that uses zone-redundant storage (ZRS)` is correct because it provides data resiliency by replicating data across multiple availability zones, ensuring that data remains available in the event of a datacenter outage. Additionally, Premium SSDs offer the lowest latency and highest performance compared to Standard SSDs. The use of ZRS ensures that data is also protected against potential failures within a specific zone, meeting the requirement of no data loss in case of a host or datacenter failure.","`Premium SSD that uses locally-redundant storage (LRS)` is incorrect because while it provides high performance and low latency, LRS only replicates data within a single datacenter, which does not provide resiliency in the event of a datacenter outage.","`Standard SSD that uses locally-redundant storage (LRS)` is incorrect because Standard SSDs do not meet the requirement for the highest performance and low latency, and LRS does not protect against datacenter outages.","`Standard SSD that uses zone-redundant storage (ZRS)` is incorrect because, while ZRS provides data resiliency across zones, Standard SSDs lack the performance and low latency required."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/overview","https://learn.microsoft.com/en-us/azure/architecture/example-scenario/identity/adds-extend-domain#vm-recommendations"],"images":[],"topic":"identity","needsImage":false},{"id":"3-57","test":3,"number":57,"stem":["You have an Azure subscription that includes a virtual machine named VM1.","You plan to attach a 1 TB data disk to VM1. The disk must meet the following requirements:","- It must remain available if an entire datacenter becomes unavailable.","- It must deliver the lowest possible latency and the highest performance.","- It must prevent data loss in the event that the host fails.","Which host caching would you recommend?"],"options":[{"text":"None","correct":false},{"text":"Read-only","correct":true},{"text":"Read/Write","correct":false}],"explanation":["`Read-only `is correct because it provides a balance between performance and data durability. Enabling Read-only caching on a Premium SSD with zone-redundant storage (ZRS) allows frequently accessed data to be cached, which enhances read performance without risking significant data loss. In the event of a host failure, data is read from the redundant storage across zones, ensuring data resiliency. Since only read operations are cached, the data stored on disk remains consistent and resilient to host failures, addressing the requirement of no data loss.","Although None caching eliminates any risk of data loss, Read-only caching is acceptable for workloads that prioritize high performance and data resiliency, as it does not impact data integrity during writes.","`None` is incorrect because, while it prevents any risk of data loss, it does not utilize the performance benefits of read caching, which may be desirable for high-performance workloads with Premium SSD storage.","`Read/Write` is incorrect as it caches both read and write operations on the host, which can result in data loss in the event of a host failure. This does not meet the requirement to ensure that no data loss occurs if a host fails."],"references":["https://learn.microsoft.com/en-us/azure/architecture/example-scenario/identity/adds-extend-domain#vm-recommendations"],"images":[],"topic":"identity","needsImage":false},{"id":"3-58","test":3,"number":58,"stem":["You have an Azure subscription that includes the following resources:","- VNet1 - Virtual network located in West US, in RG2","- VNet2 - Virtual network located in West US, in RG1","- VNet3 - Virtual network located in East US, in RG1","- NSG1 - Network security group located in East US, in RG2","To which subnets can you apply NSG1?"],"options":[{"text":"the subnets on VNet1 only","correct":false},{"text":"the subnets on VNet2 only","correct":false},{"text":"the subnets on VNet3 only","correct":true},{"text":"the subnets on VNet2 and VNet3 only","correct":false},{"text":"the subnets on VNet1, VNet2, and VNet3","correct":false}],"explanation":["`the subnets on VNet3 only` is correct because a network security group (NSG) must be in the same region as the virtual network or subnets to which it is applied. NSG1 is in the East US region, and therefore it can only be applied to the subnets within VNet3, as VNet3 is also in the East US region."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/azure/security/fundamentals/network-best-practices"],"images":[],"topic":"identity","needsImage":false},{"id":"3-59","test":3,"number":59,"stem":["**Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named ironclad.com and an Azure subscription named Subscription1. The tenant contains a group called Developers. The subscription contains a resource group named Dev.","You need to allow the Developers group to create Azure Logic Apps in the Dev resource group.","Proposed Solution: You assign the Contributor role to the Developers group at the Dev resource group scope.","Does this configuration satisfy the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because assigning the Contributor role to the Developers group at the Dev resource group level allows the group members to manage all resources within the resource group, including the ability to create Azure Logic Apps. The Contributor role provides full access to manage resources without granting permissions to assign roles or manage access, which fulfills the requirement stated in the question."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"3-60","test":3,"number":60,"stem":["**Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement.","You have a Microsoft Entra tenant named ironclad.com and an Azure subscription named Subscription1. The tenant contains a group called Developers. The subscription contains a resource group named Dev.","You need to allow the Developers group to create Azure Logic Apps in the Dev resource group.","Proposed Solution: On the Dev resource group, you grant the Logic App Contributor role to the Developers group.","Does this configuration satisfy the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because the Logic App Contributor role provides the necessary permissions to manage Azure Logic Apps within the assigned scope, which includes creating, updating, and deleting logic apps. Assigning this role to the Developers group at the Dev resource group level fulfills the requirement to allow the group to create Azure Logic Apps in the Dev resource group without granting broader permissions."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#logic-app-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"3-61","test":3,"number":61,"stem":["You have an Azure subscription that includes a virtual network named VNet1.","VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:","- Subnet0 (IP address range: 10.0.0.0/24)","- Subnet1 (IP address range: 10.0.1.0/24)","- Subnet2 (IP address range: 10.0.2.0/24)","- GatewaySubnet (IP address range: 10.0.254.0/24)","Subnet1 hosts a virtual appliance named VM1, which functions as a router.","You create a route table named RT1.","You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1.","You plan to configure RT1 accordingly.","What value should you specify for the address prefix?"],"options":[{"text":"10.0.0.0/16","correct":true},{"text":"10.0.1.0/24","correct":false},{"text":"10.0.254.0/24","correct":false}],"explanation":["`10.0.0.0/16` is correct because it represents the entire IP address range of VNet1, including all its subnets (Subnet0, Subnet1, Subnet2, and GatewaySubnet). Configuring this address prefix in the route table ensures that all traffic arriving at the VPN gateway and destined for any subnet in VNet1 is routed through the virtual appliance (VM1) in Subnet1.","`10.0.1.0/24` is incorrect because this prefix only applies to Subnet1. Configuring RT1 with this prefix will not ensure that all traffic from the VPN gateway to the other subnets passes through VM1.","`10.0.254.0/24` is incorrect because this prefix refers specifically to the GatewaySubnet. It does not cover the entire VNet, and traffic to other subnets will not be routed through VM1."],"references":["https://azure.microsoft.com/en-in/solutions/network-appliances/","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-62","test":3,"number":62,"stem":["You have an Azure subscription that includes a virtual network named VNet1.","VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:","- Subnet0 (IP address range: 10.0.0.0/24)","- Subnet1 (IP address range: 10.0.1.0/24)","- Subnet2 (IP address range: 10.0.2.0/24)","- GatewaySubnet (IP address range: 10.0.254.0/24)","Subnet1 hosts a virtual appliance named VM1, which functions as a router.","You create a route table named RT1.","You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1.","You plan to configure RT1 accordingly.","What value should you specify for the next hop type?"],"options":[{"text":"Virtual appliance","correct":true},{"text":"Virtual network","correct":false},{"text":"Virtual network gateway","correct":false}],"explanation":["`Virtual appliance` is correct because the virtual appliance next-hop type is used when traffic needs to be routed through a specific virtual machine or network virtual appliance (NVA). In this scenario, VM1 in Subnet1 acts as a router for all inbound traffic from the VPN gateway. The routing table RT1 should use the \"Virtual appliance\" next-hop type to direct traffic to the virtual machine.","`Virtual network` is incorrect because it refers to routing traffic within the virtual network itself, not specifically through a virtual machine or appliance acting as a router.","`Virtual network gateway` is incorrect because it refers to routing traffic to or through an Azure VPN Gateway. In this case, the traffic has already reached the VPN Gateway and needs to be routed through the virtual appliance (VM1)."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://azure.microsoft.com/en-in/solutions/network-appliances/"],"images":[],"topic":"identity","needsImage":false},{"id":"3-63","test":3,"number":63,"stem":["You have an Azure subscription that includes a virtual network named VNet1.","VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:","- Subnet0 (IP address range: 10.0.0.0/24)","- Subnet1 (IP address range: 10.0.1.0/24)","- Subnet2 (IP address range: 10.0.2.0/24)","- GatewaySubnet (IP address range: 10.0.254.0/24)","Subnet1 hosts a virtual appliance named VM1, which functions as a router.","You create a route table named RT1.","You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1.","You plan to configure RT1 accordingly.","Which option should you select for the Assigned to setting?"],"options":[{"text":"GatewaySubnet","correct":true},{"text":"Subnet0","correct":false},{"text":"Subnet1 and Subnet2","correct":false}],"explanation":["`GatewaySubnet` is correct because the routing table RT1 must be associated with the GatewaySubnet to ensure that all traffic coming from the VPN Gateway is routed through the virtual appliance (VM1) in Subnet1. The GatewaySubnet is a dedicated subnet for VPN Gateway and requires proper routing configuration to direct traffic appropriately.","`Subnet0` is incorrect because associating the route table with Subnet0 would not ensure that traffic from the VPN Gateway is routed through the virtual appliance in Subnet1.","`Subnet1 and Subnet2` is incorrect because associating the route table with these subnets does not target the GatewaySubnet, which is the entry point for VPN traffic. Routing must start from the GatewaySubnet."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpn-gateway-settings","https://azure.microsoft.com/en-in/solutions/network-appliances"],"images":[],"topic":"identity","needsImage":false},{"id":"3-64","test":3,"number":64,"stem":["You have a virtual network named VNET1 that includes the following subnets:","You also have the following Azure virtual machines with the listed network configurations:","For NSG1, you configure the following inbound security rule:","- Priority: 101","- Source: 10.10.2.0/24","- Destination: 10.10.1.0/24","- Destination port: TCP 1433","- Action: Allow","For NSG2, you configure the following inbound security rule:","- Priority: 125","- Source: 10.10.2.5","- Destination: 10.10.1.5","- Destination port: TCP 1433","- Action: Block","True or False:","`“VM2 can connect to the TCP port 1433 services on VM1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because the traffic from VM2 to VM1 on TCP port 1433 must be allowed by both NSGs in the inbound path. For inbound traffic to VM1, Azure evaluates the subnet-level NSG first and then the NIC-level NSG. NSG1 allows TCP 1433 traffic from 10.10.2.0/24 to 10.10.1.0/24, so the traffic is allowed at the subnet level. However, NSG2, which is associated with VM1’s NIC, explicitly blocks TCP 1433 traffic from 10.10.2.5 to 10.10.1.5. Since the traffic is denied at the NIC level, the connection from VM2 to VM1 fails."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"],"images":["assets/6eeb23b1153e978f.png","assets/01c59f3d5536523e.png"],"topic":"network","needsImage":true},{"id":"3-65","test":3,"number":65,"stem":["You have a virtual network named VNET1 that includes the following subnets:","You also have the following Azure virtual machines with the listed network configurations:","For NSG1, you configure the following inbound security rule:","- Priority: 101","- Source: 10.10.2.0/24","- Destination: 10.10.1.0/24","- Destination port: TCP 1433","- Action: Allow","For NSG2, you configure the following inbound security rule:","- Priority: 125","- Source: 10.10.2.5","- Destination: 10.10.1.5","- Destination port: TCP 1433","- Action: Block","True or False:","`“VM1 can connect to the TCP port 1433 services on VM2.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because there are no Network Security Groups (NSGs) applied to Subnet2, where VM2 resides, or directly to VM2's network interface. NSG1 is applied at Subnet1, allowing traffic from Subnet2 to Subnet1 on TCP port 1433. NSG2 is applied at VM1's network interface, but it explicitly blocks inbound traffic from 10.10.2.5 (VM2) to 10.10.1.5 (VM1) on TCP port 1433. However, the direction of traffic in this question is from VM1 to VM2, not the other way around. Therefore, the NSG rules blocking inbound traffic on VM1 do not apply in this scenario, and the outbound connection from VM1 to VM2 is not blocked."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"],"images":["assets/6eeb23b1153e978f.png","assets/01c59f3d5536523e.png"],"topic":"network","needsImage":true},{"id":"3-66","test":3,"number":66,"stem":["You have a virtual network named VNET1 that includes the following subnets:","You also have the following Azure virtual machines with the listed network configurations:","For NSG1, you configure the following inbound security rule:","- Priority: 101","- Source: 10.10.2.0/24","- Destination: 10.10.1.0/24","- Destination port: TCP 1433","- Action: Allow","For NSG2, you configure the following inbound security rule:","- Priority: 125","- Source: 10.10.2.5","- Destination: 10.10.1.5","- Destination port: TCP 1433","- Action: Block","True or False:","`“VM2 can connect to the TCP port 1433 services on VM3.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because there are no Network Security Groups (NSGs) applied to Subnet2, where VM3 resides, or directly to VM3's network interface. NSG1, applied to Subnet1, allows traffic from Subnet2 (10.10.2.0/24) to Subnet1 (10.10.1.0/24) on TCP port 1433.","The rule in NSG2 that blocks inbound traffic specifically applies to traffic from VM2 (10.10.2.5) to VM1 (10.10.1.5), but not to VM3 (10.10.2.6). Therefore, VM2 can successfully connect to TCP port 1433 services on VM3 without restriction."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"],"images":["assets/6eeb23b1153e978f.png","assets/01c59f3d5536523e.png"],"topic":"network","needsImage":true},{"id":"3-67","test":3,"number":67,"stem":["You have four Azure virtual machines with the following configurations:","- VM1 – IP address 10.1.0.4, connected to VNET1/Subnet1","- VM2 – IP address 10.1.10.4, connected to VNET1/Subnet2","- VM3 – IP address 172.16.0.4, connected to VNET2/SubnetA","- VM4 – IP address 10.2.0.8, connected to VNET3/SubnetB","A DNS service is installed on VM1.","You configure the DNS server settings on each virtual network to use a custom DNS server with the IP address 10.1.0.4.","You need to ensure that all the virtual machines can resolve DNS names by using the DNS service on VM1.","What action should you take?"],"options":[{"text":"Add service endpoints on VNET2 and VNET3.","correct":false},{"text":"Configure peering between VNET1, VNET2, and VNET3.","correct":true},{"text":"Add service endpoints on VNET1.","correct":false},{"text":"Configure a conditional forwarder on VM1.","correct":false}],"explanation":["`Configure peering between VNET1, VNET2, and VNET3` is the correct option because DNS queries sent to a custom DNS server (VM1 in this case) require network connectivity between the virtual networks. Virtual network peering allows resources in different VNets to communicate seamlessly. Once peering is configured, all DNS traffic can route correctly through VM1.","`Add service endpoints on VNET2 and VNET3` is incorrect because service endpoints are used for secure connections to Azure services like Storage or SQL, not for enabling DNS resolution between VNets.","`Add service endpoints on VNET1` is incorrect for the same reason, as service endpoints don't facilitate cross-VNet DNS resolution.","`Configure a conditional forwarder on VM1` is incorrect because a conditional forwarder directs DNS queries to specific DNS servers based on domain names. However, without VNet peering, the DNS traffic wouldn't route between VNets."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"images":[],"topic":"network","needsImage":false},{"id":"3-68","test":3,"number":68,"stem":["You intend to use Azure Network Watcher to perform the following activity:","- Test and confirm outbound network connectivity from an Azure virtual machine to an external destination.","Which feature should you use for the above task?"],"options":[{"text":"Connection troubleshoot","correct":true},{"text":"IP flow verify","correct":false},{"text":"Next hop","correct":false},{"text":"NSG flow logs","correct":false},{"text":"Traffic Analytics","correct":false}],"explanation":["`Connection troubleshoot` is the correct option because it is specifically designed to validate outbound connectivity from an Azure virtual machine (VM) to an external host. This feature checks the end-to-end connection and identifies if the connection succeeds or fails, providing insights into network latency, packet loss, and the point of failure.","`IP flow verify` is incorrect because it checks whether a specific packet is allowed or denied by security rules, but it does not validate the entire outbound connection path.","`Next hop `is incorrect because it shows the next hop a packet will take to reach its destination but does not validate the outbound connection itself.","`NSG flow logs` is incorrect because it provides a record of traffic through network security groups (NSGs) but does not validate outbound connectivity.","`Traffic Analytics` is incorrect because it analyzes traffic patterns and usage but does not validate specific outbound connections."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-connectivity-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview"],"images":[],"topic":"compute","needsImage":false},{"id":"3-69","test":3,"number":69,"stem":["You intend to use Azure Network Watcher to perform the following activity:","- Determine which security rule is blocking a network packet from reaching an Azure virtual machine.","Which feature should you use for the above task?"],"options":[{"text":"IP flow verify","correct":true},{"text":"Next hop","correct":false},{"text":"Packet capture","correct":false},{"text":"Traffic Analytics","correct":false}],"explanation":["`IP flow verify` is the correct option because this feature in Azure Network Watcher is specifically designed to identify whether a network packet is allowed or denied to or from an Azure virtual machine (VM). It evaluates the effective security rules applied to the VM's network interface and identifies the rule responsible for blocking or allowing the traffic.","`Next hop` is incorrect because it helps determine the route a packet takes to reach its destination but does not identify security rules blocking traffic.","`Packet capture` is incorrect because it captures live packet data for network traffic but does not identify which security rule is affecting the traffic.","`Traffic Analytics` is incorrect because it provides insights into traffic flow patterns and network resource usage, but it does not identify the specific security rule blocking traffic."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-ip-flow-verify-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview"],"images":[],"topic":"compute","needsImage":false},{"id":"3-70","test":3,"number":70,"stem":["You have an Azure subscription named Subscription1 that includes a virtual network called VNet1, which resides in a resource group named RG1.","A user named User1 has been assigned the following roles at the Subscription1 scope:","- Reader","- Security Admin","- Security Reader","You must ensure that User1 is able to assign the Reader role on VNet1 to other users.","What action should you take?"],"options":[{"text":"Remove User1 from the Security Reader and Reader roles at the Subscription1 level, and then assign User1 the Contributor role for Subscription1.","correct":false},{"text":"Remove User1 from the Security Reader and Reader roles at the Subscription1 level.","correct":false},{"text":"Assign User1 the User Access Administrator role at the VNet1 scope.","correct":true},{"text":"Remove User1 from the Security Reader role at the Subscription1 level, and then assign User1 the Contributor role for the RG1 resource group.","correct":false}],"explanation":["`Assign User1 the User Access Administrator role at the VNet1 scope` is the correct answer because the User Access Administrator role allows a user to manage user access to resources, including assigning RBAC roles such as Reader to other users. While User1 already has the Reader, Security Admin, and Security Reader roles, none of these roles grant the ability to assign RBAC roles to other users. Assigning the User Access Administrator role at the scope of VNet1 ensures that User1 has the necessary permissions to assign roles without granting broader privileges at the subscription or resource group level, adhering to the principle of least privilege.","`Remove User1 from the Security Reader and Reader roles at the Subscription1 level, and then assign User1 the Contributor role for Subscription1` is incorrect because the Contributor role allows managing resources but does not grant role assignment capabilities.","`Remove User1 from the Security Reader and Reader roles at the Subscription1 level` is incorrect because simply removing existing roles does not grant any permissions for role assignment.","`Remove User1 from the Security Reader role at the Subscription1 level, and then assign User1 the Contributor role for the RG1 resource group` is incorrect because the Contributor role at the resource group level (RG1) does not allow assigning roles for VNet1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/role-definitions","https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-71","test":3,"number":71,"stem":["You have an Azure subscription that includes the following resources:","- Ten network security groups (NSGs)","- Ten virtual machines","- One Log Analytics workspace named Workspace1","Each network security group is associated with the network interface of a virtual machine.","You want to configure an Azure Monitor Network Insights alert that triggers when suspicious network traffic is detected.","What action should you perform first?"],"options":[{"text":"Deploy Connection Monitor.","correct":false},{"text":"Configure NSG flow logs.","correct":true},{"text":"Configure data collection endpoints.","correct":false},{"text":"Configure a private link.","correct":false}],"explanation":["`Configure NSG flow logs` is the correct answer because Azure Monitor Network Insights relies on NSG flow logs to analyze and detect suspicious network traffic. NSG flow logs capture detailed information about IP traffic flowing through network security groups, including source and destination IPs, ports, and protocols.","Enabling NSG flow logs is a prerequisite for Azure Monitor to process network traffic data and identify anomalies or suspicious activities. These logs are sent to a Log Analytics workspace (e.g., Workspace1) for further analysis.","`Deploy Connection Monitor` is incorrect because Connection Monitor is used for monitoring network connectivity and performance between Azure resources or between Azure and on-premises resources. It does not directly facilitate alerting based on suspicious network traffic.","`Configure data collection endpoints` is incorrect because data collection endpoints (DCEs) are primarily used for routing Azure Monitor Agent data. They are not directly related to enabling NSG flow logs or configuring Network Insights alerts.","`Configure a private link` is incorrect because private links are used to securely access Azure services over a private IP address. They do not play a role in enabling network traffic analysis or triggering alerts for suspicious traffic."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/nsg-flow-logs-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"3-72","test":3,"number":72,"stem":["You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit.","On January 1, the following blobs are uploaded to storage1:","- File1 is stored in the Hot access tier","- File2 is stored in the Cool access tier","- File3 is stored in the Archive access tier","You then perform these actions:","- On January 5, File1 is deleted","- On January 15, File2 is moved to the Archive access tier","- On April 5, File3 is rehydrated","True or False:","`“You are charged an early deletion penalty for File1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. File1 was uploaded to the storage account under the Hot access tier on January 1 and then deleted on January 5. The Hot tier does not have an early deletion penalty, regardless of the deletion time.","For reference, the access tiers and their minimum retention periods for avoiding early deletion charges are as follows:","- Hot: No minimum retention period; early deletion penalty does not apply.","- Cool: 30 days minimum retention period.","- Cold: 90 days minimum retention period.","- Archive: 180 days minimum retention period.","Since File1 was stored in the Hot tier, it incurs no early deletion penalty even if it is deleted within days of upload.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview#early-deletion-charge"],"references":[],"images":["assets/8c55c4a24715e4ee.png"],"topic":"storage","needsImage":true},{"id":"3-73","test":3,"number":73,"stem":["You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit.","On January 1, the following blobs are uploaded to storage1:","- File1 is stored in the Hot access tier","- File2 is stored in the Cool access tier","- File3 is stored in the Archive access tier","You then perform these actions:","- On January 5, File1 is deleted","- On January 15, File2 is moved to the Archive access tier","- On April 5, File3 is rehydrated","True or False:","`“You are charged an early deletion penalty for File2.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. File2 was added on January 1 with the Cool access tier and was moved to the Archive access tier on January 15; just 14 days after it was created. The Cool tier has a minimum retention period of 30 days, meaning that if a blob is deleted, overwritten, or moved to another tier before 30 days, an early deletion penalty applies.","Since File2 was moved from Cool to Archive after 14 days, Azure will apply a prorated early deletion charge for 16 days (i.e., 30 - 14). This charge reflects the unused portion of the required minimum retention period in the Cool tier.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview"],"references":[],"images":["assets/8c55c4a24715e4ee.png"],"topic":"storage","needsImage":true},{"id":"3-74","test":3,"number":74,"stem":["You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit.","On January 1, the following blobs are uploaded to storage1:","- File1 is stored in the Hot access tier","- File2 is stored in the Cool access tier","- File3 is stored in the Archive access tier","You then perform these actions:","- On January 5, File1 is deleted","- On January 15, File2 is moved to the Archive access tier","- On April 5, File3 is rehydrated","True or False:","`“You are charged an early deletion penalty for File3.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. File3 was uploaded on January 1 and placed in the Archive access tier. It was then rehydrated (i.e., restored to an online tier such as Hot or Cool) on April 5, which is 94 days after it was archived.","The Archive tier has a minimum retention period of 180 days. If a blob is rehydrated, deleted, or moved before 180 days, Azure applies a prorated early deletion fee for the remaining days.","In this case, File3 remained in the Archive tier for only 94 days, so an early deletion charge equivalent to 86 days (180 - 94) will be incurred.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview#early-deletion-charge"],"references":[],"images":["assets/8c55c4a24715e4ee.png"],"topic":"storage","needsImage":true},{"id":"3-75","test":3,"number":75,"stem":["You manage two Azure subscriptions named Subscription1 and Subscription2.","Subscription1 has the following virtual networks:","The virtual networks contain the following subnets:","Subscription 2 contains the following virtual network:","- Name: VNETA","- Address space: 10.10.128.0/17","- Location: Canada Central","VNETA contains the following subnets:","True or False:","`“A Site-to-site connection can be established between VNET1 and VNET2.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. A Site-to-Site connection in Azure requires a gateway subnet to be present in each virtual network that participates in the connection. However, in this case, VNet1 uses the entire address space `10.10.10.0/24` for Subnet11, leaving no free IP range available to define a gateway subnet within VNet1.","Since Azure requires a dedicated subnet named `GatewaySubnet` with available IPs in the address space for a VPN gateway to function, and VNet1 does not have any spare address space, you cannot deploy a gateway there.","Because of this, a Site-to-Site connection cannot be established between VNet1 and VNet2, even though their address spaces do not overlap.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-howto-site-to-site-resource-manager-portal","- https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways","- https://learn.microsoft.com/en-us/azure/vpn-gateway/tutorial-site-to-site-portal"],"references":[],"images":["assets/8cf997d02f9b9243.png","assets/cdff7dffa0b86d54.png","assets/a824d6e01381eb66.png"],"topic":"identity","needsImage":true},{"id":"3-76","test":3,"number":76,"stem":["You manage two Azure subscriptions named Subscription1 and Subscription2.","Subscription1 has the following virtual networks:","The virtual networks contain the following subnets:","Subscription 2 contains the following virtual network:","- Name: VNETA","- Address space: 10.10.128.0/17","- Location: Canada Central","VNETA contains the following subnets:","True or False:","`“VNET1 and VNET2 can be peered.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. Azure virtual network peering supports connections between virtual networks under the following conditions:","- The address spaces of the VNets must not overlap","- The VNets can be in the same or different Azure regions","- The VNets can belong to the same or different subscriptions","In this case:","- VNET1 has an address space of `10.10.10.0/24`","- VNET2 has an address space of `172.16.0.0/16`","These address spaces do not overlap, which satisfies the IP requirement.","Additionally:","- VNET1 is located in West US","- VNET2 is located in West Europe","Azure supports global virtual network peering, which allows peering between virtual networks in different Azure regions.","Therefore, VNET1 and VNET2 can be peered using global VNet peering, and no technical limitation prevents this configuration.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"],"references":[],"images":["assets/8cf997d02f9b9243.png","assets/cdff7dffa0b86d54.png","assets/a824d6e01381eb66.png"],"topic":"identity","needsImage":true},{"id":"3-77","test":3,"number":77,"stem":["You manage two Azure subscriptions named Subscription1 and Subscription2.","Subscription1 has the following virtual networks:","The virtual networks contain the following subnets:","Subscription 2 contains the following virtual network:","- Name: VNETA","- Address space: 10.10.128.0/17","- Location: Canada Central","VNETA contains the following subnets:","True or False:","`“VNET1 and VNETA can be peered.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here.","Azure allows peering between VNets as long as the following conditions are met:","- No overlapping address ranges","- VNets can be in the same or different subscriptions","- VNets can be in the same or different regions","Since VNET1 and VNETA are in different regions but have non-overlapping IP ranges, they can be peered using global VNet peering.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"],"references":[],"images":["assets/8cf997d02f9b9243.png","assets/cdff7dffa0b86d54.png","assets/a824d6e01381eb66.png"],"topic":"identity","needsImage":true},{"id":"3-78","test":3,"number":78,"stem":["You have an Azure virtual machine named VM1 that is connected to a virtual network called VNet1. VM1 has the following configuration:","- Subnet: 10.0.0.0/24","- Availability set: AVSet","- Network security group (NSG): None","- Private IP address: 10.0.0.4 (dynamic)","- Public IP address: 40.90.219.6 (dynamic)","You deploy a Standard, internet-facing Azure Load Balancer named slb1.","You need to configure slb1 to allow inbound traffic to VM1, and you are permitted to make any required changes to VM1 during the configuration.","Complete the following statement:","“Before creating a backend pool on slb1, you must ____________________.”"],"options":[{"text":"Create and assign an NSG to VM1","correct":false},{"text":"Remove the public IP address from VM1","correct":true},{"text":"Change the private IP address of VM1 to static","correct":false}],"explanation":["`Remove the public IP address from VM1` is the correct answer here. When using a Standard, Internet-facing Azure Load Balancer, virtual machines that are part of the backend pool should not have individual public IP addresses assigned. Instead, all inbound traffic should be directed to the load balancer’s frontend public IP, and the load balancer will distribute that traffic to the VMs in the backend pool.","In this case, VM1 currently has a dynamic public IP address. For proper configuration with Standard SKU Load Balancer, this dynamic public IP should be removed, and the VM should receive traffic only through the load balancer. The Standard Load Balancer also requires a Standard SKU public IP to be assigned to its frontend configuration—not to the individual VM.","`Create and assign an NSG to VM1` is incorrect because NSGs control traffic flow at the subnet or NIC level but are not required to add a VM to a Standard Load Balancer backend pool. While NSGs can be used for security, they are not relevant to this prerequisite.","`Change the private IP address of VM1 to static` is incorrect in this specific scenario because the VM is being added to a Standard Load Balancer in an Internet-facing configuration. In such cases, the VM’s private IP does not need to be static—only the load balancer’s public IP needs to be static and Standard SKU. The private IP requirement typically applies when the load balancer is internal, not Internet-facing.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/quickstart-load-balancer-standard-public-portal","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-troubleshoot#vms-in-backend-pool-need-to-have-no-public-ip-or-use-standard-public-ip-only"],"references":[],"images":[],"topic":"network","needsImage":false},{"id":"3-79","test":3,"number":79,"stem":["You have an Azure virtual machine named VM1 that is connected to a virtual network called VNet1. VM1 has the following configuration:","- Subnet: 10.0.0.0/24","- Availability set: AVSet","- Network security group (NSG): None","- Private IP address: 10.0.0.4 (dynamic)","- Public IP address: 40.90.219.6 (dynamic)","You deploy a Standard, internet-facing Azure Load Balancer named slb1.","You need to configure slb1 to allow inbound traffic to VM1, and you are permitted to make any required changes to VM1 during the configuration.","Complete the following statement:","“Before you can connect to VM1 from slb1, you must______________________.”"],"options":[{"text":"Create and configure an NSG","correct":true},{"text":"Remove the public IP address from VM1","correct":false},{"text":"Change the private IP address of VM1 to static","correct":false}],"explanation":["`Create and configure an NSG` is the correct answer here. In the context of an Internet-facing Standard Load Balancer, after configuring the load balancer and assigning a static, standard public IP to the frontend, you must ensure that traffic is allowed through to the VM. A Network Security Group (NSG) is required to define and permit inbound traffic (such as TCP on port 80 or 443) to the VM or subnet where the VM resides.","By default, no inbound traffic is allowed unless explicitly permitted via an NSG. Without an NSG rule allowing the required traffic, even if the frontend IP and backend pool are configured correctly, the connection to VM1 through slb1 would fail due to traffic being denied at the network layer.","`Remove the public IP address from VM1` is incorrect because this step is only relevant if the VM had a dynamic public IP that conflicted with the Standard Load Balancer setup. Since the public IP has already been properly configured in the prior step, there's no need to remove it again. The focus now is on allowing traffic through to the VM, not modifying its IP configuration.","`Change the private IP address of VM1 to static` is incorrect because this is only required in the context of an internal load balancer or when backend pools rely on consistent internal addressing. For Internet-facing load balancers, private IP settings are not critical for enabling frontend communication. What’s essential is that the NSG allows the traffic to reach the backend VM.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-troubleshoot#ensure-nsgs-allow-traffic-to-vms-in-the-backend-pool"],"references":[],"images":[],"topic":"network","needsImage":false},{"id":"3-80","test":3,"number":80,"stem":["You have an Azure virtual network named VNet1 that is connected to an on-premises network by using a site-to-site VPN. VNet1 includes a single subnet named Subnet1.","Subnet1 is associated with a network security group (NSG) called NSG1. The subnet hosts a basic internal load balancer named ILB1, which has three Azure virtual machines configured in its backend pool.","You need to collect information about the IP addresses that establish connections to ILB1. The collected data must be available for interactive querying directly from the Azure portal.","Which resource should you create to meet this requirement?"],"options":[{"text":"An Azure Event Grid","correct":false},{"text":"An Azure Log Analytics workspace","correct":true},{"text":"An Azure Storage account","correct":false}],"explanation":["`An Azure Log Analytics workspace` is the correct answer here. To collect and analyze data about incoming IP addresses connecting to resources like an internal load balancer (ILB1), and to run interactive queries via the Azure portal, the data must be sent to a Log Analytics workspace.","By enabling NSG flow logs on NSG1 (which is associated with Subnet1), you can capture information such as source and destination IP addresses, ports, protocols, and whether traffic was allowed or denied. These logs can be sent to a Log Analytics workspace, where they are indexed and made available for querying using Kusto Query Language (KQL).","`An Azure Event Grid` is incorrect because it is used for event-based messaging and automation—not for storing or querying traffic flow data.","`An Azure Storage account` is incorrect in this context because although NSG flow logs can be stored in a storage account, you cannot run interactive queries on the data from the Azure portal unless the data is also sent to a Log Analytics workspace.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-monitor/logs/quick-create-workspace?tabs=azure-portal","- https://learn.microsoft.com/en-us/azure/azure-monitor/logs/log-analytics-workspace-overview","- https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-portal","- https://learn.microsoft.com/en-us/azure/event-grid/overview","- https://learn.microsoft.com/en-us/azure/storage/common/storage-introduction"],"references":[],"images":[],"topic":"network","needsImage":false},{"id":"3-81","test":3,"number":81,"stem":["You have an Azure virtual network named VNet1 that is connected to an on-premises network by using a site-to-site VPN. VNet1 includes a single subnet named Subnet1.","Subnet1 is associated with a network security group (NSG) called NSG1. The subnet hosts a basic internal load balancer named ILB1, which has three Azure virtual machines configured in its backend pool.","You need to collect information about the IP addresses that establish connections to ILB1. The collected data must be available for interactive querying directly from the Azure portal.","On which resource should you enable diagnostics?"],"options":[{"text":"ILB1","correct":false},{"text":"NSG1","correct":true},{"text":"The Azure virtual machines","correct":false}],"explanation":["`NSG1` is the correct answer here. To collect data about the IP addresses that connect to ILB1, you must monitor network traffic, and the correct way to do this in Azure is by enabling NSG flow logs on the Network Security Group (NSG) associated with the subnet or network interface.","In this case:","- NSG1 is associated with Subnet1, which contains ILB1 and its backend virtual machines.","- Enabling diagnostic settings (NSG flow logs) on NSG1 captures detailed flow-level information such as source IP, destination IP, port, protocol, and action (allow/deny).","- The logs can be sent to a Log Analytics workspace, where you can run interactive queries using Kusto Query Language (KQL) directly from the Azure portal.","`ILB1` is incorrect because while you can enable diagnostics on a load balancer, it captures metrics like health probe status and data throughput, not connection-level details like source IP addresses.","`The Azure virtual machines` is incorrect because enabling diagnostics on the VMs focuses on performance and system logs (e.g., CPU, disk, guest OS), but not on the network flow data you need for this scenario.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-overview","- https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-portal"],"references":[],"images":[],"topic":"network","needsImage":false},{"id":"3-82","test":3,"number":82,"stem":["You manage an Azure subscription in which you create an Azure Container Registry (ACR) and build a container image locally.","You plan to upload the container image to the Azure Container Registry by using the Azure Command-Line Interface (CLI).","After successfully signing in to the container registry, what should you do next to prepare the image for upload?"],"options":[{"text":"Assign a tag to the container image that includes the container registry’s login server name.","correct":true},{"text":"Display a list of container images that already exist in the container registry.","correct":false},{"text":"Deploy a container group.","correct":false},{"text":"Configure a YAML file.","correct":false}],"explanation":["`Assign a tag to the container image that includes the container registry’s login server name` is the correct answer here. After signing in to an Azure Container Registry (ACR), the next required step to push a container image is to tag the image using the registry’s login server URL. This tag identifies the destination registry and repository for the image. The format typically looks like:","az acr login --name <registryName>","docker tag <localImageName> <registryName>.azurecr.io/<repositoryName>:<tag>","docker push <registryName>.azurecr.io/<repositoryName>:<tag>This step is necessary because Docker uses the tag to determine where the image should be pushed. Without tagging the image with the correct registry address, the `docker push` command will not know the target location.","`Display a list of container images that already exist in the container registry` is incorrect because it does not help in preparing an image for upload.","`Deploy a container group` is incorrect because this step would come after the image is already pushed and available in the container registry.","`Configure a YAML file` is incorrect because YAML files are typically used for defining deployments in Kubernetes or other orchestration platforms, not for pushing container images.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-azure-cli","- https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"3-83","test":3,"number":83,"stem":["You have an application named App1 that will be deployed on two Azure virtual machines, VM1 and VM2.","You plan to use an Azure Availability Set for App1. The solution must ensure that App1 remains available when Azure performs planned maintenance on the physical hardware hosting VM1 and VM2.","What configuration should you include when creating the Availability Set?"],"options":[{"text":"one update domain","correct":false},{"text":"two update domains","correct":true},{"text":"one fault domain","correct":false},{"text":"two fault domains","correct":false}],"explanation":["`two update domains` is the correct answer here. Update domains in an Availability Set ensure that not all virtual machines are rebooted at the same time during planned maintenance events, such as OS patching or Azure platform updates. By placing VM1 and VM2 in two separate update domains, Azure ensures that only one VM is rebooted at a time, keeping App1 available during maintenance.","This satisfies the requirement to maintain availability of App1 during planned maintenance, which is exactly what update domains are designed to protect against.","`one update domain` is incorrect because placing both VMs in the same update domain would allow both to be rebooted simultaneously during planned maintenance, causing downtime for App1.","`one fault domain` and `two fault domains` are incorrect in this context because fault domains deal with unplanned hardware failures, not planned maintenance. While fault domains enhance resilience to physical failures, they do not ensure availability during platform maintenance activities.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview","- https://learn.microsoft.com/en-us/azure/virtual-machines/availability"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"3-84","test":3,"number":84,"stem":["You have an Azure subscription that includes an Azure Storage account named storage1.","The subscription has the following users and group memberships:","- User1 is a member of Group1.","- User2 is a member of Group2.","- User3 is a member of Group1.","You plan to monitor storage1 and configure email notifications for specific monitoring signals.","The notification requirements are as follows:","How many Alert rules are required to meet all the monitoring and notification requirements."],"options":[{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":false},{"text":"4","correct":true}],"explanation":["`4` is correct. Four alert rules are required because alert rules are based on unique combinations of signal type (Metric vs. Activity log) and conditions.","Here we have 4 different signals, so each rule will monitor a distinct event."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"],"images":["assets/bc8d5ac3d3b26d26.png"],"topic":"identity","needsImage":true},{"id":"3-85","test":3,"number":85,"stem":["You have an Azure subscription that includes an Azure Storage account named storage1.","The subscription has the following users and group memberships:","- User1 is a member of Group1.","- User2 is a member of Group2.","- User3 is a member of Group1.","You plan to monitor storage1 and configure email notifications for specific monitoring signals.","The notification requirements are as follows:","How many Action groups are required to meet all the monitoring and notification requirements."],"options":[{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":true},{"text":"4","correct":false}],"explanation":["`3` is correct. An Action Group defines who gets notified and how. You need a separate Action Group only when the set of recipients (users) is different. Looking at the notification requirements:","- Ingress: Notifies User1 and User3 - Action Group 1","- Egress: Notifies User1 only - Action Group 2","- Delete storage account: Notifies User1, User2, and User3 - Action Group 3","- Restore blob ranges: Notifies User1 and User3 - Same as Ingress - reuse Action Group 1","So, only three distinct sets of recipients, hence 3 Action Groups are required."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups","https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview"],"images":["assets/bc8d5ac3d3b26d26.png"],"topic":"identity","needsImage":true},{"id":"3-86","test":3,"number":86,"stem":["You manage two Azure App Service apps named App1 and App2. Each app contains:","- A production deployment slot","- A test deployment slot","The backup settings for the production slots are configured as follows:","- App1","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 0 days","- Keep at least one backup: Yes","- App2","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 30 days","- Keep at least one backup: Yes","Based on this configuration, determine the effect of the backup and retention settings.","True or False:","`“On January 15, 2024, App1 will have only one backup in storage.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because the backup configuration for App1 specifies a retention period of 0 days with “Keep at least one backup” set to Yes. In Azure App Service, setting the retention to 0 means backups are retained indefinitely unless manually deleted. Additionally, the “keep at least one backup” option ensures that even if retention policies are applied, at least one backup is preserved.","Since App1 is backed up daily starting from January 6, 2024, by January 15, 2024, there would be multiple backups retained unless manually removed. Therefore, App1 would not have only one backup in storage on that date."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-backup","https://learn.microsoft.com/en-us/cli/azure/webapp/config/backup?view=azure-cli-latest"],"images":[],"topic":"storage","needsImage":false},{"id":"3-87","test":3,"number":87,"stem":["You manage two Azure App Service apps named App1 and App2. Each app contains:","- A production deployment slot","- A test deployment slot","The backup settings for the production slots are configured as follows:","- App1","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 0 days","- Keep at least one backup: Yes","- App2","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 30 days","- Keep at least one backup: Yes","Based on this configuration, determine the effect of the backup and retention settings.","True or False:","`“On February 6, 2024, you can access the backup of the App2 test slot from January 15, 2024.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because the backup configuration applies only to the production slot of App2, not the test slot. The table provided shows backup settings for the production slots of App1 and App2, and there is no mention of backups being configured for the test slot of App2.","Since Azure App Service does not automatically back up deployment slots other than the production slot unless explicitly configured, no backup of the App2 test slot from January 15, 2024 would exist by February 6, 2024."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-backup","https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"],"images":[],"topic":"compute","needsImage":false},{"id":"3-88","test":3,"number":88,"stem":["You manage two Azure App Service apps named App1 and App2. Each app contains:","- A production deployment slot","- A test deployment slot","The backup settings for the production slots are configured as follows:","- App1","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 0 days","- Keep at least one backup: Yes","- App2","- Backup frequency: Every 1 day","- Schedule start date: January 6, 2024","- Retention period: 30 days","- Keep at least one backup: Yes","Based on this configuration, determine the effect of the backup and retention settings.","True or False:","`“On January 15, 2024, you can restore the App2 production slot backup from January 6 to the App2 test slot.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct  because Azure App Service allows you to restore a backup taken from the production slot to any other slot of the same app, including a test slot. The backup of the App2 production slot from January 6, 2024 would still be available on January 15, 2024 because the retention policy is set to 30 days and the \"Keep at least one backup\" option is enabled.","This means that the backup from January 6 is retained and can be used to restore not only to the production slot but also to the test slot, assuming the restore operation is initiated within the retention period."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-backup#restore-an-app","https://learn.microsoft.com/en-us/azure/app-service/web-sites-staged-publishing"],"images":[],"topic":"compute","needsImage":false},{"id":"3-89","test":3,"number":89,"stem":["You are creating an Azure Resource Manager (ARM) template (shown below) that performs the following actions:","- Creates a new resource group.","- Deploys an Azure Storage account into that resource group by using a nested deployment.","{","\"$schema\": \"https://schema.management.azure.com/schemas/2023-04-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"resources\": [","{","\"type\": \"Microsoft.Resources/resourceGroups\",","\"apiVersion\": \"2025-11-01\",","\"location\": \"eastus\",","\"name\": \"RG1\"","},","{","\"type\": \"Microsoft.Resources/deployments\",","\"apiVersion\": \"2025-11-01\",","\"name\": \"storageDeployment\",","\"resourceGroup\": \"RG1\",","\"dependsOn\": [","\"[resourceId('Microsoft.Resources/resourceGroups/', 'RG1')]\"","],","\"properties\": {","\"mode\": \"Incremental\",","\"template\": {","\"$schema\": \"https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\",","\"contentVersion\": \"1.0.0.0\",","\"resources\": [","{","\"type\": \"Microsoft.Storage/storageAccounts\",","\"apiVersion\": \"2025-05-01\",","\"name\": \"storage1\",","\"location\": \"eastus\",","\"kind\": \"StorageV2\",","\"sku\": {","\"name\": \"Standard_LRS\"","}","}","]","}","}","}","]","}","Which PowerShell cmdlet should you run to deploy the template?"],"options":[{"text":"New-AzDeployment","correct":true},{"text":"New-AzResource","correct":false},{"text":"New-AzResourceGroupDeployment","correct":false},{"text":"New-AzTenantDeployment","correct":false}],"explanation":["`New-AzDeployment` is the correct cmdlet to use when your ARM template includes a nested deployment of a resource group, as shown in the image. This cmdlet allows you to deploy resources at the subscription level, which is necessary here because the template first creates a resource group (RG1) and then deploys a storage account into that group.","The nested deployment structure in the ARM template includes:","- A `Microsoft.Resources/resourceGroups` resource to create the resource group.","- A `Microsoft.Resources/deployments` resource that deploys the storage account into the newly created group using a nested template.","Since the deployment targets multiple scopes (subscription and resource group), you must use a subscription-level deployment cmdlet like `New-AzDeployment`.","`New-AzResourceGroupDeployment` is incorrect because it's used to deploy resources within an existing resource group. It cannot be used when your template includes the creation of a new resource group.","`New-AzSubscriptionDeployment` is an alias for `New-AzDeployment`, but the preferred cmdlet name is `New-AzDeployment`, which works consistently across all scopes in newer versions of the Az PowerShell module."],"references":["https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azdeployment","https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"],"images":[],"topic":"storage","needsImage":false},{"id":"3-90","test":3,"number":90,"stem":["You have an Azure subscription that includes a web app named webapp1.","You want to associate a custom domain, www.apexcore.com, with webapp1.","Before you can complete the custom domain configuration, what is the first action you must take?"],"options":[{"text":"Upload a certificate.","correct":false},{"text":"Stop webapp1.","correct":false},{"text":"Create a DNS record.","correct":true},{"text":"Add a connection string.","correct":false}],"explanation":["`Create a DNS record` is the correct answer because before you can map a custom domain (like `www.apexcore.com`) to an Azure Web App (e.g., `webapp1`), you must prove ownership of the domain. This is done by creating a CNAME or A record in the public DNS zone for the domain, pointing to the web app's default Azure domain (e.g., `webapp1.azurewebsites.net`). This step allows Azure to validate that you control the domain name.","`Upload a certificate` is incorrect because uploading an SSL certificate is only required if you plan to enable HTTPS for the custom domain. It’s not required as the first step in domain assignment.","`Stop webapp1` is incorrect because there's no need to stop the app when adding or validating a custom domain. The app can stay running throughout the process.","`Add a connection string` is incorrect because this relates to configuring access to backend services like databases. It has nothing to do with custom domain configuration."],"references":["https://learn.microsoft.com/en-us/azure/app-service/app-service-web-tutorial-custom-domain","https://learn.microsoft.com/en-us/Azure/app-service/app-service-web-tutorial-custom-domain?tabs=root%2Cazurecli"],"images":[],"topic":"identity","needsImage":false},{"id":"4-1","test":4,"number":1,"stem":["You have an Azure subscription that includes the virtual networks listed below:","- VNet1 in the West US region, peered with VNet2","- VNet2 in the West US region, peered with VNet1 and VNet3","- VNet3 in the East US region, peered with VNet2","The subscription also contains the following virtual machines:","- VM1, connected to VNet1","- VM2, connected to VNet2","- VM3, connected to VNet3","All virtual machines have private IP addresses only.","You deploy an Azure Bastion host named Bastion1 in VNet1.","Which virtual machines can you connect to by using Bastion1?"],"options":[{"text":"VM1 only","correct":false},{"text":"VM1 and VM2 only","correct":true},{"text":"VM1 and VM3 only","correct":false},{"text":"VM1, VM2, and VM3","correct":false}],"explanation":["`VM1 and VM2 only` is the correct answer because Azure Bastion allows connections to virtual machines within the same virtual network or peered virtual networks. Since Bastion1 is deployed in VNet1, it can connect to VM1 (in VNet1) and VM2 (in VNet2), as VNet1 and VNet2 are peered. However, VM3 is in VNet3, which is peered only with VNet2 but not directly with VNet1, preventing Bastion1 from connecting to VM3.","`VM1 only` is incorrect because Bastion1 can also connect to VM2 in VNet2 through the peering with VNet1.","`VM1 and VM3 only` is incorrect because, while VM1 is accessible, VM3 is not reachable via Bastion1 due to the lack of direct peering between VNet1 and VNet3.","`VM1, VM2, and VM3` is incorrect because Bastion1 cannot connect to VM3 since there is no direct peering between VNet1 and VNet3."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/bastion/vnet-peering","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-2","test":4,"number":2,"stem":["You have an Azure subscription that includes the following resources:","- A virtual network named VNET1 deployed in the East US region","- A public IP address named IP1 deployed in the West Europe region","- A route table named RT1 deployed in the North Europe region","You are required to create a network interface named NIC1. The solution must use only existing resources, and no additional Azure resources can be created as part of the process.","In which Azure region can NIC1 be created?"],"options":[{"text":"East US only","correct":true},{"text":"East US and West Europe only","correct":false},{"text":"East US and North Europe only","correct":false},{"text":"East US, West Europe, and North Europe","correct":false}],"explanation":["`East US only` is the correct answer because network interfaces (NICs) must be created in the same region as the virtual network (VNet) they are associated with. In this case, VNET1 is in the East US region, so NIC1 must also be created in East US to connect to VNET1 without requiring additional resources.","`East US and West Europe only` is incorrect because a NIC must be in the same region as its associated virtual network, and VNET1 is only in East US.","`East US and North Europe only` is incorrect for the same reason. NIC1 cannot be created in North Europe if it needs to connect to VNET1, which is located in East US.","`East US, West Europe, and North Europe` is incorrect because the NIC must be in the same region as the VNet, which is East US in this case."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-network-interface"],"images":[],"topic":"identity","needsImage":false},{"id":"4-3","test":4,"number":3,"stem":["You have an Azure subscription that includes three virtual networks: VNet-A, VNet-B, and VNet-C.","The current peering configuration is as follows:","- VNet-A","- Peered with VNet-B -> Status: Connected -> Gateway transit: Disabled","- Peered with VNet-C -> Status: Connected -> Gateway transit: Disabled","- VNet-B","- Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled","- VNet-C","- Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled","Each peering shows a connected status.","Based on the information shown in the exhibits, complete the following statement by selecting the correct option:","“Traffic originating from VNET-A can be routed to __________.”"],"options":[{"text":"VNet-B only","correct":false},{"text":"VNet-C only","correct":false},{"text":"VNet-B and VNet-C","correct":true}],"explanation":["`VNet-B and VNet-C` is the correct answer because VNet-A has peering connections established with both VNet-B and VNet-C. This setup allows packets from VNet-A to be routed directly to both VNet-B and VNet-C through the peering connections. The peering status is connected, and no additional configurations are needed since the gateway transit is disabled for all peering links, which does not impact routing between the peered networks.","`VNET-B only` is incorrect because packets can also be routed to VNet-C due to the established peering connection between VNet-A and VNet-C.","`VNET-C only` is incorrect because packets can also be routed to VNet-B due to the established peering connection between VNet-A and VNet-B."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","https://docs.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-peering-gateway-transit"],"images":[],"topic":"identity","needsImage":false},{"id":"4-4","test":4,"number":4,"stem":["You have an Azure subscription that includes three virtual networks: VNet-A, VNet-B, and VNet-C.","The current peering configuration is as follows:","- VNet-A","- Peered with VNet-B -> Status: Connected -> Gateway transit: Disabled","- Peered with VNet-C -> Status: Connected -> Gateway transit: Disabled","- VNet-B","- Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled","- VNet-C","- Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled","Each peering shows a connected status.","Based on the information shown in the exhibits, complete the following statement by selecting the correct option:","“Traffic originating from VNet-B can be routed to __________.”"],"options":[{"text":"VNet-A only","correct":true},{"text":"VNet-C only","correct":false},{"text":"VNet-A and VNet-C","correct":false}],"explanation":["`VNet-A only` is the correct answer because VNet-B has a direct peering connection with VNet-A, which allows routing of packets between these two virtual networks. Since gateway transit is disabled, VNet-B cannot leverage VNet-A as a transit network to reach other networks, such as VNet-C. This configuration restricts communication to only those virtual networks with direct peering links.","`VNet-C only` is incorrect because there is no direct peering connection between VNet-B and VNet-C, and VNet-B cannot route through VNet-A due to the disabled gateway transit.","`VNet-A and VNet-C` is incorrect because, without gateway transit enabled, VNet-B is restricted to direct communication only with VNet-A."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","https://docs.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-peering-gateway-transit"],"images":[],"topic":"identity","needsImage":false},{"id":"4-5","test":4,"number":5,"stem":["You have an Azure subscription that includes the following public IP address resources:","- IP1: IPv4, Standard SKU, Regional tier, Static assignment","- IP2: IPv4, Standard SKU, Global tier, Static assignment","- IP3: IPv4, Basic SKU, Regional tier, Dynamic assignment","- IP4: IPv4, Basic SKU, Regional tier, Static assignment","- IP5: IPv6, Basic SKU, Regional tier, Dynamic assignment","You plan to deploy an Azure Bastion host named Bastion1 using the Basic SKU.","Which of the listed public IP addresses can be used for Bastion1?"],"options":[{"text":"IP1 only","correct":true},{"text":"IP1 and IP2 only","correct":false},{"text":"IP3, IP4, and IP5 only","correct":false},{"text":"IP1, IP2, IP4, and IP5 only","correct":false},{"text":"IP1, IP2, IP3, IP4, and IP5","correct":false}],"explanation":["`IP1 only` is the correct answer because Azure Bastion requires a Standard Public IP address for both the Basic and Standard SKUs. Additionally, the IP address must be IPv4, have a Regional tier, and use a Static assignment. Among the provided options, IP1 is the only address that satisfies all these conditions, making it suitable for Azure Bastion.","Note: The Microsoft documentation does not explicitly list “Regional tier” as a Bastion requirement. However, in practice, Azure Bastion supports only Regional tier public IPs. Global tier public IPs are intended for cross-region load balancers and cannot be attached to Azure Bastion. This behavior is also confirmed when attempting deployment in the Azure portal, where attaching a Global tier public IP to Bastion results in an error.","- IP2 is incorrect because it has a Global tier, while the requirement is for a Regional tier.","- IP3 is incorrect due to its Basic SKU and Dynamic assignment, both of which are incompatible with Azure Bastion.","- IP4 is incorrect because it also uses the Basic SKU, which does not meet the Standard SKU requirement.","- IP5 is incorrect as it is an IPv6 address, and Azure Bastion supports only IPv4."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview","https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/configure-public-ip-bastion","https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/configure-public-ip-bastion"],"images":[],"topic":"identity","needsImage":false},{"id":"4-6","test":4,"number":6,"stem":["You have an Azure subscription.","You plan to deploy a virtual network named VNET1 by using an Azure Resource Manager (ARM) template. The virtual network will be configured to support Azure Bastion.","You are provided with a partially completed ARM template that defines the virtual network, its address space, and two subnets. One subnet definition contains two placeholders that must be completed.","What should you choose for `Code Segment A`?"],"options":[{"text":"AzureBastionSubnet","correct":true},{"text":"AzureFirewallSubnet","correct":false},{"text":"LAN01","correct":false},{"text":"RemoteAccessSubnet","correct":false}],"explanation":["`AzureBastionSubnet` is the correct answer because, to use Azure Bastion, a subnet specifically named AzureBastionSubnet is required. This subnet name is reserved for Azure Bastion deployments and must be configured in the virtual network where Bastion is being deployed.","`AzureFirewallSubnet` is incorrect because this is the reserved subnet name required for Azure Firewall, not Azure Bastion.","`LAN01` is incorrect because it is a generic subnet name and does not meet the specific naming requirement for Azure Bastion.","`RemoteAccessSubnet` is incorrect because it does not align with the required naming convention for Azure Bastion."],"references":["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings","https://learn.microsoft.com/en-us/azure/bastion/tutorial-create-host-portal#createhost"],"images":["assets/8c722354366a2f4b.png"],"topic":"identity","needsImage":true},{"id":"4-7","test":4,"number":7,"stem":["You have an Azure subscription.","You plan to deploy a virtual network named VNET1 by using an Azure Resource Manager (ARM) template. The virtual network will be configured to support Azure Bastion.","You are provided with a partially completed ARM template that defines the virtual network, its address space, and two subnets. One subnet definition contains two placeholders that must be completed.","What should you choose for `Code Segment B`?"],"options":[{"text":"10.10.10.0/26","correct":true},{"text":"10.10.10.0/28","correct":false},{"text":"10.10.10.0/30","correct":false}],"explanation":["`10.10.10.0/26` is the correct answer because the AzureBastionSubnet for Azure Bastion requires a subnet prefix of at least /26 to function properly. This prefix size provides a sufficient number of IP addresses for Azure Bastion to manage connections and maintain operational capacity.","`10.10.10.0/28` is incorrect because a /28 subnet does not provide enough IP addresses for Azure Bastion, which requires a minimum of /26.","`10.10.10.0/30` is incorrect because a /30 subnet provides only a very limited number of IP addresses, far below the requirements for Azure Bastion."],"references":["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings","https://learn.microsoft.com/en-us/azure/bastion/tutorial-create-host-portal#createhost"],"images":["assets/8c722354366a2f4b.png"],"topic":"identity","needsImage":true},{"id":"4-8","test":4,"number":8,"stem":["You have a Windows 11 computer named Device1 and an Azure subscription that includes the following resources:","- A virtual network named VNET1","- A virtual machine named VM1 that runs Windows Server 2022, has no public IP address, and is connected to VNET1","- An Azure Bastion Basic SKU host named Bastion1 that is connected to VNET1","Device1 has both Azure PowerShell and the Azure CLI installed.","You need to establish a Remote Desktop (RDP) connection from Device1 to VM1.","Which three actions should you perform in sequence?","ACTIONS","- From Bastion1, select Native Client Support.","- On Device1, run mstsc.exe.","- Upgrade Bastion1 to the Standard SKU.","- From Bastion1, enable Kerberos authentication.","- From VM1, enable just-in-time (JIT) VM access.","- From Azure CLI on Device1, run az network bastion rdp."],"options":[{"text":"3-6-1","correct":false},{"text":"3-4-1","correct":false},{"text":"3-2-6","correct":false},{"text":"3-1-6","correct":true}],"explanation":["`(Action 3) Upgrade Bastion1 to the Standard SKU` – To use the native client feature for Azure Bastion, which allows connecting via a local RDP client (such as mstsc.exe), Bastion1 must be upgraded to the Standard SKU, as this feature is not available with the Basic SKU.","`(Action 1) From Bastion1, select Native Client Support` – After upgrading, enable the native client support option within the Azure Bastion configuration. This feature allows Device1 to connect to VM1 through Bastion using an RDP client.","`(Action 6) From Azure CLI on Device1, run az network bastion rdp` – Use the `az network bastion rdp` command on Device1’s Azure CLI to initiate the RDP connection to VM1 through Bastion1. This command establishes the RDP session without requiring the direct use of `mstsc.exe`.","To connect via RDP, use the following command:","`az network bastion rdp --name \"<BastionName>\" --resource-group \"<ResourceGroupName>\" --target-resource-id \"<VMResourceId>\"`","`(Action 2) On Device1, run mstsc.exe` is not necessary when using the Azure CLI command, as `az network bastion rdp` initiates the connection directly.","`(Action 4) Enable Kerberos authentication` and `(Action 5) Enable just-in-time (JIT) VM access` are not required for this setup."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-cli","https://learn.microsoft.com/en-us/azure/bastion/native-client"],"images":[],"topic":"identity","needsImage":false},{"id":"4-9","test":4,"number":9,"stem":["You have an Azure subscription that includes the following resources:","- VMRG – Resource group","- VNet1 – Virtual network","- VNet2 – Virtual network","- VM5 – Virtual machine connected to VNet1","- VM6 – Virtual machine connected to VNet2","You create an Azure private DNS zone named apexcore.com.","You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link.","The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit.","True or False:","`“The A record for VM5 will be registered automatically in the apexcore.com zone.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer. Azure DNS allows for the automatic registration of virtual machines from one designated virtual network linked to a private DNS zone as the registration network. In this case, VNet2 is set as the registration virtual network for the apexcore.com zone. However, VM5 is part of VNet1, not VNet2. Since VM5 does not belong to the registration virtual network, its DNS record will not be automatically registered in the apexcore.com zone."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"images":["assets/30ad62d81e67c9cf.png"],"topic":"identity","needsImage":true},{"id":"4-10","test":4,"number":10,"stem":["You have an Azure subscription that includes the following resources:","- VMRG – Resource group","- VNet1 – Virtual network","- VNet2 – Virtual network","- VM5 – Virtual machine connected to VNet1","- VM6 – Virtual machine connected to VNet2","You create an Azure private DNS zone named apexcore.com.","You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link.","The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit.","True or False:","`“VM5 can resolve VM9.apexcore.com.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct. VM5 cannot resolve VM9.apexcore.com because VM5 is connected to VNet1, while VM9 is connected to VNet2. Forward DNS resolution is only supported across virtual networks that are linked to the private DNS zone as resolution virtual networks. In this setup, VNet2 is linked to the apexcore.com private DNS zone, but VNet1 is not linked to this zone nor is it peered with VNet2. Since VNet1 is not configured as a resolution virtual network, VM5 cannot resolve the domain name VM9.apexcore.com."],"references":["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"images":["assets/30ad62d81e67c9cf.png"],"topic":"identity","needsImage":true},{"id":"4-11","test":4,"number":11,"stem":["You have an Azure subscription that includes the following resources:","- VMRG – Resource group","- VNet1 – Virtual network","- VNet2 – Virtual network","- VM5 – Virtual machine connected to VNet1","- VM6 – Virtual machine connected to VNet2","You create an Azure private DNS zone named apexcore.com.","You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link.","The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit.","True or False:","`“VM6 can resolve VM9.apexcore.com.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct. VM6 can resolve VM9.apexcore.com because it belongs to VNet2, which is configured as the registration virtual network for the apexcore.com private DNS zone. Since VNet2 is the registration virtual network, it also serves as the resolution virtual network by default, allowing DNS resolution within this virtual network. An A (Host) record for VM9 exists in the DNS zone, enabling VM6 to successfully resolve the domain name VM9.apexcore.com from within VNet2."],"references":["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns","https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"],"images":["assets/30ad62d81e67c9cf.png"],"topic":"identity","needsImage":true},{"id":"4-12","test":4,"number":12,"stem":["You have two Azure virtual machines running Windows Server, configured as shown below:","You then create a private Azure DNS zone named apexcore.com and configure the zone to allow automatic DNS registration from VNet-A.","Which A record will be automatically created in the apexcore.com private DNS zone for VM-A?"],"options":[{"text":"None","correct":false},{"text":"Private IP address only","correct":true},{"text":"Public IP address only","correct":false},{"text":"Private IP address and public IP address","correct":false}],"explanation":["`Private IP address only` is the correct answer because when a private Azure DNS zone (such as apexcore.com) is configured for auto-registration in a virtual network (VNet-A), only the private IP addresses of virtual machines in that network are automatically registered in the DNS zone. Public IP addresses are not registered in private DNS zones. Therefore, for VM-A, only the private IP address 10.1.0.4 will be added as an A record in the apexcore.com zone, while the public IP address 52.186.85.63 will not be included.","`None` is incorrect because VM-A is part of VNet-A, and VNet-A is configured for auto-registration in the apexcore.com DNS zone. Therefore, VM1’s private IP address will be registered in the zone.","`Public IP address only` is incorrect because public IP addresses are not registered in private DNS zones. Auto-registration only includes the private IP address.","`Private IP address and public IP address` is incorrect because only the private IP address will be registered in the apexcore.com zone. Public IP addresses are excluded from auto-registration."],"references":["https://docs.microsoft.com/en-us/azure/dns/private-dns-overview","https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios","https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios#scenario-split-horizon-functionality"],"images":["assets/8d401b293545f8b3.png"],"topic":"network","needsImage":true},{"id":"4-13","test":4,"number":13,"stem":["You have two Azure virtual machines running Windows Server, configured as shown below:","You then create a private Azure DNS zone named apexcore.com and configure the zone to allow automatic DNS registration from VNet-A.","Which A record will be automatically created in the apexcore.com private DNS zone for VM-B?"],"options":[{"text":"None","correct":false},{"text":"Private IP address only","correct":true},{"text":"Public IP address only","correct":false},{"text":"Private IP address and public IP address","correct":false}],"explanation":["`Private IP address only` is the correct answer because in Azure private DNS zones, DNS records are created based on the Virtual network links to the VNet rather than the DNS suffix configured on the VM itself. Since VNet-A is linked to the adatum.com private DNS zone and auto-registration is enabled, VM-B’s private IP address (10.1.0.5) will be automatically registered in the apexcore.com zone despite its DNS suffix being set to ironclad.com.","`None` is incorrect because the DNS name configured on the VM does not impact auto-registration; as long as the VNet is linked, VM-B’s private IP will be registered.","`Public IP address only` is incorrect because Azure private DNS zones do not register public IP addresses; they register only private IP addresses.","`Private IP address and public IP address` is incorrect because Azure private DNS zones only register private IP addresses, not public ones."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration","https://docs.microsoft.com/en-us/azure/dns/private-dns-overview","https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios","https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios#scenario-split-horizon-functionality"],"images":["assets/8d401b293545f8b3.png"],"topic":"network","needsImage":true},{"id":"4-14","test":4,"number":14,"stem":["You have an Azure subscription that includes the container images listed below:","- Image1: Built on Windows Server","- Image2: Built on Linux","You plan to deploy containers by using the following Azure services:","- Azure Container Instances","- Azure Container Apps","- Azure App Service","Based on the supported operating systems for each service,  which of the listed Azure services can be used to run Image1?"],"options":[{"text":"Azure Container Instances only","correct":false},{"text":"Azure Container Apps only","correct":false},{"text":"Azure Container Instances and App Services only","correct":true},{"text":"Azure Container Apps and App Services only","correct":false},{"text":"Azure Container Instances, Azure Container Apps, and App Services","correct":false}],"explanation":["`Azure Container Instances and App Services only` is the correct answer because Image1 is based on Windows Server, and Azure Container Instances (ACI) and Azure App Service support Windows-based containers. Azure Container Apps, however, only supports Linux-based containers, so it cannot be used to run Image1.","`Azure Container Instances only` is incorrect because Azure App Service also supports Windows-based containers, making it a valid option for running Image1.","`Azure Container Apps only` is incorrect because Azure Container Apps does not support Windows-based containers; it only supports Linux-based containers.","`Azure Container Apps and App Services only` is incorrect because Azure Container Apps does not support Windows-based containers.","`Azure Container Instances, Azure Container Apps, and App Services` is incorrect because Azure Container Apps does not support Windows-based containers, so it cannot be used to run Image1."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview","https://learn.microsoft.com/en-us/azure/container-apps/containers","https://learn.microsoft.com/en-us/azure/app-service/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-15","test":4,"number":15,"stem":["You have an Azure subscription that includes the container images listed below:","- Image1: Built on Windows Server","- Image2: Built on Linux","You plan to deploy containers by using the following Azure services:","- Azure Container Instances","- Azure Container Apps","- Azure App Service","Based on the supported operating systems for each service,  which of the listed Azure services can be used to run Image2?"],"options":[{"text":"Azure Container Instances only","correct":false},{"text":"Azure Container Apps only","correct":false},{"text":"Azure Container Instances and App Services only","correct":false},{"text":"Azure Container Apps and App Services only","correct":false},{"text":"Azure Container Instances, Azure Container Apps, and App Services","correct":true}],"explanation":["`Azure Container Instances, Azure Container Apps, and App Services` is the correct answer because Image2 is based on Linux, and all three services — Azure Container Instances (ACI), Azure Container Apps, and Azure App Service — support Linux-based containers. Therefore, Image2 can run on any of these services.","`Azure Container Instances only` is incorrect because both Azure Container Apps and Azure App Service also support Linux-based containers, making them valid options for running Image2.","`Azure Container Apps only` is incorrect because Azure Container Instances and Azure App Service can also run Linux-based containers, so this option is too restrictive.","`Azure Container Instances and App Services only` is incorrect because Azure Container Apps also supports Linux-based containers, making it another valid option for Image2.","`Azure Container Apps and App Services only` is incorrect because Azure Container Instances is also capable of running Linux-based containers."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview","https://learn.microsoft.com/en-us/azure/container-apps/containers","https://learn.microsoft.com/en-us/azure/app-service/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-16","test":4,"number":16,"stem":["You have a Microsoft Entra tenant that contains the users listed in the following table, each assigned specific administrative roles.","The tenant also contains the groups as shown in the below table, with different group types and membership configurations.","Self-service password reset (SSPR) must be configured for the tenant.","Which of the listed users are permitted to configure SSPR?"],"options":[{"text":"AdminA only","correct":false},{"text":"AdminB only","correct":false},{"text":"AdminC only","correct":false},{"text":"AdminA and AdminB only","correct":true},{"text":"AdminB and AdminC only","correct":false},{"text":"AdminA, AdminB, and AdminC","correct":false}],"explanation":["`AdminA and AdminB only` is correct because in order to configure Self-Service Password Reset (SSPR) in Microsoft Entra, a user must have at least the Authentication Policy Administrator role. In this case, AdminA is the user with the Global Administrator role and AdminA has Authentication Policy Admin role which grant them the necessary permissions to configure SSPR.","`AdminA only` is the incorrect answer because AdminB (Authentication Policy Administrator) also has the required permissions to configure SSPR.","`AdminB only` is incorrect  because AdminA (Global Administrator) also has permissions to configure SSPR, and AdminB cannot be the only one who can configure it.","`AdminC only` is incorrect because neither Authentication Administrator nor Security Administrator roles provide permissions to configure SSPR.","`AdminB and AdminC only` is incorrect because AdminC does not have the required role to configure SSPR. Only AdminA and AdminB have the necessary roles.","`AdminA, AdminB, and AdminC` is incorrect because AdminC does not hold a role that permits configuring SSPR. Only AdminA and AdminB meet the role requirements."],"references":["https://learn.microsoft.com/en-us/azure/active-directory/authentication/tutorial-enable-sspr","https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/permissions-reference#authentication-policy-administrator"],"images":["assets/548af2eafa615052.png","assets/1abb48ecd1f9d9c5.png"],"topic":"identity","needsImage":true},{"id":"4-17","test":4,"number":17,"stem":["You have a Microsoft Entra tenant that contains the users listed in the following table, each assigned specific administrative roles.","The tenant also contains the groups as shown in the below table, with different group types and membership configurations.","Self-service password reset (SSPR) must be configured for the tenant.","For which group can SSPR be enabled?"],"options":[{"text":"SecGroup only","correct":false},{"text":"M365Group only","correct":false},{"text":"SecGroup or M365Group only","correct":true},{"text":"SecGroup or MailSecGroup only","correct":false},{"text":"SecGroup, M365Group, or MailSecGroup","correct":false}],"explanation":["`SecGroup or M365Group only` is the correct answer because Self-Service Password Reset (SSPR) can be enabled for security groups and Microsoft 365 groups. SecGroup is a Security group, and M365Group is a Microsoft 365 group, both of which are supported for SSPR.","`MailSecGrou` is a Mail-enabled security group, which does not support SSPR."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-howitworks","https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr#enable-self-service-password-reset"],"images":["assets/548af2eafa615052.png","assets/1abb48ecd1f9d9c5.png"],"topic":"identity","needsImage":true},{"id":"4-18","test":4,"number":18,"stem":["You have an Azure subscription and plan to create an Azure Container Registry named ContReg1.","You must ensure that container images pushed to and pulled from ContReg1 are cryptographically signed and that only trusted images are allowed.","What configuration should you apply to ContReg1 to meet this requirement?"],"options":[{"text":"Enable encryption by using a customer-managed key.","correct":false},{"text":"Create a connected registry.","correct":false},{"text":"Add a token.","correct":false},{"text":"Enable content trust.","correct":true}],"explanation":["`Enable content trust` is the correct answer here. To ensure that you can push and pull signed container images in ContReg1, you need to enable content trust. Content trust ensures that the integrity of the images is maintained by verifying that the images are signed and have not been tampered with. This allows only trusted and signed images to be pushed and pulled from the registry.","`Enable encryption by using a customer-managed key` is incorrect because encryption protects data at rest but does not address image signing.","`Create a connected registry` is incorrect because connected registries are used for geo-replication and scaling deployments but do not address signed images.","`Add a token` is incorrect because tokens are used to manage authentication for accessing the registry, not for image signing."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-content-trust","https://learn.microsoft.com/en-us/azure/container-registry/container-registry-tasks-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-19","test":4,"number":19,"stem":["You provision an Azure Storage account and plan to create 10 blob containers within the account. One of these containers must use a separate encryption key for data that is encrypted at rest.","What action should you take before creating that container?"],"options":[{"text":"Rotate the access keys.","correct":false},{"text":"Create an encryption scope.","correct":true},{"text":"Change the minimum supported TLS version.","correct":false},{"text":"Generate a shared access signature (SAS).","correct":false}],"explanation":["`Create an encryption scope` is the correct answer because to use a different key for encrypting data at rest for a specific blob container, you need to create an encryption scope in Azure Storage. Once created, the encryption scope can be assigned to individual containers, allowing them to use a distinct encryption key.","`Rotate the access keys` is incorrect because rotating access keys changes the authentication keys used to access the storage account but does not provide a way to use a different encryption key for a specific container.","`Change the minimum supported TLS version` is incorrect because modifying the TLS version affects the security protocol for data in transit, not the encryption of data at rest.","`Generate a shared access signature (SAS)` is incorrect because a SAS provides controlled access to the storage account resources but does not influence encryption settings for data at rest."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-overview","https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-manage?tabs=portal"],"images":[],"topic":"storage","needsImage":false},{"id":"4-20","test":4,"number":20,"stem":["You have an Azure subscription that contains the storage account shown in the following exhibit.","Based on the information provided, select the answer choice that completes the following statement correctly.","“The maximum number of additional stored access policies that can be created for container1 is ________.”"],"options":[{"text":"0","correct":false},{"text":"1","correct":false},{"text":"3","correct":true},{"text":"5","correct":false},{"text":"6","correct":false}],"explanation":["`3` is the correct answer because Azure Storage accounts support a maximum of 5 stored access policies per container. Since there are already 2 stored access policies (Policy1 and Policy2) defined for container1, you can add 3 more policies to reach the limit of 5."],"references":["https://learn.microsoft.com/en-us/rest/api/storageservices/define-stored-access-policy"],"images":["assets/0b08b1710391b617.png"],"topic":"identity","needsImage":true},{"id":"4-21","test":4,"number":21,"stem":["You have an Azure subscription that contains the storage account shown in the following exhibit.","Based on the information provided, select the answer choice that completes the following statement correctly.","“The maximum number of additional immutable blob storage policies that can be created for container1 is ________.”"],"options":[{"text":"0","correct":false},{"text":"1","correct":true},{"text":"2","correct":false},{"text":"4","correct":false},{"text":"5","correct":false}],"explanation":["`1` is the correct answer because Azure Storage accounts support a maximum of 2 immutable blob storage policies per container. Since there is already 1 immutable blob storage policy configured for container1 (with a time-based retention of 14 days), you can add 1 more to reach the maximum limit of 2."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/immutable-storage-overview"],"images":["assets/0b08b1710391b617.png"],"topic":"identity","needsImage":true},{"id":"4-22","test":4,"number":22,"stem":["You have an on-premises server that contains a folder named at D:\\DataFolder.","You need to upload all the contents of D:\\DataFolder to the public blob container in an Azure Storage account named apexcoredata.","Which command should you run to complete this task?"],"options":[{"text":"az storage blob copy start D:\\DataFolder https://apexcoredata.blob.core.windows.net/public","correct":false},{"text":"azcopy copy D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --recursive","correct":true},{"text":"azcopy sync D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --snapshot","correct":false},{"text":"az storage blob copy start-batch D:\\DataFolder https://apexcoredata.blob.core.windows.net/public","correct":false}],"explanation":["`azcopy copy D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --recursive` is the correct answer because the `azcopy copy` command is used to upload files from an on-premises folder to an Azure Storage container. The `--recursive` option ensures that all files within D:\\Folder1 are copied to the destination container in Azure.","`az storage blob copy start D:\\DataFolder https://apexcoredata.blob.core.windows.net/public` is incorrect because `az storage blob copy start` is intended for copying blobs within Azure Storage, not for uploading files from an on-premises location.","`azcopy sync D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --snapshot` is incorrect because `azcopy sync` is used to synchronize files between a local folder and a storage container, rather than a direct copy. The `--snapshot` parameter is not relevant for this task.","`az storage blob copy start-batch D:\\DataFolder https://apexcoredata.blob.core.windows.net/public` is incorrect because `az storage blob copy start-batch` is designed for batch copying blobs within Azure Storage, not from an on-premises location."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-blobs","https://docs.microsoft.com/en-us/azure/storage/common/storage-ref-azcopy-copy"],"images":[],"topic":"storage","needsImage":false},{"id":"4-23","test":4,"number":23,"stem":["You have an Azure subscription named ProdSub01. In the subscription, you create an Azure file share named fileshare01. You then generate a shared access signature (SAS) named SASKey01 with the following configuration:","- Allowed services: File","- Allowed resource types: Service, Container, Object","- Allowed permissions: Read, Write, List","- Start date/time: September 1, 2018 at 2:00 PM","- End date/time: September 14, 2018 at 2:00 PM","- Allowed IP addresses: 193.77.134.10 – 193.77.134.50","- Allowed protocols: HTTPS only","- Signing key: key1","Based on this configuration, complete the following statement:","`“If on September 2, 2018, you use Microsoft Azure Storage Explorer from a computer with the IP address 193.77.134.1, and connect to the storage account using SASKey01, you __________.”`"],"options":[{"text":"will be asked for credentials","correct":false},{"text":"will have no access","correct":true},{"text":"will have read, write, and list access","correct":false},{"text":"will have read-only access","correct":false}],"explanation":["`will have no access` is the correct answer because, as given, the SAS (Shared Access Signature) restricts access to IP addresses within the range 193.77.134.10 to 193.77.134.50. Although the date of September 2, 2018 is within the permitted time period (2018-09-01 2:00 PM to 2018-09-14 2:00 PM), the IP address 193.77.134.1 does not fall within the specified IP address range, resulting in no access to the storage account.","`will be asked for credentials` is incorrect because SAS tokens provide access based on the permissions and restrictions defined in the token itself, without requiring additional credentials.","`will have read, write, and list access` is incorrect because, while these permissions are specified in the SAS, the IP address restriction prevents any access.","`will have read-only access` is incorrect because the IP address falls outside the permitted range, so access will not be granted regardless of the permissions."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-sas-overview","https://docs.microsoft.com/en-us/azure/vs-azure-tools-storage-manage-with-storage-explorer?tabs=windows"],"images":[],"topic":"identity","needsImage":false},{"id":"4-24","test":4,"number":24,"stem":["You have an Azure subscription named ProdSub01. In the subscription, you create an Azure file share named fileshare01. You then generate a shared access signature (SAS) named SASKey01 with the following configuration:","- Allowed services: File","- Allowed resource types: Service, Container, Object","- Allowed permissions: Read, Write, List","- Start date/time: September 1, 2018 at 2:00 PM","- End date/time: September 14, 2018 at 2:00 PM","- Allowed IP addresses: 193.77.134.10 – 193.77.134.50","- Allowed protocols: HTTPS only","- Signing key: key1","Based on this configuration, complete the following statement:","`If on September 10, 2018, you run the net use command on a computer that has an IP address of 193.77.134.50, and you use SASKey01 as the password to connect to fileshare01, you _________________________.”`"],"options":[{"text":"will be asked for credentials","correct":false},{"text":"will have no access","correct":true},{"text":"will have read, write, and list access","correct":false},{"text":"will have read-only access","correct":false}],"explanation":["`will have no access` is the correct answer here because the net use command relies on the SMB (Server Message Block) protocol, which only supports authentication using the Azure Storage account key for access to Azure File Shares. The SAS token cannot be used for authentication in this context, and attempting to use it will result in an error indicating invalid credentials. Therefore, the user will not gain any access to the file share with the net use command when using the SAS token.","`will be asked for credentials` is incorrect because the SAS token is not valid for SMB authentication, so no prompt for credentials will occur in a way that allows access.","`will have read, write, and list access` is incorrect because, without support for SAS authentication, the SMB protocol cannot grant any permissions in this scenario.","`will have read-only access` is incorrect because the net use command with SAS authentication will not provide any access due to the limitations of the SMB protocol, which requires the storage account key."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview","https://learn.microsoft.com/en-us/azure/storage/storage-explorer/vs-azure-tools-storage-manage-with-storage-explorer?tabs=windows"],"images":[],"topic":"identity","needsImage":false},{"id":"4-25","test":4,"number":25,"stem":["You have an Azure subscription and plan to create a new Azure Storage account. You must configure encryption for the storage account and ensure that the solution meets the following criteria:","- Encryption must use a customer-managed key stored in an Azure Key Vault.","- The key must use the highest supported bit length.","Which type of encryption key should you select?"],"options":[{"text":"AES","correct":false},{"text":"3DES","correct":false},{"text":"RSA","correct":true}],"explanation":["`RSA` is the correct answer here because when using customer-managed keys with Azure Storage, the service supports RSA keys for encryption stored in Azure Key Vault. For Azure Storage encryption, RSA keys support the maximum bit length of 4096 bits, which is currently the highest supported bit length in Azure Key Vault for customer-managed keys.","`AES` is incorrect because, while AES is commonly used for encryption, Azure Key Vault only supports RSA for customer-managed keys in this context. AES is not an option for customer-managed keys stored in Azure Key Vault.","`3DES` is incorrect because 3DES (Triple DES) is an older encryption standard and is not supported for customer-managed keys in Azure Key Vault. Azure Key Vault supports RSA keys for customer-managed storage account encryption."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-service-encryption","https://learn.microsoft.com/en-us/azure/storage/common/customer-managed-keys-overview","https://learn.microsoft.com/en-us/azure/key-vault/keys/about-keys"],"images":[],"topic":"identity","needsImage":false},{"id":"4-26","test":4,"number":26,"stem":["You have an Azure subscription and plan to create a new Azure Storage account. You must configure encryption for the storage account and ensure that the solution meets the following criteria:","- Encryption must use a customer-managed key stored in an Azure Key Vault.","- The key must use the highest supported bit length.","Which bit length should you use?"],"options":[{"text":"2048","correct":false},{"text":"3072","correct":false},{"text":"4096","correct":true},{"text":"8192","correct":false}],"explanation":["`4096` is the correct answer here because, for customer-managed keys stored in Azure Key Vault, the maximum supported bit length for RSA encryption keys is 4096 bits. This is the highest supported bit length in Azure Key Vault for customer-managed keys used for storage account encryption, meeting the requirement for maximum security.","`2048` is incorrect because, although 2048-bit keys are secure, they do not meet the requirement to use the maximum supported bit length.","`3072` is incorrect because, while 3072-bit keys offer stronger encryption than 2048-bit keys, they still do not meet the requirement to use the maximum supported bit length.","`8192` is incorrect because Azure Key Vault does not support RSA keys with an 8192-bit length. The maximum supported bit length for customer-managed RSA keys in Azure Key Vault is 4096 bits."],"references":["https://docs.microsoft.com/en-us/azure/storage/common/storage-service-encryption","https://learn.microsoft.com/en-us/azure/storage/common/customer-managed-keys-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-27","test":4,"number":27,"stem":["You create an Azure Storage account called apexcorestorage and plan to add an Azure file share named data. Users must be able to map a network drive to the data file share from their home computers running Windows 10.","Which outbound port must be allowed between the users’ computers and the Azure file share?"],"options":[{"text":"80","correct":false},{"text":"443","correct":false},{"text":"445","correct":true},{"text":"3389","correct":false}],"explanation":["`445` is the correct answer here because SMB (Server Message Block) protocol, which is used to access Azure file shares, operates over port 445. Windows clients need access to port 445 to map a drive to the Azure file share, which allows users to access the data remotely from their home computers.","`80` is incorrect because port 80 is typically used for HTTP traffic, which is not used for SMB file share connections.","`443` is incorrect because port 443 is commonly used for HTTPS traffic, which is not required for SMB file share connections.","`3389` is incorrect because port 3389 is used for Remote Desktop Protocol (RDP) connections, not for mapping file shares."],"references":["https://docs.microsoft.com/en-us/azure/storage/files/storage-troubleshoot-windows-file-connection"],"images":[],"topic":"storage","needsImage":false},{"id":"4-28","test":4,"number":28,"stem":["You have an Azure web app named webapp1. You also have a virtual network named VNET1 and an Azure virtual machine named VM1 that hosts a MySQL database. VM1 is connected to VNET1.","You must ensure that webapp1 can access the data stored on VM1.","What action should you take?"],"options":[{"text":"Connect webapp1 to VNET1.","correct":true},{"text":"Set up an internal load balancer.","correct":false},{"text":"Configure virtual network peering between VNET1 and another virtual network.","correct":false},{"text":"Deploy an Azure Application Gateway.","correct":false}],"explanation":["`Connect webapp1 to VNET1` is the correct answer because, to enable direct network communication between the Azure web app (webapp1) and the virtual machine (VM1) hosting the MySQL database, the web app needs to be integrated with the same virtual network (VNET1). This integration allows webapp1 to access VM1 over the private network, ensuring secure and seamless connectivity to the database.","`Set up an internal load balancer` is incorrect because a load balancer manages traffic distribution but does not enable direct network connectivity between web apps and VMs.","`Configure virtual network peering between VNET1 and another virtual network` is incorrect because peering with another virtual network does not directly enable webapp1 to access VM1; webapp1 must be connected to VNET1 itself.","`Deploy an Azure Application Gateway` is incorrect because an Application Gateway manages HTTP/S traffic to web applications, not private connectivity between a web app and a VM in a virtual network."],"references":["https://docs.microsoft.com/en-us/azure/app-service/web-sites-integrate-with-vnet"],"images":[],"topic":"network","needsImage":false},{"id":"4-29","test":4,"number":29,"stem":["You have an Azure App Service named AppService01 that includes two folders: LogsFolder and TempFolder.","You must configure a daily backup of AppService01, but ensure that TempFolder is excluded from the backup process.","What should you create first to meet this requirement?"],"options":[{"text":"An Azure Storage account","correct":true},{"text":"A Backup vault","correct":false},{"text":"A Recovery Services vault","correct":false},{"text":"A resource group","correct":false}],"explanation":["`An Azure Storage account` is the correct answer because Azure App Service backups require an Azure Storage account to store the backup data. When configuring the backup, you can specify which files and folders to include or exclude, allowing you to exclude TempFolder from the backup of WebApp1.","`A Backup vault` is incorrect because App Service backups do not use Backup vaults. They rely on Azure Storage accounts.","`A Recovery Services vault` is incorrect because Recovery Services vaults are used for Azure Backup and Azure Site Recovery, not for App Service backups.","`A resource group` is incorrect because, while required for organizing resources, it is not specifically needed to configure backups for App Service."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-backup"],"images":[],"topic":"compute","needsImage":false},{"id":"4-30","test":4,"number":30,"stem":["You have an Azure App Service named AppService01 that includes two folders: LogsFolder and TempFolder.","You must configure a daily backup of AppService01, but ensure that TempFolder is excluded from the backup process.","What should you use to exclude TempFolder?"],"options":[{"text":"A _backup.filter file","correct":true},{"text":"A backup policy","correct":false},{"text":"A lock","correct":false},{"text":"A WebJob","correct":false}],"explanation":["`A _backup.filter file` is the correct answer because, in Azure App Service, you can exclude specific files or directories from a backup by creating a _backup.filter file in the root directory of the app. This file allows you to specify any files or directories that should be excluded from the backup, such as TempFolder.","`A backup policy` is incorrect because Azure App Service does not use backup policies to exclude specific directories. It relies on the _backup.filter file.","`A lock` is incorrect because locks are used to prevent accidental modification or deletion of resources, not to control backup contents.","`A WebJob` is incorrect because WebJobs are used to run background tasks in Azure App Service, not to manage backup configurations or exclusions."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-backup"],"images":[],"topic":"compute","needsImage":false},{"id":"4-31","test":4,"number":31,"stem":["You have an Azure subscription that includes the resources listed in the following table.","You need to configure a proximity placement group for ScaleSet01.","Which proximity placement groups should you use?"],"options":[{"text":"PPG-West-01 only","correct":true},{"text":"PPG-West-01 and PPG-Central-02 only","correct":false},{"text":"PPG-Central-01 only","correct":false},{"text":"PPG-West-01, PPG-Central-01, and PPG-Central-02","correct":false}],"explanation":["`PPG-West-01 only` is the correct answer because a virtual machine scale set can only use a proximity placement group that is located in the same Azure region. Proximity placement groups are used to ensure that compute resources are placed physically close to each other within an Azure datacenter to minimize latency.","In this scenario, ScaleSet01 is located in the West US region. Among the available proximity placement groups, only PPG-West-01 is also located in West US, making it the only valid option.","It is important to note that the proximity placement group and the virtual machine scale set do not need to be in the same resource group. They only need to exist in the same region.","`PPG-West-01 and PPG-Central-02 only` is incorrect because PPG-Central-02 is located in Central US, which does not match the West US** region of ScaleSet01.","`PPG-Central-01 only` is incorrect because PPG-Central-01 is located in Central US, while ScaleSet01 is located in West US. Proximity placement groups must be in the same region as the compute resources that use them.","`PPG-West-01, PPG-Central-01, and PPG-Central-02` is incorrect because only PPG-West-01 is located in the West US region required by ScaleSet01. The other proximity placement groups are located in Central US and therefore cannot be associated with the scale set."],"references":["https://azure.microsoft.com/en-us/blog/introducing-proximity-placement-groups/"],"images":["assets/676ad2fe73842478.png"],"topic":"identity","needsImage":true},{"id":"4-32","test":4,"number":32,"stem":["You create an App Service plan named Plan1 and an Azure web app named webapp1. You notice that the option to create a staging slot is currently unavailable.","You need to create a staging slot for Plan1.","What should you do first?"],"options":[{"text":"From Plan1, scale up the App Service plan.","correct":true},{"text":"From Plan1, scale out the App Service plan.","correct":false},{"text":"From webapp1, add a custom domain.","correct":false},{"text":"From webapp1, modify the Application settings.","correct":false}],"explanation":["`From Plan1, scale up the App Service plan` is the correct answer here. To create a staging slot for an Azure App Service plan, it must be in the Standard, Premium, or higher pricing tier. Since staging slots are not available for the Free, Shared, or Basic tiers, the solution here is to scale up Plan1 to a tier that supports deployment slots. This will allow you to create a staging slot for testing or other purposes without affecting the production slot.","`From Plan1, scale out the App Service plan` is incorrect because scaling out increases the number of instances within the same tier but does not change the tier itself. To enable staging slots, you need to change the tier by scaling up.","`From webapp1, add a custom domain` is incorrect because adding a custom domain does not impact the ability to create a staging slot.","`From webapp1, modify the Application settings` is incorrect because modifying application settings does not affect the availability of staging slots, which is determined by the App Service plan tier."],"references":["https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"],"images":[],"topic":"compute","needsImage":false},{"id":"4-33","test":4,"number":33,"stem":["You have an Azure subscription that includes a virtual machine named VM1, which hosts a line-of-business application that must remain available around the clock. VM1 has a single network interface, one managed disk, and is currently configured with the D4s v3 size.","You plan to apply the following modifications to VM1:","- Resize the virtual machine to D8s v3.","- Attach an additional 500-GB managed disk.","- Install the Puppet Agent virtual machine extension.","- Enable Desired State Configuration (DSC) management.","Which of these changes will result in downtime for VM1?"],"options":[{"text":"Adding the Puppet Agent extension.","correct":false},{"text":"Attaching a 500-GB managed disk.","correct":false},{"text":"Changing the size to D8s v3.","correct":true},{"text":"Enabling Desired State Configuration Management.","correct":false}],"explanation":["`Changing the size to D8s v3` is the correct answer here. Changing the size of a virtual machine in Azure requires it to be deallocated and then re-provisioned, which causes downtime. During the resizing process, VM1 will not be available, resulting in a temporary outage for the line-of-business application.","`Adding the Puppet Agent extension` is incorrect because adding an extension to a virtual machine does not require deallocation, so it does not cause downtime.","`Attaching a 500-GB managed disk` is incorrect because attaching an additional managed disk to a virtual machine can be done while the VM is running, and it does not cause downtime.","`Enabling Desired State Configuration Management` is incorrect because enabling Desired State Configuration (DSC) does not require the virtual machine to be stopped or deallocated, so it does not cause downtime."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/resize-vm","https://azure.microsoft.com/en-us/blog/resize-virtual-machines"],"images":[],"topic":"identity","needsImage":false},{"id":"4-34","test":4,"number":34,"stem":["You manage an Azure subscription that contains an existing Azure Storage account.","You plan to deploy an Azure Container Instance named sqlcontainer01, which runs a Docker image named mssqlimage01. The image includes a Microsoft SQL Server instance that requires persistent data storage beyond the lifecycle of the container.","You must configure a storage solution that ensures the SQL Server data remains available even if sqlcontainer01 is restarted or redeployed.","Which Azure storage service should you use to provide persistent storage for sqlcontainer01?"],"options":[{"text":"Azure Queue storage","correct":false},{"text":"Azure Blob storage","correct":false},{"text":"Azure Table storage","correct":false},{"text":"Azure Files","correct":true}],"explanation":["`Azure Files` is the correct answer because it provides a fully managed SMB file share that can be mounted by Azure container instances as persistent storage. This is essential for scenarios like running Microsoft SQL Server in a container, where data needs to persist across container restarts. However, it is important to note that volume mounting, including Azure Files, is currently only supported for `Linux-based` Azure container instances. Therefore, this solution assumes that mssqlimage01 is a Linux container image running SQL Server for Linux (which is fully supported).","`Azure Queue storage` is incorrect because it is designed for messaging between application components and does not provide file system-based persistent storage.","`Azure Blob storage` is incorrect because it is used for storing unstructured object data and cannot be mounted as a file system by container instances.","`Azure Table storage` is incorrect because it is a NoSQL key-value store intended for structured data and not suitable for use as a mounted persistent file system."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-volume-azure-files","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"],"images":[],"topic":"identity","needsImage":false},{"id":"4-35","test":4,"number":35,"stem":["You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1.","You successfully deploy the following Azure Resource Manager template.","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM1\",","\"zones\": \"1\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM1\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","}","]","}","}","},","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM2\",","\"zones\": \"2\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM2\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","}","]","}","}","}","True or False:","`“VM1 and VM2 can connect to VNET1.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. VM1 and VM2 can connect to VNET1 as they both have network interfaces (VM1-NI and VM2-NI) explicitly linked to VNET1 within the same location, \"East US 2.\" This configuration ensures that both virtual machines are part of VNET1 and can communicate within this virtual network."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-vnet-plan-design"],"images":[],"topic":"identity","needsImage":false},{"id":"4-36","test":4,"number":36,"stem":["You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1.","You successfully deploy the following Azure Resource Manager template.","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM1\",","\"zones\": \"1\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM1\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","}","]","}","}","},","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM2\",","\"zones\": \"2\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM2\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","}","]","}","}","}","True or False:","`“If an Azure datacenter becomes unavailable, VM1 or VM2 will be available.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. In the ARM template, VM1 is assigned to `\"zones\": \"1\"` and VM2 to `\"zones\": \"2\"`, which places them in separate availability zones within the same Azure region. This configuration ensures that if one datacenter within the region becomes unavailable, the other virtual machine in a different zone remains operational. Azure's availability zones are designed to protect against datacenter-level failures, providing high availability by distributing resources across multiple zones within a region."],"references":["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview?tabs=azure-cli"],"images":[],"topic":"identity","needsImage":false},{"id":"4-37","test":4,"number":37,"stem":["You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1.","You successfully deploy the following Azure Resource Manager template.","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM1\",","\"zones\": \"1\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM1\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\"","}","]","}","}","},","{","\"apiVersion\": \"2017-03-30\",","\"type\": \"Microsoft.Compute/virtualMachines\",","\"name\": \"VM2\",","\"zones\": \"2\",","\"location\": \"EastUS2\",","\"dependsOn\": [","\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","],","\"properties\": {","\"hardwareProfile\": {","\"vmSize\": \"Standard_A2_v2\"","},","\"osProfile\": {","\"computerName\": \"VM2\",","\"adminUsername\": \"AzureAdmin\",","\"adminPassword\": \"[parameters('adminPassword')]\"","},","\"storageProfile\": {","\"imageReference\": \"[variables('image')]\",","\"osDisk\": {","\"createOption\": \"FromImage\"","}","},","\"networkProfile\": {","\"networkInterfaces\": [","{","\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\"","}","]","}","}","}","True or False:","`“If the East US 2 region becomes unavailable, VM1 or VM2 will be available.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. Although VM1 and VM2 are placed in different availability zones within the East US 2 region, they are still limited to that specific region. If the entire East US 2 region becomes unavailable, both virtual machines will be affected, resulting in downtime for the application hosted on them. Availability zones provide resilience within a region, but they do not protect against a full regional outage."],"references":["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview?tabs=azure-cli"],"images":[],"topic":"identity","needsImage":false},{"id":"4-38","test":4,"number":38,"stem":["You have an Azure subscription in which a virtual machine scale set is deployed with the following scaling configuration:","- Initial instance count: 2","- Scaling policy: Custom","- Minimum number of instances: 1","- Maximumnumber of  instances: 10","Scale-out settings:","- CPU Threshold: 75%","- Duration in minutes: 10 minutes","- Number of instances to increase by: 1","Scale-in settings:","- CPU Threshold: 25%","- Number of instances to increase by: 1","Based on the configuration provided, select the answer choice that completes the following statement correctly.","“At 9:00 AM, the virtual machine scale set starts running, and CPU utilization remains at 90 percent for 15 minutes. How many virtual machine instances will be running at 9:15 AM?”"],"options":[{"text":"2","correct":false},{"text":"3","correct":true},{"text":"4","correct":false},{"text":"5","correct":false}],"explanation":["`3` is the correct answer here. Given that the CPU utilization is 90% for 15 minutes, which is above the scale-out threshold of 75%, the scale set will evaluate this sustained high CPU usage after the 10-minute duration set for scale-out. Since the threshold has been exceeded, the scale set will add 1 instance as specified in the \"Number of instances to increase by\" setting. Therefore, starting with two instances at 9:00 AM, the scale set will have three instances running by 9:15 AM."],"references":["https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview","https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview","https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"4-39","test":4,"number":39,"stem":["You have an Azure subscription in which a virtual machine scale set is deployed with the following scaling configuration:","- Initial instance count: 2","- Scaling policy: Custom","- Minimum number of instances: 1","- Maximumnumber of  instances: 10","Scale-out settings:","- CPU Threshold: 75%","- Duration in minutes: 10 minutes","- Number of instances to increase by: 1","Scale-in settings:","- CPU Threshold: 25%","- Number of instances to increase by: 1","Based on the configuration provided, select the answer choice that completes the following statement correctly.","“At 10:00 AM, the scale set is running five virtual machine instances, and CPU utilization drops below 15 percent for 60 minutes. How many virtual machine instances will be running at 11:00 AM?”"],"options":[{"text":"1","correct":true},{"text":"2","correct":false},{"text":"3","correct":false},{"text":"4","correct":false}],"explanation":["`1` is the correct answer.","Based on this information, at 11:00 AM, there will be 1 virtual machine instance running.","At 10:00 AM, the scale set has five virtual machine instances running, and CPU utilization falls to less than 15% for 60 minutes, which is below the scale-in CPU threshold of 25%. With the default scale-in duration set to 10 minutes, the scale set will evaluate the CPU utilization every 10 minutes during the 60-minute period and determine that it is below the scale-in threshold.","If the CPU utilization remains below 15% continuously for 60 minutes, the autoscale mechanism will evaluate the conditions every 10 minutes. Each time the condition is met, it will decrease the instance count by 1, subject to the minimum instance limit.​","Assuming the minimum number of instances is set to 1, the scaling would proceed as follows:","- 10:10 AM: Decrease to 4 instances","- 10:20 AM: Decrease to 3 instances","- 10:30 AM: Decrease to 2 instances","- 10:40 AM: Decrease to 1 instance","- 10:50 AM: No further decrease (minimum limit reached)","- 11:00 AM: No change​","Therefore, at 11:00 AM, you will have 1 virtual machine instance running."],"references":["https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview","https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview","https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"4-40","test":4,"number":40,"stem":["You have an Azure subscription and intend to deploy multiple Azure Container Instances, defined as follows:","- Instance1: Windows Server 2019 (Nano Server installation)","- Instance2: Windows Server 2019 (Server Core installation)","- Instance3: Linux","- Instance4: Linux","Which of these instances are eligible to be deployed together within the same container group?"],"options":[{"text":"Instance1 only","correct":false},{"text":"Instance2 only","correct":false},{"text":"Instance1 and Instance2 only","correct":false},{"text":"Instance3 and Instance4 only","correct":true}],"explanation":["`Instance3 and Instance4 only` is correct because Azure Container Instances (ACI) currently supports multi-container groups only for Linux containers. This means you can deploy multiple Linux-based containers (such as Instance3 and Instance4) together within a single container group that shares networking, storage volumes, and lifecycle.","Instance1 and Instance2 are Windows-based containers (Nano Server and Server Core). Azure Container Instances does not support deploying multiple Windows containers in a group. Windows containers can only be deployed as single-container instances. Therefore, even though both are Windows-based, they cannot be combined into a container group.","Instance1 only, Instance2 only, and Instance1 and Instance2 only are incorrect because these configurations would either use Windows containers (unsupported for container groups) or fail to meet the definition of a multi-container group."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview","https://learn.microsoft.com/en-us/azure/container-instances/container-instances-container-groups"],"images":[],"topic":"identity","needsImage":false},{"id":"4-41","test":4,"number":41,"stem":["You have an Azure subscription containing the following storage accounts:","- storage1 - General-purpose v2 (StorageV2), located in Central US","- storage2 - BlobStorage, located in West US","- storage3 - BlockBlobStorage, located in West US","- storage4 - FileStorage, located in East US","You deploy a web application named App1 to the West US region. You must configure a backup solution for App1 while minimizing costs.","Which storage account should you choose as the backup target?"],"options":[{"text":"storage1","correct":false},{"text":"storage2","correct":true},{"text":"storage3","correct":false},{"text":"storage4","correct":false}],"explanation":["`storage2` is the correct answer here. This storage account is of the BlobStorage type and is located in the West US region, the same region as the web app, App1. Azure Backup uses block blobs to store backup data, making BlobStorage an appropriate type for this purpose. Additionally, placing backup data in the same region as the resource being backed up minimizes latency and avoids additional costs associated with cross-region data transfers.","`storage1` is incorrect because it is located in Central US, a different region than the web app’s region (West US). While StorageV2 can also be used for backup, cross-region data transfers can lead to increased latency and additional costs, making it less ideal.","`storage3` is incorrect despite being in the same region as App1 (West US). Although it is of the BlockBlobStorage type, which supports block blobs, it is generally more expensive than BlobStorage or StorageV2, due to its premium performance characteristics. Given the requirement to minimize costs, BlockBlobStorage is not the optimal choice.","`storage4` is incorrect as it is of the FileStorage type, which is intended for Azure File Shares rather than backups. Furthermore, it is located in East US, which is a different region from the web app, leading to potential additional latency and transfer costs."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-overview","https://docs.microsoft.com/en-us/azure/storage/common/storage-account-overview","https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction","https://docs.microsoft.com/en-us/azure/storage/blobs/premium-blob-faqs"],"images":[],"topic":"identity","needsImage":false},{"id":"4-42","test":4,"number":42,"stem":["You have an Azure environment that includes a virtual network named VNet1. The virtual machines deployed in VNet1 are configured to allow Remote Desktop access.","Several users will be working from home and must securely connect to these virtual machines over the internet. You are required to implement Point-to-Site (P2S) VPN connectivity so that each user can establish a private connection to the virtual network.","Which three actions should you perform in sequence?","ACTIONS","- Provision a local network gateway resource.","- Configure a public IP address for each virtual machine.","- Create an additional subnet within VNet1.","- Add an IP address pool.","- Deploy a load balancer to VNet1.","- Deploy a VPN gateway for the virtual network."],"options":[{"text":"1-6-4","correct":false},{"text":"2-4-6","correct":false},{"text":"3-6-4","correct":true},{"text":"4-6-3","correct":false},{"text":"5-6-1","correct":false}],"explanation":["`(Action 3) Create an additional subnet within VNet1` – A specific subnet is needed for the VPN gateway within VNet1. This subnet is usually named the GatewaySubnet and is required to deploy the VPN gateway for a Point-to-Site (P2S) VPN connection.","`(Action 6) Create a VPN gateway` – After the subnet is created, you need to deploy a VPN gateway in VNet1. The VPN gateway provides the Point-to-Site (P2S) VPN functionality, allowing users to securely connect to the virtual network from a remote location.**","`(Action 4) Add an IP address pool` – Once the VPN gateway is set up, you configure an IP address pool. This pool assigns IP addresses to users who connect through the P2S VPN, ensuring they can connect to resources within VNet1.**","`(Action 1) Provision a local network gateway resource` is incorrect  because a local network gateway is used for Site-to-Site (S2S) VPN connections to represent the on-premises VPN device, not for Point-to-Site connections.**","`(Action 2) Configure a public IP address for each virtual machine` is incorrect  because with a P2S VPN, users can securely connect to the VMs over the VPN without needing public IPs on each VM, enhancing security.**","`(Action 5) Deploy a load balancer to VNet1` is incorrect because a load balancer is not required for P2S VPN connectivity. It’s typically used for distributing traffic across multiple VMs."],"references":["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways"],"images":[],"topic":"network","needsImage":false},{"id":"4-43","test":4,"number":43,"stem":["You have three Azure storage accounts configured as follows:","- storage1 — General-purpose v2 (StorageV2), Standard performance, Locally-redundant storage (LRS), Cool tier","- storage2 — General-purpose v2 (StorageV2), Standard performance, Read-access geo-redundant storage (RA-GRS), Hot tier","- storage3 — BlobStorage, Premium performance, Locally-redundant storage (LRS), Hot tier","You must identify which storage account can be changed to use zone-redundant storage (ZRS) replication.","Which storage account meets this requirement?"],"options":[{"text":"storage1 only","correct":true},{"text":"storage2 only","correct":false},{"text":"storage3 only","correct":false},{"text":"storage2 and storage3","correct":false},{"text":"storage1, storage2, and storage3","correct":false}],"explanation":["`storage1 only` is correct because it is an LRS account that can directly be converted to a ZRS account.","`storage2 only` is incorrect because RA-GRS account cannot be directly converted to ZRS. However, it can be converted to LRS and then finally converted to ZRS. So technically, both Storage1 and Storage2 accounts can be converted to ZRS, but since we do not have \"Storage1 and Storage2 only\" as an option in the question, we are assuming it to be asking about direct conversion only.","`storage3` is incorrect because BlobStorage accounts are not eligible for ZRS replication, regardless of their performance or replication settings.","`storage2 and storage3 only` is  incorrect answer here. Storage2 account is RA-GRS which cannot be converted to ZRS directly. Storage3  being a BlobStorage account is not supported for ZRS replication.","`storage1, storage2, and storage3` are incorrect because only storage1 meets the criteria for direct conversion to ZRS."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/redundancy-migration?tabs=portal#changing-redundancy-configurationhttps://learn.microsoft.com/en-us/azure/storage/common/storage-redundancy"],"images":[],"topic":"storage","needsImage":false},{"id":"4-44","test":4,"number":44,"stem":["You have a registered DNS domain named apexcore.com. You then create a public Azure DNS zone with the same name (apexcore.com).","You must ensure that any DNS records added to this Azure DNS zone can be successfully resolved by clients on the public internet.","What action should you take?"],"options":[{"text":"Update the SOA record in the DNS domain registrar.","correct":false},{"text":"Create the SOA record in apexcore.com.","correct":false},{"text":"Update the NS records in the DNS domain registrar.","correct":true},{"text":"Create NS records in apexcore.com.","correct":false}],"explanation":["`Update the NS records in the DNS domain registrar` is the correct answer here. To ensure that records created in the apexcore.com Azure DNS zone are resolvable from the internet, you need to update the NS (Name Server) records in your DNS domain registrar. These records should point to the Azure DNS name servers associated with the apexcore.com zone in Azure. This change directs external DNS queries for apexcore.com to Azure DNS, allowing them to be resolved by the public Azure DNS servers.","`Update the SOA record in the DNS domain registrar` is incorrect because the SOA (Start of Authority) record is managed by Azure DNS, and you do not need to modify it in the domain registrar to enable public resolution.","`Create the SOA record in apexcore.com` is incorrect because the SOA record is automatically created and managed by Azure DNS for the zone. No manual action is needed for this record to enable internet resolvability.","`Create NS records in apexcore.com` is incorrect because NS records within the Azure DNS zone are already created automatically. The critical step is to update the NS records at the DNS domain registrar, not within Azure DNS."],"references":["https://learn.microsoft.com/en-us/azure/dns/dns-delegate-domain-azure-dns"],"images":[],"topic":"network","needsImage":false},{"id":"4-45","test":4,"number":45,"stem":["You have an Azure subscription that includes a virtual network named VNet1. VNet1 is connected to two separate on-premises datacenters by using two ExpressRoute circuits.","You need to build a dashboard that provides in-depth network metrics and a graphical view of the network topology.","Which Azure service should you use?"],"options":[{"text":"Azure Virtual Network Watcher","correct":false},{"text":"Azure Monitor Network Insights","correct":true},{"text":"a Data Collection Rule (DCR)","correct":false},{"text":"Log Analytics","correct":false}],"explanation":["`Azure Monitor Network Insights` is the correct answer here. Azure Monitor Network Insights provides a comprehensive view of your network’s health and performance. It includes detailed metrics, visualizations, and insights into the network topology, making it ideal for monitoring complex environments like the one described with multiple ExpressRoute circuits.","`Azure Virtual Network Watcher` is incorrect because, while it offers some monitoring and diagnostic tools for network resources, it does not provide an all-encompassing dashboard or a visual representation of network topology as effectively as Network Insights.","`A Data Collection Rule (DCR)` is incorrect because DCRs are primarily used to define data collection and ingestion rules for Azure Monitor. They do not provide a visual representation of network topology or a network-specific dashboard.","`Log Analytics` is incorrect because it is a tool for querying and analyzing logs. While you can use Log Analytics to query network data, it does not provide a pre-built dashboard or topology visualization as Network Insights does."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-topology?toc=%2Fazure%2Fazure-monitor%2Ftoc.json&bc=%2Fazure%2Fazure-monitor%2Fbreadcrumb%2Ftoc.json"],"images":[],"topic":"identity","needsImage":false},{"id":"4-46","test":4,"number":46,"stem":["You have an Azure subscription that includes the resources mentioned below:","- A virtual network named VNet1","- A subnet named Subnet1, which is part of VNet1","- Two virtual machines, VM1 and VM2, both deployed to Subnet1","VM1 and VM2 were created from the same deployment template and host line-of-business applications.","You configure a network security group (NSG) as shown in the exhibit.","You need to ensure that users on VM1 and VM2 are unable to browse websites on the internet by using TCP port 80.","What should you do?"],"options":[{"text":"Modify the DenyWebSites outbound security rule.","correct":false},{"text":"Update the Port_80 inbound security rule.","correct":false},{"text":"Associate the network security group with Subnet1.","correct":true},{"text":"Remove the network security group association from a network interface.","correct":false}],"explanation":["`Associate the network security group with Subnet1` is the correct answer here. The question specifies the need to prevent users of VM1 and VM2 from accessing websites on the Internet over TCP port 80. In the exhibit, there is an outbound rule, DenyWebSites, configured to block traffic on TCP port 80. However, if you look at the \"Associated with\" section in the top right corner of the exhibit, it shows \"0 subnets, 0 network interfaces\", meaning this NSG is not currently associated with any subnet or network interface.","To apply this restriction to VM1 and VM2, which are located in Subnet1, it is necessary to associate the NSG with Subnet1. By doing so, the NSG rules, including the DenyWebSites rule, will take effect, blocking outbound access to websites on TCP port 80 for both VM1 and VM2. Therefore, Associate the NSG to Subnet1 is the correct choice here.","`Modify the DenyWebSites outbound security rule` is incorrect because modifying the rule itself won’t make any difference if the NSG is not associated with Subnet1 or the network interfaces of VM1 and VM2.","`Update the Port_80 inbound security rule` is incorrect because this rule manages inbound traffic on port 80, which is unrelated to the requirement to restrict outbound web access.","`Remove the network security group association from a network interface` is incorrect because there is no existing association to remove, as indicated by the \"0 subnets, 0 network interfaces\" status."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/manage-network-security-group?tabs=network-security-group-portal"],"images":["assets/b169fa3988a24fe3.png"],"topic":"identity","needsImage":true},{"id":"4-47","test":4,"number":47,"stem":["You have an Azure virtual machine named VM1. You use Azure Backup to create a backup of VM1 called Backup1.","After Backup1 is created, you make the following changes to VM1:","- Change the virtual machine size.","- Copy a file named Budget.xls into a folder named Data.","- Reset the password for the built-in administrator account.","- Attach an additional data disk to the virtual machine.","An administrator then restores VM1 from Backup1 by using the Replace existing restore option.","You need to ensure that all the changes made after the backup are present on VM1 again.","Which action must you perform again?"],"options":[{"text":"Attach an additional data disk.","correct":false},{"text":"Copy Budget.xls into the Data folder.","correct":true},{"text":"Change the size of VM1.","correct":false},{"text":"Reset the password for the built-in administrator account.","correct":false}],"explanation":["`Copy Budget.xls into the Data folder` is correct because the Replace existing restore option restores the virtual machine disks from the selected recovery point. Any changes made to the contents of the disks after Backup1 was created are reverted. Since the Budget.xls file was copied into the Data folder after the backup was taken, it will not exist after the restore and must be copied again.","`Attach an additional data disk` is incorrect because attaching a data disk is a configuration change to the Azure virtual machine resource itself. The Replace existing restore operation primarily restores the VM disks from the backup recovery point and does not necessarily remove VM-level configuration changes such as attached disk references.","`Change the size of VM1` is incorrect because the VM size is a property of the Azure virtual machine resource and is not part of the disk contents restored from the recovery point. Restoring the VM disks does not typically revert the VM size configuration.","`Reset the password for the built-in administrator account` is incorrect because password reset operations are commonly managed through VM extensions and VM resource configuration rather than through the restored disk contents alone. The Replace existing operation does not necessarily revert these VM-level settings."],"references":["https://docs.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm","https://docs.microsoft.com/en-us/azure/backup/backup-azure-arm-restore-vms"],"images":[],"topic":"storage","needsImage":false},{"id":"4-48","test":4,"number":48,"stem":["You have an Azure subscription named Subscription1 that contains a resource group with the following characteristics:","- Name: RG1","- Region: West US","- Tags: `\"tag1\": \"value1\"`","You assign an Azure Policy named Policy1 at the Subscription1 scope with these settings:","- Exclusions: None","- Policy definition: Append a tag and its value to resources","- Assignment name: Policy1","- Parameters:","- Tag name: tag2","- Tag value: value2","After assigning Policy1, you create a storage account with the following properties:","- Name: storage1","- Region: West US","- Resource group: RG1","- Tags: `\"tag3\": \"value3\"`","Which tags are applied to RG1?"],"options":[{"text":"\"tag1\" : \"value1\" only","correct":true},{"text":"\"tag2\" : \"value2\" only","correct":false},{"text":"\"tag1\" : \"value1\" and \"tag2\" : \"value2\"","correct":false}],"explanation":["`\"tag1\" : \"value1\" only` is the correct answer here. The policy definition \"Append a tag and its value to resources\" is configured to apply to resources within Subscription1, not to the resource group RG1 itself. This policy assignment means that any new resources created under Subscription1 will have the specified tag2 : value2 appended if they do not already have this tag. However, it does not apply the tag to the resource group where the resources are created. Therefore, RG1 retains only the original tag, \"tag1\" : \"value1\". It should also be noted here that “Subscription” and “Policy1” are created at the initial stage itself and therefore the created policy would apply to the resource group – namely “RG1” within this subscription.","`\"tag2\" : \"value2\" only` is incorrect because Policy1 does not add tag2 : value2 to the resource group itself, only to resources created within the scope of Subscription1.","`\"tag1\" : \"value1\" and \"tag2\" : \"value2\"` is incorrect because, as explained, Policy1 does not alter tags on the resource group RG1 directly. It only affects newly created resources within Subscription1."],"references":["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies","https://docs.microsoft.com/en-us/azure/governance/policy/concepts/effects#append"],"images":[],"topic":"identity","needsImage":false},{"id":"4-49","test":4,"number":49,"stem":["You have an Azure subscription named Subscription1 that contains a resource group with the following characteristics:","- Name: RG1","- Region: West US","- Tags: `\"tag1\": \"value1\"`","You assign an Azure Policy named Policy1 at the Subscription1 scope with these settings:","- Exclusions: None","- Policy definition: Append a tag and its value to resources","- Assignment name: Policy1","- Parameters:","- Tag name: tag2","- Tag value: value2","After assigning Policy1, you create a storage account with the following properties:","- Name: storage1","- Region: West US","- Resource group: RG1","- Tags: `\"tag3\": \"value3\"","`","Which tags are assigned to storage1?"],"options":[{"text":"\"tag3\" : \"value3\" only","correct":false},{"text":"\"tag1\" : \"value1\" and \"tag3\" : \"value3\" only","correct":false},{"text":"\"tag2\" : \"value2\" and \"tag3\" : \"value3\" only","correct":true},{"text":"\"tag1\" : \"value1\", \"tag2\" : \"value2\", and \"tag3\" : \"value3\"","correct":false}],"explanation":["`\"tag2\" : \"value2\" and \"tag3\" : \"value3\" only` is the correct answer here. Tags are not inherited automatically from a resource group or subscription to the resources within them. However, in this case, Policy1 was applied to Subscription1 with the definition to append a specific tag to all new resources created in this subscription. The policy was configured with Exclusions: None and parameters Tag name: \"tag2\" and Tag value: \"value2\". This means that all resources created after this policy assignment will automatically have \"tag2\" : \"value2\" appended.","When storage1 was created in RG1 after the policy was assigned, it had \"tag3\" : \"value3\" specified. Since Policy1 was already in effect, \"tag2\" : \"value2\" was appended to storage1 due to the policy, resulting in storage1 having the tags \"tag2\" : \"value2\" and \"tag3\" : \"value3\" only.","`\"tag3\" : \"value3\" only` is incorrect because the policy enforces \"tag2\" : \"value2\" on all new resources in the subscription.","`\"tag1\" : \"value1\" and \"tag3\" : \"value3\" only` is incorrect because \"tag1\" : \"value1\" is assigned only to RG1 and does not get inherited by resources within the group.","`\"tag1\" : \"value1\", \"tag2\" : \"value2\", and \"tag3\" : \"value3\"` is incorrect because storage1 does not inherit \"tag1\" : \"value1\" from RG1."],"references":["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies","https://docs.microsoft.com/en-us/azure/governance/policy/concepts/effects#append"],"images":[],"topic":"identity","needsImage":false},{"id":"4-50","test":4,"number":50,"stem":["You have a Microsoft Entra tenant that contains the groups listed below, each with a specific group type and security setting.","- Group1 - Security group (Security enabled: Yes)","- Group2 - Mail-enabled security group (Security enabled: Yes)","- Group3 - Microsoft 365 group (Security enabled: Yes)","- Group4 - Microsoft 365 group (Security enabled: No)","You purchase Microsoft Entra ID P2 licenses and want to assign the licenses by using group-based licensing.","To which groups can you assign a license?"],"options":[{"text":"Group1 only","correct":false},{"text":"Group1 and Group3 only","correct":false},{"text":"Group3 and Group4 only","correct":false},{"text":"Group1, Group2, and Group3 only","correct":true},{"text":"Group1, Group2, Group3, and Group4","correct":false}],"explanation":["Group1, Group2, and Group3 only is correct because group-based licensing in Microsoft Entra ID supports security groups (including mail-enabled security groups) and Microsoft 365 groups that have securityEnabled=TRUE.","- Group1 is a security group with security enabled, so it can be used.","- Group2 is a mail-enabled security group, which is still a type of security group, and Microsoft documentation confirms that it is supported for license assignment.","- Group3 is a Microsoft 365 group with security enabled, so it also qualifies.","Group1 only is incorrect because Group3 (a security-enabled Microsoft 365 group) and Group2 (a mail-enabled security group) are also supported.","Group1 and Group3 only is incorrect because Group2 is also eligible for license assignment, as mail-enabled security groups are supported.","Group3 and Group4 only is incorrect because Group4 is a Microsoft 365 group with security disabled, making it ineligible.","Group1, Group2, Group3, and Group4 is incorrect because Group4 is security-disabled and cannot be used for license assignment."],"references":["https://learn.microsoft.com/en-us/microsoft-365/admin/manage/manage-group-licenses?view=o365-worldwide","https://learn.microsoft.com/en-us/microsoft-365/admin/create-groups/compare-groups?view=o365-worldwide"],"images":[],"topic":"identity","needsImage":false},{"id":"4-51","test":4,"number":51,"stem":["You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below.","{","\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\",","\"properties\": {","\"roleName\": \"Role1\",","\"description\": \"\",","\"assignableScopes\": [","\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\"","],","\"permissions\": [","{","\"actions\": [","\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\",","\"Microsoft.Resources/subscriptions/resourceGroups/read\",","\"Microsoft.Resourcehealth/*\",","\"Microsoft.Authorization/*/read\",","\"Microsoft.Compute/*/read\",","\"Microsoft.Support/*\",","\"Microsoft.Network/virtualNetworks/read\",","\"Microsoft.Resources/deployments/*\",","\"Microsoft.Storage/storageAccounts/read\",","\"Microsoft.Compute/virtualMachines/start/action\",","\"Microsoft.Compute/virtualMachines/powerOff/action\",","\"Microsoft.Compute/virtualMachines/deallocate/action\",","\"Microsoft.Compute/virtualMachines/restart/action\",","\"Microsoft.Compute/virtualMachines/*\",","\"Microsoft.Compute/disks/*\",","\"Microsoft.Compute/availabilitySets/*\",","\"Microsoft.Network/virtualNetworks/subnets/join/action\",","\"Microsoft.Network/virtualNetworks/subnets/read\",","\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\",","\"Microsoft.Network/networkInterfaces/*\",","\"Microsoft.Compute/snapshots/*\"","],","\"notActions\": [","\"Microsoft.Authorization/*/Delete\",","\"Microsoft.Authorization/*/Write\",","\"Microsoft.Authorization/elevateAccess/Action\"","]","}","]","}","}","True or False:","`“Users who are assigned Role1 are able to assign Role1 to other users.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. The custom role \"Role1\" includes various permissions under the \"actions\" section, but the \"notActions\" section explicitly denies permissions related to **Microsoft.Authorization/*/Delete, Microsoft.Authorization/*/Write, and Microsoft.Authorization/elevateAccess/Action**. These restricted permissions prevent users assigned with \"Role1\" from performing role assignments or modifications, including the ability to assign \"Role1\" to other users."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"4-52","test":4,"number":52,"stem":["You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below.","{","\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\",","\"properties\": {","\"roleName\": \"Role1\",","\"description\": \"\",","\"assignableScopes\": [","\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\"","],","\"permissions\": [","{","\"actions\": [","\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\",","\"Microsoft.Resources/subscriptions/resourceGroups/read\",","\"Microsoft.Resourcehealth/*\",","\"Microsoft.Authorization/*/read\",","\"Microsoft.Compute/*/read\",","\"Microsoft.Support/*\",","\"Microsoft.Network/virtualNetworks/read\",","\"Microsoft.Resources/deployments/*\",","\"Microsoft.Storage/storageAccounts/read\",","\"Microsoft.Compute/virtualMachines/start/action\",","\"Microsoft.Compute/virtualMachines/powerOff/action\",","\"Microsoft.Compute/virtualMachines/deallocate/action\",","\"Microsoft.Compute/virtualMachines/restart/action\",","\"Microsoft.Compute/virtualMachines/*\",","\"Microsoft.Compute/disks/*\",","\"Microsoft.Compute/availabilitySets/*\",","\"Microsoft.Network/virtualNetworks/subnets/join/action\",","\"Microsoft.Network/virtualNetworks/subnets/read\",","\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\",","\"Microsoft.Network/networkInterfaces/*\",","\"Microsoft.Compute/snapshots/*\"","],","\"notActions\": [","\"Microsoft.Authorization/*/Delete\",","\"Microsoft.Authorization/*/Write\",","\"Microsoft.Authorization/elevateAccess/Action\"","]","}","]","}","}","True or False:","`“Users who are assigned Role1 are able to deploy new virtual machines.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here.","Although `Microsoft.Compute/virtualMachines/*` alone is not always sufficient to deploy a new virtual machine, Role1 includes all the additional permissions required to create a VM and its associated resources.","The role grants the following key permissions:","- `Microsoft.Compute/virtualMachines/*` – Allows all operations on virtual machines, including creating (`write`), updating, deleting, starting, stopping, restarting, and deallocating VMs.","- `Microsoft.Compute/disks/*` – Allows creation and management of managed disks required by the VM.","- `Microsoft.Network/networkInterfaces/*` – Allows creation and management of network interfaces.","- `Microsoft.Network/virtualNetworks/subnets/join/action` – Allows the network interface to be attached to a subnet.","- `Microsoft.Resources/deployments/*` – Allows ARM template deployments, which are commonly used when deploying virtual machines.","Because Role1 includes permissions for both the virtual machine and its dependent resources, users assigned this role can successfully deploy new virtual machines.","The `notActions` section only prevents users from modifying Azure RBAC role assignments or elevating their own permissions. It does not restrict virtual machine deployment."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"4-53","test":4,"number":53,"stem":["You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below.","{","\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\",","\"properties\": {","\"roleName\": \"Role1\",","\"description\": \"\",","\"assignableScopes\": [","\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\"","],","\"permissions\": [","{","\"actions\": [","\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\",","\"Microsoft.Resources/subscriptions/resourceGroups/read\",","\"Microsoft.Resourcehealth/*\",","\"Microsoft.Authorization/*/read\",","\"Microsoft.Compute/*/read\",","\"Microsoft.Support/*\",","\"Microsoft.Network/virtualNetworks/read\",","\"Microsoft.Resources/deployments/*\",","\"Microsoft.Storage/storageAccounts/read\",","\"Microsoft.Compute/virtualMachines/start/action\",","\"Microsoft.Compute/virtualMachines/powerOff/action\",","\"Microsoft.Compute/virtualMachines/deallocate/action\",","\"Microsoft.Compute/virtualMachines/restart/action\",","\"Microsoft.Compute/virtualMachines/*\",","\"Microsoft.Compute/disks/*\",","\"Microsoft.Compute/availabilitySets/*\",","\"Microsoft.Network/virtualNetworks/subnets/join/action\",","\"Microsoft.Network/virtualNetworks/subnets/read\",","\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\",","\"Microsoft.Network/networkInterfaces/*\",","\"Microsoft.Compute/snapshots/*\"","],","\"notActions\": [","\"Microsoft.Authorization/*/Delete\",","\"Microsoft.Authorization/*/Write\",","\"Microsoft.Authorization/elevateAccess/Action\"","]","}","]","}","}","True or False:","`“Users who are assigned Role1 are able to configure a virtual machine to use a static IP address.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. The custom role \"Role1\" includes Microsoft.Network/networkInterfaces/* in the allowed actions, which grants users permissions to manage network interfaces, including the ability to set IP configurations on them. This permission allows users assigned \"Role1\" to configure settings such as static IP addresses on the network interface associated with a virtual machine."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"4-54","test":4,"number":54,"stem":["You have an Azure Load Balancer named LB1.","A user named User1 has the following role assignments:","- User Access Administrator assigned at the scope of LB1","- Virtual Machine Contributor assigned at the resource group level that contains LB1 (this assignment is inherited by LB1)","Based on these role assignments and their scopes, select the answer choice that completes the following statement correctly.","`“User 1 can __________________________.”`"],"options":[{"text":"delete LB1","correct":false},{"text":"create a NAT rule for LB1","correct":false},{"text":"assign access permissions to other users for LB1","correct":true}],"explanation":["`assign access permissions to other users for LB1` is the correct answer here. User1 has been assigned the User Access Administrator role on the specific resource, LB1. The User Access Administrator role allows User1 to manage access for other users on that resource, including assigning roles and permissions. This role provides the capability to delegate access without providing permissions to modify the resource itself.","`delete LB1` is incorrect because User1 does not have the Owner or Contributor role, which are required to delete resources in Azure. The assigned roles of User Access Administrator and Virtual Machine Contributor (at the resource group level) do not provide delete permissions for the Load Balancer.","`create a NAT rule for LB1` is incorrect because configuring or modifying NAT rules on a load balancer requires the Network Contributor or Load Balancer Contributor role. The User Access Administrator role does not allow User1 to configure or modify network settings, and the Virtual Machine Contributor role (inherited at the resource group level) also does not include permissions for network configurations."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"4-55","test":4,"number":55,"stem":["You have an Azure Load Balancer named LB1.","A user named User1 has the following role assignments:","- User Access Administrator assigned at the scope of LB1","- Virtual Machine Contributor assigned at the resource group level that contains LB1 (this assignment is inherited by LB1)","Based on these role assignments and their scopes, select the answer choice that completes the following statement correctly.","`“User 1 can __________________________ the resource group.”`"],"options":[{"text":"delete a virtual machine from","correct":true},{"text":"modify the load balancing rules in","correct":false},{"text":"deploy an Azure Kubernetes Service (AKS) cluster to","correct":false}],"explanation":["`delete a virtual machine from` is the correct answer here. User1 has been assigned the Virtual Machine Contributor role at the resource group level (inherited), which grants them permissions to manage virtual machines within that resource group. This includes creating, updating, and deleting virtual machines. Therefore, User1 can delete a virtual machine within the specified resource group. However, this role does not grant permissions to modify load balancing rules or deploy resources unrelated to virtual machines, such as an AKS cluster.","`modify the load balancing rules in` is incorrect because the Virtual Machine Contributor role does not include permissions to modify network settings or load balancing configurations. To modify load balancing rules, User1 would need the Network Contributor or Load Balancer Contributor role, which is not assigned in this scenario.","`deploy an Azure Kubernetes Service (AKS) cluster to` is incorrect because deploying an AKS cluster requires additional permissions beyond those granted by the Virtual Machine Contributor role. Typically, the Contributor role or specific permissions related to AKS deployment would be needed to create and manage AKS clusters in the resource group."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"4-56","test":4,"number":56,"stem":["You have an Azure subscription that follows the resource hierarchy shown in the diagram, which includes a Tenant Root Group, ManagementGroup1, Subscription1, a resource group named RG1, and a virtual machine named VM1.","You create an Azure Policy definition named Policy1.","To which Azure resources in this hierarchy can Policy1 be assigned?"],"options":[{"text":"Subscription1 and RG1 only","correct":false},{"text":"ManagementGroup1 and Subscription1 only","correct":false},{"text":"Tenant Root Group, ManagementGroup1, and Subscription1 only","correct":false},{"text":"Tenant Root Group, ManagementGroup1, Subscription1, and RG1 only","correct":false},{"text":"Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1","correct":true}],"explanation":["`Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1` is correct because Azure Policy definitions can be assigned at any level in the Azure hierarchy, including the tenant root group, management groups, subscriptions,  resource groups, and individual resource.","It should be noted that policy cannot be applied to an individual resource from the Azure Portal, however, it can be done via Azure CLI or PowerShell.","Since the question dosen't specifically state that the policy should be applied using Azure Portal only, we can safely assume  that using CLI/PowerShell, the policy can also be applied to an individual resource (VM1)."],"references":["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/assignment-structure","https://learn.microsoft.com/en-us/azure/governance/policy/concepts/scope#assignment-scopes","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/overview#understand-scope"],"images":["assets/6b856d8aa5e1c5d0.png"],"topic":"identity","needsImage":true},{"id":"4-57","test":4,"number":57,"stem":["You have an Azure subscription that follows the resource hierarchy shown in the diagram, which includes a Tenant Root Group, ManagementGroup1, Subscription1, a resource group named RG1, and a virtual machine named VM1.","You create an Azure Policy definition named Policy1.","Which Azure resources can you specify as exclusions from Policy1?"],"options":[{"text":"VM1 only","correct":false},{"text":"RG1 and VM1 only","correct":false},{"text":"Subscription1, RG1, and VM1 only","correct":false},{"text":"ManagementGroup1, Subscription1, RG1, and VM1 only","correct":true},{"text":"Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1","correct":false}],"explanation":["`ManagementGroup1, Subscription1, RG1, and VM1 only` is correct because when assigning a policy, you can exclude resources at any level in the hierarchy, including management groups, subscriptions, resource groups, and individual resources. Exclusions are designed to provide flexibility in policy enforcement by allowing specific resources or groups to be excluded from a policy's scope.","`Tenant Root Group` cannot be excluded from policy assignments. Exclusions are applicable to management groups, subscriptions, resource groups, and individual resources only."],"references":["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/assignment-structure","https://learn.microsoft.com/en-us/azure/governance/policy/overview"],"images":["assets/6b856d8aa5e1c5d0.png"],"topic":"identity","needsImage":true},{"id":"4-58","test":4,"number":58,"stem":["Your Azure environment contains 20 Windows Server virtual machines, an existing network security group called NSG1, and two virtual networks — VNET1 and VNET2 — that are connected through peering.","You intend to deploy an Azure Bastion host using the Basic SKU into VNET1. To ensure the Bastion service is reachable from external networks, you need to update NSG1 to allow incoming traffic from the internet.","When creating the inbound rule in NSG1, which destination port must be allowed?"],"options":[{"text":"22","correct":false},{"text":"443","correct":true},{"text":"3389","correct":false},{"text":"8080","correct":false}],"explanation":["`443` is correct because Azure Bastion uses HTTPS on port 443 for secure communication from the user's browser to the Azure Bastion host. This allows secure RDP or SSH access to virtual machines in the virtual network without exposing these VMs directly to the internet. When deploying Azure Bastion, an inbound rule must be added to the NSG for port 443 to allow this secure connection from the internet to the Bastion host.","`22` is incorrect because port 22 is used for SSH connections, but with Azure Bastion, the communication is tunneled over port 443 via HTTPS, making SSH directly over port 22 unnecessary.","`3389` is incorrect because port 3389 is used for RDP connections. Azure Bastion tunnels RDP sessions over port 443, eliminating the need to open port 3389 in the NSG.","`8080` is incorrect because port 8080 is not used by Azure Bastion for any connection."],"references":["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview"],"images":[],"topic":"network","needsImage":false},{"id":"4-59","test":4,"number":59,"stem":["You have an Azure subscription that includes a user named User1 and a storage account named storage1.","The storage account contains the following resources:","- A blob container named container1","- A file share named folder1","- A table named Table1","User1 is assigned the following roles on storage1:","- Storage Blob Data Reader","- Storage Table Data Contributor","- Storage File Data SMB Share Contributor","A shared access signature (SAS) named SAS1 is created for storage1 with the configuration shown in the exhibit.","Which of the following resources can User1 write to by using SAS1?"],"options":[{"text":"Table1 only","correct":true},{"text":"Table1 and container1 only","correct":false},{"text":"folder1 and Table1 only","correct":false},{"text":"folder1 and container1 only","correct":false},{"text":"Table1, folder1, and container1","correct":false}],"explanation":["`Table1 only` is correct because the SAS policy shown in the exhibit explicitly grants permissions only for the Table service. This means that when connecting to the storage account using SAS1, the scope of access is restricted to Table-based resources, such as Table1. Other services, such as Blob or File (which include container1 and folder1, respectively), are not included in the SAS policy. Therefore, only Table1 is accessible for all permitted operations, including creating, reading, updating, and deleting (CRUD). Other services will not be visible or accessible when connecting using this SAS key."],"references":[],"images":["assets/9bd8832f5a770f88.png"],"topic":"identity","needsImage":true},{"id":"4-60","test":4,"number":60,"stem":["You have an Azure subscription that includes a user named User1 and a storage account named storage1.","The storage account contains the following resources:","- A blob container named container1","- A file share named folder1","- A table named Table1","User1 is assigned the following roles on storage1:","- Storage Blob Data Reader","- Storage Table Data Contributor","- Storage File Data SMB Share Contributor","A shared access signature (SAS) named SAS1 is created for storage1 with the configuration shown in the exhibit.","Which of the following resources can User1 write to by using key1?"],"options":[{"text":"Table1 only","correct":false},{"text":"Table1 and container1 only","correct":false},{"text":"folder1 and Table1 only","correct":false},{"text":"folder1 and container1 only","correct":false},{"text":"Table1, folder1, and container1","correct":true}],"explanation":["`Table1, folder1, and container1` is the correct answer because access via `key1` refers to the use of a storage account access key, not a SAS token. Storage account keys act like root-level credentials and grant unrestricted full access to all services and data types in the storage account, including blobs (containers), files (file shares), and tables, regardless of the user's Azure RBAC roles. This means that even though User1 has limited RBAC roles, once they connect using the key, those restrictions are bypassed and they can read/write to all three resources."],"references":[],"images":["assets/9bd8832f5a770f88.png"],"topic":"identity","needsImage":true},{"id":"4-61","test":4,"number":61,"stem":["You have an Azure subscription that includes the storage accounts listed below:","- storage1: StorageV2 with geo-zone-redundant storage (GZRS)","- storage2: BlobStorage with read-access geo-redundant storage (RA-GRS)","- storage3: BlockBlobStorage with zone-redundant storage (ZRS)","You need to determine which of these storage accounts support Azure Blob lifecycle management policies.","Which storage accounts meet this requirement?"],"options":[{"text":"storage1 only","correct":false},{"text":"storage2 only","correct":false},{"text":"storage1 and storage3 only","correct":false},{"text":"storage2 and storage3 only","correct":false},{"text":"storage1, storage2, and storage3","correct":true}],"explanation":["`storage1, storage2, and storage3` is correct because all three storage account types—StorageV2, BlobStorage, and BlockBlobStorage—support lifecycle management policies for block blobs and append blobs. These policies enable automated tiering, deletion, and management of blob data to optimize costs and resource usage."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-62","test":4,"number":62,"stem":["You have an Azure subscription that includes the storage accounts listed below:","- storage1: StorageV2 with geo-zone-redundant storage (GZRS)","- storage2: BlobStorage with read-access geo-redundant storage (RA-GRS)","- storage3: BlockBlobStorage with zone-redundant storage (ZRS)","You need to determine which of these storage accounts support moving blob data to the Archive access tier.","Which storage accounts satisfy this requirement?"],"options":[{"text":"storage1 only","correct":false},{"text":"storage2 only","correct":true},{"text":"storage1 and storage3 only","correct":false},{"text":"storage2 and storage3 only","correct":false},{"text":"storage1, storage2, and storage3","correct":false}],"explanation":["`storage2 only` is correct because only storage accounts configured with LRS (Locally Redundant Storage), GRS (Geo-Redundant Storage), or RA-GRS (Read-Access Geo-Redundant Storage) support moving blob data to the Archive access tier.","`storage1` is incorrect because it is a StorageV2 account configured with GZRS (Geo-Zone-Redundant Storage), which does not support the Archive access tier.","`storage3` is incorrect because it is a BlockBlobStorage account configured with ZRS (Zone-Redundant Storage), which does not support the Archive access tier."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-63","test":4,"number":63,"stem":["You have an Azure Storage account named storage1.","You plan to use AzCopy to transfer data into storage1.","You need to determine which storage services within storage1 support data uploads by using AzCopy.","Which storage services should you identify?"],"options":[{"text":"file storage only","correct":false},{"text":"blob storage and file storage only","correct":true},{"text":"file storage and table storage only","correct":false},{"text":"blob storage, table storage, and queue storage only","correct":false},{"text":"blob storage, file storage, table storage, and queue storage","correct":false}],"explanation":["`blob storage and file storage only` is correct because AzCopy supports copying data to Blob storage and File storage, but not Table storage or Queue storage. AzCopy is specifically designed for transferring blob and file data efficiently within and across Azure storage accounts."],"references":[],"images":[],"topic":"storage","needsImage":false},{"id":"4-64","test":4,"number":64,"stem":["An Azure Storage account stores approximately 10,000 blob objects and is accessed by several different users.","You must implement a solution that restricts visibility so that each user can list and access only certain blobs according to their assigned blob index tags.","What component or configuration should you implement to meet this requirement?"],"options":[{"text":"a stored access policy","correct":false},{"text":"a role assignment condition","correct":true},{"text":"just-in-time (JIT) virtual machine access","correct":false},{"text":"a shared access signature (SAS)","correct":false}],"explanation":["`a role assignment condition` is correct because role assignment conditions in Azure can enforce granular access control based on blob index tags. By using conditions in role assignments, you can ensure that users are restricted to viewing only the blobs that match specific index tags. This is an advanced Azure Role-Based Access Control (RBAC) feature designed for fine-grained access control scenarios.","`a stored access policy` is incorrect because stored access policies are used in conjunction with Shared Access Signatures (SAS) to manage shared access over time, but they cannot enforce access based on blob index tags.","`just-in-time (JIT) virtual machine access` is incorrect because JIT VM access is designed to provide temporary access to virtual machines and has no relevance to blob access control or index tags.","`a shared access signature (SAS)` is incorrect because while SAS can provide temporary access to blobs, it cannot enforce blob index tag-based conditions for granular access control."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-custom-security-attributes","https://docs.microsoft.com/en-us/azure/role-based-access-control/conditions-overview","https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blob-index-how-to","https://docs.microsoft.com/en-us/azure/security-center/just-in-time-explained"],"images":[],"topic":"storage","needsImage":false},{"id":"4-65","test":4,"number":65,"stem":["In an Azure subscription named Subscription1, there is a resource group named RG1.","Inside RG1, two load balancers are deployed:","- LB1 – configured as an internal load balancer","- LB2 – configured as a public load balancer","You need to grant a user named Admin1 the ability to add and configure a backend address pool for LB1 by using backend resources in RG1. The solution must follow the principle of least privilege.","To enable Admin1 to create and configure a backend address pool for LB1, which Azure RBAC role should be assigned?"],"options":[{"text":"Contributor role assigned at the LB1 scope","correct":false},{"text":"Network Contributor role assigned at the LB1 scope","correct":false},{"text":"Network Contributor role assigned at the RG1 scope","correct":true},{"text":"Owner role assigned at the LB1 scope","correct":false}],"explanation":["`Network Contributor role assigned at the RG1 scope` is correct because adding a backend pool to a load balancer requires permissions not only on the load balancer itself but also on the resources (e.g., virtual machines or virtual machine scale sets) that will be added to the backend pool. The Network Contributor role at the resource group (RG1) level ensures Admin1 has the necessary permissions to manage network resources across RG1, including both the load balancer and the backend pool resources, while still adhering to the principle of least privilege.","`Contributor role assigned at the LB1 scope` is incorrect because this role grants overly broad permissions beyond just managing network resources. It does not align with the principle of least privilege.","`Owner role assigned at the LB1 scope` is incorrect because the Owner role allows full control, including assigning roles, which exceeds the requirements for adding a backend pool.","`Network Contributor role assigned at the LB1 scope` is incorrect because while this role provides permissions to manage the load balancer, it does not include permissions for managing the backend pool's underlying resources (e.g., virtual machines). These additional permissions are required to successfully add resources to the backend pool."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#network-contributor","https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-66","test":4,"number":66,"stem":["In an Azure subscription named Subscription1, there is a resource group named RG1.","Inside RG1, two load balancers are deployed:","- LB1 – configured as an internal load balancer","- LB2 – configured as a public load balancer","You need to grant Admin1 the ability to create a health probe on LB2. The solution must follow the principle of least privilege.","Which Azure RBAC role should assignment be assigned to Admin1 to allow the creation of a health probe on LB2?"],"options":[{"text":"Contributor role assigned at the LB2 scope","correct":false},{"text":"Network Contributor role assigned at the LB2 scope","correct":true},{"text":"Network Contributor role assigned at the RG1 scope","correct":false},{"text":"Owner role assigned at the LB2 scope","correct":false}],"explanation":["`Network Contributor role assigned at the LB2 scope` is correct because it adheres to the principle of least privilege. This role provides sufficient permissions to configure and manage health probes on the specific load balancer without granting unnecessary access to the entire resource group or other unrelated network resources. The Network Contributor role at the resource group level ensures Admin1 has the necessary access to both the load balancer and the related network resources, adhering to the principle of least privilege.","`Network Contributor role assigned at the RG1 scope` is incorrect because assigning this role at the resource group level grants broader permissions than necessary. While it enables the required operations, it goes against the principle of least privilege by providing access to all network resources within the resource group, not just LB2.","`Contributor role assigned at the LB2 scope` is incorrect because it grants excessive permissions, including access to non-network-related tasks, violating the principle of least privilege.","`Owner role assigned at the LB2 scope` is incorrect because the Owner role provides full administrative control, including the ability to assign roles, which far exceeds the permissions needed to add a health probe."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#network-contributor","https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"4-67","test":4,"number":67,"stem":["You have an Azure subscription that includes 10 virtual machines running Windows Server. Each VM hosts a website using IIS, and the Azure Monitor Agent is already installed on all machines.","Your objective is to collect IIS log files from each virtual machine and store them in a Log Analytics workspace.","What should you configure as the initial step?"],"options":[{"text":"a private endpoint","correct":false},{"text":"Diagnostic settings","correct":true},{"text":"a data collection endpoint","correct":false},{"text":"VM insights","correct":false},{"text":"an Azure Monitor Private Link Scope (AMPLS)","correct":false}],"explanation":["`Diagnostic settings` is the correct answer because Diagnostic settings in Azure allow you to specify which logs and metrics should be collected from your virtual machines and where they should be sent, such as a Log Analytics workspace. To collect IIS logs from each virtual machine and store them in a Log Analytics workspace, you must configure Diagnostic settings on each virtual machine to enable and route IIS log data appropriately.","`a private endpoint` is incorrect because private endpoints are used to provide private access to Azure services via a private IP address, which is unrelated to configuring IIS log collection.","`a data collection endpoint` is incorrect because a Data Collection Endpoint (DCE) is only needed if Azure Monitor Private Links are in use, which is not specified in this scenario.","`VM insights` is incorrect because VM insights focuses on performance monitoring and dependency mapping for virtual machines. It does not handle IIS log collection and routing to a Log Analytics workspace.","`an Azure Monitor Private Link Scope (AMPLS)` is incorrect because AMPLS enables private access to Azure Monitor resources using Private Links. It is not a requirement for IIS log collection in this context."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/diagnostic-settings","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-collection-iis"],"images":[],"topic":"identity","needsImage":false},{"id":"4-68","test":4,"number":68,"stem":["You plan to deploy multiple Azure virtual machines running Windows Server 2022 as part of a virtual machine scale set by using an Azure Resource Manager template.","You must ensure that NGINX is installed and available on all virtual machines after the deployment completes.","Which two options should you use?"],"options":[{"text":"a Desired State Configuration (DSC) extension","correct":true},{"text":"Azure Application Insights","correct":false},{"text":"the Publish-AzVMDscConfiguration cmdlet","correct":true},{"text":"the New-AzConfigurationAssignment cmdlet","correct":false}],"explanation":["`a Desired State Configuration (DSC) extension` is the correct answer because the DSC extension allows you to define a desired state configuration for virtual machines in a scale set. This configuration can include installing and configuring software like NGINX on all virtual machines automatically after deployment.","`the Publish-AzVMDscConfiguration cmdlet` is also correct because this cmdlet is used to upload and publish a DSC configuration script to an Azure storage account. This script can then be used by the DSC extension to ensure NGINX is installed and configured on the virtual machines in the scale set.","`Azure Application Insights` is incorrect because Application Insights is a monitoring service used to track application performance and detect issues. It does not install or configure software like NGINX on virtual machines.","`the New-AzConfigurationAssignment cmdlet` is incorrect because this cmdlet is used to assign configurations in Azure Policy for governance, not for installing or configuring software on virtual machines."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-overview","https://learn.microsoft.com/en-us/powershell/module/az.compute/publish-azvmdscconfiguration?view=azps-13.0.0","https://learn.microsoft.com/en-us/azure/azure-monitor/app/app-insights-overview","https://learn.microsoft.com/en-us/powershell/module/az.maintenance/new-azconfigurationassignment?view=azps-13.0.0"],"images":[],"topic":"compute","needsImage":false},{"id":"4-69","test":4,"number":69,"stem":["You have a subnet named Subnet1 that hosts several Azure virtual machines. A network security group named NSG1 is associated with Subnet1, and NSG1 currently includes only the default security rules.","You must add a rule to NSG1 that blocks the virtual machines in Subnet1 from accessing the Azure portal. At the same time, the virtual machines must continue to have access to other destinations on the internet.","What value should you configure for the Destination setting in the rule?"],"options":[{"text":"Application security group","correct":false},{"text":"IP Addresses","correct":false},{"text":"Any","correct":false},{"text":"Service Tag","correct":true}],"explanation":["`Service Tag` is the correct answer because Service Tags simplify network security group (NSG) rules by allowing you to reference a group of IP addresses associated with a specific Azure service. In this scenario, to block access to the Azure portal while still allowing access to other internet resources, you would use the AzureCloud service tag as the Destination in your NSG rule. This ensures that traffic specifically destined for the Azure portal is denied without impacting other internet traffic.","`Application security group` is incorrect because Application Security Groups (ASGs) are used to group virtual machines within the same virtual network to simplify NSG management. They cannot be used to target Azure services like the Azure portal.","`IP Addresses` is incorrect because blocking access to the Azure portal using IP addresses would require you to manually identify and maintain the list of Azure portal IP ranges, which is not practical or recommended.","`Any` is incorrect because setting the destination to \"Any\" would block all internet traffic, including non-Azure-related services, which does not meet the requirement of allowing access to other internet hosts."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/service-tags-overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"],"images":[],"topic":"network","needsImage":false},{"id":"4-70","test":4,"number":70,"stem":["You have two Azure virtual machines named VM1 and VM2, and two Recovery Services vaults named RSV1 and RSV2.","Currently, VM2 is protected by backups stored in RSV1.","You want to configure backups for VM2 by using RSV2 instead.","What action should you perform first?"],"options":[{"text":"From the RSV1 blade, click Backup items and stop the VM2 backup.","correct":true},{"text":"From the RSV2 blade, click Backup. From the Backup blade, select the backup for the virtual machine, and then click Backup.","correct":false},{"text":"From the VM2 blade, click Disaster recovery, click Replication settings, and then select RSV2 as the Recovery Services vault.","correct":false},{"text":"From the RSV1 blade, click Backup Jobs and export the VM2 job.","correct":false}],"explanation":["`From the RSV1 blade, click Backup items and stop the VM2 backup` is the correct answer because an Azure virtual machine can only be backed up to one Recovery Services vault at a time. To back up VM2 to a different vault (RSV2), you must first stop the existing backup in RSV1. Once the backup is stopped and the backup data is removed, you can reconfigure the backup for VM2 in RSV2.","`From the RSV2 blade, click Backup. From the Backup blade, select the backup for the virtual machine, and then click Backup` is incorrect because you cannot directly configure VM2 to back up in RSV2 without first stopping the existing backup configuration in RSV1.","`From the VM2 blade, click Disaster recovery, click Replication settings, and then select RSV2 as the Recovery Services vault` is incorrect because Disaster Recovery settings are for replicating a VM to another region, not for configuring backup to a Recovery Services vault.","`From the RSV1 blade, click Backup Jobs and export the VM2 job` is incorrect because exporting backup jobs does not change the Recovery Services vault assigned to the virtual machine."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix","https://docs.microsoft.com/en-us/azure/backup/backup-azure-move-recovery-services-vault#must-preserve-previous-backed-up-data","https://docs.microsoft.com/en-in/azure/backup/backup-azure-vms-first-look-arm"],"images":[],"topic":"compute","needsImage":false},{"id":"4-71","test":4,"number":71,"stem":["You have an Azure subscription named Sub1 with the subscription ID 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40.","You want to create a custom Azure RBAC role named CustomRole1 that meets the following conditions:","- The role can be assigned only at the resource group scope within Sub1.","- The role must not allow users to manage access permissions (RBAC) on the resource groups.","- The role must allow users to view, create, update, and delete resources inside the resource groups.","You are defining the role by using a JSON definition that includes the assignableScopes and permissions sections.","What value should you specify for `Code Segment A` in the definition of CustomRole1?"],"options":[{"text":"\"/\"","correct":false},{"text":"\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40\"","correct":true},{"text":"\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40/resourceGroups/\"","correct":false}],"explanation":["`\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40\"` is the correct answer here. The assignableScopes property defines where a custom role can be assigned, and it accepts scopes such as management groups, subscriptions, or specific resource groups. Since Subscription1 has a subscription ID of 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40, and the requirement is to allow assignment of the role only to resource groups within this subscription, the correct assignable scope is the subscription level. This ensures the custom role is available for assignment at the resource group level within that subscription without being overly permissive.","`\"/\"` is incorrect because the root scope is not supported in custom role definitions. AssignableScopes cannot be set to \"/\", and attempting to do so will result in a validation error.","`\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40/resourceGroups\"` is incorrect because this is not a valid scope. The string \"resourceGroups\" is a collection placeholder, and not a valid scope by itself. Using it will result in a validation error such as:","\"Validation error: Invalid scope: /subscriptions/<SubscriptionID>/resourceGroups\".","Additionally, the question does not reference any specific resource group. It refers broadly to “resource groups” within the subscription, and therefore the assignable scope must be set at the subscription level.","Reference(s.):","- https://docs.microsoft.com/en-us/azure/role-based-access-control/custom-roles","- https://docs.microsoft.com/en-us/azure/role-based-access-control/role-definitions#assignablescopes"],"references":[],"images":["assets/33563e53c8509864.png"],"topic":"identity","needsImage":true},{"id":"4-72","test":4,"number":72,"stem":["You have an Azure subscription named Sub1 with the subscription ID 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40.","You want to create a custom Azure RBAC role named CustomRole1 that meets the following conditions:","- The role can be assigned only at the resource group scope within Sub1.","- The role must not allow users to manage access permissions (RBAC) on the resource groups.","- The role must allow users to view, create, update, and delete resources inside the resource groups.","You are defining the role by using a JSON definition that includes the assignableScopes and permissions sections.","What value should you specify for `Code Segment B` in the definition of CustomRole1?"],"options":[{"text":"\"Microsoft.Authorization/\"","correct":true},{"text":"\"Microsoft.Resources/\"","correct":false},{"text":"\"Microsoft.Security/*\"","correct":false}],"explanation":["`\"Microsoft.Authorization/\"` is the correct answer here. In the context of custom RBAC role definitions, the \"notActions\" element (Dropdown 2) is used to explicitly deny certain management operations, even if the `\"actions\"` list includes a wildcard like `\"*\"`. In this scenario, the custom role CustomRole1 must allow full access to view, create, modify, and delete resources within resource groups, but it must prevent the user from managing access permissions (i.e., prevent role assignments).","Role assignment and access control operations in Azure are managed through the Microsoft.Authorization namespace. Therefore, to block permission management, you need to specify \"Microsoft.Authorization/\" in the \"notActions\" array. This removes the ability to read, create, or delete role assignments, while still allowing other actions.","`\"Microsoft.Resources/\"` is incorrect because this namespace is used for general resource management tasks like creating and managing resource groups or deployments, not for managing access control. Including it in \"notActions\" would block legitimate resource operations that the role should be allowed to perform.","`**\"Microsoft.Security/*\"` is incorrect** because it relates to security center operations such as policy management, security recommendations, and alerts. It is not relevant to access control and does not affect permissions related to RBAC.","Reference(s.):","- https://docs.microsoft.com/en-us/azure/role-based-access-control/custom-roles","- https://docs.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations#microsoftresources","- https://docs.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations#microsoftsecurity"],"references":[],"images":["assets/33563e53c8509864.png"],"topic":"identity","needsImage":true},{"id":"4-73","test":4,"number":73,"stem":["You have an Azure web app named App1 that uses deployment slots, as shown below:","- webapp1-prod -> Production","- webapp1-test -> Staging","You validate multiple updates to App1 in the webapp1-test slot.","After completing testing, you create a backup of App1.","You then swap the webapp1-test slot with webapp1-prod, after which the application starts showing performance problems.","You must roll back App1 to the earlier, stable version in the shortest possible time.","What action should you take?"],"options":[{"text":"Restore App1 from the backup.","correct":false},{"text":"Create a clone of App1.","correct":false},{"text":"Redeploy the application to App1.","correct":false},{"text":"Swap the deployment slots again.","correct":true}],"explanation":["`Swap the deployment slots again` is the correct answer here. Azure App Service deployment slots allow you to deploy and test changes in a staging slot (in this case, `webapp1-test`) and then swap the staging slot with the production slot (`webapp1-prod`) when ready. When a swap is performed, the content and configuration of the slots are exchanged, allowing for a quick rollback if needed.","Since you already swapped the test slot into production and discovered performance issues, the fastest way to revert is to swap the slots again. This will return the original production version (which is now in the test slot) back to its place, restoring the last working state almost instantly and with zero downtime.","`Restore App1 from the backup` is incorrect because although it can restore the app to a previous state, it is a slower operation and involves data loss risk and manual effort, making it less ideal for quick recovery.","`Create a clone of App1` is incorrect because cloning creates a new app instance, which is not a recovery mechanism and would not affect the current deployment state of App1.","`Redeploy the application to App1` is incorrect because this would require rebuilding and redeploying the application code, which takes more time and may not exactly match the last known good state.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"],"references":[],"images":[],"topic":"monitor","needsImage":false},{"id":"4-74","test":4,"number":74,"stem":["You have a pay-as-you-go Azure subscription with the following virtual machines:","- VM1 in resource group RG1, costing 20 euros per day","- VM2 in resource group RG2, costing **30 euros per day","You create the budget shown in the following exhibit.","The budget is set up with alert thresholds at 50%, 70%, and 100%, each linked to different action groups.","The action group AG1 contains only the user admin@apexcore.com.","Based on this configuration, complete the following statement:","“When VM1 and VM2 reach the maximum budget limit, ___________________________________.”"],"options":[{"text":"Both VM1 and VM2 are automatically shut down.","correct":false},{"text":"VM1 and VM2 continue running.","correct":true},{"text":"VM1 is stopped, while VM2 continues to run.","correct":false}],"explanation":["`VM1 and VM2 continue running` is the correct answer here. Azure budgets are a monitoring and alerting tool only. They do not enforce or take automatic action such as shutting down resources. In the case study:","- Budget1 is scoped to Resource Group RG1, which contains VM1.","- VM2, which is in RG2, is not within the scope of the budget and is therefore not tracked or managed by this budget.","- Even when the budget is fully consumed (100%), the configured action groups (AG1, AG2, AG3) only send notifications (via Email, SMS, or Azure app), but do not stop or deallocate any virtual machines.","Therefore, when both VM1 and VM2 reach their maximum cost, they continue to run, and no automatic shutdown occurs.","Reference(s.):**","- https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets","- https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/cost-management-budget-scenario","- https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/cost-mgt-alerts-monitor-usage-spending"],"references":[],"images":["assets/51eeeceea2976350.png"],"topic":"identity","needsImage":true},{"id":"4-75","test":4,"number":75,"stem":["You have a pay-as-you-go Azure subscription with the following virtual machines:","- VM1 in resource group RG1, costing 20 euros per day","- VM2 in resource group RG2, costing **30 euros per day","You create the budget shown in the following exhibit.","The budget is set up with alert thresholds at 50%, 70%, and 100%, each linked to different action groups.","The action group AG1 contains only the user admin@apexcore.com.","Based on this configuration, complete the following statement:","“Given the existing usage costs of the virtual machines, _________________________.”"],"options":[{"text":"no email notifications will be sent each month","correct":false},{"text":"one email notification will be sent each month","correct":true},{"text":"two email notifications will be sent each month","correct":false},{"text":"three email notifications will be sent each month","correct":false}],"explanation":["`one email notification will be sent each month` is the correct answer here. This is a common area of confusion, so let's clarify it step by step to avoid misinterpretation.","In the provided scenario:","- VM1 is the only virtual machine within the scope of Budget1 (since VM1 is in RG1, and the budget is scoped to RG1).","- VM1 costs €20 per day, which totals approximately €600 per month.","- The budget thresholds are:","- 50% of €1,000 → triggers Action Group AG1 (configured to send 1 email)","- 70% of €1,000 → triggers AG2 (sends 1 SMS)","- 100% of €1,000 → triggers AG3 (sends 1 Azure app notification)","At €600, only the 50% threshold is crossed, which triggers AG1.","Why it’s not two emails:","You may mistakenly think that:","- One email is sent because AG1 is triggered","- Another email is sent because admin@apexcore.com is listed as an alert recipient","This is not correct.","In Azure Budgets, email alerts are sent only via Action Groups. The person listed (e.g., `admin@apexcore.com`) in the budget configuration is part of the Action Group (AG1) that is associated with the 50% threshold. They are not receiving a second, separate notification outside the Action Group.","So even though the name appears in the recipient list, it does not represent an additional notification beyond what AG1 is configured to send.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets","- https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/cost-management-budget-scenario","- https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/cost-mgt-alerts-monitor-usage-spending"],"references":[],"images":["assets/51eeeceea2976350.png"],"topic":"identity","needsImage":true},{"id":"4-76","test":4,"number":76,"stem":["You have an Azure subscription that contains the following App Service plans:","- ASP1 runs on Linux and uses the Basic B1 pricing tier.","- ASP2 runs on Windows and uses the Standard S1 pricing tier.","- ASP3 runs on Linux and uses the Premium v3 pricing tier.","You plan to create an additional App Service plan with these settings:","- Name: ASP4","- Operating system: Windows","- Pricing tier: Premium v3","You need to determine which of the App Service plans support rule-based scale-out.","Which App Service plans should you identify?"],"options":[{"text":"ASP4 only","correct":false},{"text":"ASP2 and ASP4 only","correct":false},{"text":"ASP2, ASP3, and ASP4 only","correct":true},{"text":"ASP1, ASP2, ASP3, and ASP4","correct":false}],"explanation":["`ASP2, ASP3, and ASP4 only` is correct. The question asks which App Service plans support rule-based scale out, which refers specifically to autoscale—the ability to automatically increase or decrease the number of instances based on predefined rules, such as CPU usage, memory load, or a schedule.","According to Microsoft documentation:","- Autoscale is not supported in the Basic (B1) pricing tier. While Basic plans support manual scale-out (up to 3 instances), they do not support rule-based scaling.","- Standard (S1) and Premium v3 plans do support autoscale, allowing automatic instance management based on defined rules and schedules.","Therefore, ASP2, ASP3, and ASP4 all support rule-based scale out, while ASP1 does not.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-get-started","- https://learn.microsoft.com/en-us/azure/app-service/manage-automatic-scaling?tabs=azure-portal","- https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up","- https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-77","test":4,"number":77,"stem":["You have an Azure subscription that contains the following App Service plans:","- ASP1 runs on Linux and uses the Basic B1 pricing tier.","- ASP2 runs on Windows and uses the Standard S1 pricing tier.","- ASP3 runs on Linux and uses the Premium v3 pricing tier.","You plan to create an additional App Service plan with these settings:","- Name: ASP4","- Operating system: Windows","- Pricing tier: Premium v3","You need to determine which of the App Service plans support zone redundancy.","Which App Service plans should you identify?"],"options":[{"text":"ASP4 only","correct":true},{"text":"ASP2 and ASP4 only","correct":false},{"text":"ASP2, ASP3, and ASP4 only","correct":false},{"text":"ASP1, ASP2, ASP3, and ASP4","correct":false}],"explanation":["`ASP4 only` is the correct answer here. Azure App Service supports zone redundancy only on the Premium v2 and Premium v3 pricing tiers. This makes ASP3 and ASP4 eligible, since both are using the Premium v3 tier.","But since the correct combination (ASP3 and ASP4 only) is not available among the answer choices, we need to select the best possible correct option from the list.","Among the choices provided:","- `ASP4 only` is the most accurate, because while it omits ASP3, it is the only option that exclusively lists a supported plan.","Therefore, ASP4 only is the best and most appropriate answer based on the available options.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/reliability/reliability-app-service?pivots=free-shared-basic#regions-supported","- https://learn.microsoft.com/en-us/azure/app-service/overview-hosting-plans#premiumv3-pricing-tier"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-78","test":4,"number":78,"stem":["You have an Azure subscription with a virtual network named VNet1.","VNet1 includes four subnets named Gateway, Perimeter, NVA, and Production.","The NVA subnet hosts two network virtual appliances (NVAs).","These NVAs are used to inspect network traffic flowing between the Perimeter subnet and the Production subnet.","You need to deploy an Azure Load Balancer in front of the NVAs.","The solution must meet the following conditions:","- The NVAs must operate in an active-active setup with automatic failover.","- Traffic must be load balanced to two different services in the Production subnet, and each service uses a different IP address.","Which three actions should you take?"],"options":[{"text":"Add a frontend IP configuration, two backend pools, and a health probe","correct":true},{"text":"Add a frontend IP configuration, a backend pool, and a health probe","correct":false},{"text":"Deploy a basic load balancer","correct":false},{"text":"Deploy a standard load balancer","correct":true},{"text":"Add two load balancing rules that have HA Ports enabled and Floating IP disabled","correct":false},{"text":"Add two load balancing rules that have HA Ports and Floating IP enabled","correct":true}],"explanation":["`Add a frontend IP configuration, two backend pools, and a health probe` is correct because the requirement involves load balancing traffic to two services on different IP addresses in the Production subnet. This necessitates two separate backend pools, each associated with one of the services. A frontend IP configuration is needed to receive incoming traffic, and a health probe is essential to determine the availability of the NVAs in the backend pool for failover.","`Deploy a standard load balancer` is correct because only the Standard SKU load balancer supports advanced features like HA Ports, Floating IP, and availability zones, all of which are needed for this high availability active-active NVA setup. The Basic SKU does not support multiple backend pools or advanced configurations required in this scenario.","`Add two load balancing rules that have HA Ports and Floating IP enabled` is correct because:","- HA Ports allows the load balancer to listen on all ports for the services, ensuring full connectivity through the NVAs.","- Floating IP (also known as Direct Server Return) must be enabled for scenarios that involve high availability and active-active NVAs, because it ensures the return path of packets doesn't interfere with source NAT.","`Add a frontend IP configuration, a backend pool, and a health probe` is incorrect because a single backend pool cannot load balance traffic to two distinct IP addresses (services). This setup lacks the isolation needed for managing traffic across both services.","`Deploy a basic load balancer` is incorrect because Basic SKU does not support HA Ports or multiple backend pools, which are essential for this solution.","`Add two load balancing rules that have HA Ports enabled and Floating IP disabled` is incorrect because disabling Floating IP prevents the correct routing behavior necessary for high availability and direct server return, which is needed in an active-active NVA configuration.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-ha-ports-overview","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-floating-ip","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-outbound-connections#scenarios-for-floating-ip-enabled","- https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-multivip-overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-79","test":4,"number":79,"stem":["You have the following Azure virtual networks configured:","- VNet1","- Address space: 10.11.0.0/16","- Subnet: 10.11.0.0/17","- Resource group Azure region: West US","- VNet2","- Address space: 10.11.0.0/17","- Subnet: 10.11.0.0/25","- Resource group Azure region: West US","- VNet3","- Address space: 10.10.0.0/22","- Subnet: 10.10.1.0/24","- Resource group Azure region: East US","- VNet4","- Address space: 192.168.16.0/22","- Subnet: 192.168.16.0/24","- Resource group Azure region: North Europe","You want to configure virtual network peering for VNet1.","Which of the listed virtual networks can be peered with VNet1?"],"options":[{"text":"VNet2 only","correct":false},{"text":"VNet3 and VNet4 only","correct":true},{"text":"VNet2 and VNet3 only","correct":false},{"text":"VNet2, VNet3, and VNet4","correct":false}],"explanation":["`VNet3 and VNet4 only` is the correct answer here. To peer virtual networks in Azure, one of the main requirements is that the address spaces must not overlap. In the case of VNet1 (10.11.0.0/16):","- VNet2 (10.11.0.0/17) has an address space that overlaps with VNet1. Peering is not allowed in this case due to the overlapping IP ranges, even though it’s in the same region.","- VNet3 (10.10.0.0/22) has a non-overlapping address space and is in a different region (East US), which is still supported via global virtual network peering.","- VNet4 (192.168.16.0/22) also has a non-overlapping address space and is in North Europe, which again supports global VNet peering.","Therefore, only VNet3 and VNet4 can be peered with VNet1.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","- https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"],"references":[],"images":[],"topic":"network","needsImage":false},{"id":"4-80","test":4,"number":80,"stem":["You have two Azure subscriptions named Sub1 and Sub2.","In Sub1, there is a virtual machine named VM1 and a storage account named storage1.","The virtual machine VM1 is associated with the following resources:","- Disk1, which is the operating system disk for VM1","- NetInt1, which is the network interface attached to VM1","- VNet1, which is the virtual network that VM1 connects to","You need to move VM1 from Sub1 to Sub2.","Which of the associated resources must you move to Sub2 to complete this task?"],"options":[{"text":"VM1, Disk1, and NetInt1 only","correct":false},{"text":"VM1, Disk1, and VNet1 only","correct":false},{"text":"VM1, Disk1, and storage1 only","correct":false},{"text":"VM1, Disk1, NetInt1, and VNet1","correct":true}],"explanation":["`VM1, Disk1, NetInt1, and VNet1` is the correct answer here. When you move a virtual machine (VM1) to another subscription, all its associated dependent resources must be moved as well. This includes the OS disk (`Disk1`), the network interface (`NetInt1`), and the virtual network (`VNet1`). Azure requires that all dependent resources are part of the move operation to ensure the VM remains functional in the target subscription. If any dependency, like the NIC or virtual network, is left behind, the VM will lose connectivity or fail validation during the move.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription#virtual-machines","- https://learn.microsoft.com/en-us/azure/virtual-machines/network-overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"4-81","test":4,"number":81,"stem":["You manage two Azure subscriptions: Subscription1 and Subscription2.","In Subscription1, the following resource groups exist:","- RG1 – Region: West Europe – Lock: None","- RG2 – Region: West Europe – Lock: Read-only","The resource group RG1 contains a web application named App1, which is deployed in the West Europe region.","In Subscription2, the following resource groups are configured:","- RG3 – Region: North Europe – Lock: Delete","- RG4 – Region: Central US – Lock: None","True or False:","`“App1 can be moved to RG2.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because RG2 has a `Read Only` lock applied. When a resource group is locked with `Read Only`, you cannot add or move any resources into it. This type of lock prevents all write operations, including the action of moving a resource (such as App1) into the locked resource group. Even though App1 and RG2 are in the same region and subscription, the lock on RG2 blocks the move."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources?tabs=json","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription"],"images":[],"topic":"identity","needsImage":false},{"id":"4-82","test":4,"number":82,"stem":["You manage two Azure subscriptions: Subscription1 and Subscription2.","In Subscription1, the following resource groups exist:","- RG1 – Region: West Europe – Lock: None","- RG2 – Region: West Europe – Lock: Read-only","The resource group RG1 contains a web application named App1, which is deployed in the West Europe region.","In Subscription2, the following resource groups are configured:","- RG3 – Region: North Europe – Lock: Delete","- RG4 – Region: Central US – Lock: None","True or False:","`“App1 can be moved to RG3.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because Azure allows moving supported resources, such as an App Service web app, between resource groups and even between subscriptions within the same tenant. When a resource is moved between resource groups or subscriptions, the resource itself does not move to another region. Only the Azure Resource Manager metadata changes, and the resource continues to run in its original region.","In this scenario, App1 is deployed in the West Europe region, and moving it to RG3 does not change its location. Even though RG3 is associated with North Europe, resource groups can contain resources from different regions, so this does not prevent the move.","Additionally, if the web app depends on other resources, such as an App Service Plan, those dependent resources must be moved together in the same operation.","The Delete lock on RG3 does not block the move because a delete lock only prevents deletion of the resource group or its resources. It does not prevent adding or moving resources into the resource group.","Therefore, App1 can be moved to RG3, making the statement True."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-support-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"],"images":[],"topic":"identity","needsImage":false},{"id":"4-83","test":4,"number":83,"stem":["You manage two Azure subscriptions: Subscription1 and Subscription2.","In Subscription1, the following resource groups exist:","- RG1 – Region: West Europe – Lock: None","- RG2 – Region: West Europe – Lock: Read-only","The resource group RG1 contains a web application named App1, which is deployed in the West Europe region.","In Subscription2, the following resource groups are configured:","- RG3 – Region: North Europe – Lock: Delete","- RG4 – Region: Central US – Lock: None","True or False:","`“App1 can be moved to RG4.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because App1 can be moved to RG4, which is located in the Central US region, provided that RG4 does not contain any existing App Service resources such as web apps, App Service plans, or TLS/SSL certificates.","Although App1 is in West Europe, moving an app across resource groups or subscriptions does not change the region of the app. The app retains its original region (West Europe) after the move. The metadata such as resource group or subscription may change, but the physical location of the app stays the same.","There is no lock on RG4, so it won’t block the operation."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-move-across-resources","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-support-resources"],"images":[],"topic":"identity","needsImage":false},{"id":"4-84","test":4,"number":84,"stem":["You have an Azure subscription that contains a virtual machine named VM1.","The virtual machine has two disks attached:","- An operating system disk named Disk1","- A data disk named Disk2","You are required to back up only Disk2 by using Azure Backup.","Which three actions should you perform in sequence?","ACTIONS","- Create a backup policy and configure the backup.","- Create a Recovery Services vault.","- Create an Azure Backup vault.","- Configure a managed identity.","- Delegate permissions for the vault."],"options":[{"text":"1-3-4","correct":false},{"text":"4-3-1","correct":false},{"text":"3-1-4","correct":true},{"text":"2-1-4","correct":false},{"text":"4-2-1","correct":false}],"explanation":["`3-1-4` is the correct sequence of actions.","`(Action 3)` Create an Azure Backup vault is correct. For Azure Disk Backup (as opposed to full VM backup), you use an Azure Backup vault, which is a specific vault type designed for backing up individual managed disks. This is different from a Recovery Services vault, which is used for broader scenarios like VM, SQL, and file backups.","`(Action 1)` Create a backup policy and configure the backup is correct. After the vault is created, you define a backup policy that dictates the schedule and retention for the disk backup. You then associate Disk2 with this policy.","`(Action 4)` Configure a managed identity is correct. Azure Disk Backup uses Azure RBAC and managed identities for access. You must configure a user-assigned managed identity with appropriate roles (like `Disk Backup Reader`) to allow the vault to access and back up Disk2.","`(Action 2)` Create a Recovery Services vault is incorrect. This is used for VM-level backup and is not applicable to Azure Disk Backup, which requires a Backup vault.","`(Action 5)` Delegate permissions for the vault is incorrect. Disk Backup uses managed identity and RBAC instead of manual permission delegation. You assign roles to the managed identity instead of explicitly delegating permissions."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-managed-disks"],"images":[],"topic":"identity","needsImage":false},{"id":"4-85","test":4,"number":85,"stem":["You have deployed Azure virtual machines across three different Azure regions.","In each region:","- There is one virtual network.","- Each virtual network contains multiple subnets.","- All virtual networks are connected using full-mesh VNet peering.","A user reports that they are unable to connect over TCP port 33000 from a virtual machine in one region to a virtual machine in another region.","Which two options can you use to investigate and troubleshoot this connectivity issue?"],"options":[{"text":"Azure Monitor Network Insights","correct":false},{"text":"IP flow verify","correct":true},{"text":"effective security rules","correct":false},{"text":"Azure Virtual Network Manager","correct":false},{"text":"Connection troubleshoot","correct":true}],"explanation":["`IP flow verify` is correct because it allows you to test whether traffic is allowed to or from a virtual machine based on NSG (Network Security Group) rules. It specifically helps in identifying whether a particular port (like 33000) is blocked or allowed, which is essential for troubleshooting connectivity between VMs.","`Connection troubleshoot` is correct because it helps diagnose issues with connectivity between two endpoints. It checks DNS resolution, network latency, and whether TCP connections (like on port 33000) can be established, making it ideal for this scenario involving cross-region VM communication.","`Azure Monitor Network Insights` is incorrect because it gives you a high-level view of the health and topology of your network resources, but it doesn't perform port-level diagnostics or simulate connection attempts.","`effective security rules` is incorrect because it shows the final set of NSG rules applied to a NIC or subnet but doesn't actively test whether a specific port is blocked or allowed. It's useful for analysis, but not direct diagnostics.","`Azure Virtual Network Manager` is incorrect because it's used for centralized network management and policy enforcement across VNets, not for diagnosing connectivity issues like blocked ports."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-ip-flow-verify-overview","https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-connectivity-overview"],"images":[],"topic":"network","needsImage":false},{"id":"4-86","test":4,"number":86,"stem":["You have an Azure subscription called Subscription1 that includes two virtual machines named VM1 and VM2, both running Windows Server 2016.","VM1 is protected with Azure Backup, configured to run daily backups without using the Azure Backup agent.","VM1 has been compromised by ransomware that encrypts data.","You need to restore data from the most recent backup of VM1.","To which of the following targets can you perform a file-level recovery for VM1?"],"options":[{"text":"VM1 only","correct":false},{"text":"VM1 or a new Azure virtual machine only","correct":false},{"text":"VM1 and VM2 only","correct":false},{"text":"A new Azure virtual machine only","correct":false},{"text":"Any Windows computer that has Internet connectivity","correct":true}],"explanation":["`Any Windows computer that has Internet connectivity` is the correct answer because Azure Backup supports file-level recovery from a VM backup even when the Azure Backup agent is not used. The recovery is performed by downloading and running a script provided by the portal, which mounts the backup snapshot as a virtual drive. This can be done on any supported Windows machine with internet access, allowing files to be copied to any desired location."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm","https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"],"images":[],"topic":"identity","needsImage":false},{"id":"4-87","test":4,"number":87,"stem":["You have an Azure subscription called Subscription1 that includes two virtual machines named VM1 and VM2, both running Windows Server 2016.","VM1 is protected with Azure Backup, configured to run daily backups without using the Azure Backup agent.","VM1 has been compromised by ransomware that encrypts data.","You need to restore data from the most recent backup of VM1.","To which location can you restore the backup?"],"options":[{"text":"VM1 only","correct":false},{"text":"VM1 or a new Azure virtual machine only","correct":true},{"text":"VM1 and VM2 only","correct":false},{"text":"Any Windows computer that has Internet connectivity","correct":false}],"explanation":["`VM1 or a new Azure virtual machine only` is the correct answer because when Azure Backup is used to back up a VM without using the Azure Backup agent, it performs a full image-level backup of the virtual machine. In the event of data loss (e.g., ransomware), the entire VM can be restored either to the original VM (VM1) or as a new Azure virtual machine from the latest recovery point. This method does not support file-level recovery to arbitrary machines unless the MARS agent is used, which is not applicable in this scenario.","`VM1 only` is incorrect because Azure Backup allows restoring the VM to a new VM as well, not just to the original one.","`VM1 and VM2 only` is incorrect because Azure Backup does not allow restoring a VM backup to a different existing VM like VM2. Restores are limited to the original VM or a new one.","`Any Windows computer that has Internet connectivity` is incorrect because that type of file-level restore is only supported when using the Azure Backup agent (MARS) or the System Center DPM/MABS, which is not being used in this scenario."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-arm-restore-vms","https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix-iaas","https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"],"images":[],"topic":"identity","needsImage":false},{"id":"4-88","test":4,"number":88,"stem":["You have an Azure subscription that contains the following resources:","You configure Azure Site Recovery to replicate VM1 from East US to West US.","You then initiate a test failover and choose VNET2 as the destination virtual network.","After the test failover completes, to which subnet in VNET2 will the test instance of VM1 be connected?"],"options":[{"text":"RecoverySubnetB","correct":false},{"text":"DemoSubnet1","correct":true},{"text":"TestSubnet1","correct":false},{"text":"RecoverySubnetA","correct":false}],"explanation":["`DemoSubnet1` is the correct answer because when performing a test failover in Azure Site Recovery and no matching subnet name exists in the target virtual network (VNET2), the test virtual machine is automatically connected to the first subnet in alphabetical order. In this case, the source subnet is `Subnet2`, which does not exist in VNET2. Among the available subnets in VNET2—DemoSubnet1, RecoverySubnetA, RecoverySubnetB, and TestSubnet1—the one that comes first alphabetically is DemoSubnet1, so the test VM is connected there.","`RecoverySubnetA` is incorrect because although it contains “Recovery” in the name, it comes after DemoSubnet1 alphabetically.","`RecoverySubnetB` is incorrect because it is not the first subnet in alphabetical order and does not match the source subnet name.","`TestSubnet1` is incorrect because ASR does not prioritize subnets based on naming conventions like “Test”. It only looks for an exact match or falls back to the first subnet in alphabetical order."],"references":["https://learn.microsoft.com/en-us/azure/site-recovery/azure-to-azure-network-mapping#specify-a-subnet"],"images":["assets/8b132af0d5d5b596.png"],"topic":"identity","needsImage":true},{"id":"5-1","test":5,"number":1,"stem":["You manage an Azure App Service application called PortalApp.","The development team plans to publish updates to PortalApp using Web Deploy. They must be able to authenticate using their Microsoft Entra ID accounts when deploying the application.","The solution must follow the principle of least privilege and avoid granting excessive permissions.","Which action should you take?"],"options":[{"text":"Grant the developers the Owner role on the web app.","correct":false},{"text":"Set up application-level FTPS credentials.","correct":false},{"text":"Configure user-specific FTPS credentials.","correct":false},{"text":"Assign the Website Contributor role to the developers.","correct":true}],"explanation":["`Assign the Website Contributor role to the developers` is the correct answer here. The Website Contributor role provides the necessary permissions to manage the web app, including deploying content, without giving the developers excessive privileges such as those granted by the Owner role. This ensures the solution follows the principle of least privilege.","`Grant the developers the Owner role on the web app` is incorrect because the Owner role gives full control over the resource, including the ability to delete or modify access permissions, which violates the principle of least privilege.","`Set up application-level FTPS credentials` is incorrect  because using app-level credentials does not involve using Microsoft Entra credentials and does not follow the principle of least privilege.","`Configure user-specific FTPS credentials` is incorrect  because this does not involve using Microsoft Entra credentials and provides too much access for just deploying content."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#website-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"5-2","test":5,"number":2,"stem":["You have an Azure subscription named Sub1 that includes several blob containers, as shown in the following table.","Name           In storage account         Contains blob**","-------         -------------------         ---------------","cont1            storage1                            blob1","cont2           storage1                            blob2","cont1            storage2                           blob3","Each container resides in a specific storage account and contains one blob.","The subscription includes two users named User1 and User2. Both users are assigned the Reader role at the Sub1 subscription scope.","You have defined a condition named `Condition1` with the following logic:","- The condition evaluates to true when the requested action is not a blob read operation","OR","- The container name equals cont1","You have also defined a second condition named `Condition2` with the following logic:","- The condition evaluates to true when the requested action is not a blob write operation","OR","- The blob path matches a pattern that contains the value 2","You then assign roles to the users:","- User1 is assigned the Storage Blob Data Reader role at the Sub1 scope with Condition1 applied.","- User2 is assigned the Storage Blob Data Owner role at the storage1 account scope with Condition2 applied.","True or False:","“User1 can read blob2.”"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 is assigned the Storage Blob Data Reader role at the Sub1 scope with Condition1, which restricts access to the blobs unless certain conditions are met. Condition1 specifies that User1 can only read blobs within containers named cont1. Since blob2 is in container cont2, User1 cannot read it due to the condition restricting access to containers named cont1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-overview","https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-3","test":5,"number":3,"stem":["You have an Azure subscription named Sub1 that includes several blob containers, as shown in the following table.","Name           In storage account         Contains blob**","-------         -------------------         ---------------","cont1            storage1                            blob1","cont2           storage1                            blob2","cont1            storage2                           blob3","Each container resides in a specific storage account and contains one blob.","The subscription includes two users named User1 and User2. Both users are assigned the Reader role at the Sub1 subscription scope.","You have defined a condition named `Condition1` with the following logic:","- The condition evaluates to true when the requested action is not a blob read operation","OR","- The container name equals cont1","You have also defined a second condition named `Condition2` with the following logic:","- The condition evaluates to true when the requested action is not a blob write operation","OR","- The blob path matches a pattern that contains the value 2","You then assign roles to the users:","- User1 is assigned the Storage Blob Data Reader role at the Sub1 scope with Condition1 applied.","- User2 is assigned the Storage Blob Data Owner role at the storage1 account scope with Condition2 applied.","True or False:","“User1 can read blob3.”"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because, based on the conditions set in Condition1, User1 is restricted from reading any blob outside of the cont1 container. Although blob3 is in a different container (cont1 in storage2), the condition will allow User1 to access it. The condition in Condition1 only allows User1 to read blobs from the cont1 container in any storage account in that subscription."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format"],"images":[],"topic":"identity","needsImage":false},{"id":"5-4","test":5,"number":4,"stem":["You have an Azure subscription named Sub1 that includes several blob containers, as shown in the following table.","Name           In storage account         Contains blob**","-------         -------------------         ---------------","cont1            storage1                            blob1","cont2           storage1                            blob2","cont1            storage2                           blob3","Each container resides in a specific storage account and contains one blob.","The subscription includes two users named User1 and User2. Both users are assigned the Reader role at the Sub1 subscription scope.","You have defined a condition named `Condition1` with the following logic:","- The condition evaluates to true when the requested action is not a blob read operation","OR","- The container name equals cont1","You have also defined a second condition named `Condition2` with the following logic:","- The condition evaluates to true when the requested action is not a blob write operation","OR","- The blob path matches a pattern that contains the value 2","You then assign roles to the users:","- User1 is assigned the Storage Blob Data Reader role at the Sub1 scope with Condition1 applied.","- User2 is assigned the Storage Blob Data Owner role at the storage1 account scope with Condition2 applied.","True or False:","“User2 can read blob1.”"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct. User2 is assigned the Storage Blob Data Owner role at the storage1 scope, which includes blob1 and grants permissions to read and write blob data, subject to Condition2.","Condition2 evaluates to true when either the requested action is not a blob write operation or the blob path contains the value `2`. Because reading blob1 is not a write operation, the first clause evaluates to true. Although blob1’s path does not contain `2`, the complete expression evaluates as `true OR false`, which is true.","Therefore, Condition2 permits the read operation, and User2 can read blob1. The blob-path requirement would only restrict write operations, because for a write operation the first clause would evaluate to false."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format"],"images":[],"topic":"identity","needsImage":false},{"id":"5-5","test":5,"number":5,"stem":["You have two Azure virtual machines as shown in the following table. Each virtual machine runs a different operating system, has both private and public IP addresses assigned, and is connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not.","You then create the following Azure DNS resources:","- A public DNS zone named contoso.com","- A private DNS zone named fabrikam.com","You perform the following actions:","- For fabrikam.com, you create a virtual network link to vnet1 and enable automatic registration.","- For contoso.com, you assign the Owner role to both vm1 and vm2.","True of False:","“The DNS A record for vm1 is created in contoso.com and resolves to the IP address 131.107.50.20.”"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the contoso.com zone is a public DNS zone, not a private DNS zone. Auto registration for DNS records is supported only for private DNS zones when linked to virtual networks. Since contoso.com is a public DNS zone and auto registration is not enabled for public zones, a DNS A record for vm1 will not be automatically added with its public IP address of 131.107.50.20.","Additionally, the assignment of the Owner role to vm1 and vm2 does not influence DNS auto registration, as that pertains to role-based access control (RBAC) and not DNS management."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"],"images":["assets/2f774d2a72309e4f.png"],"topic":"identity","needsImage":true},{"id":"5-6","test":5,"number":6,"stem":["You have two Azure virtual machines as shown in the following table. Each virtual machine runs a different operating system, has both private and public IP addresses assigned, and is connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not.","You then create the following Azure DNS resources:","- A public DNS zone named contoso.com","- A private DNS zone named fabrikam.com","You perform the following actions:","- For fabrikam.com, you create a virtual network link to vnet1 and enable automatic registration.","- For contoso.com, you assign the Owner role to both vm1 and vm2.","True of False:","“The DNS A record for vm1 is created in fabrikam.com and resolves to the IP address 10.0.1.4.”"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because fabrikam.com is a private DNS zone, and since auto-registration is enabled for vnet1, the private IP address (10.0.1.4) of vm1 will be automatically added as an A record to the fabrikam.com private DNS zone. Auto-registration is supported for private DNS zones, and linking the virtual network ensures that virtual machines connected to the network can have their private IP addresses automatically registered in the private DNS zone."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"],"images":["assets/2f774d2a72309e4f.png"],"topic":"identity","needsImage":true},{"id":"5-7","test":5,"number":7,"stem":["You have two Azure virtual machines as shown in the following table. Each virtual machine runs a different operating system, has both private and public IP addresses assigned, and is connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not.","You then create the following Azure DNS resources:","- A public DNS zone named contoso.com","- A private DNS zone named fabrikam.com","You perform the following actions:","- For fabrikam.com, you create a virtual network link to vnet1 and enable automatic registration.","- For contoso.com, you assign the Owner role to both vm1 and vm2.","True of False:","“The DNS A record for vm2 is created in fabrikam.com and resolves to the IP address 10.0.1.5.”"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because fabrikam.com is an Azure Private DNS zone that is linked to vnet1 with automatic registration enabled. When automatic registration is enabled, Azure automatically creates DNS A records for all virtual machines connected to the linked virtual network.","vm2 is connected to vnet1 and has a private IP address of 10.0.1.5, so Azure automatically registers an A record for vm2.fabrikam.com that resolves to the private IP address.","The operating system type of vm2 and the absence of a DNS suffix configured inside the operating system do not affect Azure Private DNS auto-registration, as the registration is handled by the Azure platform.","The public DNS zone contoso.com and the assignment of the Owner role to the virtual machines are not relevant to Private DNS auto-registration and do not influence the creation of records in the fabrikam.com private DNS zone."],"references":["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"],"images":["assets/2f774d2a72309e4f.png"],"topic":"identity","needsImage":true},{"id":"5-8","test":5,"number":8,"stem":["You have two Azure subscriptions named Sub1 and Sub2. Sub1 is in a management group named MG1. Sub2 is in a management group named MG2.","The following resource groups exist in the subscriptions:","Name      Subscription","**------      --------------","RG1          Sub1","RG2         Sub2**","The following virtual machines are deployed:","Name      Resource group","**------      --------------","VM1          RG1","VM2         RG2","VM3         RG2**","You assign roles to users as shown in the following table.","Name      Role                                                Resource","**------      -----------------------------      ----------","User1      Virtual Machine Contributor      MG1**","User1      Virtual Machine User Login       Sub2","User2     Virtual Machine Contributor      MG2","User2     Virtual Machine User Login       Sub1","User2     Virtual Machine User Login       VM3","True of False:","`\"User1 can sign in to VM1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 does not have the \"Virtual Machine User Login\" role assigned for VM1 or at the scope of Sub1. While User1 has the \"Virtual Machine Contributor\" role for management group MG1, which includes Sub1, the \"Virtual Machine Contributor\" role alone does not grant login permissions. The \"Virtual Machine User Login\" role is required to allow the user to sign in to the virtual machine, and this role is not assigned to User1 for VM1, Sub1, or RG1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-9","test":5,"number":9,"stem":["You have two Azure subscriptions named Sub1 and Sub2. Sub1 is in a management group named MG1. Sub2 is in a management group named MG2.","The following resource groups exist in the subscriptions:","Name      Subscription","**------      --------------","RG1          Sub1","RG2         Sub2**","The following virtual machines are deployed:","Name      Resource group","**------      --------------","VM1          RG1","VM2         RG2","VM3         RG2**","You assign roles to users as shown in the following table.","Name      Role                                                Resource","**------      -----------------------------      ----------","User1      Virtual Machine Contributor      MG1**","User1      Virtual Machine User Login       Sub2","User2     Virtual Machine Contributor      MG2","User2     Virtual Machine User Login       Sub1","User2     Virtual Machine User Login       VM3","True of False:","`\"User2 has the ability to administer the disks and disk snapshots associated with VM1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User2 has the \"Virtual Machine Contributor\" role assigned to management group MG2, which includes Sub2, but VM1 is located in Sub1. Therefore, User2 does not have the necessary permissions to manage the disks or disk snapshots for VM1. The \"Virtual Machine Contributor\" role assigned at MG2 does not apply to resources in Sub1, including VM1. As a result, User2 cannot manage disks or snapshots of VM1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-10","test":5,"number":10,"stem":["You have two Azure subscriptions named Sub1 and Sub2. Sub1 is in a management group named MG1. Sub2 is in a management group named MG2.","The following resource groups exist in the subscriptions:","Name      Subscription","**------      --------------","RG1          Sub1","RG2         Sub2**","The following virtual machines are deployed:","Name      Resource group","**------      --------------","VM1          RG1","VM2         RG2","VM3         RG2**","You assign roles to users as shown in the following table.","Name      Role                                                Resource","**------      -----------------------------      ----------","User1      Virtual Machine Contributor      MG1**","User1      Virtual Machine User Login       Sub2","User2     Virtual Machine Contributor      MG2","User2     Virtual Machine User Login       Sub1","User2     Virtual Machine User Login       VM3","True of False:","`\"User2 has the ability to administer the disks and disk snapshots associated with VM3.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the \"Virtual Machine Contributor\" role allows users to manage virtual machines and attached disks but does not grant permissions to manage disk snapshots. Managing disk snapshots requires specific permissions, such as those granted by the \"Disk Snapshot Contributor\" role. Since User2 only has the \"Virtual Machine Contributor\" role, they can manage disks but cannot manage snapshots for VM3."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-11","test":5,"number":11,"stem":["You manage an Azure Storage account named dataarchive01, which contains a blob container called images. This container holds a a large collection of image files.","You plan to deploy an Azure Resource Manager (ARM) template to configure a blob inventory rule named inventoryRule1.","The configuration must ensure that a daily inventory report is generated in CSV format and stored in the images container. The report must include only those blobs whose names start with the prefix “finance”.","You need to complete the configuration of rule1, shown below.","Which value should you choose for Code Segment A?"],"options":[{"text":"appendBlob","correct":false},{"text":"blockBlob","correct":true},{"text":"pageBlob","correct":false}],"explanation":["`blockBlob` is the correct answer. Block blobs are designed to store large amounts of unstructured data, such as images or backups, which is the use case described here with thousands of image files. Additionally, block blobs are more suitable for use cases where data needs to be frequently accessed, stored, or replaced (such as in a daily CSV file). This fits the requirements for the blob inventory rule where you need to filter blobs whose names start with \"finance.\"","`appendBlob` is incorrect because it is generally used for log data where the need is to continuously append new data. It is not optimized for image storage or daily CSV storage.","`pageBlob` is incorrect because page blobs are typically used for storing virtual hard disks (VHDs) for Azure virtual machines, not for storing images or daily CSV files."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction","https://learn.microsoft.com/en-us/rest/api/storageservices/understanding-block-blobs--append-blobs--and-page-blobs"],"images":["assets/d18fc1821560c345.png"],"topic":"storage","needsImage":true},{"id":"5-12","test":5,"number":12,"stem":["You manage an Azure Storage account named dataarchive01, which contains a blob container called images. This container holds a a large collection of image files.","You plan to deploy an Azure Resource Manager (ARM) template to configure a blob inventory rule named inventoryRule1.","The configuration must ensure that a daily inventory report is generated in CSV format and stored in the images container. The report must include only those blobs whose names start with the prefix “finance”.","You need to complete the configuration of rule1, shown below.","Which value should you choose for Code Segment B?"],"options":[{"text":"images/*","correct":false},{"text":"images/finance","correct":true},{"text":"finance","correct":false}],"explanation":["`images/finance` is the correct answer. According to the documentation, the prefix match string in a blob policy must always start with the container name followed by the desired blob name prefix. In this case, \"images\" is the container, and \"finance\" is the required blob prefix, making images/finance the appropriate match string for blobs starting with the word \"finance.\"","`images/*` is incorrect because it would match all blobs within the container and not only those starting with \"finance.\"","`finance` is incorrect because it does not include the container name as required by the blob policy format."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blob-faq#the-blob-prefix-match-string-didn-t-apply-the-policy-to-the-expected-blobs"],"images":["assets/d18fc1821560c345.png"],"topic":"storage","needsImage":true},{"id":"5-13","test":5,"number":13,"stem":["You manage an Azure Storage account called mediafiles01 that contains a collection of image blobs.","You plan to provision an additional storage account and configure object replication to copy the existing images from mediafiles01 to the new account.","After creating and configuring the destination storage account, you need to determine the appropriate object type that must be created within it to support object replication.","Which object type should you create in the destination storage account?"],"options":[{"text":"Container","correct":true},{"text":"File share","correct":false},{"text":"Table","correct":false},{"text":"Queue","correct":false}],"explanation":["`Container` is the correct answer here. Azure Object Replication is a feature of Azure Blob Storage, and it works at the container level. To replicate blobs from one storage account to another, you must configure object replication policies between source and destination containers. This means that in the new storage account, you must create a container, as it's the fundamental object that holds blobs (such as images in this case). Without a container, the replication policy cannot be configured or function.","`File share` is incorrect because object replication does not support Azure Files. File shares are used in Azure Files, which is a completely separate service from Blob Storage, and is not part of object replication capabilities.","`Table` is incorrect because Azure Table storage is used for NoSQL structured data, and again, object replication only applies to block blobs in containers, not table data.","`Queue` is incorrect because Azure Queue Storage is designed for messaging between application components. It is not related to blob storage or object replication and cannot be used for replicating blob data."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-overview","https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-configure?tabs=portal","https://learn.microsoft.com/en-us/azure/storage/queues/storage-queues-introduction","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction","https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"],"images":[],"topic":"storage","needsImage":false},{"id":"5-14","test":5,"number":14,"stem":["You manage an Azure Storage account called mediafiles01 that contains a collection of image blobs.","You plan to provision an additional storage account and configure object replication to copy the existing images from mediafiles01 to the new account.","After creating and configuring the destination storage account, you need to determine the appropriate object type that must be created within it to support object replication.","Which account type should you create in the destination storage account?"],"options":[{"text":"StorageV2 only","correct":false},{"text":"StorageV2 or FileStorage only","correct":false},{"text":"StorageV2 or BlobStorage only","correct":true},{"text":"StorageV2, BlobStorage, or FileStorage","correct":false}],"explanation":["`StorageV2 or BlobStorage only` is correct because object replication is supported by both general-purpose v2 storage accounts (StorageV2) and premium block blob storage accounts (BlobStorage). These account types meet the requirements for object replication, allowing replication of blobs between the source and destination accounts.","`StorageV2 only` is incorrect because while StorageV2 supports object replication, premium block blob storage accounts (BlobStorage) also support object replication, and they should not be excluded from the correct answer.","`StorageV2 or FileStorage only `and `StorageV2, BlobStorage, or FileStorage` are incorrect because FileStorage accounts do not support blob storage, which is necessary for object replication."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-overview"],"images":[],"topic":"storage","needsImage":false},{"id":"5-15","test":5,"number":15,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage.","When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error.","You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry.","Proposed solution: `Configure a private endpoint for corpRegistry.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because while a private endpoint connection allows secure access to the container registry over a private network, it does not resolve all potential issues with deploying a container instance. The error might be related to permissions, image availability, or networking configuration rather than the absence of a private endpoint. Other issues like missing Azure Container Instance permissions, registry access policies, or image tags could prevent deployment.","A more appropriate solution would be ensuring that the container instance has the proper permissions to pull images from the registry. This can be done by checking if the container instance has the necessary identities (system-assigned or user-assigned) and permissions to access the container registry."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"],"images":[],"topic":"network","needsImage":false},{"id":"5-16","test":5,"number":16,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage.","When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error.","You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry.","Proposed solution: `Enable the Use dedicated data endpoint setting for corpRegistry.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because selecting \"Use dedicated data endpoint\" for Registry1 is primarily used to isolate data plane traffic from management plane traffic in a container registry. While it improves network security and performance, it does not directly address issues related to deploying a container instance using an image. The error message could be caused by other factors, such as missing permissions, improper image tags, or incorrect access configurations for the Azure Container Instance. Using a dedicated data endpoint does not resolve these issues.","A more suitable solution would involve verifying the necessary access permissions and configurations to ensure the container instance can pull the image from the registry."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"],"images":[],"topic":"compute","needsImage":false},{"id":"5-17","test":5,"number":17,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage.","When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error.","You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry.","Proposed solution: `You assign the AcrPull role to ACR-Tasks-Network for Registry1.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because assigning the AcrPull role to ACR-Tasks-Network does not resolve the error when deploying a container instance. The AcrPull role allows a service or identity to pull images from the container registry, but ACR-Tasks-Network is typically used for managing tasks within the Azure Container Registry (ACR). This role is unrelated to the container instance’s ability to pull images from the registry. The container instance itself or the identity running the container instance should have the AcrPull role assigned for successful image deployment.","A better solution would involve assigning the AcrPull role to the identity or service principal running the container instance, ensuring it has permission to pull images from the registry."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-roles?tabs=azure-cli","https://learn.microsoft.com/en-us/azure/container-instances/container-instances-managed-identity"],"images":[],"topic":"identity","needsImage":false},{"id":"5-18","test":5,"number":18,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage.","When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error.","You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry.","Proposed solution: `You set Admin user to Enable for corpRegistry.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because enabling the Admin user on the Azure container registry provides credentials (username and password) that can be used to authenticate and pull images from the registry. This can resolve authentication issues when deploying a container instance, as the container instance can use the admin credentials to access the registry and pull image1. This is a quick solution to grant access, especially when other identity-based methods, such as Microsoft Entra, are not configured."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication?tabs=azure-cli","https://learn.microsoft.com/en-us/azure/container-instances/container-instances-using-azure-container-registry"],"images":[],"topic":"compute","needsImage":false},{"id":"5-19","test":5,"number":19,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Storage account named datastore01.","A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary.","Proposed solution: `Assign the Storage Account Encryption Scope Contributor role to UserA at the scope of datastore01.`","Does this solution achieve the objective?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the Storage Account Encryption Scope Contributor role does not grant permissions to list or regenerate storage account keys. To enable a user to list and regenerate storage account keys, the user needs to have the Storage Account Key Operator Service Role or Storage Account Contributor role. These roles specifically allow the management of storage account keys, which is not covered by the Storage Account Encryption Scope Contributor role."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-20","test":5,"number":20,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Storage account named datastore01.","A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary.","Proposed solution: `You assign the Storage Account Key Operator Service Role to UserA.`","Does this solution achieve the objective?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because the Storage Account Key Operator Service Role grants the necessary permissions to list and regenerate storage account keys without providing broader access to the storage account's data. This role is specifically designed for key management tasks, allowing the user to perform actions related to storage account keys.","Assigning this role to UserA will enable them to list and regenerate the keys for storage1 as required."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-key-operator-service-role","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"5-21","test":5,"number":21,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Storage account named datastore01.","A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary.","Proposed solution: `You assign the Storage Account Contributor role to UserA.`","Does this solution achieve the objective?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is correct because the Storage Account Contributor role provides the necessary permissions to manage storage accounts, including listing and regenerating storage account keys. This role covers both the management of the storage account itself and the associated keys, which meets the requirement stated in the scenario."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-22","test":5,"number":22,"stem":["**Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure Storage account named datastore01.","A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary.","Proposed solution: `You assign the Reader and Data Access role to UserA.`","Does this solution achieve the objective?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the Reader and Data Access role allows a user to view storage account data and metadata but does not provide the necessary permissions to list or regenerate storage account keys. To achieve the goal of allowing UserA to list and regenerate storage account keys, the appropriate role would be the Storage Account Key Operator Service Role or a more privileged role like Contributor.","The Reader and Data Access role is insufficient for key management tasks."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-key-operator-service-role"],"images":[],"topic":"identity","needsImage":false},{"id":"5-23","test":5,"number":23,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `From the ProdVM01 Updates blade, select One-time update.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct because the One-time update option applies maintenance updates to the virtual machine, but it doesn't guarantee moving the VM to a new host to avoid impending maintenance.","To immediately move the VM to a different host, you would need to Redeploy the virtual machine, which moves it to a new host within the same region."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-configurations"],"images":[],"topic":"compute","needsImage":false},{"id":"5-24","test":5,"number":24,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `From the Overview blade, move ProdVM01 to another subscription`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is correct. The Overview blade provides the details of the VM. Moving a VM to another subscription is a logical change and does not affect the underlying physical infrastructure. To move VM1 to a different host to avoid maintenance impacts, you should redeploy the VM instead."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-configurations","https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription"],"images":[],"topic":"identity","needsImage":false},{"id":"5-25","test":5,"number":25,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `Move the VM to a different resource group from the Overview balde.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. Moving a virtual machine to a different resource group does not change the physical host on which the VM is running. The operation is a metadata-level move within Azure Resource Manager, and the underlying compute resources (including the physical host) remain unchanged.","Since the goal is to move ProdVM01 to a different host immediately (e.g., to avoid upcoming planned maintenance), simply moving the VM to a different resource group does not meet the requirement.","To move a VM to a different host, you must perform an operation that redeploys the VM, such as using the Redeploy option from the Azure portal or running the `az vm redeploy` command. This action will provision the VM on a new physical host.","Reference(s.):","- https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"5-26","test":5,"number":26,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `From the Updates blade, you click Enable.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. Clicking Enable from the Updates blade typically refers to enabling automatic VM guest patching or maintenance control features, depending on the context. However, this action does not immediately move the VM to a different host.","The goal is to move ProdVM01 to a different physical host immediately to avoid potential impact from scheduled maintenance. The correct action to achieve that is to use the Redeploy option, which reprovisions the virtual machine onto a new physical host in the same region.","Reference(s.):","- https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"5-27","test":5,"number":27,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `From the ProdVM01 Redeploy + reapply blade, you click Redeploy.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":true},{"text":"No","correct":false}],"explanation":["`Yes` is the correct answer here. Clicking Redeploy from the Redeploy + reapply blade of ProdVM01 moves the virtual machine to a new physical host within the same Azure region. This operation is specifically designed to address issues related to the underlying host, including planned maintenance, host failures, or performance degradation.","When you redeploy a VM:","- The OS and data disks are preserved.","- The VM is moved to a different host.","- The public IP (if static) and other configurations remain unchanged.","Reference(s.):","- https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"5-28","test":5,"number":28,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You manage an Azure virtual machine named ProdVM01, which was deployed using a custom Azure Resource Manager template called deployVM.json.","You receive an alert stating that ProdVM01 will be affected by a scheduled platform maintenance event.","You must immediately relocate ProdVM01 to another host to avoid the upcoming maintenance impact.","Proposed solution: `Move ProdVM01 to another resource group from the RG blade.`","Does this solution meet the requirement?"],"options":[{"text":"Yes","correct":false},{"text":"No","correct":true}],"explanation":["`No` is the correct answer here. Moving ProdVM01 to another resource group from the resource group blade is a logical metadata move within Azure Resource Manager. It does not involve changing the physical host on which the virtual machine runs. The VM’s underlying infrastructure—including the compute host—remains the same.","Since the goal is to move ProdVM01 to a different host immediately (to avoid disruption due to planned maintenance), this solution does not meet the requirement. The correct action would be to redeploy the virtual machine using the Redeploy option, which moves the VM to a new physical host.","Reference(s.):","- https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"],"references":[],"images":[],"topic":"compute","needsImage":false},{"id":"5-29","test":5,"number":29,"stem":["You have an Azure subscription that uses Azure Container Instances.","You are working on a computer where the Azure Command-Line Interface (CLI) and Docker are installed.","You build a container image named image1.","You need to create a new Azure container registry and then push image1 to that registry.","Which command should you run to create a new container registry?"],"options":[{"text":"az acr build","correct":false},{"text":"az acr create","correct":true},{"text":"az container create","correct":false},{"text":"docker create","correct":false}],"explanation":["`az acr create` is the correct answer here. This command is used to create a new Azure Container Registry (ACR). Once the container registry is created, you can push your container images (such as image1) to the registry. This satisfies the requirement of provisioning a new Azure Container Registry.","`az acr build` is incorrect because this command is used to build and push a Docker container image to an Azure Container Registry, but it does not provision the registry itself.","`az container create` is incorrect because this command is used to create a container instance, not a container registry.","`docker create` is incorrect because this Docker command is used to create a new container from an image on your local machine, not to provision a container registry in Azure."],"references":["https://learn.microsoft.com/en-us/cli/azure/acr?view=azure-cli-latest"],"images":[],"topic":"identity","needsImage":false},{"id":"5-30","test":5,"number":30,"stem":["You have an Azure subscription that uses Azure Container Instances.","You are working on a computer where the Azure Command-Line Interface (CLI) and Docker are installed.","You build a container image named image1.","You need to create a new Azure container registry and then push image1 to that registry.","Which command should you run to add image1 to the registry?"],"options":[{"text":"az acr create","correct":false},{"text":"az container create","correct":false},{"text":"docker pull","correct":false},{"text":"docker push","correct":true}],"explanation":["`docker push` is the correct answer here. This command is used to upload (push) your locally built Docker container image, such as image1, to a container registry. Once the Azure Container Registry has been created, you use the docker push command to push the image to the registry.","`az acr create` is incorrect because this command is used to create a new Azure Container Registry, not to upload an image.","`az container create` is incorrect because this command is used to create a container instance in Azure, not to push an image to a registry.","`docker pull` is incorrect because this command is used to download (pull) an image from a registry, not to upload (push) an image."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-docker-cli?tabs=azure-cli","https://docs.docker.com/reference/cli/docker/image/push/"],"images":[],"topic":"identity","needsImage":false},{"id":"5-31","test":5,"number":31,"stem":["An Azure subscription includes a container group named Group1. The container group hosts two Azure container instances, as detailed in the following table.","Each container has defined CPU resource requests and limits.","You must ensure that each container cannot consume more CPU resources than it requests, and that cont2 does not negatively affect cont1.","What action should you take?"],"options":[{"text":"Increase the CPU resource limit for cont1 to three CPUs.","correct":false},{"text":"Increase the CPU resource limit of cont2 to six CPUs.","correct":false},{"text":"Remove the CPU resource limits configured on both containers.","correct":true},{"text":"Reduce the CPU resource limit of cont2 to two CPUs.","correct":false}],"explanation":["`Remove the CPU resource limits configured on both containers` is the correct answer. Azure Container Instances allocates CPU resources to a container group based on the sum of the containers’ resource requests. If no resource limit is specified for a container, its maximum CPU usage is equal to its resource request. Therefore, after removing the limits, cont1 cannot use more than its requested 2 CPUs, and cont2 cannot use more than its requested 3 CPUs. This ensures that neither container can consume CPU resources beyond its request and that cont2 cannot use additional shared CPU resources at the expense of cont1.","`Reduce the CPU resource limit of cont2 to two CPUs` is incorrect because a container’s resource limit must be equal to or greater than its resource request. Since cont2 requests 3 CPUs, its limit cannot be reduced to 2 CPUs.","`Increase the CPU resource limit of cont2 to six CPUs` is incorrect because a container’s resource limit cannot exceed the total CPU resources allocated to the container group. The group is allocated 5 CPUs based on the combined requests of cont1 and cont2. Increasing cont2’s limit would also work against the requirement to prevent it from consuming more CPU than it requests.","`Increase the CPU resource limit for cont1 to three CPUs` is incorrect because this would allow cont1 to consume more CPU than its requested 2 CPUs. It would not ensure that each container is restricted to its resource request and could increase resource contention within the group."],"references":["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-container-groups"],"images":["assets/dc3a24a104afcf8d.png"],"topic":"identity","needsImage":true},{"id":"5-32","test":5,"number":32,"stem":["You are managing a tenant in Microsoft Entra.","You want to ensure that whenever a new Microsoft 365 group is created, the group name automatically follows this format:","<Department><Group name>","Which three actions must you carry out, in the correct order, from the Microsoft Entra admin center to achieve this configuration?","ACTIONS","- Set Add suffix to Attribute.","- Create a group naming policy.","- Set Add prefix to Attribute.","- Set Add suffix to String.","- Set Add prefix to String.","- Set Select type to Department.","- Customize the company branding."],"options":[{"text":"2-6-3","correct":false},{"text":"2-3-6","correct":true},{"text":"3-2-6","correct":false},{"text":"6-3-2","correct":false}],"explanation":["`2-3-6` is the correct sequence of actions.","`(Action 2) Create a group naming policy`: You need to create a group naming policy in the Microsoft Entra admin center to enforce a specific naming convention.","`(Action 3) Set Add prefix to Attribute`: In the group naming policy, set Add prefix to Attribute and choose Department as the attribute. This ensures that the department name is added as a prefix to the group name.","`(Action 6) Set Select type to Department`: Finally, ensure that you set Select type to Department to specify that the department attribute should be used when creating the group name."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/groups-naming-policy"],"images":[],"topic":"identity","needsImage":false},{"id":"5-33","test":5,"number":33,"stem":["You have a Microsoft Entra tenant that is linked to the subscriptions shown in the following table.","You have the resource groups shown in the following table.","You assign roles to users as shown in the following table.","True or False:","`\"User1 can resize ProdVM01.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User1 has the Contributor role assigned at the Corp-MG2 management group level, which includes SubC. Since SubC contains RG-Compute, and RG-Compute has ProdVM01, the Contributor role grants User1 full management rights over all resources within this scope. The Contributor role allows actions such as resizing virtual machines, making User1 capable of resizing ProdVM01."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/governance/management-groups/overview"],"images":["assets/d3546c355e674ded.png","assets/c9bdf1556f194b04.png","assets/bbaee92db899eca3.png"],"topic":"identity","needsImage":true},{"id":"5-34","test":5,"number":34,"stem":["You have a Microsoft Entra tenant that is linked to the subscriptions shown in the following table.","You have the resource groups shown in the following table.","You assign roles to users as shown in the following table.","True or False:","`\"User2 can create a new storage account in RG-Storage.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User2 has the Storage Account Contributor role assigned specifically to dataStore1, not to the entire resource group (RG-Storage). The Storage Account Contributor role allows User2 to manage the specific storage account (dataStore1) but does not provide the ability to create new storage accounts or manage other resources within RG-Storage."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor"],"images":["assets/71ba28e6c985d098.png","assets/c9bdf1556f194b04.png","assets/bbaee92db899eca3.png"],"topic":"identity","needsImage":true},{"id":"5-35","test":5,"number":35,"stem":["You have a Microsoft Entra tenant that is linked to the subscriptions shown in the following table.","You have the resource groups shown in the following table.","You assign roles to users as shown in the following table.","True or False:","`\"User3 can assign User1 the Owner role for RG-Compute.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User3 has the User Access Administrator role assigned at the Tenant Root Group scope. This role allows User3 to manage access and assign roles at any level within the tenant, including management groups, subscriptions, and resource groups. Since RG-Compute is within the tenant, User3 can assign roles such as the Owner role to User1 for RG-Compute."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator","https://learn.microsoft.com/en-us/azure/governance/management-groups"],"images":["assets/71ba28e6c985d098.png","assets/c9bdf1556f194b04.png","assets/bbaee92db899eca3.png"],"topic":"identity","needsImage":true},{"id":"5-36","test":5,"number":36,"stem":["An Azure subscription contains two backup-related services:","- An Azure Backup vault named VaultA","- A Recovery Services vault named VaultB","The subscription includes the following deployed resources:","- VM01 - Virtual machine","- Disk01 - Disk","- WebApp01 - Azure App Service web application","- SQLDB01 - Azure SQL Database","You plan to configure backup protection for these resources.","Which of the listed resources can be backed up using VaultA (the Azure Backup vault)?"],"options":[{"text":"WebApp01","correct":false},{"text":"SQLDB01","correct":false},{"text":"Disk01","correct":true},{"text":"VM01","correct":false}],"explanation":["`Disk01` is correct because Azure managed disks are backed up using Azure Disk Backup, which requires an Azure Backup vault. This allows disks to be backed up independently without backing up the entire virtual machine.","`VM01` could also be backed up, but the backup would include the entire virtual machine, not just the disk. The question specifically focuses on backing up a resource like Disk1.","`WebApp01` (Azure App Service web app) and `SQLDB01` (Azure SQL Database) have different built-in backup features and are not backed up directly using Azure Backup."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-37","test":5,"number":37,"stem":["An Azure subscription contains two backup-related services:","- An Azure Backup vault named VaultA","- A Recovery Services vault named VaultB","The subscription includes the following deployed resources:","- VM01 - Virtual machine","- Disk01 - Disk","- WebApp01 - Azure App Service web application","- SQLDB01 - Azure SQL Database","You plan to configure backup protection for these resources.","Which of the listed resources can be backed up using VaultB (the Recovery Services vault)?"],"options":[{"text":"WebApp01","correct":false},{"text":"SQLDB01","correct":false},{"text":"Disk01","correct":false},{"text":"VM01","correct":true}],"explanation":["`VM01` is the correct answer because a Recovery Services vault (like VaultB) is used to back up entire virtual machines (VMs) in Azure. Azure Backup supports backing up the operating system, data disks, and attached resources of the VM using a Recovery Services vault.","`Disk01`: While individual disks can be backed up as part of a VM backup, they are not directly backed up independently to a Recovery Services vault.","`WebApp01` (Azure App Service web app) and `SQLDB01` (Azure SQL Database) are not backed up using Azure Backup through a Recovery Services vault. They have their own specific backup mechanisms."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-overview","https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix"],"images":[],"topic":"identity","needsImage":false},{"id":"5-38","test":5,"number":38,"stem":["You have a Microsoft Entra tenant with the following characteristics:","- Tenant name: Default Directory","- License type: Microsoft Entra ID Free","- Primary domain: an onmicrosoft.com domain","The tenant includes these identities:","- UserA - User account","- SecGroup01 - Security group","- M365Group01 - Microsoft 365 group","You purchase a Microsoft Fabric license.","Which of the listed identities can be assigned the Microsoft Fabric license?"],"options":[{"text":"UserA only","correct":true},{"text":"UserA and SecGroup01 only","correct":false},{"text":"UserA and M365Group01 only","correct":false},{"text":"UserA, SecGroup01, and M365Group01","correct":false}],"explanation":["`UserA only` is correct because in a free Microsoft Entra ID tenant, you can only assign licenses to individual users like UserA. Group-based licensing (for SecGroup01 or M365Group01) requires a paid version of Microsoft Entra ID (such as P1 or P2).","`UserA and SecGroup01 only` is incorrect because, in the free version, SecGroup01 (a security group) cannot be assigned licenses.","`UserA and M365Group01 only` is incorrect for the same reason. Group-based licensing (whether it's a security group or a Microsoft 365 group) is not supported in the free tier.","`UserA, SecGroup01, and M365Group01` is incorrect since neither SecGroup01 nor M365Group01 can have licenses assigned in the free tenant."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing"],"images":[],"topic":"identity","needsImage":false},{"id":"5-39","test":5,"number":39,"stem":["You have an Azure subscription that includes the following Microsoft Entra identities:","- UserA - A User","- SecGroup01 -  A Security group","- M365Group01 - A Microsoft 365 group","You plan to enable Self-Service Password Reset (SSPR) using the Azure portal.","For which of the listed identities can SSPR be enabled?"],"options":[{"text":"UserA only","correct":false},{"text":"SecGroup01 only","correct":false},{"text":"UserA and SecGroup01 only","correct":false},{"text":"SecGroup01 and M365Group01 only","correct":true},{"text":"UserA, SecGroup01, and M365Group01","correct":false}],"explanation":["`SecGroup01 and M365Group01 only` is correct because SSPR can be directly assigned only to a group of users or to ALL users but not to individual users. The setting is then applicable on all the users in that group. You can select individual users in a group if you do not want to enable the setting for all the users in that group."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr"],"images":[],"topic":"identity","needsImage":false},{"id":"5-40","test":5,"number":40,"stem":["You have an Azure environment that includes two virtual networks, VNet1 and VNet2, which are configured with virtual network peering.","A Network Virtual Appliance named NetVA1 is deployed in the environment.","You must ensure that all network traffic flowing from VNet1 to VNet2 is routed through NetVA1 so that it can be inspected before reaching its destination.","Which option should you implement to meet this requirement?"],"options":[{"text":"Configure a local network gateway.","correct":false},{"text":"a route table that has custom routes","correct":true},{"text":"Enable a service endpoint.","correct":false},{"text":"Configure IP address reservations.","correct":false}],"explanation":["`A route table that has custom routes` is the correct answer here. To ensure that the traffic from VNet1 to VNet2 is inspected by NetVA1, you need to use a custom route in the route table. You can create a route that forces traffic from VNet1 to pass through the Network Virtual Appliance (NetVA1) for inspection before it reaches VNet2. This is achieved by setting the next hop in the custom route to the IP address of NetVA1.","`Configure a local network gateway` is incorrect because it is used for configuring connections between an Azure virtual network and an on-premises network, not for routing traffic between peered virtual networks.","`Enable a service endpoint` is incorrect because service endpoints provide secure access to Azure services but are not used for routing traffic through a Network Virtual Appliance.","`Configure IP address reservations` is incorrect because IP reservations are used to reserve public IP addresses, and they do not help with routing or traffic inspection between virtual networks."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview","https://learn.microsoft.com/en-us/azure/virtual-wan/scenario-route-through-nva"],"images":[],"topic":"network","needsImage":false},{"id":"5-41","test":5,"number":41,"stem":["An Azure subscription contains several resources distributed across two resource groups, as detailed in the table below. The resources include a container app and multiple Azure Key Vault instances deployed in different regions.","You intend to use an Azure Key Vault to securely supply a secret to containerApp01.","What should you create so that containerApp01 can authenticate and retrieve the secret from the key vault?"],"options":[{"text":"A Managed identity","correct":true},{"text":"A Private endpoint","correct":false},{"text":"A Service principal","correct":false},{"text":"A User account","correct":false}],"explanation":["`A Managed identity` is the correct answer. To securely provide a secret from an Azure Key Vault to containerApp01, you should create a managed identity for containerApp01. Managed identities allow Azure resources to securely access other Azure services (like Key Vault) without needing to manage credentials. Once the managed identity is created, it can be granted the necessary permissions to access the Key Vault and retrieve secrets.","`A Private endpoint` is incorrect because this is used for securing the network access to the Key Vault but does not handle authentication for accessing secrets.","`A Service principal` is incorrect because while service principals can be used to access resources, using a managed identity is a simpler and more secure method for Azure resources.","`A User account` is incorrect because user accounts are not typically used for resource-to-resource access in Azure."],"references":["https://learn.microsoft.com/en-us/azure/key-vault/general/assign-access-policy?tabs=azure-portal","https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"],"images":["assets/45be5c7bf275e896.png"],"topic":"identity","needsImage":true},{"id":"5-42","test":5,"number":42,"stem":["An Azure subscription contains several resources distributed across two resource groups, as detailed in the table below. The resources include a container app and multiple Azure Key Vault instances deployed in different regions.","You intend to use an Azure Key Vault to securely supply a secret to containerApp01.","Which Azure Key Vault can be used to supply the secret to containerApp01?"],"options":[{"text":"Vault1 only","correct":false},{"text":"Vault1 and Vault2 only","correct":false},{"text":"Vault1 and Vault3 only","correct":false},{"text":"Vault1, Vault2, or Vault3","correct":true}],"explanation":["`Vault1, Vault2, or Vault3` is correct because there are no Azure-imposed barriers that prevent containerApp01 from accessing Key Vaults located in different regions or resource groups. While it is generally recommended to use a Key Vault in the same region as the resource for performance and latency considerations, the question does not specify best practices, only whether the secret can be used. Therefore, containerApp01 can access all three Key Vaults—Vault1, Vault2, and Vault3—with appropriate permissions."],"references":["https://learn.microsoft.com/en-us/azure/key-vault/general/disaster-recovery-guidance","https://learn.microsoft.com/en-us/azure/key-vault/general/best-practices"],"images":["assets/45be5c7bf275e896.png"],"topic":"identity","needsImage":true},{"id":"5-43","test":5,"number":43,"stem":["You are working with an Azure subscription.","A user-defined route table named RT1 has been created.","You must add a route to RT1 that requires specifying an IP address for the next hop.","Which next hop option should you choose when configuring the route?"],"options":[{"text":"Internet","correct":false},{"text":"Virtual network gateway","correct":false},{"text":"Virtual network","correct":false},{"text":"Virtual appliance","correct":true}],"explanation":["`Virtual appliance` is the correct answer here. When adding a route to a routing table and specifying a next hop IP address, the correct next hop type is Virtual appliance. A virtual appliance refers to a Network Virtual Appliance (NVA), such as a firewall or load balancer, which inspects or processes network traffic. By choosing Virtual appliance, you can specify the IP address of the NVA that will handle the routed traffic.","`Internet` is incorrect because it routes traffic directly to the public internet without specifying a next hop IP address.","`Virtual network gateway` is incorrect because it is used to route traffic to an Azure VPN gateway for on-premises connectivity.","`Virtual network` is incorrect because it routes traffic within the same virtual network and does not require specifying a next hop IP address."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-44","test":5,"number":44,"stem":["You are planning to provision an Azure Storage account named storage1.","The storage account must satisfy the following conditions:","- It must be compatible with Azure Data Lake Storage capabilities.","- It should be optimized to reduce costs for data that is accessed infrequently.","- Data must be replicated automatically to another Azure region for resiliency.","Which three options should you configure for storage1?"],"options":[{"text":"geo-redundant storage (GRS)","correct":true},{"text":"hierarchical namespace","correct":true},{"text":"zone-redundant storage (ZRS)","correct":false},{"text":"the Hot access tier","correct":false},{"text":"the Cool tier","correct":true}],"explanation":["`geo-redundant storage (GRS)` is correct because the requirement states that data must automatically replicate to a secondary Azure region. GRS provides this replication capability, ensuring redundancy across regions.","`hierarchical namespace` is correct because enabling the hierarchical namespace is necessary to support Azure Data Lake Storage, which uses this feature to organize data in a directory-based structure.","`the Cool tier` is correct because the Cool access tier minimizes costs for infrequently accessed data. This is aligned with the requirement to reduce costs for such data usage scenarios.","`zone-redundant storage (ZRS)` is incorrect because ZRS replicates data only within a single region across availability zones and does not provide cross-region replication, which is a requirement in this scenario.","`the Hot access tier` is incorrect because the Hot tier is optimized for frequently accessed data, which would result in higher costs for infrequently accessed data, contradicting the requirement to minimize costs."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-account-options","https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"],"images":[],"topic":"storage","needsImage":false},{"id":"5-45","test":5,"number":45,"stem":["You have an Azure subscription named Subscription1 that includes a virtual network called VNet1.","The following users are assigned roles within the subscription:","- User1 is assigned the Owner role.","- User2 is assigned the Security Admin role.","- User3 is assigned the Network Contributor role.","You need to determine which user is permitted to carry out the following task:","“Create a new subnet within VNet1.”"],"options":[{"text":"User1 only","correct":false},{"text":"User3 only","correct":false},{"text":"User1 and User3 only","correct":true},{"text":"User2 and User3 only","correct":false},{"text":"User1, User2, and User3","correct":false}],"explanation":["`User1 and User3 only` is correct because the Owner role (User1) has full permissions, including managing resources and configurations like adding a subnet to VNet1. The Network Contributor role (User3) also has sufficient permissions to manage the network, which includes adding subnets.","`User2 and User3 only` is incorrect because although User3 (Network Contributor) has the required permissions, User2 with the Security Admin role does not have permissions to modify or add subnets in a virtual network.","`User1 only` is incorrect because User3 (Network Contributor) also has the required permissions to add a subnet.","`User1, User2, and User3` is incorrect because User2 (Security Admin) does not have permissions to manage network resources like subnets."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-46","test":5,"number":46,"stem":["You have an Azure subscription named Subscription1 that includes a virtual network called VNet1.","The following users are assigned roles within the subscription:","- User1 is assigned the Owner role.","- User2 is assigned the Security Admin role.","- User3 is assigned the Network Contributor role.","You need to determine which user is permitted to carry out the following task:","“Assign a user the Reader role to VNet1”"],"options":[{"text":"User1 only","correct":true},{"text":"User2 only","correct":false},{"text":"User3 only","correct":false},{"text":"User1 and User2 only","correct":false},{"text":"User2 and User3 only","correct":false},{"text":"User1, User2, and User3","correct":false}],"explanation":["`User1 only` is correct because the Owner role provides full access to manage the VNet and its access, including assigning roles such as the Reader role to VNet1. The Owner role allows complete control over the resource, including RBAC permissions.","`User2 only` is incorrect because the Security Admin role is focused on managing security-related policies and configurations but does not grant the ability to manage access to a VNet.","`User3 only` is incorrect because the Network Contributor role allows management of networking resources, such as creating or modifying VNets and subnets, but does not allow role assignments or access management for the VNet.","`User1 and User2 only` is incorrect because the Security Admin role does not include permissions to manage RBAC for the VNet.","`User2 and User3 only` is incorrect because neither the Security Admin nor the Network Contributor roles allow assigning roles to the VNet.","`User1, User2, and User3` is incorrect because only the Owner role (User1) has the necessary permissions to assign roles to VNet1."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"5-64","test":5,"number":64,"stem":["An Azure subscription contains a user named User1 along with the following resources:","- RG1, which is a resource group","- networkinterface1, which is a virtual network interface","- NSG1, which is a network security group","The network security group NSG1 is linked to networkinterface1.","User1 has been assigned the following roles related to NSG1:","- Contributor at the NSG1 resource scope","- Reader at the subscription scope (inherited)","- Storage Account Contributor at the resource group scope (inherited)","True of False:**","`\"User1 is able to create a storage account within RG1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because even though the question states that User1 has role assignments on NSG1, the Storage Account Contributor role is assigned at the Resource Group (RG1) level, as shown in the role assignments table. This means User1 inherits the permissions provided by that role for all resources within RG1.","The `Storage Account Contributor` role allows full management of storage accounts, including the ability to create them. Since this role is applied at the RG1 scope, User1 can create storage accounts anywhere within that resource group regardless of their other roles at narrower scopes like NSG1.","The mention of role assignments for NSG1 in the question context simply lists additional roles that User1 has, but those do not restrict or override the broader permissions granted at the resource group level. RBAC in Azure is additive by design, meaning User1’s permissions accumulate across scopes.","**Reference(s):","**https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal","https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-65","test":5,"number":65,"stem":["An Azure subscription contains a user named User1 along with the following resources:","- RG1, which is a resource group","- networkinterface1, which is a virtual network interface","- NSG1, which is a network security group","The network security group NSG1 is linked to networkinterface1.","User1 has been assigned the following roles related to NSG1:","- Contributor at the NSG1 resource scope","- Reader at the subscription scope (inherited)","- Storage Account Contributor at the resource group scope (inherited)","True of False:**","`\"User1 can modify the DNS settings of networkinterface1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 has the Contributor role assigned only at the NSG1 resource scope, not at the networkinterface1 scope. The Contributor role on NSG1 allows User1 to manage the Network Security Group (NSG1), but it does not extend permissions to manage or modify DNS settings of the associated network interface (networkinterface1).","Additionally, the Reader role at the Subscription level only grants read permissions and does not allow modification of resources. Similarly, the Storage Account Contributor role at the Resource Group (RG1) level is specific to storage accounts and does not provide permissions to modify network interface settings.","Therefore, User1 cannot modify the DNS settings of networkinterface1."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-66","test":5,"number":66,"stem":["An Azure subscription contains a user named User1 along with the following resources:","- RG1, which is a resource group","- networkinterface1, which is a virtual network interface","- NSG1, which is a network security group","The network security group NSG1 is linked to networkinterface1.","User1 has been assigned the following roles related to NSG1:","- Contributor at the NSG1 resource scope","- Reader at the subscription scope (inherited)","- Storage Account Contributor at the resource group scope (inherited)","True of False:**","`\"User1 can create an inbound security rule to filter inbound traffic to networkinterface1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User1 has the Contributor role explicitly assigned to NSG1 (Network Security Group). The Contributor role allows full management permissions over the NSG, including the ability to create, modify, and delete inbound and outbound security rules to control traffic flow.","Since NSG1 is associated with networkinterface1, any inbound security rules configured on NSG1 will apply to networkinterface1. Therefore, User1 has the required permissions to create an inbound security rule to filter inbound traffic to networkinterface1.","**Reference(s):","**https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/overview","https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-67","test":5,"number":67,"stem":["You configure the custom role shown below.","{","\"properties\": {","\"roleName\": \"role1\",","\"description\": \"\",","\"roleType\": \"true\",","\"assignableScopes\": [","\"/subscriptions/8f3a91c2-5b47-4d6e-9a21-7c8f0e3b4a6d/\"","],","\"permissions\": [","{","\"actions\": [","\"Microsoft.Authorization/*/read\",","\"Microsoft.Compute/availabilitySets/*\",","\"Microsoft.Compute/locations/*\",","\"Microsoft.Compute/virtualMachines/*\",","\"Microsoft.Compute/virtualMachineScaleSets/*\",","\"Microsoft.Compute/disks/write\",","\"Microsoft.Compute/disks/read\",","\"Microsoft.Compute/disks/delete\",","\"Microsoft.Network/locations/*\",","\"Microsoft.Network/networkInterfaces/*\",","\"Microsoft.Network/networkSecurityGroups/join/action\",","\"Microsoft.Network/networkSecurityGroups/read\",","\"Microsoft.Network/publicIPAddresses/join/action\",","\"Microsoft.Network/publicIPAddresses/read\",","\"Microsoft.Network/virtualNetworks/read\",","\"Microsoft.Network/virtualNetworks/subnets/join/action\",","\"Microsoft.Resources/deployments/*\",","\"Microsoft.Resources/subscriptions/resourceGroups/read\",","\"Microsoft.Support/*\"","],","\"notActions\": [],","\"dataActions\": [],","\"notDataActions\": []","}","]","}","}","Based on the information presented, select the answer choice that completes the following statement correctly.","“To ensure that users can sign in to virtual machines that are assigned role1, modify the _____________ section.”"],"options":[{"text":"actions","correct":false},{"text":"roletype","correct":false},{"text":"notActions","correct":false},{"text":"dataActions","correct":true},{"text":"notDataActions","correct":false},{"text":"assignableScopes","correct":false}],"explanation":["`dataActions` is the correct option because permissions like \"Microsoft.Compute/virtualMachines/login/action\" or \"Microsoft.Compute/virtualMachines/loginAsAdmin/action\" are categorized as data plane operations. These permissions determine access to the operational level of the virtual machine, such as signing in or interacting with its data, and should therefore be placed in the dataActions section.","`actions` is incorrect because this section controls management-level (control plane) operations, such as creating, updating, or deleting resources. Signing in to a virtual machine does not fall under this category.","`roletype` is incorrect because it specifies the type of role (e.g., built-in or custom) and does not influence permission assignments.","`notActions` is incorrect because it is used to exclude specific control plane operations from a role rather than granting access.","`notDataActions` is incorrect because it is used to exclude specific data plane operations, not to define permissions for logging into virtual machines.","`assignableScopes` is incorrect because this section only determines where the role can be assigned (e.g., subscription, resource group) and does not directly grant or restrict resource-level permissions."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-68","test":5,"number":68,"stem":["You configure the custom role shown below.","{","\"properties\": {","\"roleName\": \"role1\",","\"description\": \"\",","\"roleType\": \"true\",","\"assignableScopes\": [","\"/subscriptions/8f3a91c2-5b47-4d6e-9a21-7c8f0e3b4a6d/\"","],","\"permissions\": [","{","\"actions\": [","\"Microsoft.Authorization/*/read\",","\"Microsoft.Compute/availabilitySets/*\",","\"Microsoft.Compute/locations/*\",","\"Microsoft.Compute/virtualMachines/*\",","\"Microsoft.Compute/virtualMachineScaleSets/*\",","\"Microsoft.Compute/disks/write\",","\"Microsoft.Compute/disks/read\",","\"Microsoft.Compute/disks/delete\",","\"Microsoft.Network/locations/*\",","\"Microsoft.Network/networkInterfaces/*\",","\"Microsoft.Network/networkSecurityGroups/join/action\",","\"Microsoft.Network/networkSecurityGroups/read\",","\"Microsoft.Network/publicIPAddresses/join/action\",","\"Microsoft.Network/publicIPAddresses/read\",","\"Microsoft.Network/virtualNetworks/read\",","\"Microsoft.Network/virtualNetworks/subnets/join/action\",","\"Microsoft.Resources/deployments/*\",","\"Microsoft.Resources/subscriptions/resourceGroups/read\",","\"Microsoft.Support/*\"","],","\"notActions\": [],","\"dataActions\": [],","\"notDataActions\": []","}","]","}","}","Based on the information presented, select the answer choice that completes the following statement correctly.","“To ensure that role1 can be assigned only to a resource group named RG1, modify the __________________ section.”"],"options":[{"text":"actions","correct":false},{"text":"roletype","correct":false},{"text":"notActions","correct":false},{"text":"dataActions","correct":false},{"text":"notDataActions","correct":false},{"text":"assignableScopes","correct":true}],"explanation":["`assignableScopes` is the correct option because this section defines where a role can be assigned within Azure. By specifying the resource group scope (e.g., /subscriptions/{subscriptionId}/resourceGroups/RG1) in the assignableScopes section, the custom role role1 can be restricted to be assigned only to RG1.","This ensures that the role cannot be assigned to other subscriptions, resource groups, or resources outside the specified scope.","`actions` is incorrect because it defines control plane permissions for resource management but does not restrict where the role can be assigned.","`roletype` is incorrect because it only specifies whether the role is built-in or custom and does not affect the scope of assignment.","`notActions` is incorrect because it is used to exclude specific actions from the role, not to define assignment scope.","`dataActions` is incorrect because it controls data-level permissions, not role assignment scope.","`notDataActions` is incorrect because it specifies excluded data-level operations and does not define assignment scope."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-69","test":5,"number":69,"stem":["You have an Azure policy as shown in the following exhibit.","What is the effect of the policy?"],"options":[{"text":"You can create Azure SQL servers in any resource group within Subscription 1.","correct":false},{"text":"You are prevented from creating Azure SQL servers anywhere in Subscription 1.","correct":false},{"text":"You can create Azure SQL servers in ContosoRG1 only.","correct":true},{"text":"You are prevented from creating Azure SQL Servers in ContosoRG1 only.","correct":false}],"explanation":["`You can create Azure SQL servers in ContosoRG1 only` is correct because the policy defines a Not allowed resource types rule for Microsoft.Sql/servers at the Subscription 1 scope. However, the ContosoRG1 resource group is explicitly excluded from this policy. This means that while creating Azure SQL servers is blocked across the entire subscription, ContosoRG1 is exempt from this restriction, allowing Azure SQL servers to be created there.","`You can create Azure SQL servers in any resource group within Subscription 1` is incorrect because the policy explicitly prevents creating Azure SQL servers at the Subscription 1 level, except for the excluded resource group ContosoRG1.","`You are prevented from creating Azure SQL servers anywhere in Subscription 1` is incorrect because the exclusion for ContosoRG1 allows creating Azure SQL servers specifically in that resource group, overriding the subscription-wide restriction.","`You are prevented from creating Azure SQL Servers in ContosoRG1 only` is incorrect because ContosoRG1 is explicitly excluded from the policy, making it the only place where creating Azure SQL servers is permitted."],"references":[],"images":["assets/ea8d5285511336c3.png"],"topic":"identity","needsImage":true},{"id":"5-70","test":5,"number":70,"stem":["You have an Azure subscription with an existing Azure Storage account.","You plan to upload an on-premises virtual machine image to a blob container named vmimages.","Before uploading the image, you must create the required container in the storage account.","To do this, you intend to run an AzCopy command, as shown below.","`https://mystorageaccount.<service>.core.windows.net/vmimages`","Which command should you run?"],"options":[{"text":"azcopy sync ‘https://mystorageacount. blob .core.windows.net/vmimages’","correct":false},{"text":"azcopy make ‘https://mystorageacount.queue.core.windows.net/vmimages’","correct":false},{"text":"azcopy copy ‘https://mystorageacount.table.core.windows.net/vmimages’","correct":false},{"text":"azcopy sync ‘https://mystorageacount.dfs.core.windows.net/vmimages’","correct":false},{"text":"azcopy make ‘https://mystorageacount.blob.core.windows.net/vmimages’","correct":true},{"text":"azcopy copy ‘https://mystorageacount.images.core.windows.net/vmimages’","correct":false}],"explanation":["`azcopy make ‘https://mystorageaccount.blob.core.windows.net/vmimages’` is correct because the make command in AzCopy is specifically used to create a new container in an Azure Blob Storage account.","- The blob endpoint (blob.core.windows.net) is the correct endpoint for creating containers in Blob Storage.","- The container name vmimages indicates that it is intended for storing blobs, which aligns with the blob endpoint.","- The correct syntax for creating a new blob container using AzCopy is:","azcopy make 'https://<storage-account-name>.blob.core.windows.net/<container-name>'","**azcopy sync ‘https://mystorageaccount.blob.core.windows.net/vmimages’","Sync is used to synchronize data between a source and a destination**, not to create a container.","azcopy make ‘https://mystorageaccount.queue.core.windows.net/vmimages’","The queue** endpoint is for Azure Queue Storage, not Blob Storage.","azcopy copy ‘https://mystorageaccount.table.core.windows.net/vmimages’","The table** endpoint is for Azure Table Storage, not Blob Storage.","azcopy sync ‘https://mystorageaccount.dfs.core.windows.net/vmimages’","The dfs** endpoint is for Azure Data Lake Storage, not Blob Storage.","azcopy copy ‘https://mystorageaccount.images.core.windows.net/vmimages’","The images** endpoint is invalid in Azure Storage."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-71","test":5,"number":71,"stem":["You provision an Azure virtual machine named VM1 that runs Windows Server 2019.","The current configuration of VM1 is shown in the below exhibit.","You are required to enable Desired State Configuration (DSC) for VM1.","What is the first action you should take?"],"options":[{"text":"Assign a DNS name to VM1.","correct":false},{"text":"Establish a connection to VM1.","correct":false},{"text":"Power on VM1.","correct":true},{"text":"Capture a snapshot of VM1.","correct":false}],"explanation":["`Power on VM1` is correct because Desired State Configuration (DSC) requires the virtual machine to be in a running state to enable and configure it. In the exhibit, VM1 is currently stopped (deallocated), which means it is not operational. DSC operates by configuring the state of an actively running VM, and it cannot perform any operations on a stopped or deallocated VM.","`Assign a DNS name to VM1` is incorrect because assigning a DNS name is related to external name resolution and not a requirement for enabling DSC.","`Establish a connection to VM1` is incorrect because without starting the VM, you cannot establish a remote connection to perform DSC configuration.","`Capture a snapshot of VM1` is incorrect because snapshots are primarily used for backup or creating new VMs, not for enabling DSC."],"references":["https://learn.microsoft.com/en-us/azure/automation/automation-dsc-overview","https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-overview"],"images":["assets/e6b0c52712bb1c72.png"],"topic":"compute","needsImage":true},{"id":"5-72","test":5,"number":72,"stem":["You have defined a custom security attribute named Attr1 in your Microsoft Entra tenant.","The tenant includes a user account, a security group, and a service principal, as shown below.","- UserA - User","- SecGroup01 - Security group","- AppPrincipal01 - Service principal","You want to apply Attr1 to every identity type that supports custom security attributes.","To which identities can you assign Attr1?"],"options":[{"text":"UserA only","correct":false},{"text":"SecGroup01 only","correct":false},{"text":"UserA and SecGroup01 only","correct":false},{"text":"UserA and AppPrincipal01 only","correct":true},{"text":"UserA, SecGroup01, and AppPrincipal01","correct":false}],"explanation":["`UserA and AppPrincipal011 only` is correct because custom security attributes in Microsoft Entra ID can only be assigned to users and service principals (enterprise applications). Security groups are not supported objects for custom security attributes."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/custom-security-attributes-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-73","test":5,"number":73,"stem":["You have an Azure subscription named Sub1 that contains two users named User1 and User2.","You must assign Azure role-based access control (RBAC) roles to both users so they can perform the following actions within Sub1:","- User1 must view the data in any storage account.","- User2 must assign users the Contributor role for storage accounts.","The assignment must follow the principle of least privilege.","Which RBAC role should you assign to User 1?"],"options":[{"text":"Owner","correct":false},{"text":"Contributor","correct":false},{"text":"Reader and Data Access","correct":true},{"text":"Storage Account Contributor","correct":false},{"text":"User Access Administrator","correct":false}],"explanation":["`Reader and Data Access` is the correct role to assign to User1. This role provides read-only access to management operations (like the standard Reader role), but also adds the ability to read the data inside Azure Storage containers and blobs, queues, tables, and files. This aligns perfectly with the requirement that User1 must be able to view the data in any storage account, without allowing write or management capabilities. It also adheres to the principle of least privilege, as it grants exactly what is required and nothing more.","`Owner` is incorrect because it grants full access to manage all resources, including access management permissions. This is far more than what User1 needs just to view storage data, and violates the principle of least privilege.","`Contributor` is incorrect because while it allows full management of resources, it does not grant access to the underlying data in storage accounts (like reading blob contents). So it’s not sufficient for User1's data access requirement, and it overgrants permissions on the management plane.","`Storage Account Contributor` is incorrect because it provides management access to storage accounts (e.g., configuring settings, managing firewalls), but it does not grant data plane access (like reading blobs or files). Therefore, this role does not meet User1’s requirement to view the data inside storage accounts.","`User Access Administrator` is incorrect because it allows managing role assignments, not accessing data. This role is relevant for User2’s requirement, but not for User1. It provides no data access or management access to storage resources, so it is not applicable here."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles/storage#reader-and-data-access","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#owner","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator"],"images":[],"topic":"identity","needsImage":false},{"id":"5-74","test":5,"number":74,"stem":["You have an Azure subscription named Sub1 that contains two users named User1 and User2.","You must assign Azure role-based access control (RBAC) roles to both users so they can perform the following actions within Sub1:","- User1 must view the data in any storage account.","- User2 must assign users the Contributor role for storage accounts.","The assignment must follow the principle of least privilege.","Which RBAC role should you assign to User 2?"],"options":[{"text":"Owner","correct":false},{"text":"Contributor","correct":false},{"text":"Reader and Data Access","correct":false},{"text":"Storage Account Contributor","correct":false},{"text":"User Access Administrator","correct":true}],"explanation":["`User Access Administrator` is the correct role to assign to User2. This role allows a user to manage role assignments in Azure RBAC, including assigning others roles such as Contributor. It does not grant permissions to manage resources directly, making it ideal when the sole requirement is to delegate access control, as is the case here. Since User2 needs to assign users the Contributor role for storage accounts, User Access Administrator provides precisely the needed capability while following the principle of least privilege.","`Owner` is incorrect because although it allows full access to resources and access management, it overgrants permissions by allowing the user to create, delete, and manage any resource, which goes beyond just assigning RBAC roles. This violates the principle of least privilege.","`Contributor` is incorrect because this role allows managing Azure resources, but does not include permission to assign roles to other users. Therefore, it cannot fulfill the requirement to assign the Contributor role to others.","`Reader and Data Access` is incorrect because it only grants read access to Azure resources and data (e.g., in storage accounts), but does not provide any permissions related to role assignments or resource management.","`Storage Account Contributor` is incorrect because it grants permissions to manage storage accounts, including configuration, but it does not allow role assignments. It does not fulfill the need for User2 to assign RBAC roles to others."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#owner","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader-and-data-access","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor"],"images":[],"topic":"identity","needsImage":false},{"id":"5-75","test":5,"number":75,"stem":["You have an Azure subscription that includes a storage account hosting website content.","You need to ensure that users accessing the website are routed through the Microsoft point-of-presence (POP) that is geographically closest to them.","What configuration should you implement to meet this requirement?"],"options":[{"text":"Load balancing","correct":false},{"text":"Routing preference","correct":true},{"text":"Azure Firewall rules","correct":false},{"text":"private endpoints","correct":false}],"explanation":["`Routing preference` is the correct answer. In Azure Storage, the routing preference setting allows you to specify how user traffic reaches your storage account; either through the Microsoft global network or over the public internet. To ensure that inbound user traffic uses the Microsoft point-of-presence (POP) closest to the user’s location, you should configure the routing preference to use Microsoft network routing (also called \"Microsoft edge network\"). This ensures that user traffic enters the Microsoft network at the POP closest to the user's location and is routed through Microsoft's backbone to the storage account, optimizing performance and reducing latency.","`Load balancing` is incorrect because while Azure Load Balancer distributes traffic across virtual machines and services, it does not apply to Azure Storage accounts or influence the routing behavior of traffic to them.","`Azure Firewall rules` is incorrect because Azure Firewall is used for controlling and monitoring traffic to/from Azure resources, based on configured rules. It is not responsible for routing user traffic through the Microsoft POPs or determining how traffic enters the Microsoft network.","`Private endpoints` is incorrect because they are used to provide private connectivity to Azure services over a virtual network. While they enhance security by avoiding public internet exposure, they do not control whether traffic is routed through the Microsoft edge network or influence the POP usage."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/network-routing-preference#microsoft-global-network-versus-internet-routing","https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security","https://learn.microsoft.com/en-us/azure/firewall/overview","https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-76","test":5,"number":76,"stem":["You have an Azure subscription that includes a storage account named storage1.","You intend to apply role-based access control (RBAC) role assignments to storage1 by using conditional access expressions.","Which services within storage1 allow RBAC role assignments to be configured with conditions?"],"options":[{"text":"containers only","correct":false},{"text":"file shares only","correct":false},{"text":"tables only","correct":false},{"text":"queues only","correct":false},{"text":"containers and queues only","correct":true},{"text":"files shares and tables only","correct":false}],"explanation":["`containers and queues only` is the correct answer. Azure supports Azure role assignment conditions for Blob Storage containers and Queue Storage. This means you can apply conditional access controls—such as limiting access by IP address, resource tags, or actions—when assigning RBAC roles to these services. This feature enhances fine-grained access control, enabling you to enforce least privilege principles more effectively.","`file shares only` is incorrect because Azure Files currently does not support role assignment conditions. You can assign roles, but not with conditional logic.","`tables only` is incorrect because Azure Table storage does not support RBAC role assignment conditions. Access is typically controlled through account-level keys or Shared Access Signatures (SAS), not conditional RBAC.","`queues only` is incorrect because while queue services support conditional role assignments, selecting this option alone ignores the fact that containers (Blob storage) are also supported.","`containers only` is incorrect for the same reason—it's incomplete. Both containers and queues support conditional role assignments, so the correct answer must include both.","`file shares and tables only` is incorrect because neither of those services supports conditional access using RBAC role assignments."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format#actions","https://learn.microsoft.com/en-us/azure/storage/blobs/assign-azure-role-data-access?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/storage/queues/assign-azure-role-data-access?tabs=portal"],"images":[],"topic":"identity","needsImage":false},{"id":"5-77","test":5,"number":77,"stem":["You have an Azure subscription called Sub1 that includes the resource groups, as shown in the table below.","Each resource group is associated with a specific Azure region and has an Azure Policy assigned to it.","A web app named CustomerWeb01 exists in ResGrp1 and is deployed in the West Europe region.","You move CustomerWeb01 to ResGrp2.","What happens as a result of this move?"],"options":[{"text":"The App Service plan for CustomerWeb01 moves to North Europe. Pol2 applies to CustomerWeb01.","correct":false},{"text":"The App Service plan for CustomerWeb01 remains in West Europe. Pol1 applies to CustomerWeb01.","correct":false},{"text":"The App Service plan for CustomerWeb01 remains in West Europe. Pol2 applies to CustomerWeb01.","correct":true},{"text":"The App Service plan for CustomerWeb01 moves to North Europe. Pol1 applies to CustomerWeb01.","correct":false}],"explanation":["`The App Service plan for CustomerWeb01 remains in West Europe. Pol2 applies to CustomerWeb01` is the correct answer here. When you move a resource like a web app to a different resource group, the region of the resource does not change—it stays in the same physical location unless explicitly redeployed. Therefore, CustomerWeb01 and its App Service plan will remain in West Europe.","However, after the move, the policy assigned to the destination resource group (ResGrp2) will now govern CustomerWeb01. Since CustomerWeb01 is now in ResGrp2, Pol2 applies to it.","`The App Service plan for CustomerWeb01 moves to North Europe. Pol2 applies to CustomerWeb01` is incorrect because the App Service plan does not change regions automatically during a resource group move.","`The App Service plan for CustomerWeb01 remains in West Europe. Pol1 applies to CustomerWeb01` is incorrect because although the location remains unchanged, the applied policy comes from the new resource group (ResGrp2), not the original one.","`The App Service plan for CustomerWeb01 moves to North Europe. Pol1 applies to CustomerWeb01` is incorrect for both reasons—the region doesn’t change, and the policy from the original group doesn’t carry over.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription","- https://learn.microsoft.com/en-us/azure/governance/policy/overview","- https://learn.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure-basics","- https://learn.microsoft.com/en-us/azure/app-service/app-service-plan-manage"],"references":[],"images":["assets/60335540dc25cd32.png"],"topic":"identity","needsImage":true},{"id":"5-78","test":5,"number":78,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant.","The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1.","Both Sub1 and Sub2 are assigned to MG1.","Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions.","The following role assignments are configured at the MG1 scope:","- Group1 is assigned the Reader role","- User1 is assigned the User Access Administrator role","Additionally:","- User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2","- User1 is assigned the Contributor role on RG1","True or False:","`“Members of Group1 can view the configuration settings of the Azure Functions.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. The members of Group1 can view the configurations of the Azure functions because Group1 has been assigned the Reader role at the management group level (MG1). Since Sub1 and Sub2 are members of MG1, and RG1 (which contains the Azure Functions) is part of Sub1, the Reader role cascades down from MG1 to Sub1 and RG1.","The Reader role allows users to view all resources, including their configurations, but does not permit any modifications. Therefore, even without direct permissions at the resource group or subscription level, Group1 members inherit read-only access and can view the Azure Functions in RG1.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader","- https://learn.microsoft.com/en-us/azure/governance/management-groups/overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-79","test":5,"number":79,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant.","The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1.","Both Sub1 and Sub2 are assigned to MG1.","Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions.","The following role assignments are configured at the MG1 scope:","- Group1 is assigned the Reader role","- User1 is assigned the User Access Administrator role","Additionally:","- User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2","- User1 is assigned the Contributor role on RG1","True or False:","`\"User1 can assign the Owner role for RG1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer here. User1 is assigned the User Access Administrator role at the management group (MG1) level. This role grants the ability to manage role assignments (i.e., grant or remove access) on resources within that scope and all its child scopes—including subscriptions and resource groups beneath MG1. Since Sub1 is part of MG1, and RG1 is inside Sub1, the User Access Administrator permission applies to RG1 as well.","While Contributor alone does not allow role assignment, the User Access Administrator role is specifically designed to allow assigning any RBAC role, including Owner, as long as the user has this role at the appropriate level—which User1 does in this case.","Therefore, User1 can assign the Owner role for RG1, even if they are not currently an Owner themselves.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator","- https://learn.microsoft.com/en-us/azure/role-based-access-control/elevate-access-global-admin","- https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal#prerequisites-for-role-assignments","- https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal-subscription-admin#prerequisites"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-80","test":5,"number":80,"stem":["Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement.","You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant.","The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1.","Both Sub1 and Sub2 are assigned to MG1.","Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions.","The following role assignments are configured at the MG1 scope:","- Group1 is assigned the Reader role","- User1 is assigned the User Access Administrator role","Additionally:","- User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2","- User1 is assigned the Contributor role on RG1","True or False:","`\"User1 can create a new resource group and deploy a virtual machine to the new group.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer here. Although User1 has the Virtual Machine Contributor role assigned at the Sub1 and Sub2 subscription levels, and the Contributor role for RG1, they do not have permissions to create a new resource group unless they are granted Owner or Contributor at the subscription level where they want to create that new resource group.","The Virtual Machine Contributor role allows managing virtual machines, but does not grant permissions to create resource groups. Additionally, the Contributor role assigned at RG1 only provides permissions within RG1, not at the subscription level needed to create new resource groups.","Therefore, User1 cannot create a new resource group, and thus, cannot deploy a VM to a new resource group.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#virtual-machine-contributor","- https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor","- https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal#prerequisites-for-role-assignments","- https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-steps"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-81","test":5,"number":81,"stem":["You have an Azure subscription named Subscription1 and an on-premises deployment of Microsoft System Center Service Manager.","Within Subscription1, there is a virtual machine named VM1.","You must ensure that Service Manager generates an alert whenever the available memory on VM1 drops below 10 percent.","What should you do first?"],"options":[{"text":"Create an automation runbook","correct":false},{"text":"Deploy a function app","correct":false},{"text":"Deploy the IT Service Management Connector (ITSM)","correct":true},{"text":"Create a notification","correct":false}],"explanation":["`Deploy the IT Service Management Connector (ITSM)` is the correct answer here. The IT Service Management Connector (ITSM) allows you to integrate Azure Monitor with IT service management tools such as System Center Service Manager (SCSM). This connector enables alerts from Azure (e.g., when VM1's available memory drops below a threshold) to automatically generate incidents or alerts within Service Manager.","Before you can generate alerts or trigger incidents in Service Manager based on Azure metrics, you must first deploy and configure the ITSM connector in Azure. Only then can you map Azure alerts (like memory thresholds) to corresponding actions in Service Manager.","`Create an automation runbook` is incorrect because automation runbooks are used for remediating or performing actions based on alerts, not for integrating with Service Manager directly.","`Deploy a function app` is incorrect as it’s generally used for executing custom serverless logic—not necessary in this scenario where a built-in integration exists via ITSM Connector.","`Create a notification` is incorrect because notifications are used to inform users via email or SMS, but not to trigger actions or alerts in Service Manager.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/itsmc-overview","- https://learn.microsoft.com/en-in/azure/azure-functions/functions-overview?pivots=programming-language-csharp","- https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-82","test":5,"number":82,"stem":["You have an Azure subscription that includes the following resources, all deployed in the East US region:","- 10 virtual machines","- A key vault named Vault1","- A network security group named NSG1","All virtual machines are protected by using NSG1, which is configured to deny all outbound internet traffic.","You must allow the virtual machines to access Vault1. The solution must follow the principle of least privilege and require minimal ongoing administration.","Which destination should you specify in the outbound security rule for NSG1?"],"options":[{"text":"a service tag","correct":true},{"text":"an application security group","correct":false},{"text":"an IP address range","correct":false}],"explanation":["`a service tag` is the correct answer here. To allow the virtual machines to access Vault1 (which is an Azure Key Vault resource) while keeping outbound internet access blocked, you should configure the NSG outbound rule to allow traffic only to the AzureKeyVault service tag.","Service tags represent a group of IP address prefixes for specific Azure services and are automatically maintained by Microsoft, which minimizes administrative effort and adheres to the principle of least privilege. By using the `AzureKeyVault` service tag, you allow access only to Key Vault endpoints and nothing else on the internet, satisfying both security and operational requirements.","`an application security group` is incorrect because ASGs are used to group VMs and simplify NSG rules within a virtual network, not for allowing access to Azure services like Key Vault.","`an IP address range` is incorrect because allowing access via public IP ranges to Key Vault would require you to manage and update the ranges manually, which increases administrative overhead and violates the principle of least privilege.","Reference(s.):","- https://learn.microsoft.com/en-us/azure/virtual-network/service-tags-overview","- https://learn.microsoft.com/en-us/azure/key-vault/general/network-security","- https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"5-83","test":5,"number":83,"stem":["You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):","- VM-A","- OS: Windows Server","- Subnet: SubnetA","- VM-B","- OS: Windows Server","- Subnet: SubnetB","- VM-C","- OS: Red Hat Enterprise Linux","- Subnet: SubnetC","Each virtual machine’s network interface is configured with the following DNS settings:","- VM-A -> No DNS server configured","- VM-B -> 192.168.10.15","- VM-C -> 192.168.10.15","At the virtual network level, custom DNS settings are configured with the following DNS server:","- 193.77.134.10","All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10).","True or False:","`“VM-A connects to 193.77.134.10 for DNS queries.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM-A does not have a custom DNS server configured at the network interface level. In such cases, Azure virtual machines inherit their DNS server settings from the virtual network (VNET) they are connected to. From the information provided, VNET1 is configured with a single custom DNS server: 193.77.134.10. Therefore, VM-A uses 193.77.134.10 for DNS queries. The DNS server 192.168.10.15 is manually configured only for VM-B and VM-C at their respective NIC level and is not part of the VNET-wide configuration. Since VM-A lacks its own DNS override, it relies solely on the VNET1 configuration."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server","https://learn.microsoft.com/en-us/azure/dns/dns-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-84","test":5,"number":84,"stem":["You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):","- VM-A","- OS: Windows Server","- Subnet: SubnetA","- VM-B","- OS: Windows Server","- Subnet: SubnetB","- VM-C","- OS: Red Hat Enterprise Linux","- Subnet: SubnetC","Each virtual machine’s network interface is configured with the following DNS settings:","- VM-A -> No DNS server configured","- VM-B -> 192.168.10.15","- VM-C -> 192.168.10.15","At the virtual network level, custom DNS settings are configured with the following DNS server:","- 193.77.134.10","All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10).","True or False:","`“VM-B connects to 193.77.134.10 for DNS queries”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because VM-B is explicitly configured with a custom DNS server: 192.168.10.15 on its network interface.","When a virtual machine has a DNS server manually set at the NIC level, this custom setting overrides the DNS settings inherited from the virtual network (VNET1).","As a result, VM-B will only use 192.168.10.15 for DNS resolution, and it will not use the secondary DNS server (193.77.134.10) defined at the VNET level unless 193.77.134.10 is manually added as a secondary DNS server on the NIC itself."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server","https://learn.microsoft.com/en-us/azure/dns/dns-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-85","test":5,"number":85,"stem":["You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):","- VM-A","- OS: Windows Server","- Subnet: SubnetA","- VM-B","- OS: Windows Server","- Subnet: SubnetB","- VM-C","- OS: Red Hat Enterprise Linux","- Subnet: SubnetC","Each virtual machine’s network interface is configured with the following DNS settings:","- VM-A -> No DNS server configured","- VM-B -> 192.168.10.15","- VM-C -> 192.168.10.15","At the virtual network level, custom DNS settings are configured with the following DNS server:","- 193.77.134.10","All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10).","True or False:","`“VM-C connects to 192.168.10.15 for DNS queries.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because VM-C is explicitly configured with the DNS server 192.168.10.15 on its network interface.","In Azure, when a virtual machine’s NIC is manually configured with a DNS server IP, it overrides the DNS server settings configured at the virtual network level. As a result, VM-C will use 192.168.10.15 for all DNS queries unless that server is unreachable and multiple DNS servers are configured on the NIC (which is not shown in this case).","Therefore, VM-C connects to 192.168.10.15 for DNS resolution."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server","https://learn.microsoft.com/en-us/azure/dns/dns-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-86","test":5,"number":86,"stem":["You have an Azure subscription that contains the following virtual networks:","- VNet-West (Region: West Europe)","- VNet-Asia (Region: Southeast Asia)","- VNet-US (Region: South Central US)","The subscription also includes the following subnets:","- Subnet-A","- Virtual network: VNet-West","- Service endpoint: None","- Subnet-B","- Virtual network: VNet-Asia","- Service endpoint: Microsoft.Storage","- Subnet-C","- Virtual network: VNet-US","- Service endpoint: Microsoft.Storage","- Subnet-D","- Virtual network: VNet-US","- Service endpoint: None","Additionally, the following storage accounts exist:","- storagewest01","- Region: West Europe","- Kind: StorageV2","- storageus01","- Region: South Central US","- Kind: BlobStorage","- storageasia01","- Region: Southeast Asia","- Kind: StorageV2","You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription.","True or False:","`“StoragePolicy01 can be applied to Subnet-C.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because `Subnet-C` is in VNet-US, which is located in the South Central US region, the same region in which the service endpoint policy (StoragePolicy01) was created.","For a service endpoint policy to be applied to a subnet:","- The subnet must have a matching service endpoint (in this case, `Microsoft.Storage`).","- The subnet and the service endpoint policy must be in the same region.","Since Subnet3 has a `Microsoft.Storage` endpoint enabled and is located in the South Central US region (same as StoragePolicy01), it meets both conditions and therefore Policy1 can be applied to Subnet3."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-87","test":5,"number":87,"stem":["You have an Azure subscription that contains the following virtual networks:","- VNet-West (Region: West Europe)","- VNet-Asia (Region: Southeast Asia)","- VNet-US (Region: South Central US)","The subscription also includes the following subnets:","- Subnet-A","- Virtual network: VNet-West","- Service endpoint: None","- Subnet-B","- Virtual network: VNet-Asia","- Service endpoint: Microsoft.Storage","- Subnet-C","- Virtual network: VNet-US","- Service endpoint: Microsoft.Storage","- Subnet-D","- Virtual network: VNet-US","- Service endpoint: None","Additionally, the following storage accounts exist:","- storagewest01","- Region: West Europe","- Kind: StorageV2","- storageus01","- Region: South Central US","- Kind: BlobStorage","- storageasia01","- Region: Southeast Asia","- Kind: StorageV2","You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription.","True or False:","`“Only storagewest01 and storageus01 can be accessed from VNet-Asia.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because Subnet-B in VNet-Asia has the Microsoft.Storage service endpoint enabled, and no service endpoint policy is associated with that subnet. When a subnet has a Storage service endpoint enabled and no endpoint policy restricting access, it can connect to any Azure Storage account that allows access through service endpoints, regardless of the region.","In this scenario:","- VNet-Asia is in Southeast Asia","- Subnet-B has the Microsoft.Storage service endpoint enabled","- No service endpoint policy is applied to Subnet-B","Therefore, Subnet-B can access all storage accounts that permit service endpoint traffic, including:","- storagewest01 (West Europe)","- storageus01 (South Central US)","- storageasia01 (Southeast Asia)","The service endpoint policy StoragePolicy01 does not affect Subnet-B because it is not associated with that subnet.","The statement is incorrect because access is not limited to only storagewest01 and storageus01. The subnet can also access storageasia01."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-88","test":5,"number":88,"stem":["You have an Azure subscription that contains the following virtual networks:","- VNet-West (Region: West Europe)","- VNet-Asia (Region: Southeast Asia)","- VNet-US (Region: South Central US)","The subscription also includes the following subnets:","- Subnet-A","- Virtual network: VNet-West","- Service endpoint: None","- Subnet-B","- Virtual network: VNet-Asia","- Service endpoint: Microsoft.Storage","- Subnet-C","- Virtual network: VNet-US","- Service endpoint: Microsoft.Storage","- Subnet-D","- Virtual network: VNet-US","- Service endpoint: None","Additionally, the following storage accounts exist:","- storagewest01","- Region: West Europe","- Kind: StorageV2","- storageus01","- Region: South Central US","- Kind: BlobStorage","- storageasia01","- Region: Southeast Asia","- Kind: StorageV2","You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription.","True or False:","`\"Only storageus01 can be accessed from VNet-US.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because VNet-US is in the South Central US region, and both Subnet-C and Subnet-D belong to VNet-US. While Subnet-C has a Microsoft.Storage service endpoint and StoragePolicy01 applied, Subnet-D does not have any service endpoint or policy.","Here's what that means:","- Subnet-C can access only storage accounts allowed by StoragePolicy01, which includes storagewest01, storageus01, and storageasia01 (all storage accounts in the subscription), even though it is in South Central US.","- Subnet-D, which has no service endpoint configured, can still access public endpoints of any storage account over the internet if firewall rules and access configurations allow it.","Therefore, it is incorrect to say that only storageus01 can be accessed from VNet-US. In fact, storagewest01, storageus01, and storageasia01 can all potentially be accessed depending on which subnet the traffic originates from and whether it goes through the service endpoint or over the public internet."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-89","test":5,"number":89,"stem":["You manage an Azure subscription.","You need to create a custom Azure RBAC role with the following requirements:","- The assigned users must be able to perform all management operations for a virtual network.","- The permissions must adhere to the principle of least privilege, meaning no unnecessary access beyond what is required to manage the virtual network.","Which permissions should you specify in the role definition to meet these requirements?"],"options":[{"text":"\"Microsoft.Network/virtualNetworks/*\"","correct":true},{"text":"\"Microsoft.Network/virtualNetworks/delete\"","correct":false},{"text":"\"Microsoft.Network/virtualNetworks/write\"","correct":false}],"explanation":["`**\"Microsoft.Network/virtualNetworks/*\"` is the correct answer because it grants permission to perform all actions** on virtual networks, including read, write, delete, and other operations such as joining subnets or modifying settings. The asterisk `*` is a wildcard that encompasses all actions under the `Microsoft.Network/virtualNetworks` resource provider. This meets the requirement that users must be able to perform all actions on a virtual network.","`\"Microsoft.Network/virtualNetworks/delete\"` is incorrect because it grants only the ability to delete virtual networks and does not include permissions to read, write, or manage other aspects of the virtual network.","`\"Microsoft.Network/virtualNetworks/write\"` is incorrect because it only provides write access (e.g., create or update) but not read or delete access, and therefore does not fulfill the requirement of allowing all actions."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/custom-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"5-90","test":5,"number":90,"stem":["You manage an Azure subscription.","You need to create a custom Azure RBAC role with the following requirements:","- Users must be able to view the configuration settings of a storage account.","- The permissions must adhere to the principle of least privilege, meaning no unnecessary access beyond what is required to manage the virtual network.","Which permissions should you specify in the role definition to meet these requirements?"],"options":[{"text":"\"Microsoft.Storage/StorageAccounts/*\"","correct":false},{"text":"\"Microsoft.Storage/StorageAccounts/read\"","correct":true},{"text":"\"Microsoft.Storage/StorageAccounts/blobServices/containers/blob/read\"","correct":false}],"explanation":["`\"Microsoft.Storage/storageAccounts/read\"` is the correct answer because it grants users read-only access to the configuration and metadata of the storage account (such as properties, settings, keys, and networking configurations), without allowing any modifications or access to the actual data stored in blobs, queues, or files. This fully aligns with the principle of least privilege and the stated requirement to view configuration data only.","`**\"Microsoft.Storage/storageAccounts/*\"` is incorrect** because it grants all permissions on the storage account, including write and delete operations, which violates the principle of least privilege.","`\"Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read\"` is incorrect because it only provides read access to blob data, not to the configuration settings of the storage account itself."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview","https://learn.microsoft.com/en-us/azure/role-based-access-control/custom-roles"],"images":[],"topic":"identity","needsImage":false},{"id":"6-1","test":6,"number":1,"stem":["An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1.","The configuration is as follows:","- VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1","- VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2","- VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1","The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit.","Based on the current firewall and virtual network settings of the storage account, evaluate the following statement.","True or False:","`\"VM1 can connect to contoso2024 by using 131.107.10.10.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM1 can connect to the contoso2024 storage account using the IP address 131.107.10.10. The storage account's firewall settings allow access from selected IP addresses, and 131.107.10.10, the public IP address of VM1, is explicitly listed as an allowed address. Additionally, VM1 is connected to VNet1/Subnet1, and the storage account is configured to accept traffic from VNet1/Subnet1 as well."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"6-2","test":6,"number":2,"stem":["An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1.","The configuration is as follows:","- VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1","- VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2","- VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1","The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit.","Based on the current firewall and virtual network settings of the storage account, evaluate the following statement.","True or False:","`\"VM2 can connect to contoso2024 by using 150.120.10.10.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM2 has the public IP address 150.120.10.10, which is explicitly listed in the firewall rules of the contoso2024 storage account. While VM2 is connected to VNet1/Subnet2 (a different subnet than Subnet1), the public IP address being listed in the firewall allows VM2 to connect to the storage account, regardless of its subnet within VNet1.","Therefore, VM2 can still connect to contoso2024 using its public IP address."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"6-3","test":6,"number":3,"stem":["An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1.","The configuration is as follows:","- VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1","- VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2","- VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1","The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit.","Based on the current firewall and virtual network settings of the storage account, evaluate the following statement.","True or False:","`\"VM3 must use its private IP address to connect to contoso2024.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because although VM3 is in VNet1/Subnet1, which is allowed in the storage account’s virtual network rules, the firewall configuration also explicitly permits VM3’s public IP address. This means VM3 is not strictly forced to use its private IP for connectivity. The word “must” makes the statement incorrect: VM3 can connect using its private IP via the service endpoint, but it could also connect using its public IP since that IP is in the firewall allowlist."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":["assets/600aaf214ca94dd0.png"],"topic":"identity","needsImage":true},{"id":"6-4","test":6,"number":4,"stem":["You have an Azure App Service plan named AppServicePlanA that is configured with the Standard pricing tier.","You need to configure the plan so that it automatically increases its instance count whenever the web app’s CPU utilization exceeds 80 percent.","Which configuration setting should you enable for AppServicePlanA to achieve this behavior?"],"options":[{"text":"Automatic scaling configured in the Scale out settings","correct":false},{"text":"Rule-based scaling configured in the Scale out settings","correct":true},{"text":"Premium P1 selected under the Scale up (App Service plan) settings","correct":false},{"text":"Standard S1 selected under the Scale up (App Service plan) settings","correct":false},{"text":"Manual scaling configured in the Scale out settings","correct":false}],"explanation":["`Rule-based scaling configured in the Scale out settings` is the correct answer here. By selecting Rules Based, you can configure specific conditions for automatic scaling, such as when CPU usage exceeds 80 percent. This allows AppServicePlanA to automatically add more instances when the CPU utilization goes above the defined threshold. In this case, a rule can be created to automatically scale out based on CPU performance, which satisfies the requirement.","`Automatic scaling configured in the Scale out settings` is incorrect because it doesn't allow setting specific scaling conditions, such as CPU thresholds.","`Manual scaling configured in the Scale out settings` is incorrect because it requires manual intervention to scale, which does not meet the requirement of automatic scaling when CPU usage exceeds 80 percent.","`Premium P1 selected under the Scale up (App Service plan) settings` and","`Standard S1 selected under the Scale up (App Service plan) settings` are incorrect because these refer to scaling up (increasing the resources of the plan itself), not scaling out (adding more instances) based on a specific condition like CPU usage."],"references":["https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up","https://learn.microsoft.com/en-us/training/modules/scale-apps-app-service/2-autoscale-factors"],"images":[],"topic":"compute","needsImage":false},{"id":"6-5","test":6,"number":5,"stem":["You have an Azure virtual network named VNet1 with the following configuration:","- The IPv4 address space is 172.16.10.0/24","- A subnet named Subnet1 exists within the virtual network","- Subnet1 uses the address range 172.16.10.0/25","Based on this configuration, what is the maximum number of virtual machines that can be deployed and connected to Subnet1?"],"options":[{"text":"24","correct":false},{"text":"25","correct":false},{"text":"123","correct":true},{"text":"128","correct":false},{"text":"251","correct":false}],"explanation":["`123` is the correct answer. The subnet 172.16.10.0/25 has a total of 128 IP addresses. However, Azure reserves the first four and the last IP address in every subnet for internal use. Therefore, the available IP addresses for virtual machines are:","128 (total IP addresses) - 5 (reserved addresses) = 123 usable IP addresses.","These 123 addresses can be assigned to virtual machines or other resources within the subnet.","- 172.16.10.0/25 means the subnet has 128 total IP addresses (2^7 = 128).","- Azure reserves five IP addresses in each subnet:","- The first IP is the network address.","- The second through fourth IP addresses are reserved for Azure services.","- The last IP address is reserved for the broadcast address.","- Thus, 123 addresses remain available for virtual machines."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq"],"images":[],"topic":"network","needsImage":false},{"id":"6-6","test":6,"number":6,"stem":["Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:","- User1 is a user account located in OU2.","- User2 is a user account located in OU1.","- Group1 is a global security group that includes User1 and is located in OU1.","You have an Azure subscription that contains a storage account named storage1.","The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups.","You create an Azure Files share named share1 and assign the following roles:","- User2 is assigned the Storage File Data SMB Share Reader role.","- Group1 is assigned the Storage File Data SMB Share Contributor role.","You also have a Microsoft Entra tenant that includes a cloud-only user named User3.","Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant.","True or False:","`“User1 is able to access the data stored in share1.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because User1 can access share1 by using AD DS authentication, even though User1 is not synchronized to Microsoft Entra ID.","The storage account uses AD DS as the identity source, and default share-level permissions are enabled for all authenticated users and groups. For Azure Files with AD DS authentication, Microsoft states that when a default share-level permission is configured, on-premises AD DS identities do not need to be synchronized to Microsoft Entra ID. The identity only needs to authenticate against the AD DS deployment associated with the storage account.","In addition, User1 is a member of Group1 in the on-premises AD DS domain. Group1 is located in OU1, is synchronized to Microsoft Entra ID, and has the Storage File Data SMB Share Contributor role on share1. Microsoft states that for AD DS authentication, non-synchronized users can still access Azure file shares through membership in a synchronized AD DS group. Azure Files reads the group SIDs from the user’s Kerberos ticket and applies the matching RBAC role assignments.","Therefore, User1 can access the data in share1, assuming the applicable NTFS/file-level permissions do not deny access. Azure Files evaluates both share-level permissions and Windows ACLs, and the most restrictive permission applies."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-assign-share-level-permissions?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-configure-file-level-permissions"],"images":[],"topic":"identity","needsImage":false},{"id":"6-7","test":6,"number":7,"stem":["Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:","- User1 is a user account located in OU2.","- User2 is a user account located in OU1.","- Group1 is a global security group that includes User1 and is located in OU1.","You have an Azure subscription that contains a storage account named storage1.","The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups.","You create an Azure Files share named share1 and assign the following roles:","- User2 is assigned the Storage File Data SMB Share Reader role.","- Group1 is assigned the Storage File Data SMB Share Contributor role.","You also have a Microsoft Entra tenant that includes a cloud-only user named User3.","Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant.","True or False:","`\"User2 can access content in share1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct.","User2 can access share1 because User2 is located in OU1, and OU1 is synchronized to Microsoft Entra ID. User2 is also explicitly assigned the Storage File Data SMB Share Reader role on share1, which grants read access at the Azure Files share level.","Additionally, the question states that the default share-level permissions are configured to allow access for all authenticated users and groups. Therefore, even without the explicit RBAC assignment, User2 could still be allowed at the share level if User2 can authenticate against the associated AD DS domain and the default permission grants sufficient access.","However, Azure Files access is controlled by both share-level permissions and NTFS file/directory permissions. Therefore, actual access to the content also depends on the applicable NTFS ACLs. In this question, no restrictive NTFS ACL is mentioned, so User2 can access the content in share1."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"6-8","test":6,"number":8,"stem":["Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:","- User1 is a user account located in OU2.","- User2 is a user account located in OU1.","- Group1 is a global security group that includes User1 and is located in OU1.","You have an Azure subscription that contains a storage account named storage1.","The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups.","You create an Azure Files share named share1 and assign the following roles:","- User2 is assigned the Storage File Data SMB Share Reader role.","- Group1 is assigned the Storage File Data SMB Share Contributor role.","You also have a Microsoft Entra tenant that includes a cloud-only user named User3.","Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant.","True or False:","`\"User3 can access content in share1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct. For AD DS-based Azure Files authentication, Azure Files uses Kerberos through the configured identity source, and Microsoft states that only hybrid identities that exist in both on-premises AD DS and Microsoft Entra ID can be authenticated and authorized for Azure file share access. Also, a storage account can use only one identity source for SMB identity-based authentication, so cloud-only access would require a different identity source such as Microsoft Entra Kerberos, not AD DS."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"6-9","test":6,"number":9,"stem":["You manage two Azure subscriptions, Sub1 and Sub2. Each subscription is linked to a separate Microsoft Entra tenant.","The environment includes the following virtual networks:","- VNet1 – Located in East US – Associated with Sub1","- VNet2 – Located in East US – Associated with Sub1","- VNet3 – Located in West US – Associated with Sub1","- VNet4 – Located in East US – Associated with Sub2","- VNet5 – Located in Central US – Associated with Sub2","You want to establish virtual network peering from VNet1.","Which of the listed virtual networks are eligible to be peered with VNet1?"],"options":[{"text":"VNet2 only","correct":false},{"text":"VNet2 and VNet3 only","correct":false},{"text":"VNet2 and VNet4 only","correct":false},{"text":"VNet2, VNet3, and VNet4 only","correct":false},{"text":"VNet2, VNet3, VNet4, and VNet5","correct":true}],"explanation":["VNet1 can peer with `VNet2, VNet3, VNet4, and VNet5` because global virtual network peering allows you to peer virtual networks across different regions and subscriptions, even when they are linked to different Microsoft Entra tenants.","- VNet2: Same region (East US), same subscription (Sub1).","- VNet3: Different region (West US), same subscription (Sub1).","- VNet4: Same region (East US), different subscription (Sub2).","- VNet5: Different region (Central US), different subscription (Sub2).","With global VNet peering, you can enable communication between virtual networks in different regions and subscriptions, as long as the necessary permissions are configured."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-10","test":6,"number":10,"stem":["You have an Azure subscription that includes a storage account named storage1.","You want to restrict access to storage1 so that it is reachable only from specific networks and from your home office. The approach must require the least amount of ongoing administrative effort.","What is the first configuration change you should make for storage1?"],"options":[{"text":"Create a private endpoint for the storage account.","correct":false},{"text":"Update the public network access configuration for the storage account.","correct":true},{"text":"Configure the storage account to use internet-based routing.","correct":false},{"text":"Change the role-based access control (IAM) settings.","correct":false}],"explanation":["`Update the public network access configuration for the storage account` is the correct answer here. To allow access to storage1 from selected networks and your home office while minimizing administrative effort, you should first modify the Public network access settings. By selecting the option to allow access only from selected virtual networks and IP addresses, you can define specific networks and IP addresses, such as your home office's public IP address, without needing to configure more complex solutions like private endpoints.","`Create a private endpoint for the storage account` is incorrect because private endpoints require additional setup and would only allow access through a private network, not minimizing administrative effort.","`Configure the storage account to use internet-based routing` is incorrect because this would open the storage account to access from the internet, which doesn't fulfill the requirement of limiting access to selected networks and your home office.","`Change the role-based access control (IAM) settings` is incorrect because IAM controls user and group permissions for accessing resources but does not control network access."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal","https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal#public-network-access"],"images":[],"topic":"identity","needsImage":false},{"id":"6-11","test":6,"number":11,"stem":["An Azure subscription contains three Azure Container Registry (ACR) instances. Each registry is configured with a different pricing tier:","- ContReg1 – Service tier: Premium","- ContReg2 – Service tier: Standard","- ContReg3 – Service tier: Basic","You plan to use Azure Container Registry (ACR) Tasks and also require support for private endpoint connections.","Which of the listed container registries can be used to run ACR Tasks?"],"options":[{"text":"ContReg1 only","correct":false},{"text":"ContReg1 and ContReg2 only","correct":false},{"text":"ContReg1, ContReg2, and ContReg3","correct":true}],"explanation":["`ContReg1, ContReg2, and ContReg3 `is the correct answer here. ACR Tasks are supported in all service tiers: Basic, Standard, and Premium. While there are performance and feature differences across the tiers (such as the number of concurrent tasks or webhook triggers), ACR Tasks functionality is available in all three tiers, including Basic."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"],"images":[],"topic":"identity","needsImage":false},{"id":"6-12","test":6,"number":12,"stem":["An Azure subscription contains three Azure Container Registry (ACR) instances. Each registry is configured with a different pricing tier:","- ContReg1 – Service tier: Premium","- ContReg2 – Service tier: Standard","- ContReg3 – Service tier: Basic","You plan to use Azure Container Registry (ACR) Tasks and also require support for private endpoint connections.","Which of the container registries can be configured to use private endpoints?"],"options":[{"text":"ContReg1 only","correct":true},{"text":"ContReg1 and ContReg2 only","correct":false},{"text":"ContReg1, ContReg2, and ContReg3","correct":false}],"explanation":["`ContReg1 only` is the correct answer because only the Premium tier of Azure Container Registry supports private endpoints. ContReg1 is configured with the Premium tier, which allows the use of private endpoints. Standard and Basic tiers, as seen in ContReg2 and ContReg3, do not support private endpoints.","`ContReg1 and ContReg2 only` is incorrect because the Standard tier (used by ContReg2) does not support private endpoints.","`ContReg1, ContReg2, and ContReg3` is incorrect because neither the Standard nor Basic tiers (used by ContReg2 and ContReg3) support private endpoints."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"],"images":[],"topic":"identity","needsImage":false},{"id":"6-13","test":6,"number":13,"stem":["You have an Azure container registry named contoso2023 as shown below.","You want to configure contoso2023 so that it uses a dedicated data endpoint for data operations.","Which two configuration settings must you enable or modify on contoso2023 to meet this requirement?"],"options":[{"text":"Overview","correct":false},{"text":"Properties","correct":true},{"text":"Networking","correct":true},{"text":"Tasks","correct":false},{"text":"Access control (IAM)","correct":false},{"text":"Events","correct":false}],"explanation":["To enable contoso2023 to use a dedicated data endpoint, you need to configure the following two settings:","`Properties`: This is where you can enable and configure the dedicated data endpoint for your Azure container registry. From this blade, you must first change the pricing plan from Standard to Premium. This setting is crucial for routing all data plane operations through a dedicated endpoint.","`Networking`: After the registry is upgraded to Premium, you must go to Networking and enable the dedicated data endpoint setting. Dedicated data endpoints provide registry-specific data endpoint URLs, such as `<registry-name>.<region>.data.azurecr.io`, for data operations.","`Overview`, `Tasks`, `Access control (IAM)`, and `Events` are NOT relevant for enabling or configuring a dedicated data endpoint."],"references":["https://learn.microsoft.com/en-gb/azure/container-registry/container-registry-firewall-access-rules#enable-dedicated-data-endpoints","https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"],"images":["assets/4206c8ced0be67c1.png"],"topic":"compute","needsImage":true},{"id":"6-14","test":6,"number":14,"stem":["You have a Microsoft Entra tenant named contoso.com.","You work with an external organization that uses the domain fabrikam.com.","You plan to invite external users from fabrikam.com into the contoso.com tenant.","You must ensure that invitations can be sent exclusively to users from fabrikam.com and not to users from any other external domains.","What configuration should you perform in the Microsoft Entra admin center?"],"options":[{"text":"From Cross-tenant access settings, configure the Tenant restrictions settings.","correct":false},{"text":"From Cross-tenant access settings, configure the Microsoft cloud settings.","correct":false},{"text":"From External collaboration settings, configure the Guest user access restrictions settings.","correct":false},{"text":"From External collaboration settings, configure the Collaboration restrictions settings.","correct":true}],"explanation":["`From External collaboration settings, configure the Collaboration restrictions settings` is the correct answer. In Microsoft Entra, you can restrict who can be invited as a guest by configuring Collaboration restrictions. By specifying the allowed domains, such as fabrikam.com, you can ensure that invitations can only be sent to users from that domain.","`From Cross-tenant access settings, configure the Tenant restrictions settings` is incorrect because tenant restrictions are used to control which tenants users can access, not to restrict guest invitations.","`From Cross-tenant access settings, configure the Microsoft cloud settings` is incorrect because these settings are used for managing cross-tenant access policies between Microsoft cloud environments, not for restricting guest user invitations.","`From External collaboration settings, configure the Guest user access restrictions settings` is incorrect because this setting controls what guest users can do once they are in your tenant, not who can be invited."],"references":["https://learn.microsoft.com/en-us/entra/external-id/external-collaboration-settings-configure"],"images":[],"topic":"identity","needsImage":false},{"id":"6-15","test":6,"number":15,"stem":["You have an Azure subscription that includes three virtual machines named VM1, VM2, and VM3. All three virtual machines are deployed in the same availability set called AVSet1.","You want to resize VM1 to a larger virtual machine size. However, the target size is currently not available.","What action should you take first?"],"options":[{"text":"Create a proximity placement group and associate it with the virtual machines.","correct":false},{"text":"Deallocate VM1.","correct":true},{"text":"Convert AvSet1 into a managed availability set.","correct":false},{"text":"Power off VM2 and VM3.","correct":false}],"explanation":["`Deallocate VM1` is the correct answer here. When a specific virtual machine size is unavailable for a VM that is part of an availability set (like AVSet1), the first step is to deallocate the virtual machine. Deallocating the VM releases the hardware allocation, potentially freeing up capacity for the new VM size. Once the VM is deallocated, you can attempt to resize it.","`Create a proximity placement group and associate it with the virtual machines` is incorrect because proximity placement groups are used to ensure low-latency placement of VMs but have no direct impact on resizing availability.","`Convert AVSet1 into a managed availability set` is incorrect because the availability set is already managed by default when using managed disks, and this action wouldn't resolve the size availability issue.","`Power off VM2 and VM3` is incorrect because shutting down the other VMs in the availability set does not affect the resizing of VM1."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/sizes/resize-vm?tabs=portal"],"images":[],"topic":"identity","needsImage":false},{"id":"6-16","test":6,"number":16,"stem":["An Azure subscription contains the following resources:","- VM1 – Virtual machine","- VNet1 – Virtual network","- NIC1 – Network interface","- LB1 – Load balancer","- VPN1 – Virtual network gateway","You create a new public IP address named IP1.","Which two of the listed resources can be linked to IP1?"],"options":[{"text":"VM1","correct":false},{"text":"LB1","correct":true},{"text":"NIC1","correct":true},{"text":"VPN1","correct":false},{"text":"VNet1","correct":false}],"explanation":["`LB1 (Load balancer)` and `NIC1 (Network interface) `are the correct answers. Public IP addresses can be associated with a load balancer or a network interface to enable external communication with resources like virtual machines or services behind the load balancer.","- LB1: A public IP can be associated with a load balancer to distribute incoming traffic across multiple backend resources, such as virtual machines.","- NIC1: A public IP can also be associated with a network interface, allowing a virtual machine to have direct access to the internet.","`VM1` is incorrect because public IP addresses are associated with network interfaces (like NIC1) rather than directly with virtual machines.","`VPN1` is incorrect because virtual network gateways use their own public IPs but are not directly associated with manually created public IPs.","`VNet1` is incorrect because virtual networks themselves do not have public IP addresses directly associated with them."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/public-ip-addresses","https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-17","test":6,"number":17,"stem":["You have an Azure subscription with two virtual networks, VNet1 and VNet2, that are peered with each other.","VNet1 includes a VPN gateway that is configured to use static routing.","The on-premises network has a VPN connection that uses the VPN gateway of VNet1.","You need to enable users from the on-premises network to access a virtual machine hosted in VNet2. The solution must be cost-effective.","Which connectivity approach should you implement?"],"options":[{"text":"Deploy Azure Firewall and route traffic through its private IP address","correct":false},{"text":"Use service chaining together with user-defined routes (UDRs)","correct":true},{"text":"Deploy an Azure Application Gateway","correct":false},{"text":"Provision an ExpressRoute circuit connected to VNet2","correct":false}],"explanation":["`Use service chaining together with user-defined routes (UDRs)` is the correct answer. By using service chaining and configuring user-defined routes (UDRs), you can route traffic from the on-premises network, through the VPN gateway on VNet1, to VNet2. This setup leverages the existing peering between VNet1 and VNet2 without requiring additional costly infrastructure like Azure Firewall or ExpressRoute, thereby minimizing costs. UDRs will ensure that the traffic is directed through the correct paths.","`Deploy Azure Firewall and route traffic through its private IP address` is incorrect because while it could provide routing and security, it is more costly than using UDRs and is not necessary for this scenario.","`Deploy an Azure Application Gateway` is incorrect because this is primarily used for managing and load balancing web traffic, not for routing network traffic between VNets or from on-premises networks.","`Provision an ExpressRoute circuit connected to VNet2` is incorrect because ExpressRoute is a high-cost solution that provides private connectivity between on-premises and Azure, which is not required since you already have a VPN gateway in place for the on-premises connection."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-18","test":6,"number":18,"stem":["You have an Azure subscription that contains a storage account named storage1.","You want to make sure that the access keys for storage1 are rotated automatically.","Which configuration should you set up?"],"options":[{"text":"Configure a backup vault","correct":false},{"text":"Configure redundancy settings for storage1","correct":false},{"text":"Configure lifecycle management for storage1","correct":false},{"text":"Configure an Azure Key Vault","correct":true},{"text":"Configure a Recovery Services vault","correct":false}],"explanation":["`Configure an Azure Key Vault` is the correct answer. To ensure that the access keys for storage1 rotate automatically, you should store the keys in Azure Key Vault and enable key rotation policies. Key Vault allows for the secure storage of secrets, including storage account access keys, and provides the ability to configure automatic key rotation.","`Configure a backup vault` and `Configure a Recovery Services vault` are incorrect because these are used for backing up data and managing disaster recovery, not for rotating access keys.","`Configure redundancy settings for storage1` is incorrect because this deals with the replication of storage data across different locations for high availability, not key management.","`Configure lifecycle management for storage1` is incorrect because this manages data retention policies, not access key rotation."],"references":["https://learn.microsoft.com/en-us/azure/key-vault/general/overview","https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"6-19","test":6,"number":19,"stem":["You have an Azure subscription that includes a storage account named storage1, which stores blob data.","You must assign a role to a user named User1 so that the user can access the blob data in storage1. The role assignment must support Azure role assignment conditions.","Which two roles are suitable for assigning to User1?"],"options":[{"text":"Owner","correct":false},{"text":"Storage Account Contributor","correct":false},{"text":"Storage Account Backup Contributor","correct":false},{"text":"Storage Blob Data Contributor","correct":true},{"text":"Storage Blob Data Owner","correct":true},{"text":"Storage Blob Delegator","correct":false}],"explanation":["`Storage Blob Data Contributor` is the correct answer because this role allows the user to read, write, and delete blob data within a storage account. This role supports conditions, which can help control access based on specific criteria like time, IP address, or other factors.","`Storage Blob Data Owner` is the correct answer because this role grants full control over blob data, including setting access policies and modifying blob content. It also supports conditions for access.","`Owner` is incorrect because while this role gives full administrative access to the storage account, it does not allow direct blob data access, nor does it support conditions for blob-level data access.","`Storage Account Contributor` is incorrect because it grants management access to the storage account but does not provide direct access to blob data.","`Storage Account Backup Contributor` is incorrect because this role is designed for backup and recovery operations but doesn't provide direct access to blob data.","`Storage Blob Delegator` is incorrect because this role is used to delegate access through OAuth 2.0 on behalf of a user or service and is not intended for direct blob data access."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-owner"],"images":[],"topic":"identity","needsImage":false},{"id":"6-20","test":6,"number":20,"stem":["You have a Microsoft Entra tenant.","You plan to import a large number of user accounts at once.","You must ensure that newly imported users are automatically added to a specific group based on the value of their department attribute. The solution should require minimal ongoing administrative effort.","Which two actions should you take?"],"options":[{"text":"Create groups that use the Assigned membership type.","correct":false},{"text":"Create an Azure Resource Manager (ARM) template.","correct":false},{"text":"Create groups that use the Dynamic User membership type.","correct":true},{"text":"Write a PowerShell script that parses an import file.","correct":false},{"text":"Create an XML file that contains user information and the appropriate attributes.","correct":false},{"text":"Create a CSV file that contains user information and the appropriate attributes.","correct":true}],"explanation":["`Create groups that use the Dynamic User membership type` is the correct answer because dynamic membership rules allow users to be automatically added to groups based on specific attributes, such as department. This minimizes administrative effort since the users will be automatically placed into the correct group based on their department attribute without manual intervention.","`Create a CSV file that contains user information and the appropriate attributes` is the correct answer because CSV is the supported format for bulk importing users into Microsoft Entra. The CSV file will contain the necessary user information, including department attributes, which are used to assign users to the appropriate dynamic groups.","`Create groups that use the Assigned membership type` is incorrect because assigned groups require manual assignment of users, which does not minimize administrative effort.","`Create an Azure Resource Manager (ARM) template` is incorrect because ARM templates are used to deploy Azure resources, not for user or group management.","`Write a PowerShell script that parses an import file` is incorrect because while it can be used, it would increase administrative effort, which is against the goal of minimizing effort.","`Create an XML file that contains user information and the appropriate attributes` is incorrect because CSV is the recommended format for bulk user import, not XML."],"references":["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership","https://learn.microsoft.com/en-us/entra/identity/users/groups-bulk-import-members"],"images":[],"topic":"identity","needsImage":false},{"id":"6-21","test":6,"number":21,"stem":["You have an Azure subscription that contains an Azure Container Registry named RegistryProd01, which is currently configured with the Standard pricing tier.","You need to enable support for geo-replication for RegistryProd01.","What is the first step you should perform on RegistryProd01 to meet this requirement?"],"options":[{"text":"Enable the admin user for the registry.","correct":false},{"text":"Create a scope map for the registry.","correct":false},{"text":"Configure an automation task.","correct":false},{"text":"Define a cache rule.","correct":false},{"text":"Change the registry to a higher SKU tier.","correct":true}],"explanation":["`Change the registry to a higher SKU tier` is the correct answer here. Geo-replication in Azure Container Registry is only supported in the Premium SKU. Since RegistryProd01 is currently using the Standard SKU, the first step to enable geo-replication is to upgrade the SKU to Premium. Once the SKU is upgraded, you can configure geo-replication across multiple regions.","`Enable the admin user for the registry` is incorrect because this is related to authentication and does not enable geo-replication.","`Create a scope map for the registry` is incorrect because scope maps are used for defining permissions for tokens, not for geo-replication.","`Configure an automation task` is incorrect because automation tasks are used for building and pushing images, not for geo-replication.","`Define a cache rule` is incorrect because cache rules are unrelated to geo-replication."],"references":["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-geo-replication","https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"],"images":[],"topic":"identity","needsImage":false},{"id":"6-22","test":6,"number":22,"stem":["You have an Azure subscription that includes a storage account named storage1 which contains a blob used to store images.","Access to storage1 is provided to clients by using a shared access signature (SAS).","You want users to see a warning whenever they create a SAS with an expiration period longer than seven days.","What configuration should you apply to the storage account?"],"options":[{"text":"Enable a read-only resource lock on the storage account.","correct":false},{"text":"Create and configure an alert rule.","correct":false},{"text":"Add a lifecycle management policy.","correct":false},{"text":"Set Allow recommended upper limit for shared access signature (SAS) expiry interval to Enabled.","correct":true}],"explanation":["`Set Allow recommended upper limit for shared access signature (SAS) expiry interval to Enabled` is the correct answer. By enabling this setting, Azure will enforce a recommended upper limit for SAS token expiry (in this case, seven days). Users will receive a warning if they try to create a SAS token that exceeds the defined limit, helping to maintain secure access practices.","`Enable a read-only resource lock on the storage account` is incorrect because locks are used to prevent modification or deletion of resources, not for configuring SAS expiry limits.","`Create and configure an alert rule` is incorrect because alert rules are used for monitoring and alerting on events, but do not directly enforce or warn about SAS expiry time.","`Add a lifecycle management policy` is incorrect because lifecycle management is used to manage blob storage tiers and deletion policies, not SAS expiry intervals."],"references":["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-23","test":6,"number":23,"stem":["You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:","- User1: Not enabled for on-premises synchronization","- User2: Enabled for on-premises synchronization","You create the following Azure Files shares:","- share1 in storage account contoso2025","- share2 in storage account contoso2025","- share3 in storage account contoso2026","You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups.","True or False:","`\"User1 can access the content in share1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 does not have on-premises synchronization enabled, as indicated. According to the identity-based access configuration shown in the exhibit, only users synchronized from on-premises AD DS or those with hybrid identities can access the file shares. User1 is not synced from an on-premises AD DS environment and is therefore not eligible for access to share1, despite the permissions being enabled for authenticated users."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"],"images":["assets/8d889cef0aef86e1.png"],"topic":"identity","needsImage":true},{"id":"6-24","test":6,"number":24,"stem":["You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:","- User1: Not enabled for on-premises synchronization","- User2: Enabled for on-premises synchronization","You create the following Azure Files shares:","- share1 in storage account contoso2025","- share2 in storage account contoso2025","- share3 in storage account contoso2026","You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups.","True or False:","`\"User2 can access the content in share2.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User2 has on-premises sync enabled, as indicated, and the identity-based access configuration for contoso2025 (which contains share2) is set to allow permissions for authenticated users and groups. Since User2 is synchronized from on-premises AD DS, they are eligible to access the content in share2."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"],"images":["assets/8d889cef0aef86e1.png"],"topic":"identity","needsImage":true},{"id":"6-25","test":6,"number":25,"stem":["You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:","- User1: Not enabled for on-premises synchronization","- User2: Enabled for on-premises synchronization","You create the following Azure Files shares:","- share1 in storage account contoso2025","- share2 in storage account contoso2025","- share3 in storage account contoso2026","You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups.","True or False:","`\"User2 can access the content in share3.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because share3 is part of the contoso2026 storage account, which is not configured for identity-based access (according to the provided information and exhibit, only contoso2025 has identity-based access enabled). Since User2 is synced and can access shares in contoso2025, they would not have access to share3 in contoso2026 unless identity-based access is configured similarly for contoso2026."],"references":["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"],"images":["assets/8d889cef0aef86e1.png"],"topic":"identity","needsImage":true},{"id":"6-26","test":6,"number":26,"stem":["A Microsoft Entra tenant contains the following users:","- User1","- Member of: Group1","- Assigned license: Microsoft Entra ID P2","- User2","- Member of: Group2","- Assigned license: None","- User3","- Member of: No groups","- Assigned license: Microsoft Entra ID P2","- User4","- Member of: No groups","- Assigned license: None","The tenant also contains the following groups and group relationships:","- Group1","- Member of: No groups","- Assigned license: None","- Group2","- Member of: Group3","- Assigned license: Microsoft Entra ID P2","- Group3","- Member of: Group4","- Assigned license: None","- Group4","- Member of: No groups","- Assigned license: Microsoft Entra ID P2","Based on the tenant configuration shown above, which `users` are eligible to be deleted from Microsoft Entra ID?"],"options":[{"text":"User4 only","correct":false},{"text":"User3 and User4 only","correct":false},{"text":"User2 and User4 only","correct":false},{"text":"User1, User2, User3, and User4","correct":true}],"explanation":["`User1, User2, User3, and User4` can all be deleted. In Microsoft Entra ID, users can be deleted regardless of whether they have licenses assigned directly or through group membership. When a user is deleted, any licenses assigned to them will be freed for reassignment."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-create-delete-users"],"images":[],"topic":"identity","needsImage":false},{"id":"6-27","test":6,"number":27,"stem":["A Microsoft Entra tenant contains the following users:","- User1","- Member of: Group1","- Assigned license: Microsoft Entra ID P2","- User2","- Member of: Group2","- Assigned license: None","- User3","- Member of: No groups","- Assigned license: Microsoft Entra ID P2","- User4","- Member of: No groups","- Assigned license: None","The tenant also contains the following groups and group relationships:","- Group1","- Member of: No groups","- Assigned license: None","- Group2","- Member of: Group3","- Assigned license: Microsoft Entra ID P2","- Group3","- Member of: Group4","- Assigned license: None","- Group4","- Member of: No groups","- Assigned license: Microsoft Entra ID P2","Based on the tenant configuration shown above, which `groups` are eligible to be deleted from Microsoft Entra ID?"],"options":[{"text":"Group1 only","correct":false},{"text":"Group4 only","correct":false},{"text":"Group1 and Group3 only","correct":true},{"text":"Group1, Group2, Group3, and Group4","correct":false}],"explanation":["`Group1 and Group3 only` is the correct answer because both groups do not have any licenses directly assigned to them. According to Microsoft Entra documentation, a group cannot be deleted if it has licenses directly assigned. Group1 and Group3 meet the criteria for deletion: Group1 has no assigned license, and Group3 is only a member of another group but does not itself have any license directly assigned.","`Group4 only` is incorrect because Group4 has a Microsoft Entra ID P2 license assigned directly, which prevents it from being deleted until the license is removed.","`Group1 only` is incorrect because while Group1 can be deleted, Group3 can also be deleted, so this answer is incomplete.","`Group1, Group2, Group3, and Group4` is incorrect because Group2 and Group4 both have licenses directly assigned, which disqualifies them from deletion until those licenses are removed."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-create-delete-users","https://learn.microsoft.com/en-us/entra/fundamentals/licensing-groups-resolve-problems#when-a-licensed-group-is-deleted"],"images":[],"topic":"identity","needsImage":false},{"id":"6-28","test":6,"number":28,"stem":["You have an Azure subscription named ProdSubscription that contains the following resources:","You plan to configure Azure Backup reports for RSVault1.","While configuring diagnostic settings for the AzureBackupReports log category, you must choose a storage account as the destination.","Which `storage accounts` are eligible to store the Azure Backup reports for RSVault1?"],"options":[{"text":"dataStore1 only","correct":false},{"text":"dataStore2 only","correct":false},{"text":"dataStore3 only","correct":true},{"text":"dataStore1, dataStore2, and dataStore3","correct":false}],"explanation":["`dataStore3 only` is correct because Azure Backup requires that the storage account used for diagnostic settings (like Azure Backup reports) be in the same region as the Recovery Services vault (RSVault1). Since RSVault1 is in the West Europe region, only dataStore3, located in West Europe, meets this requirement.","`dataStore1 only` is incorrect because dataStore1 is in the East US region, which does not match the West Europe region of Vault1.","`dataStore2 only` is incorrect because dataStore2 is in the West US region, which also does not match the West Europe region of Vault1.","`dataStore1, dataStore2, and dataStore3` is incorrect because only dataStore3 is in the same region as Vault1. dataStore1 and dataStore2 are in East US and West US, respectively, and therefore cannot be used."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-files?tabs=backup-center","https://docs.microsoft.com/en-us/azure/backup/backup-create-rs-vault"],"images":["assets/a201f6c9ade5b304.png"],"topic":"identity","needsImage":true},{"id":"6-29","test":6,"number":29,"stem":["You have an Azure subscription named ProdSubscription that contains the following resources:","You plan to configure Azure Backup reports for RSVault1.","While configuring diagnostic settings for the AzureBackupReports log category, you must choose a storage account as the destination.","Which `Log Analytics workspaces` can you use for the Azure Backup reports of RSVault1?"],"options":[{"text":"LogWorkspace1 only","correct":false},{"text":"LogWorkspace2 only","correct":false},{"text":"LogWorkspace3 only","correct":false},{"text":"LogWorkspace1, LogWorkspace2, and LogWorkspace3","correct":true}],"explanation":["`LogWorkspace1, LogWorkspace2, and LogWorkspace3` is correct because, as per the documentation, the location of the Log Analytics workspace does not need to match the location of the Recovery Services vault. Therefore, all three workspaces LogWorkspace1, LogWorkspace2, and LogWorkspace3, can be used to store the Azure Backup reports for Vault1."],"references":["https://learn.microsoft.com/en-us/azure/backup/configure-reports?tabs=recovery-services-vaults#1-create-a-log-analytics-workspace-or-use-an-existing-one"],"images":["assets/a201f6c9ade5b304.png"],"topic":"identity","needsImage":true},{"id":"6-30","test":6,"number":30,"stem":["You have an on-premises network and an Azure subscription that includes three peered virtual networks named VNET1, VNET2, and VNET3. All three virtual networks are connected to the on-premises network.","The subscription contains the following virtual machines:","- VM1 and VM2, located in West US and connected to VNET1","- VM3, located in West US and connected to VNET2","- VM4, located in Central US and connected to VNET3","You want to monitor network connectivity between the virtual machines and the on-premises network by using Connection Monitor.","What is the minimum number of Connection Monitor instances that you must deploy?"],"options":[{"text":"1","correct":false},{"text":"2","correct":true},{"text":"3","correct":false},{"text":"4","correct":false}],"explanation":["`2` is correct because Azure Network Watcher's Connection Monitor requires that the source virtual machine and the Connection Monitor instance reside in the same Azure region. In the table:","- VM1, VM2, and VM3 are in the West US region.","- VM4 is in the Central US region.","You will need:","- One Connection Monitor in West US to monitor VM1, VM2, and VM3's connectivity to the on-premises network.","- One Connection Monitor in Central US to monitor VM4’s connectivity to the on-premises network.","You cannot use a single connection monitor to monitor VMs across regions, hence two are required."],"references":["https://learn.microsoft.com/en-us/azure/network-watcher/connection-monitor-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-31","test":6,"number":31,"stem":["An Azure subscription contains two virtual machines with the following configurations:","- VM1","- Operating system: Windows Server 2019","- Connected to: Subnet1","- VM2","- Operating system: Windows Server 2019","- Connected to: Subnet2","Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine.","Subnet1 and Subnet2 belong to the same virtual network named VNET1.","The subscription contains two network security groups (NSGs):","- NSG1 contains only the default security rules.","- NSG2 contains the default rules and an additional inbound rule with the following configuration:","- Priority: 100","- Name: Rule1","- Protocol: TCP","- Port: 3389","- Source: Any","- Destination: Any","- Action: Allow","NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2.","True or False:","`“You can connect to VM1 from the internet using Remote Desktop.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because VM1 is associated with NSG1, which only has the default rules. By default, NSGs deny inbound traffic from the internet unless there is an explicit rule to allow it. Since NSG1 does not have any custom rule allowing inbound Remote Desktop Protocol (RDP) traffic on port 3389 from the internet, VM1 cannot be accessed via RDP from the internet."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-32","test":6,"number":32,"stem":["An Azure subscription contains two virtual machines with the following configurations:","- VM1","- Operating system: Windows Server 2019","- Connected to: Subnet1","- VM2","- Operating system: Windows Server 2019","- Connected to: Subnet2","Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine.","Subnet1 and Subnet2 belong to the same virtual network named VNET1.","The subscription contains two network security groups (NSGs):","- NSG1 contains only the default security rules.","- NSG2 contains the default rules and an additional inbound rule with the following configuration:","- Priority: 100","- Name: Rule1","- Protocol: TCP","- Port: 3389","- Source: Any","- Destination: Any","- Action: Allow","NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2.","True or False:","`“From the internet, you can connect to VM2 by using Remote Desktop.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because NSG2, which is associated with VM2’s network interface, has a custom rule (Rule1) that allows inbound traffic on port 3389 (TCP) from any source. This rule enables Remote Desktop Protocol (RDP) connections from the internet to VM2."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups"],"images":[],"topic":"identity","needsImage":false},{"id":"6-33","test":6,"number":33,"stem":["An Azure subscription contains two virtual machines with the following configurations:","- VM1","- Operating system: Windows Server 2019","- Connected to: Subnet1","- VM2","- Operating system: Windows Server 2019","- Connected to: Subnet2","Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine.","Subnet1 and Subnet2 belong to the same virtual network named VNET1.","The subscription contains two network security groups (NSGs):","- NSG1 contains only the default security rules.","- NSG2 contains the default rules and an additional inbound rule with the following configuration:","- Priority: 100","- Name: Rule1","- Protocol: TCP","- Port: 3389","- Source: Any","- Destination: Any","- Action: Allow","NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2.","True or False:","`“From VM1, you can connect to VM2 by using Remote Desktop.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because VM1 is in Subnet1 and VM2 is in Subnet2, both of which are part of the same virtual network, VNET1. Azure automatically routes traffic between subnets within the same virtual network, allowing connectivity between VMs across subnets by default. Additionally, NSG2, which is associated with VM2's network interface, has a custom rule (Rule1) that permits inbound RDP traffic on port 3389 from any source, which includes VM1."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview","https://learn.microsoft.com/en-us/azure/virtual-network/tutorial-create-route-table-powershell","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-34","test":6,"number":34,"stem":["You have an Azure virtual network named VNet1, as shown in the exhibit.","VNet1 has an address space of 10.2.0.0/16, and currently no devices are connected to it.","You plan to create a virtual network peering between VNet1 and another virtual network named VNet2. VNet2 also uses the address space 10.2.0.0/16.","You need to establish the peering between the two virtual networks.","What action should you perform first?"],"options":[{"text":"Add a gateway subnet to VNet1.","correct":false},{"text":"Create a subnet on VNet1 and VNet2.","correct":false},{"text":"Modify the address space of VNet1.","correct":true},{"text":"Configure a service endpoint on VNet2.","correct":false}],"explanation":["`Modify the address space of VNet1` is correct because the address spaces of two virtual networks being peered must not overlap. In this case, both VNet1 and VNet2 have the address space 10.2.0.0/16, which causes an overlap and prevents peering. To enable peering, you would first need to modify the address space of VNet1 to a non-overlapping range.","`Add a gateway subnet to VNet1` is incorrect because a gateway subnet is only required for VPN Gateway connections, not for simple VNet peering.","`Create a subnet on VNet1 and VNet2` is incorrect because the presence of subnets is not a requirement for VNet peering. The issue here is the overlapping address space, which must be resolved first.","`Configure a service endpoint on VNet2` is incorrect because service endpoints are used to secure access to Azure services and are not related to VNet peering configuration."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"],"images":["assets/2705dd5e43daa84e.png"],"topic":"network","needsImage":true},{"id":"6-35","test":6,"number":35,"stem":["You have an Azure subscription named ProductionSub.","You are designing a multi-tier application with the following architecture:","- Web tier","- Internet-facing: Yes","- Number of virtual machines: 10","- Application/Business tier","- Internet-facing: No","- Number of virtual machines: 100","- Database tier (SQL Server)","- Internet-facing: No","- Number of virtual machines: 5","`You must recommend a networking solution that ensures traffic from the web tier to the application tier is evenly distributed across all virtual machines in the application tier.`","Which Azure resource should you recommend to meet this requirement?"],"options":[{"text":"an application gateway that uses the Standard tier","correct":false},{"text":"an application gateway that uses the WAF tier","correct":false},{"text":"an internal load balancer","correct":true},{"text":"a network security group (NSG)","correct":false},{"text":"a public load balancer","correct":false}],"explanation":["`An internal load balancer` is correct because an internal load balancer in Azure is designed to distribute network traffic within a virtual network (VNet) across virtual machines (VMs) without exposing them to the internet. In this scenario, it can be used to balance the load between the front-end web servers and the business logic tier, ensuring that traffic spreads equally across the VMs in the business logic tier. Since the business logic tier is not accessible from the internet, an internal load balancer is the appropriate solution.","`An application gateway that uses the Standard tier `is incorrect because an application gateway is primarily designed for web traffic (HTTP/HTTPS) and is typically used in internet-facing scenarios or for application layer load balancing, which is not specified here.","`An application gateway that uses the WAF tier` is incorrect for the same reason as above. Additionally, the WAF tier is designed to protect applications from web vulnerabilities, which is unnecessary for internal load balancing between tiers in this setup.","`A network security group (NSG)` is incorrect because NSGs are used for filtering network traffic based on security rules and do not provide load balancing capabilities.","`A public load balancer` is incorrect because it is used to distribute traffic from the internet to VMs within a VNet. Since the business logic tier is not accessible from the internet, a public load balancer is not suitable."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-36","test":6,"number":36,"stem":["You have an Azure subscription named ProductionSub.","You are designing a multi-tier application with the following architecture:","- Web tier","- Internet-facing: Yes","- Number of virtual machines: 10","- Application/Business tier","- Internet-facing: No","- Number of virtual machines: 100","- Database tier (SQL Server)","- Internet-facing: No","- Number of virtual machines: 5","`You must recommend a networking solution that protects the web tier from SQL injection attacks originating from the internet.`","Which Azure resource should you recommend to meet this requirement?"],"options":[{"text":"an application gateway that uses the Standard tier","correct":false},{"text":"an application gateway that uses the WAF tier","correct":true},{"text":"an internal load balancer","correct":false},{"text":"a network security group (NSG)","correct":false},{"text":"a public load balancer","correct":false}],"explanation":["`An application gateway that uses the WAF tier` is correct because the Web Application Firewall (WAF) tier of Azure Application Gateway provides built-in protection against common web vulnerabilities, including SQL injection attacks. By placing an application gateway with WAF in front of the web servers, you can protect them from SQL injection and other security threats.","`An application gateway that uses the Standard tier` is incorrect because the Standard tier does not include WAF functionality, which is required to protect against SQL injection.","`An internal load balancer` is incorrect because load balancers are used to distribute network traffic and do not offer protection against SQL injection or other web vulnerabilities.","`A network security group (NSG)` is incorrect because NSGs control access through rules but do not provide protection against specific types of attacks like SQL injection.","`A public load balancer` is incorrect because, like an internal load balancer, it only distributes traffic and does not protect against web vulnerabilities."],"references":["https://learn.microsoft.com/en-us/azure/web-application-firewall/ag/ag-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-37","test":6,"number":37,"stem":["You have a virtual network named VNet1 with an address space of 10.2.0.0/16 and a single subnet configured as 10.2.0.0/24.","You plan to deploy a virtual machine in VNet1 and assign it an IP address from the 192.168.1.0/24 address range.","Before the virtual machine can receive an IP address from 192.168.1.0/24, what must you do first?"],"options":[{"text":"add a network interface","correct":false},{"text":"add a subnet","correct":false},{"text":"add an address space","correct":true},{"text":"delete a subnet","correct":false},{"text":"delete an address space","correct":false}],"explanation":["`Add an address space` is correct because the existing address space of VNet1 is configured as 10.2.0.0/16. To allow virtual machines on VNet1 to receive an IP address from 192.168.1.0/24, you must first add this new address space to VNet1. Azure virtual networks support multiple address spaces, but they must be added explicitly.","`Add a network interface` is incorrect because a network interface allows a VM to connect to a subnet but does not affect the IP range available within the virtual network.","`Add a subnet `is incorrect because adding a new subnet would require an available address space in the 192.168.1.0/24 range, which is not currently defined within VNet1.","`Delete a subnet` is incorrect because deleting a subnet will not allow adding the desired IP range.","`Delete an address space` is incorrect because the action required is to add a new address space, not remove an existing one."],"references":["https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/virtual-networks-static-private-ip-arm-pportal"],"images":["assets/4f8049854e783153.png"],"topic":"network","needsImage":true},{"id":"6-38","test":6,"number":38,"stem":["You have a virtual network named VNet1 with an address space of 10.2.0.0/16 and a single subnet configured as 10.2.0.0/24.","Based on the current address space and subnet configuration, a virtual machine deployed in VNet1 must be assigned an IP address from the 10.2.1.0/24 range.","What must you do before the virtual machine can receive an IP address from this range?"],"options":[{"text":"add a network interface","correct":false},{"text":"add a subnet","correct":true},{"text":"add an address space","correct":false},{"text":"delete a subnet","correct":false},{"text":"delete an address space","correct":false}],"explanation":["`Add a subnet` is correct because the current address space for VNet1 is 10.2.0.0/16, which already includes the 10.2.1.0/24 range. However, there is only one existing subnet (default) configured with the 10.2.0.0/24 address prefix. To assign IP addresses from 10.2.1.0/24, you would need to create a new subnet using this address range within the existing address space.","`Add a network interface` is incorrect because a network interface allows a VM to connect to a subnet but does not create a new address range or subnet.","`Add an address space` is incorrect because 10.2.1.0/24 is already part of the existing 10.2.0.0/16 address space, so adding a new address space is unnecessary.","`Delete a subnet` is incorrect because removing an existing subnet does not help in assigning a new IP range.","`Delete an address space` is incorrect because deleting an address space would reduce the IP range available, which is not required here."],"references":["https://docs.microsoft.com/en-us/microsoft-365/solutions/cloud-architecture-models?view=o365-worldwide","https://docs.microsoft.com/en-us/azure/virtual-network/virtual-networks-static-private-ip-arm-pportal"],"images":["assets/4f8049854e783153.png"],"topic":"network","needsImage":true},{"id":"6-39","test":6,"number":39,"stem":["An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain.","The domain includes the following users and assigned roles:","- SecAdmin1 – Role: Security Administrator","- BillAdmin1 – Role: Billing Administrator","- User1 – Role: Reports Reader","Self-service password reset (SSPR) is enabled for all users and configured with the following settings:","- Two authentication methods are required to reset a password.","- Available authentication methods are Mobile phone and Security questions.","- Users must register three security questions.","- Users must correctly answer three security questions during password reset.","The following security questions are configured:","- What is your favorite food?","- In what city was your first job?","- What was the name of your first pet?","True or False:","`“During a self-service password reset, SecAdmin1 must answer the security question ‘In what city was your first job?’”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because, although self-service password reset (SSPR) is enabled for all users, the regular SSPR policy does not apply to users in administrative roles, such as Security Administrator. Administrators must go through a two-gate policy to reset their password, which differs from the standard SSPR process configured for non-admin users. Since SecAdmin1 is in an administrative role, they are excluded from using security questions and instead must follow the enhanced SSPR process that applies to Microsoft Entra ID administrators. Additionally, SSPR is enabled by default for admin roles."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy","https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences","https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"],"images":[],"topic":"identity","needsImage":false},{"id":"6-40","test":6,"number":40,"stem":["An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain.","The domain includes the following users and assigned roles:","- SecAdmin1 – Role: Security Administrator","- BillAdmin1 – Role: Billing Administrator","- User1 – Role: Reports Reader","Self-service password reset (SSPR) is enabled for all users and configured with the following settings:","- Two authentication methods are required to reset a password.","- Available authentication methods are Mobile phone and Security questions.","- Users must register three security questions.","- Users must correctly answer three security questions during password reset.","The following security questions are configured:","- What is your favorite food?","- In what city was your first job?","- What was the name of your first pet?","True or False:","`“During a self-service password reset, BillAdmin1 must answer the security question ‘What is your favorite food?’”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because BillAdmin1 has been assigned the Billing Administrator role, which falls under the category of administrative roles in Microsoft Entra. By default, Azure applies a two-gate password reset policy for all administrator accounts. This two-gate policy requires two pieces of authentication data, such as an email address, authenticator app, or phone number, and does not permit the use of security questions for administrators. Therefore, BillAdmin1 would not be prompted to answer a security question, such as \"What is your favorite food?\" during the password reset process."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy","https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences","https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"],"images":[],"topic":"identity","needsImage":false},{"id":"6-41","test":6,"number":41,"stem":["An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain.","The domain includes the following users and assigned roles:","- SecAdmin1 – Role: Security Administrator","- BillAdmin1 – Role: Billing Administrator","- User1 – Role: Reports Reader","Self-service password reset (SSPR) is enabled for all users and configured with the following settings:","- Two authentication methods are required to reset a password.","- Available authentication methods are Mobile phone and Security questions.","- Users must register three security questions.","- Users must correctly answer three security questions during password reset.","The following security questions are configured:","- What is your favorite food?","- In what city was your first job?","- What was the name of your first pet?","True or False:","`“During a self-service password reset, User1 must answer the security question ‘What was the name of your first pet?’”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because User1 has the Reports Reader role, which is not an administrative role in Microsoft Entra. As a standard user, User1 will follow the regular self-service password reset (SSPR) policy that applies to non-admin users. Since security questions are enabled as an authentication method for SSPR, User1 can be prompted to answer questions like \"What was the name of your first pet?\" as part of the password reset process."],"references":["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy","https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences","https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"],"images":[],"topic":"identity","needsImage":false},{"id":"6-42","test":6,"number":42,"stem":["You have an Azure subscription that contains the following resources:","- VM1 – Virtual machine","- storage1 – Storage account","- Workspace1 – Log Analytics workspace","- DB1 – Azure SQL database","You plan to create a data collection rule named DCR1 in Azure Monitor.","Which of the listed resources can you configure as data sources in DCR1?"],"options":[{"text":"VM1 only","correct":true},{"text":"VM1 and storage1 only","correct":false},{"text":"VM1, storage1, and DB1 only","correct":false},{"text":"VM1, storage1, Workspace1, and DB1","correct":false}],"explanation":["`VM1 only` is the correct answer because Azure Monitor data collection rules (DCRs) can only collect data from specific resources, primarily virtual machines, as data sources. In this case, VM1 is a virtual machine and is eligible to be set as a data source in DCR1.","`VM1 and storage1 only` is incorrect because storage accounts, like storage1, cannot be used directly as data sources for data collection rules in Azure Monitor.","`VM1, storage1, and DB1 only` is incorrect because DB1 (an Azure SQL database) and storage1 are not supported as data sources for data collection rules in Azure Monitor.","`VM1, storage1, Workspace1, and DB1` is incorrect because Workspace1 (a Log Analytics workspace), storage1, and DB1 cannot be used as data sources in a data collection rule. Only VM1 is valid."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/data-collection-rule-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-sources-windows-events"],"images":[],"topic":"identity","needsImage":false},{"id":"6-43","test":6,"number":43,"stem":["You have an Azure subscription that contains the following resources:","- VM1 – Virtual machine","- storage1 – Storage account","- Workspace1 – Log Analytics workspace","- DB1 – Azure SQL database","You plan to create a data collection rule named DCR1 in Azure Monitor.","Which of the listed resources can you set as destinations in DCR1?"],"options":[{"text":"storage1 only","correct":false},{"text":"Workspace1 only","correct":true},{"text":"Workspace1 and storage1 only","correct":false},{"text":"Workspace1, storage1, and DB1 only","correct":false}],"explanation":["`Workspace1 only` is the correct answer. In Azure Monitor, a Data Collection Rule (DCR) defines how data is collected from sources and where it is sent. The valid destinations for a DCR are Log Analytics workspaces, which store monitoring data for query and analysis, and are the standard supported target for the Azure Monitor Agent. Other destinations such as Azure Storage accounts or Event Hubs can be used with diagnostic settings, but they are not supported destinations when configuring a DCR directly. Similarly, Azure SQL databases are not valid targets for monitoring data.","In the given scenario, this means that only Workspace1 can be set as a destination in DCR1. Storage1 and DB1 are not valid choices for a DCR destination, as the DCR framework is designed to work with Log Analytics workspaces for centralized monitoring and analytics."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/data-collection-rule-structure#valid-destinations"],"images":[],"topic":"identity","needsImage":false},{"id":"6-44","test":6,"number":44,"stem":["You have an Azure Linux virtual machine that is protected by Azure Backup.","Two files were deleted from the virtual machine one week ago.","You need to restore the deleted files to an on-premises computer in the shortest possible time.","Which four actions should you perform in sequence?","ACTIONS","- From the Azure portal, click Restore VM from the vault.","- Mount a VHD.","- From the Azure portal, click File Recovery from the vault.","- Copy the files by using AZCopy.","- Select a restore point that contains the deleted files.","- Copy the files by using File Explorer.","- Download and run the script to mount a drive on the local computer."],"options":[{"text":"2-3-5-7","correct":false},{"text":"1-5-2-6","correct":false},{"text":"3-5-7-6","correct":true},{"text":"6-4-7-2","correct":false},{"text":"4-5-1-3","correct":false},{"text":"2-4-7-3","correct":false}],"explanation":["3-5-7-6 is the correct sequence of actions.","(Action 3) From the Azure portal, click File Recovery from the vault – To begin the file recovery process, navigate to the File Recovery option in the vault associated with the backup.","(Action 5) Select a restore point that contains the deleted files – Choose a restore point from a date prior to the deletion of the files to ensure they are available in the backup.","(Action 7) Download and run the script to mount a drive on the local computer – This step mounts the backup as a drive on the local computer, allowing access to the files in the backup.","(Action 6) Copy the files by using File Explorer – Using File Explorer provides a straightforward way to restore the files to an on-premises Windows Server computer quickly.","(Action 2) Mount a VHD is not applicable in this context, as the File Recovery option does not involve VHDs directly for individual file restoration.","(Action 4) Copy the files by using AZCopy is unnecessary as File Explorer is sufficient once the drive is mounted. Also, File explorer will be faster than AzCopy.","(Action 3) From the Azure portal, click Restore VM from the vault would initiate a full VM restore, which is not required for individual file recovery."],"references":["https://docs.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm","https://docs.microsoft.com/en-us/azure/storage/common/storage-use-azcopy"],"images":[],"topic":"compute","needsImage":false},{"id":"6-45","test":6,"number":45,"stem":["You configure a Recovery Services vault backup policy named Policy1 with the following settings:","Based on the information provided, select the answer choice that completes the following statement correctly.","“The backup that occurs on Sunday, March 1, will be retained for ___________.”"],"options":[{"text":"30 days","correct":false},{"text":"10 weeks","correct":false},{"text":"36 months","correct":false},{"text":"10 years","correct":true}],"explanation":["`10 years` is the correct answer because the backup policy specifies retention of yearly backup points. Since the backup occurring on Sunday, March 1, aligns with the yearly retention schedule (March 1), it will be retained for the maximum period defined under the yearly backup retention, which is 10 years.","`30 days` is incorrect because this retention applies only to daily backup points, not yearly backups.","`10 weeks` is incorrect because this retention applies to weekly backup points, not yearly backups.","`36 months` is incorrect because this retention applies to monthly backup points, not yearly backups."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction","https://learn.microsoft.com/en-us/azure/backup/backup-azure-recovery-services-vault-overview"],"images":["assets/056d023d5df0eab2.png"],"topic":"identity","needsImage":true},{"id":"6-46","test":6,"number":46,"stem":["You configure a Recovery Services vault backup policy named Policy1 with the following settings:","Based on the information provided, select the answer choice that completes the following statement correctly.","“The backup that occurs on Sunday, November 1, will be retained for _____________.”"],"options":[{"text":"30 days","correct":false},{"text":"10 weeks","correct":false},{"text":"36 months","correct":true},{"text":"10 years","correct":false}],"explanation":["`36 months` is the correct answer because the backup that occurs on Sunday, November 1, aligns with both the weekly and monthly retention schedules. Given that the monthly backup point retention is set to 36 months and the weekly retention is 10 weeks, Azure’s retention policy dictates that the backup will be retained for the longest period in case of overlap. Therefore, this backup will be retained for 36 months.","`10 weeks` is incorrect because, although the backup aligns with the weekly retention schedule, the 36-month retention period for the monthly backup point takes precedence due to Azure’s policy of selecting the longest retention period.","`10 years` is incorrect because yearly retention is not applicable for this backup, as it is not taken on March 1.","`30 days` is incorrect because this applies only to daily backup points, which are irrelevant for this specific backup."],"references":["https://learn.microsoft.com/en-us/purview/retention?view=o365-worldwide&tabs=table-overriden","https://learn.microsoft.com/en-us/azure/backup/backup-azure-recovery-services-vault-overview"],"images":["assets/056d023d5df0eab2.png"],"topic":"identity","needsImage":true},{"id":"6-47","test":6,"number":47,"stem":["You purchase a new Azure subscription named Subscription1.","Within Subscription1, you deploy a virtual machine named VM1. VM1 is currently not protected by Azure Backup.","You need to configure Azure Backup for VM1. The backups must run daily at 01:00 and be retained for a period of 30 days.","Where should the backups be stored?"],"options":[{"text":"A blob container","correct":false},{"text":"A file share","correct":false},{"text":"A Recovery Services vault","correct":true},{"text":"A storage account","correct":false}],"explanation":["`A Recovery Services vault` is the correct answer because Azure Backup requires a Recovery Services vault to store backup data for virtual machines. The Recovery Services vault provides backup management and retention policies, allowing backups of VM1 to be created at the specified time (01:00) and retained for 30 days.","`A blob container` is incorrect because blob containers in Azure Storage accounts are not directly used for Azure VM backups. Azure Backup does not store VM backups in blob containers.","`A file share` is incorrect because Azure file shares are meant for file-level storage and sharing, not for storing VM backups using Azure Backup.","`A storage account` is incorrect because, although storage accounts are part of the Azure storage infrastructure, VM backups using Azure Backup require a Recovery Services vault rather than a generic storage account."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-overview","https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm"],"images":[],"topic":"identity","needsImage":false},{"id":"6-48","test":6,"number":48,"stem":["You purchase a new Azure subscription named Subscription1.","Within Subscription1, you deploy a virtual machine named VM1. VM1 is currently not protected by Azure Backup.","You need to configure Azure Backup for VM1. The backups must run daily at 01:00 and be retained for a period of 30 days.","Which object should you use to configure backup protection for VM1?"],"options":[{"text":"A backup policy","correct":true},{"text":"A batch job","correct":false},{"text":"A batch schedule","correct":false},{"text":"A recovery plan","correct":false}],"explanation":["`A backup policy` is the correct answer because Azure Backup uses backup policies to define the schedule and retention settings for protecting resources, such as virtual machines. To configure the protection for VM1, you would create a backup policy that specifies the backup time (01:00) and the retention period (30 days).","`A batch job` is incorrect because batch jobs are typically used in Azure Batch to execute large-scale parallel and high-performance computing tasks, not for configuring backups.","`A batch schedule` is incorrect because it is not related to Azure Backup. Batch schedules are relevant in the context of Azure Batch, not for VM backup configuration.","`A recovery plan` is incorrect because recovery plans are used in Azure Site Recovery for orchestrating failover and recovery of applications, not for scheduling and managing backups."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction","https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm"],"images":[],"topic":"identity","needsImage":false},{"id":"6-49","test":6,"number":49,"stem":["You manage an Azure subscription that contains several virtual machines connected to a virtual network named CorpVNet.","You plan to enable Azure Monitor and use VM Insights to monitor the virtual machines.","You must ensure that all communication between the virtual machines and Azure Monitor occurs only through CorpVNet, without using the public internet.","What should you create first to meet this requirement?"],"options":[{"text":"a private endpoint","correct":false},{"text":"an Azure Monitor Private Link Scope (AMPLS)","correct":true},{"text":"a data collection rule (DCR)","correct":false},{"text":"a Log Analytics workspace","correct":false}],"explanation":["`an Azure Monitor Private Link Scope (AMPLS)` is the correct answer because to ensure that virtual machines only communicate with Azure Monitor through the specified virtual network (CorpVNet), you need to set up a private link connection. An Azure Monitor Private Link Scope (AMPLS) allows you to create a private endpoint that enables secure communication between your virtual machines and Azure Monitor over the virtual network.","`a private endpoint` is incorrect because, while it is part of the setup, it must be associated with an AMPLS to connect the virtual machines to Azure Monitor privately. AMPLS is the primary requirement for establishing private connectivity.","`a data collection rule (DCR)` is incorrect because DCRs are used to define which data to collect from resources for Azure Monitor but do not control network connectivity or enable private communication with Azure Monitor.","`a Log Analytics workspace` is incorrect because, while required for Azure Monitor for VM Insights, it does not enable private connectivity with Azure Monitor. The AMPLS is necessary to restrict communication through CorpVNet."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/logs/private-link-security#advantages"],"images":[],"topic":"identity","needsImage":false},{"id":"6-50","test":6,"number":50,"stem":["You have an Azure subscription and plan to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","The virtual machine must be created with multiple data disks.","You need to complete the template shown in the below.","What should you choose for Code Segment A?"],"options":[{"text":"\"copy\":[","correct":true},{"text":"\"copyIndex\":[","correct":false},{"text":"\"dependsOn\":[","correct":false}],"explanation":["`\"copy\":[` is correct because the \"copy\" property is used in ARM templates to define an array of resources or properties that need to be created multiple times. In this case, the data disks need to be created dynamically based on the value of the numberOfDataDisks parameter. Using \"copy\":[ allows iterating over the required number of disks and defining their properties in the ARM template.","`\"copyIndex\":[` is incorrect because \"copyIndex\" is a function used within the \"copy\" property to get the current iteration index. It cannot replace the \"copy\" property itself.","`\"dependsOn\":[` is incorrect because \"dependsOn\" is used to specify dependencies between resources in an ARM template to ensure that certain resources are created before others. It does not help in defining multiple instances of a resource or property."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources"],"images":["assets/82843888be017c68.png"],"topic":"identity","needsImage":true},{"id":"6-51","test":6,"number":51,"stem":["You have an Azure subscription and plan to deploy a virtual machine by using an Azure Resource Manager (ARM) template.","The virtual machine must be created with multiple data disks.","You need to complete the template shown in the below.","What should you choose for Code Segment B?"],"options":[{"text":"\"[copy","correct":false},{"text":"\"[copyIndex","correct":true},{"text":"\"[dependsOn","correct":false}],"explanation":["`\"[copyIndex\"` is correct because the copyIndex() function is used to generate a unique index for each iteration of the copy property in an ARM template. This is particularly useful when you need to create multiple instances of a resource or property, as in this case, where each data disk is assigned a unique Logical Unit Number (LUN). By using \"[copyIndex]\", the LUN property dynamically assigns a unique index to each data disk being created.","`\"[copy\"` is incorrect because \"copy\" is a property used to define the array creation logic in an ARM template. It cannot be used directly as a value in this context.","`\"[dependsOn\"` is incorrect because \"dependsOn\" is used to specify dependencies between resources in an ARM template. It does not apply to the dynamic generation of unique indices for resources."],"references":["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources"],"images":["assets/82843888be017c68.png"],"topic":"identity","needsImage":true},{"id":"6-52","test":6,"number":52,"stem":["You have an Azure subscription that contains the following resources:","- A virtual machine named VM1, located in East US","- A storage account named storage1, located in West US","You must ensure that all data transfers between VM1 and storage1 occur entirely over the Azure private network and do not traverse the public internet.","What should you configure for storage1 to meet this requirement?"],"options":[{"text":"a shared access signature (SAS)","correct":false},{"text":"data protection","correct":false},{"text":"a private endpoint","correct":true},{"text":"Public network access in the Firewalls and virtual networks settings","correct":false}],"explanation":["`a private endpoint` is correct because configuring a private endpoint for storage1 ensures that data transfers between VM1 and storage1 occur entirely within the Azure virtual network. A private endpoint maps the storage account to a private IP address in the virtual network, preventing traffic from traversing the internet and providing a secure connection.","`a shared access signature (SAS)` is incorrect because an SAS provides granular access to resources in a storage account but does not ensure that the data transfer stays within the Azure virtual network.","`data protection` is incorrect because it relates to enabling recovery options and configuring soft delete features for protecting data but does not control the network path used for data transfer.","`Public network access in the Firewalls and virtual networks settings` is incorrect because disabling public network access would block all internet-based traffic but does not ensure that traffic is routed privately within Azure."],"references":["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-overview","https://learn.microsoft.com/en-us/azure/storage/common/storage-private-endpoints"],"images":[],"topic":"identity","needsImage":false},{"id":"6-53","test":6,"number":53,"stem":["You are configuring Microsoft Entra ID–based authentication for an Azure Storage account named storage1.","You must ensure that users who are members of a security group named Group1 can upload files to the storage account by using the Azure portal.","The access configuration must follow the principle of least privilege, granting only the minimum permissions required to perform the upload operation.","Which two roles should you assign to Group1 to meet these requirements?"],"options":[{"text":"Reader","correct":true},{"text":"Storage Blob Data Reader","correct":false},{"text":"Storage Blob Data Contributor","correct":true},{"text":"Storage Account Contributor","correct":false},{"text":"Contributor","correct":false}],"explanation":["`Reader` is correct because it grants management-plane read access to the storage account. Although this role does not allow users to upload files, it enables them to discover and navigate the storage account and its containers in the Azure portal. When using Microsoft Entra ID based authentication through the Azure portal, this role is required so users can access the storage account interface without being granted administrative permissions.","`Storage Blob Data Contributor` is correct because it grants the data-plane permissions required to read, write, modify, and delete blob data. This is the role that actually allows members of Group1 to upload files to blob storage.","`Storage Blob Data Reader` is incorrect because it only grants read access to blob data. Users can view blobs but cannot upload, modify, or delete them.","`Storage Account Contributor` is incorrect because it grants management permissions over the storage account, such as configuring storage account settings. These administrative permissions are unnecessary for uploading files and violate the principle of least privilege.","`Contributor` is incorrect because it provides broad management access to Azure resources, including the storage account. This exceeds the permissions required for uploading files and does not follow the principle of least privilege."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-contributor","https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader"],"images":[],"topic":"identity","needsImage":false},{"id":"6-54","test":6,"number":54,"stem":["You manage an Azure Storage account named datastore01.","The account includes a blob container named archivecontainer.","You must ensure that any new blobs uploaded to archivecontainer cannot be altered or deleted for a period of one year after they are created.","Which configuration should you apply to meet this requirement?"],"options":[{"text":"The Access control (IAM) settings","correct":false},{"text":"An access policy","correct":true},{"text":"The access level","correct":false},{"text":"The access tier","correct":false}],"explanation":["`An access policy` is the correct answer because immutable storage in Azure Blob Storage is configured using immutability policies (such as time-based retention or legal hold), which are set at the container level. Although technically this is not the same as a \"stored access policy\" used with SAS tokens, the term \"access policy\" here refers to the immutability policy configuration under the container’s \"Access policy\" settings in the Azure portal. By configuring a time-based retention policy under these settings, you can ensure that any new blobs added to the container cannot be modified or deleted for one year, thereby satisfying the requirement for data immutability.","`The Access control (IAM) settings` is incorrect because IAM controls role-based access to storage resources, defining who can read, write, or manage resources, but it does not enforce data immutability or retention policies.","`The access level` is incorrect because it defines whether the container and blobs can be publicly accessed (e.g., private, blob, or container level), but it has no impact on the ability to modify or retain content.","`The access tier` is incorrect because it specifies the performance and cost model of the blob data (Hot, Cool, Cold, or Archive). It does not prevent modifications or define retention behavior."],"references":["https://learn.microsoft.com/en-us/azure/storage/blobs/immutable-storage-overview","https://docs.microsoft.com/en-us/azure/storage/blobs/immutable-time-based-retention-policy-overview"],"images":[],"topic":"storage","needsImage":false},{"id":"6-55","test":6,"number":55,"stem":["You have an Azure subscription named ProdSub1 that contains the following resources:","- RegGrp1 – A resource group","- Action1 – An action group configured to send an email notification to admin1@apexcore.com","The subscription includes an alert rule with the following configuration:","- Name: Alert1","- Scope: All resource groups in ProdSub1, including any resource groups created in the future","- Condition: All administrative operations","- Action: Action1","The subscription also includes an alert processing rule with the following settings:","- Name: Rule1","- Scope: ProdSub1","- Rule type: Suppress notifications","- Schedule:","- Start: September 10, 2024","- End: September 13, 2024","True or False:","`\"If you create a resource group in ProdSub1 on September 11, 2024, Alert1 is listed in the Azure portal.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct because Alert1 has a scope that includes all resource groups in ProdSub1. It also includes all future resources. This means that any resource group created in ProdSub1, regardless of when it's created, will fall under the scope of Alert1. So, if a new resource group is created in ProdSub1 on September 11, 2024, Alert1 would be listed in the Azure portal for that resource group."],"references":["https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-create","https://docs.microsoft.com/en-us/azure/azure-monitor/platform/action-groups","https://docs.microsoft.com/en-us/azure/azure-monitor/platform/alerts-action-rules"],"images":[],"topic":"identity","needsImage":false},{"id":"6-56","test":6,"number":56,"stem":["You have an Azure subscription named ProdSub1 that contains the following resources:","- RegGrp1 – A resource group","- Action1 – An action group configured to send an email notification to admin1@apexcore.com","The subscription includes an alert rule with the following configuration:","- Name: Alert1","- Scope: All resource groups in ProdSub1, including any resource groups created in the future","- Condition: All administrative operations","- Action: Action1","The subscription also includes an alert processing rule with the following settings:","- Name: Rule1","- Scope: ProdSub1","- Rule type: Suppress notifications","- Schedule:","- Start: September 10, 2024","- End: September 13, 2024","True or False:","`\"If you create a resource group in ProdSub1 on September 12, 2024, an email message is sent to admin1@apexcore.com.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because, although Alert1 is configured to send an email to admin1@apexcore.com for all administrative operations, there is an alert processing rule (Rule1) in place that suppresses notifications between September 10, 2024 and September 13, 2024. Therefore, despite a new resource group being created in ProdSub1 on September 12, 2024, which is an administrative operation, the suppress rule will prevent the email notification from being sent to admin1@apexcore.com."],"references":["https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://docs.microsoft.com/en-us/azure/azure-monitor/platform/action-groups","https://docs.microsoft.com/en-us/azure/azure-monitor/platform/alerts-action-rules"],"images":[],"topic":"identity","needsImage":false},{"id":"6-57","test":6,"number":57,"stem":["You have an Azure subscription named ProdSub1 that contains the following resources:","- RegGrp1 – A resource group","- Action1 – An action group configured to send an email notification to admin1@apexcore.com","The subscription includes an alert rule with the following configuration:","- Name: Alert1","- Scope: All resource groups in ProdSub1, including any resource groups created in the future","- Condition: All administrative operations","- Action: Action1","The subscription also includes an alert processing rule with the following settings:","- Name: Rule1","- Scope: ProdSub1","- Rule type: Suppress notifications","- Schedule:","- Start: September 10, 2024","- End: September 13, 2024","True or False:","`“If you add a tag to RG1 on September 15, 2022, an email message is sent to admin1@apexcore.com.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because the alert rule, Alert1, is set to monitor all administrative operations, and adding a tag to a resource is considered an administrative operation in Azure. Since the alert applies to all resource groups in ProdSub1, including future resources, and the suppression rule (which suppresses notifications) only applies between September 10, 2024, and September 13, 2024, the action group linked to Alert1 will trigger an email to admin1@apexcore.com when the tag is added on September 15, 2024."],"references":["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"],"images":[],"topic":"identity","needsImage":false},{"id":"6-58","test":6,"number":58,"stem":["You have an Azure subscription that contains a virtual machine named VM1.","You need to configure backups for VM1. The solution must ensure that the backup data is stored across three availability zones within the primary Azure region.","Which three actions should you perform in sequence?","ACTIONS","- Configure a replication policy.","- Create a Recovery Services vault.","- Set the vault replication type to Zone-redundant storage (ZRS).","- Set the vault replication type to Locally-redundant storage (LRS).","- Create a backup policy for VM1 and enable backup for the virtual machine."],"options":[{"text":"2-5-3","correct":false},{"text":"2-3-5","correct":true},{"text":"5-3-2","correct":false},{"text":"3-5-2","correct":false}],"explanation":["`(Action 2) Create a Recovery Services vault` is the first step because the Recovery Services vault is where backup data is stored, and it supports multiple types of replication, including zone-redundant storage (ZRS) which is necessary for availability across three zones.","`(Action 3) Set the vault replication type to Zone-redundant storage (ZRS)` is the second step. After creating the vault, you must configure it to use zone-redundant storage, ensuring that the backups are replicated across three availability zones for higher availability.","`(Action 5) Create a backup policy for VM1 and enable backup for the virtual machine` is the final step. After the vault is created and configured, you need to create a backup policy and link it to VM1 to manage backup schedules and retention.","`(Action 1) Configure a replication policy` is incorrect because the backup replication type (ZRS) is set as part of the vault configuration, not a separate policy.","`(Action 4) Set the vault replication type to Locally-redundant storage (LRS)` is incorrect because LRS only replicates within a single data center, not across multiple availability zones, and thus does not meet the requirement of storing backups across three zones."],"references":["https://learn.microsoft.com/en-us/azure/backup/backup-create-recovery-services-vault","https://learn.microsoft.com/en-us/azure/backup/quick-backup-vm-portal"],"images":[],"topic":"identity","needsImage":false},{"id":"6-59","test":6,"number":59,"stem":["You have a Microsoft Entra tenant named adatum.com.","The tenant contains the following security groups:","- Group1","- Type: Security","- Member of: None","- Group2","- Type: Security","- Member of: Group1","The tenant also contains the following users:","- User1","- Member of: Group1","- User2","- Member of: Group2","You assign a Microsoft Entra ID P2 license to Group1.","The license is configured so that the Microsoft Entra ID P2 service plan is enabled.","Group2 is not directly assigned any licenses.","True or False:","`“You can remove the Microsoft Entra ID P2 license from User1.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because User1 received the Microsoft Entra ID P2 license through group-based licensing via Group1. Licenses assigned through a group cannot be removed directly from an individual user. To revoke the license from User1, you must either remove User1 from Group1 or unassign the license from Group1 entirely.","Group-based licensing enforces inheritance, meaning individual license removal is not possible for users who inherit their license through a group assignment.","**Reference(s):","**https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing"],"references":[],"images":["assets/f68a35bf20b8a004.png"],"topic":"identity","needsImage":true},{"id":"6-60","test":6,"number":60,"stem":["You have a Microsoft Entra tenant named adatum.com.","The tenant contains the following security groups:","- Group1","- Type: Security","- Member of: None","- Group2","- Type: Security","- Member of: Group1","The tenant also contains the following users:","- User1","- Member of: Group1","- User2","- Member of: Group2","You assign a Microsoft Entra ID P2 license to Group1.","The license is configured so that the Microsoft Entra ID P2 service plan is enabled.","Group2 is not directly assigned any licenses.","True or False:","`“User2 is assigned the Microsoft Entra ID P2 license.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because Microsoft Entra group-based licensing does not support nested group inheritance. In this scenario, although Group1 has been assigned the Microsoft Entra ID P2 license, User2 is only a member of Group2, which is a child of Group1. Because nested groups are not supported for license propagation, User2 will not receive the license via Group1 unless Group2 is directly licensed or the license is directly assigned to User2.","**Reference(s):","**https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing","https://learn.microsoft.com/en-gb/entra/identity/users/licensing-group-advanced"],"references":[],"images":["assets/f68a35bf20b8a004.png"],"topic":"identity","needsImage":true},{"id":"6-61","test":6,"number":61,"stem":["You have a Microsoft Entra tenant named adatum.com.","The tenant contains the following security groups:","- Group1","- Type: Security","- Member of: None","- Group2","- Type: Security","- Member of: Group1","The tenant also contains the following users:","- User1","- Member of: Group1","- User2","- Member of: Group2","You assign a Microsoft Entra ID P2 license to Group1.","The license is configured so that the Microsoft Entra ID P2 service plan is enabled.","Group2 is not directly assigned any licenses.","True or False:","`“You can assign User1 the Microsoft Defender for Cloud Apps Discovery license.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because when a license is assigned to a group, the licensing options are inherited by all members of the group, and individual users cannot modify or enable specific license features that were disabled at the group level.","- User1 is a member of Group1, which has the Microsoft Entra ID P2 license assigned.","- If specific features within the license, such as Microsoft Defender for Cloud Apps Discovery, were disabled when assigning the license to Group1, they remain disabled for all members.","- License settings inherited from a group cannot be modified at the user level.","- Group-based licensing controls all assigned features.","- Microsoft Entra ID group-based licensing ensures that individual users cannot override settings configured at the group level.","- If an admin wants to enable a feature, the change must be made at the group level, not for individual users.","- User-level modifications are restricted.","- Since User1’s license is inherited from Group1, they cannot be manually assigned the Microsoft Defender for Cloud Apps Discovery license unless Group1’s settings are updated to enable it."],"references":[],"images":["assets/f68a35bf20b8a004.png"],"topic":"identity","needsImage":true},{"id":"6-62","test":6,"number":62,"stem":["You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:","- Standard BS Family vCPUs: 20 (0 currently used)","- Standard D Family vCPUs: 20 (0 currently used)","- Total Regional vCPUs: 20 (0 currently used)","The subscription currently contains the following virtual machines deployed in West US:","- VM1","- Size: Standard_B2ms","- vCPUs: 2","- Status: Running","- VM2","- Size: Standard_B16ms","- vCPUs: 16","- Status: Stopped (Deallocated)","You now plan to deploy the following additional virtual machines:","True or False:","`“You can deploy VM3 to West US.”`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is correct. In this scenario, VM1 is running and uses 2 vCPUs. VM2 is in a Stopped (Deallocated) state, but it still counts against the vCPU quota because Azure reserves resources for any provisioned (even if deallocated) VM. This brings the current vCPU usage to:","- VM1: 2 vCPUs","- VM2: 16 vCPUs","- Total usage: 18 out of 20 vCPUs (under the Total Regional vCPU quota)","VM3 requires 2 vCPUs, which would increase total usage to exactly 20, matching the quota but not exceeding it. Therefore, the deployment is allowed.","Additionally, the Standard BS Family vCPU quota is 20. VM2 (Standard_B16ms) is a B-series VM, so it counts toward this quota too, alongside VM1. Current usage is therefore 18 vCPUs (VM1's 2 + VM2's 16). Adding VM3 (2 vCPUs from the same family) brings it to exactly 20, which is also allowed."],"references":[],"images":["assets/498198c70618e5e9.png"],"topic":"identity","needsImage":true},{"id":"6-63","test":6,"number":63,"stem":["You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:","- Standard BS Family vCPUs: 20 (0 currently used)","- Standard D Family vCPUs: 20 (0 currently used)","- Total Regional vCPUs: 20 (0 currently used)","The subscription currently contains the following virtual machines deployed in West US:","- VM1","- Size: Standard_B2ms","- vCPUs: 2","- Status: Running","- VM2","- Size: Standard_B16ms","- vCPUs: 16","- Status: Stopped (Deallocated)","You now plan to deploy the following additional virtual machines:","True or False:","`“You can deploy VM4 to West US.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct as the Total Regional vCPUs quota in West US is capped at 20 vCPUs. This quota represents the maximum total vCPUs across all VM sizes, regardless of whether a virtual machine is running or stopped (deallocated).","In the current scenario:","- VM1 is consuming 2 vCPUs (Running).","- VM2 is Stopped (Deallocated) but still counts towards the total regional vCPU quota with 16 vCPUs reserved.","This results in:","2 vCPUs (VM1) + 16 vCPUs (VM2) = 18 vCPUs","This leaves only 2 vCPUs available under the regional quota.","VM4 requires 4 vCPUs, which would bring the total to:","2 vCPUs (VM1) + 16 vCPUs (VM2) + 4 vCPUs (VM4) = 22 vCPUs","This exceeds the total regional vCPU quota of 20 vCPUs, making the deployment of VM4 impossible under the current quota limits."],"references":[],"images":["assets/498198c70618e5e9.png"],"topic":"identity","needsImage":true},{"id":"6-64","test":6,"number":64,"stem":["You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:","- Standard BS Family vCPUs: 20 (0 currently used)","- Standard D Family vCPUs: 20 (0 currently used)","- Total Regional vCPUs: 20 (0 currently used)","The subscription currently contains the following virtual machines deployed in West US:","- VM1","- Size: Standard_B2ms","- vCPUs: 2","- Status: Running","- VM2","- Size: Standard_B16ms","- vCPUs: 16","- Status: Stopped (Deallocated)","You now plan to deploy the following additional virtual machines:","True or False:","`“You can deploy VM5 to West US.”`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is correct because the Total Regional vCPU quota in the West US region is 20 vCPUs. This quota accounts for all allocated and deallocated virtual machines in the region.","The current vCPU usage is as follows:","- VM1: 2 vCPUs (Running)","- VM2: 16 vCPUs (Stopped/Deallocated)","Even though VM2 is deallocated, its 16 vCPUs still count toward the regional vCPU quota because Azure reserves these resources for the VM.","This means the total vCPU usage stands at:","2 vCPUs (VM1) + 16 vCPUs (VM2) = 18 vCPUs","VM5 requires 16 vCPUs. Adding these would result in:","2 vCPUs (VM1) + 16 vCPUs (VM2) + 16 vCPUs (VM5) = 34 vCPUs","This far exceeds the 20 vCPU quota for the West US region, making it impossible to deploy VM5 without increasing the quota or deallocating other virtual machines."],"references":[],"images":["assets/498198c70618e5e9.png"],"topic":"identity","needsImage":true},{"id":"6-65","test":6,"number":65,"stem":["You manage a Microsoft Entra tenant named ironclad.com.","The tenant contains the following groups:","- Group1","- Group type: Security","- Membership type: Dynamic user","- Rule: Users where city starts with “m”","- Group2","- Group type: Microsoft 365","- Membership type: Dynamic user","- Rule: Users whose department is not “human resources”","- Group3","- Group type: Microsoft 365","- Membership type: Assigned","- No dynamic rule configured","You then create two users with the following attributes:","- User1","- City: Montreal","- Department: Human resources","- Microsoft 365 license assigned: Yes","- User2","- City: Melbourne","- Department: Marketing","- Microsoft 365 license assigned: No","Based on the configured dynamic membership rules and user properties, which group or groups does User1 belong to?"],"options":[{"text":"Group1 only","correct":true},{"text":"Group2 only","correct":false},{"text":"Group3 only","correct":false},{"text":"Group1 and Group2 only","correct":false},{"text":"Group1 and Group3 only","correct":false},{"text":"Group1, Group2, and Group3","correct":false}],"explanation":["`Group1 only` is correct because User1 meets the dynamic membership rule for Group1 but does not meet the membership criteria for Group2 or Group3.","- Group1 (Dynamic user): The rule specifies that users whose city starts with \"m\" are added to this group.","- User1's city is Montreal, which starts with \"M.\" Therefore, User1 is a member of Group1.","- Group2 (Dynamic user): The rule excludes users whose department is \"human resources.\"","- User1's department is \"Human resources,\" so User1 is excluded from Group2.","- Group3 (Assigned membership): Membership is manually assigned.","- User1 is not manually assigned to Group3, so User1 is not a member of Group3.","Therefore, User1 is only a member of Group1.","**Reference(s):","**https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership","https://learn.microsoft.com/en-us/entra/identity/users/groups-create-rule"],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"6-66","test":6,"number":66,"stem":["You manage a Microsoft Entra tenant named ironclad.com.","The tenant contains the following groups:","- Group1","- Group type: Security","- Membership type: Dynamic user","- Rule: Users where city starts with “m”","- Group2","- Group type: Microsoft 365","- Membership type: Dynamic user","- Rule: Users whose department is not “human resources”","- Group3","- Group type: Microsoft 365","- Membership type: Assigned","- No dynamic rule configured","You then create two users with the following attributes:","- User1","- City: Montreal","- Department: Human resources","- Microsoft 365 license assigned: Yes","- User2","- City: Melbourne","- Department: Marketing","- Microsoft 365 license assigned: No","Based on the configured dynamic membership rules and user properties, which group or groups does `User2` belong to?"],"options":[{"text":"Group1 only","correct":false},{"text":"Group2 only","correct":false},{"text":"Group3 only","correct":false},{"text":"Group1 and Group2 only","correct":true},{"text":"Group1 and Group3 only","correct":false},{"text":"Group2 and Group3 only","correct":false}],"explanation":["`Group1 and Group2 only` is correct because User2 meets the membership rules for both Group1 and Group2 based on their city and department attributes.","- Group1 (Dynamic user): The membership rule specifies that users are added if their city starts with \"m\".","- User2's city is Melbourne, which starts with \"M\". Therefore, User2 satisfies the rule for Group1.","- Group2 (Dynamic user): The membership rule specifies that users whose department is not \"human resources\" are included.","- User2's department is Marketing, which satisfies the notIn [\"human resources\"] rule. Therefore, User2 is included in Group2.","- Group3 (Assigned membership): Membership is manually assigned.","- User2 has not been manually added to Group3, so they are not a member of Group3.","Additionally, the Microsoft 365 license does not impact group membership. Licenses are only for accessing services and do not affect dynamic or assigned group memberships.","Therefore, User2 is a member of Group1 and Group2 only."],"references":[],"images":[],"topic":"identity","needsImage":false},{"id":"6-67","test":6,"number":67,"stem":["You have an Azure subscription that contains a virtual machine running Windows 10.","You need to join the virtual machine to an Active Directory domain by using the below Azure Resource Manager (ARM) template.","Which value should you choose for `Code Segment A`?"],"options":[{"text":"\"Extensions\",","correct":false},{"text":"\"Microsoft.Compute/VirtualMachines\",","correct":false},{"text":"\"Microsoft.Compute/virtualMachines/extensions\",","correct":true}],"explanation":["`\"Microsoft.Compute/virtualMachines/extensions\"` is correct because. This namespace specifies that the resource being managed is an extension applied to an Azure virtual machine.","`\"Extensions\"` is incorrect because it is not a valid Azure Resource Manager resource type.","`\"Microsoft.Compute/VirtualMachines\"` is incorrect because it refers to virtual machines themselves, not their extensions."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/overview","https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines/extensions","https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-template#domain-join"],"images":["assets/620b121fd09e4907.png"],"topic":"identity","needsImage":true},{"id":"6-68","test":6,"number":68,"stem":["You have an Azure subscription that contains a virtual machine running Windows 10.","You need to join the virtual machine to an Active Directory domain by using the below Azure Resource Manager (ARM) template.","Which value should you choose for `Code Segment B`?"],"options":[{"text":"\"ProtectedSettings\": {","correct":true},{"text":"\"Settings\": {","correct":false},{"text":"\"Statuses\": {","correct":false}],"explanation":["`\"ProtectedSettings\": {` is correct because in an Azure Resource Manager (ARM) template, sensitive information like passwords or secrets, such as the domainPassword, should always be placed in the ProtectedSettings section. This ensures that the sensitive values are securely encrypted and not exposed in plaintext when viewed or logged.","`\"Settings\": {` is incorrect because it is used for general configuration settings and does not handle sensitive information securely.","`\"Statuses\": {` is incorrect because it is used to report the status of an extension deployment, not for passing configuration parameters."],"references":["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/domain-join","https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines/extensions","https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-template#domain-join"],"images":["assets/620b121fd09e4907.png"],"topic":"identity","needsImage":true},{"id":"6-69","test":6,"number":69,"stem":["You have an Azure subscription that hosts several resources accessed by users from two locations:","- Users working from home connect to Azure by using a point-to-site (P2S) VPN.","- Users at customer locations connect to Azure by using site-to-site (S2S) VPNs.","There is a line-of-business application named App1 that runs on multiple Azure virtual machines.","All the virtual machines run Windows Server 2016.","You must ensure that incoming connections to App1 are evenly distributed across all the virtual machines.","Which two Azure services can you use to meet this requirement?"],"options":[{"text":"an internal load balancer","correct":true},{"text":"a public load balancer","correct":false},{"text":"an Azure Content Delivery Network (CDN)","correct":false},{"text":"Traffic Manager","correct":false},{"text":"an Azure Application Gateway","correct":true}],"explanation":["`an internal load balancer` is the correct answer because it distributes incoming traffic evenly across virtual machines within the same virtual network. Internal Load Balancers are used when applications are accessed only internally and do not require public internet exposure. This matches the scenario where users are connecting through VPNs, either point-to-site or site-to-site, and need internal routing of traffic to backend virtual machines hosting App1.","`an Azure Application Gateway` is also correct because it is a layer-7 (application layer) load balancer that can intelligently route traffic based on HTTP/HTTPS requests. It is suitable for web applications like App1, providing features such as URL-based routing, SSL termination, and session affinity, ensuring optimized and secure delivery of requests to the virtual machines hosting App1.","`a public load balancer` is incorrect because it distributes incoming traffic from public IP addresses. In this scenario, the application is accessed internally through VPN connections rather than from the public internet.","`an Azure Content Delivery Network (CDN)` is incorrect because CDN is designed to cache and deliver static content like images, videos, and scripts globally. It does not handle traffic distribution to backend virtual machines for business applications like App1.","`Traffic Manager` is incorrect because it operates at the DNS level and is used to direct users to different endpoints based on rules like geographic location or endpoint health. It does not distribute traffic across virtual machines within the same virtual network."],"references":["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview","https://learn.microsoft.com/en-us/azure/application-gateway/overview","https://learn.microsoft.com/en-us/azure/cdn/cdn-overview","https://learn.microsoft.com/en-us/azure/traffic-manager/traffic-manager-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-70","test":6,"number":70,"stem":["You have an Azure subscription that includes a user named User1.","You must grant User1 permissions to:","- Create and manage virtual machines","- Create and manage virtual networks","The permissions assigned must follow the principle of least privilege.","Which role-based access control (RBAC) role should you assign to User1?"],"options":[{"text":"Owner","correct":false},{"text":"Virtual Machine Contributor","correct":false},{"text":"Contributor","correct":true},{"text":"Virtual Machine Administrator Login","correct":false}],"explanation":["`Contributor` is the correct answer because this role grants full access to manage all Azure resources, including virtual machines and virtual networks, but does not allow access to assign roles in Azure RBAC. This aligns with the requirement to deploy virtual machines and manage virtual networks while following the principle of least privilege, as the role does not grant unnecessary permissions such as role assignment.","`Owner` is incorrect because the Owner role has full access to all resources, including the ability to assign roles in RBAC. This exceeds the principle of least privilege since User1 does not require role assignment capabilities.","`Virtual Machine Contributor` is incorrect because this role grants permissions only for managing virtual machines, but it does not include the ability to manage virtual networks, which is explicitly required in the scenario.","`Virtual Machine Administrator Login` is incorrect because this role only allows a user to log in to virtual machines with administrator privileges. It does not provide permissions to deploy virtual machines or manage virtual networks."],"references":["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles","https://learn.microsoft.com/en-us/azure/role-based-access-control/role-definitions","https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-71","test":6,"number":71,"stem":["You have an Azure subscription that includes the following resources:","- VNET1: A virtual network in resource group RG1","- VM1: A virtual machine in resource group RG1","A Not allowed resource types Azure Policy is assigned to RG1 with enforcement enabled. The policy blocks the following resource types:","- Microsoft.Network/virtualNetworks","- Microsoft.Compute/virtualMachines","You need to deploy a new virtual machine named VM2 in RG1 and connect it to VNET1.","What action must you take first?"],"options":[{"text":"Remove Microsoft.Compute/virtualMachines from the policy.","correct":true},{"text":"Add a subnet to VNET1.","correct":false},{"text":"Remove Microsoft.Network/virtualNetworks from the policy.","correct":false},{"text":"Create an Azure Resource Manager template.","correct":false}],"explanation":["`Remove Microsoft.Compute/virtualMachines from the policy` is the correct answer. The Not allowed resource types policy assigned to RG1 explicitly prevents the creation of resources with type `Microsoft.Compute/virtualMachines`, which includes any virtual machines. Since the goal is to create a new VM named VM2 in RG1, this policy must first be adjusted to allow VM creation. Otherwise, any deployment attempt for a VM (whether through portal, script, or ARM template) will be blocked due to the policy enforcement.","`Add a subnet to VNET1` is incorrect because the presence or absence of a subnet does not address the core issue. Even if VNET1 had a valid subnet, the policy blocks VM creation entirely in RG1, making this step irrelevant at this point.","`Remove Microsoft.Network/virtualNetworks from the policy` is incorrect because there is no requirement to create a new virtual network—VNET1 already exists and is intended to be used. The VM can be connected to an existing VNet as long as the policy allows VM creation. Removing this restriction isn't necessary to create the VM.","`Create an Azure Resource Manager template` is incorrect because using an ARM template will still fail if the policy prohibits creating the specified resource types. Azure Policy enforcement blocks resource creation regardless of the method used—portal, CLI, PowerShell, or ARM templates."],"references":["https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines?pivots=deployment-language-bicep","https://learn.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure#policy-rule","https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effects#deny","https://learn.microsoft.com/en-us/azure/governance/policy/samples/not-allowed-resource-types","https://learn.microsoft.com/en-us/azure/virtual-machines/overview","https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"],"images":[],"topic":"identity","needsImage":false},{"id":"6-72","test":6,"number":72,"stem":["An Azure subscription contains two resource groups with the following configurations:","Resource group settings","- RG1","- Resource group lock: None","- RG2","- Resource group lock name: Lock","- Lock type: Delete","Resources in RG1","- Storage1","- Type: Storage account","- Lock name: Lock1","- Lock type: Delete","- VNET1","- Type: Virtual network","- Lock name: Lock2","- Lock type: Read-only","- IP1","- Type: Public IP address","- Lock: None","Resources in RG2","- Storage2","- Type: Storage account","- Lock name: Lock1","- Lock type: Delete","- VNET2","- Type: Virtual network","- Lock name: Lock2","- Lock type: Read-only","- IP2","- Type: Public IP address","- Lock: None","Which resources can be moved from RG1 to RG2?"],"options":[{"text":"None","correct":false},{"text":"IP1 only","correct":false},{"text":"IP1 and storage1 only","correct":false},{"text":"IP1 and VNET1 only","correct":false},{"text":"IP1, VNET1, and storage1","correct":true}],"explanation":["`IP1, VNET1, and storage1` is correct. Azure resource locks such as Read-only and Delete are designed to prevent deletion or modification of resources, but they do not block move operations. A Delete lock on a resource (such as storage1) or the target resource group (like RG2) does not prevent resources from being moved into or out of that group. Similarly, a Read-only lock (as applied to VNET1) restricts modifications but still permits the resource to be moved. IP1 has no lock, so it is fully eligible for movement. Since none of the listed locks prohibit the act of moving resources, all three resources — IP1, VNET1, and storage1 — can be moved from RG1 to RG2.","Resources created in RG1 (used name storage1shireen instead of storage1)","Lock on RG1: None","Locks on storage account and virtual network in RG1","Lock on RG2: Delete","Resources created in RG2 (used name storage2shireen instead of storage1)","Locks on RG2 and virtual network and storage account in RG2","Attempting to move IP1, VNet1, and storage1shireen to RG2","Sucessfully moved IP1, VNet1, and storage1shireen to RG2**","Resources in RG1 after resource movement","Resources in RG2 after resource movement"],"references":["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"],"images":[],"topic":"identity","needsImage":false},{"id":"6-73","test":6,"number":73,"stem":["An Azure subscription contains two resource groups with the following configurations:","Resource group settings","- RG1","- Resource group lock: None","- RG2","- Resource group lock name: Lock","- Lock type: Delete","Resources in RG1","- Storage1","- Type: Storage account","- Lock name: Lock1","- Lock type: Delete","- VNET1","- Type: Virtual network","- Lock name: Lock2","- Lock type: Read-only","- IP1","- Type: Public IP address","- Lock: None","Resources in RG2","- Storage2","- Type: Storage account","- Lock name: Lock1","- Lock type: Delete","- VNET2","- Type: Virtual network","- Lock name: Lock2","- Lock type: Read-only","- IP2","- Type: Public IP address","- Lock: None","Which resources can be moved from RG2 to RG1?"],"options":[{"text":"None","correct":false},{"text":"IP2 only","correct":false},{"text":"IP2 and storage2 only","correct":false},{"text":"IP2 and VNET2 only","correct":false},{"text":"IP2, VNET2, and storage2","correct":true}],"explanation":["`IP2, VNET2, and storage2` is correct as Locks are designed for any update or removal. In this case, we want to move only, we are not deleting, and we are not changing anything in the resource.","In the previous question, we were able to move all resources from RG1 to RG2. Similarly, we will be able to move IP2, VNET2, and storage2 from RG2 to RG1.","Attempting to move resources from RG2 to RG1","After successful movement, RG2 resources","After successful movement, RG1 resources"],"references":["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"],"images":[],"topic":"identity","needsImage":false},{"id":"6-84","test":6,"number":84,"stem":["You have a Microsoft Entra tenant that has the ironclad.onmicrosoft.com domain name.","You have a domain name of ironclad.com registered at a third-party registrar.","You need to ensure that you can create Microsoft Entra users that have names containing a suffix of @ironclad.com.","Which three actions should you perform in sequence?","ACTIONS","- Verify the domain.","- Add a record to the public ironclad.com DNS zone.","- Create an Azure DNS zone.","- Configure company branding.","- Add a Microsoft Entra tenant.","- Add a custom domain name."],"options":[{"text":"2-3-6","correct":false},{"text":"6-2-1","correct":true},{"text":"3-2-6","correct":false},{"text":"6-1-2","correct":false}],"explanation":["`6-2-1`  is the CORRECT sequence of actions.","`(Action 6)` Add a custom domain name is correct. You begin by adding `ironclad.com` as a custom domain in your Microsoft Entra tenant. This tells Entra ID that you want to use this domain for user principal names (UPNs) and email addresses.","`(Action 2)` Add a record to the public ironclad.com DNS zone is correct. To prove ownership of the domain, Microsoft Entra ID provides a TXT or MX record that must be added to the public DNS zone where the domain (`ironclad.com`) is hosted. This is required for verification.","`(Action 1)` Verify the domain is correct. After adding the DNS record, you return to Microsoft Entra ID and complete the verification process. Once verified, the domain can be used to create users with UPNs like `user@ironclad.com`.","`(Action 3)` Create an Azure DNS zone is incorrect. Not required unless you're hosting DNS within Azure, which is not needed for verifying a third-party registered domain.","`(Action 4)` Configure company branding is incorrect. Not required to use a custom domain for user accounts.","`(Action 5)` Add a Microsoft Entra tenant is incorrect. Already provided in the question, so not needed."],"references":["https://learn.microsoft.com/en-us/azure/dns/dns-web-sites-custom-domain","https://learn.microsoft.com/en-us/entra/fundamentals/add-custom-domain"],"images":[],"topic":"identity","needsImage":false},{"id":"6-85","test":6,"number":85,"stem":["A Microsoft Entra hybrid environment contains the following user accounts:","- User1","- User type: Member","- On-premises synchronization enabled: No","- User2","- User type: Member","- On-premises synchronization enabled: Yes","- User3","- User type: Guest","- On-premises synchronization enabled: No","You need to modify the `JobTitle` attribute for these users.","For which users can the attribute be updated directly within Microsoft Entra ID?"],"options":[{"text":"User1 only","correct":false},{"text":"User1 and User2 only","correct":false},{"text":"User1 and User3 only","correct":true},{"text":"User1, User2, and User3","correct":false}],"explanation":["`User1 and User3 only` is the correct answer because their accounts are cloud-only (User1 is a member with no on-premises sync, and User3 is a guest user). This means their attributes—including JobTitle—can be modified directly in Microsoft Entra ID.","User2 is synchronized from on-premises Active Directory, so their attributes must be modified in the on-premises directory. Microsoft Entra ID does not allow attribute modification for synced users from the cloud interface."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-manage-user-profile-info"],"images":[],"topic":"identity","needsImage":false},{"id":"6-86","test":6,"number":86,"stem":["A Microsoft Entra hybrid environment contains the following user accounts:","- User1","- User type: Member","- On-premises synchronization enabled: No","- User2","- User type: Member","- On-premises synchronization enabled: Yes","- User3","- User type: Guest","- On-premises synchronization enabled: No","You need to modify the `UsageLocation` attribute for these users.","For which users can the attribute be updated directly within Microsoft Entra ID?"],"options":[{"text":"User1 only","correct":false},{"text":"User1 and User2 only","correct":false},{"text":"User1 and User3 only","correct":false},{"text":"User1, User2, and User3","correct":true}],"explanation":["User1, User2, and User3 is the correct answer because the UsageLocation attribute is always stored and managed in Microsoft Entra ID, regardless of whether the user is cloud-only (User1 and User3) or synced from on-premises Active Directory (User2). This attribute is required for assigning Microsoft 365 licenses and can be directly edited from the Microsoft Entra portal or using PowerShell for all types of users."],"references":["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-manage-user-profile-info"],"images":[],"topic":"identity","needsImage":false},{"id":"6-87","test":6,"number":87,"stem":["An Azure subscription contains the following users:","- User1 – Member of Group1","- User2 – Member of Group2","- User3 – Member of Group3","The groups are configured as follows:","- Group1 – Type: Security","- Group2 – Type: Security","- Group3 – Type: Microsoft 365","All three groups are enabled for Microsoft Entra role assignments.","You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit.","True or False:","`\"You can assign User2 the Owner role for RG1 by adding Group2 as a member of Group1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is CORRECT because nesting is supported for groups that can be assigned a role.","In the screenshots pasted below, TestGroup is the Owner of the RG. And TestGroup3 is another group with a user User1, we want to be added as Owner of RG. So, as you can see, I can add TestGroup3 as the member of TestGroup. And this gives User1 the owner access of the RG."],"references":["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#how-are-role-assignable-groups-protected"],"images":["assets/8b132af0d5d5b596.png"],"topic":"identity","needsImage":true},{"id":"6-88","test":6,"number":88,"stem":["An Azure subscription contains the following users:","- User1 – Member of Group1","- User2 – Member of Group2","- User3 – Member of Group3","The groups are configured as follows:","- Group1 – Type: Security","- Group2 – Type: Security","- Group3 – Type: Microsoft 365","All three groups are enabled for Microsoft Entra role assignments.","You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit.","True or False:","`\"You can assign User3 the Owner role for RG1 by adding Group3 as a member of Group1.\"`"],"options":[{"text":"True","correct":false},{"text":"False","correct":true}],"explanation":["`False` is the correct answer because Azure role assignments do not support nested groups when the nested group is a Microsoft 365 group. In this scenario, Group3 is a Microsoft 365 group, and even though Group1 is assigned the Owner role for RG1, adding Group3 as a member of Group1 will not grant the Owner role to User3. This is because Microsoft Entra ID (Azure AD) does not support nested group evaluation for Microsoft 365 groups in role assignments."],"references":["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#limitations-of-using-groups-in-azure-ad-roles","https://learn.microsoft.com/en-us/entra/identity/users/directory-service-limits-restrictions"],"images":["assets/8b132af0d5d5b596.png"],"topic":"identity","needsImage":true},{"id":"6-89","test":6,"number":89,"stem":["An Azure subscription contains the following users:","- User1 – Member of Group1","- User2 – Member of Group2","- User3 – Member of Group3","The groups are configured as follows:","- Group1 – Type: Security","- Group2 – Type: Security","- Group3 – Type: Microsoft 365","All three groups are enabled for Microsoft Entra role assignments.","You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit.","True or False:","`\"You can assign User3 the Owner role for RG1 by assigning the Owner role to Group3 for RG1.\"`"],"options":[{"text":"True","correct":true},{"text":"False","correct":false}],"explanation":["`True` is the correct answer because Group3 is configured to allow Microsoft Entra roles to be assigned to it (`Microsoft Entra roles can be assigned to the group: Yes`). This makes the group eligible for role-based access control (RBAC) assignments, such as assigning the Owner role for a specific resource group like RG1. Even though Group3 is a Microsoft 365 group, direct role assignments (not nested) are supported when the group is configured for role assignments. As a result, User3, a direct member of Group3, will inherit the Owner role for RG1."],"references":["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#assign-azure-ad-roles-to-groups","https://learn.microsoft.com/en-us/entra/identity/users/directory-service-limits-restrictions"],"images":["assets/8b132af0d5d5b596.png"],"topic":"identity","needsImage":true},{"id":"6-90","test":6,"number":90,"stem":["You have an Azure subscription that contains 100 virtual machines.","You need to quickly identify virtual machines that are underutilized and could be moved to a lower-cost service tier.","Which Azure portal blade should you use?"],"options":[{"text":"Monitor","correct":false},{"text":"Advisor","correct":true},{"text":"Metrics","correct":false},{"text":"Customer insights","correct":false}],"explanation":["`Advisor` is the correct answer because Azure Advisor provides personalized recommendations to optimize your Azure resources for cost, performance, security, and more. Specifically, it includes cost recommendations to help identify underutilized virtual machines that can be resized to a lower-cost SKU, thereby reducing unnecessary spend.","`Monitor` is incorrect because although it provides telemetry data and performance metrics, it doesn't offer built-in cost optimization recommendations.","`Metrics` is incorrect because it shows raw performance counters and charts but doesn't interpret or recommend changes based on utilization.","`Customer insights` is incorrect because it's related to customer data analytics (like Dynamics 365), and not relevant for Azure resource management or optimization."],"references":["https://learn.microsoft.com/en-us/azure/advisor/advisor-cost-recommendations","https://learn.microsoft.com/en-us/azure/advisor/advisor-overview"],"images":[],"topic":"identity","needsImage":false}];